/// What one `editor_surface_forget` did to one endpoint root.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RootRetirement {
    /// A newer registration (or an equal-or-newer retirement): not this
    /// forget's to touch.
    Unchanged,
    /// The root was already retired at an older generation; its fence moved up
    /// to the forget's generation.
    FenceRaised,
    /// A live root was retired; `registered_generation` is the generation it
    /// was registered at (the terminal-ownership key).
    Retired { registered_generation: u64 },
}

/// `ControllerRecvRetire` in `formal/tla/PassiveTmuxSyncRetireNet.tla`.
///
/// A forget at generation `g` retires a root registered at any generation
/// `<= g` and RAISES its fence to `g` (`RetireRaisesFence`). The shipped forget
/// matched the generation exactly, which was harmless while one plugin process
/// had one generation. Once a live endpoint re-registers above a retired
/// generation (`#surfaceretireformal`), a handoff's forget at the re-registered
/// generation can overtake the re-registering observation; an exact match then
/// ignored it and the observation drove tmux from a frame the editor had
/// declared ended (`PassiveTmuxSyncRetireNetExactForgetWedge`). A root
/// registered at a NEWER generation than the forget stays untouched, so a
/// delayed forget never retires a re-registration.
fn retire_editor_surface_root(
    current: &mut ControllerEditorSurfaceRoot,
    generation: u64,
) -> RootRetirement {
    if current.generation > generation || (current.retired && current.generation == generation) {
        return RootRetirement::Unchanged;
    }
    let registered_generation = current.generation;
    current.generation = generation;
    if current.retired {
        return RootRetirement::FenceRaised;
    }
    current.state.stop(&current.consequence);
    current.retired = true;
    RootRetirement::Retired {
        registered_generation,
    }
}

impl ControllerEditorSurfaceGraph {
    pub(super) fn new(run_intent: ControllerEditorSurfaceIntentRunner) -> Self {
        Self {
            roots: Mutex::new(BTreeMap::new()),
            terminal_ownership: Mutex::new(BTreeMap::new()),
            focus_owners: Mutex::new(BTreeMap::new()),
            navigation_mode: agent_doc_editor_surface::NavigationMode::default(),
            lane_reconcile: None,
            run_intent,
        }
    }

    /// The same graph publishing its live editor installations into the
    /// controller's navigation-lane reconcile trigger (`#ridernavp6gc`).
    pub(super) fn with_lane_reconcile(
        mut self,
        lane_reconcile: Arc<NavigationLaneReconcileGraph>,
    ) -> Self {
        self.lane_reconcile = Some(lane_reconcile);
        self
    }

    /// The editor installations with at least one live (unretired) surface
    /// on `project_root`, in every lane.
    fn live_installations(&self, project_root: &Path) -> BTreeSet<String> {
        self.roots
            .lock()
            .iter()
            .filter(|((root, _, _), entry)| root == project_root && !entry.retired)
            .filter_map(|((_, client_id, _), _)| {
                agent_doc_editor_surface::editor_installation(client_id).map(str::to_string)
            })
            .collect()
    }

    /// Publish the live installations to the lane reconcile trigger. Called
    /// with `roots` unlocked, whenever a surface joins or retires.
    fn publish_installation_liveness(&self, project_root: &Path) {
        let Some(lane_reconcile) = &self.lane_reconcile else {
            return;
        };
        if lane_reconcile.project_root() != project_root {
            return;
        }
        lane_reconcile.observe_live_installations(self.live_installations(project_root));
    }

    /// The same graph with an explicit navigation mode
    /// (`#ideriderindependentnav`), from `editor_navigation` in
    /// `.agent-doc/config.toml`. Per-installation lanes route each
    /// installation's layout to its own lane session (P2b).
    pub(super) fn with_navigation_mode(
        mut self,
        navigation_mode: agent_doc_editor_surface::NavigationMode,
    ) -> Self {
        self.navigation_mode = navigation_mode;
        self
    }

    pub(super) fn navigation_mode(&self) -> agent_doc_editor_surface::NavigationMode {
        self.navigation_mode
    }

    fn layout_owner_key(
        &self,
        project_root: &Path,
        client_id: &str,
    ) -> agent_doc_editor_surface::LayoutOwnerKey {
        agent_doc_editor_surface::LayoutOwnerKey::for_client(
            project_root,
            self.navigation_mode,
            client_id,
        )
    }

    /// Publish, per navigation lane of `project_root`, which installations
    /// still have a live surface on that lane, so a retired focus owner hands
    /// the lane's tmux surface back to the most recently focused live
    /// installation on the same lane (`#idefocusowner`). A live installation on
    /// another lane never inherits it.
    fn retain_live_installations(&self, project_root: &Path) {
        let mut live_by_key = BTreeMap::<
            agent_doc_editor_surface::LayoutOwnerKey,
            std::collections::BTreeSet<String>,
        >::new();
        for ((root, client_id, _), entry) in self.roots.lock().iter() {
            if root != project_root || entry.retired {
                continue;
            }
            if let Some(installation) = agent_doc_editor_surface::editor_installation(client_id) {
                live_by_key
                    .entry(self.layout_owner_key(project_root, client_id))
                    .or_default()
                    .insert(installation.to_string());
            }
        }
        let empty = std::collections::BTreeSet::new();
        for (key, owner) in self.focus_owners.lock().iter() {
            if key.root == project_root {
                owner.retain_live(live_by_key.get(key).unwrap_or(&empty));
            }
        }
        self.publish_installation_liveness(project_root);
    }

    /// The installation currently driving `project_root`'s shared lane.
    #[cfg(test)]
    fn focus_owner(&self, project_root: &Path) -> Option<String> {
        self.focus_owner_in(
            project_root,
            &agent_doc_editor_surface::NavigationLane::Shared,
        )
    }

    /// The installation currently driving one navigation lane of
    /// `project_root`.
    #[cfg(test)]
    fn focus_owner_in(
        &self,
        project_root: &Path,
        lane: &agent_doc_editor_surface::NavigationLane,
    ) -> Option<String> {
        self.focus_owners
            .lock()
            .get(&agent_doc_editor_surface::LayoutOwnerKey::new(
                project_root,
                lane.clone(),
            ))
            .and_then(|owner| owner.owner())
            .map(|owner| owner.installation)
    }

    /// [`Self::observe_classified`] reduced to the accepted verdict.
    #[cfg(test)]
    fn observe(
        &self,
        scope: &agent_doc_state_scope::ProcessScope,
        project_root: &Path,
        observation: EditorSurfaceObservation,
        tmux: Option<TmuxLayout>,
    ) -> (bool, SurfaceObservationReceipt) {
        let (rejection, receipt) = self.observe_classified(scope, project_root, observation, tmux);
        (rejection.is_none(), receipt)
    }

    /// [`Self::observe_monitored`] without the muted-endpoint alert.
    #[cfg(test)]
    fn observe_classified(
        &self,
        scope: &agent_doc_state_scope::ProcessScope,
        project_root: &Path,
        observation: EditorSurfaceObservation,
        tmux: Option<TmuxLayout>,
    ) -> (
        Option<SurfaceObservationRejection>,
        SurfaceObservationReceipt,
    ) {
        let (rejection, receipt, _) =
            self.observe_monitored(scope, project_root, observation, tmux);
        (rejection, receipt)
    }

    /// Fold one editor observation (`ControllerRecvObs` in
    /// `formal/tla/PassiveTmuxSyncRetireNet.tla`).
    ///
    /// `#tmuxautosyncretired`: a bare `accepted=false` could not tell a benign
    /// duplicate from an endpoint that was retired while its editor kept
    /// publishing, and only the latter mutes tab-switch auto-sync. The rejected
    /// receipt therefore names its fence, and a retired-endpoint rejection
    /// carries the re-registration directive (`reregister_above_generation`)
    /// a still-live editor acts on (`#surfaceretireformal`). The third value is
    /// the runtime monitor's alert: this endpoint just reached
    /// [`RETIRED_ENDPOINT_MUTE_THRESHOLD`] consecutive retired rejections.
    fn observe_monitored(
        &self,
        scope: &agent_doc_state_scope::ProcessScope,
        project_root: &Path,
        observation: EditorSurfaceObservation,
        tmux: Option<TmuxLayout>,
    ) -> (
        Option<SurfaceObservationRejection>,
        SurfaceObservationReceipt,
        Option<MutedLiveEndpoint>,
    ) {
        let key = (
            project_root.to_path_buf(),
            observation.client_id.clone(),
            observation.surface_id.clone(),
        );
        let mut roots = self.roots.lock();

        if let Some(current) = roots.get_mut(&key)
            && let Some(rejection) = SurfaceObservationRejection::classify(
                current.retired,
                current.generation,
                current.sequence,
                observation.generation,
                observation.sequence,
            )
        {
            let muted = current.retired_monitor.record(Some(rejection));
            let reregister_above_generation = (rejection
                == SurfaceObservationRejection::RetiredEndpoint)
                .then_some(current.generation);
            return (
                Some(rejection),
                SurfaceObservationReceipt {
                    intent: SurfaceIntent::Idle,
                    idle: true,
                    outcome: None,
                    error: None,
                    terminal_decision: SurfaceTerminalDecision::Stale,
                    deferred_to: None,
                    rejected: Some(rejection),
                    reregister_above_generation,
                },
                muted,
            );
        }

        // `#idefocusowner`: an accepted focus-lane fact moves ownership of the
        // shared tmux surface to its installation BEFORE the fact is folded, so
        // the observation that gained focus is the first one allowed to drive.
        let focus_owner = self
            .focus_owners
            .lock()
            .entry(self.layout_owner_key(project_root, &observation.client_id))
            .or_insert_with(|| agent_doc_editor_surface::InstallationFocusOwner::new_in(scope))
            .clone();
        focus_owner.observe(&observation.client_id, &observation.surface);

        let replace_generation = roots
            .get(&key)
            .is_some_and(|current| observation.generation > current.generation);
        if replace_generation && let Some(retired) = roots.remove(&key) {
            retired.state.stop(&retired.consequence);
        }

        let terminal_observation = SurfaceOwnershipObservation {
            source_id: observation.client_id.clone(),
            surface_id: observation.surface_id.clone(),
            generation: observation.generation,
            sequence: observation.sequence,
            authoritative_focus: observation.surface.focus_only,
            focused: observation.surface.focused.clone(),
            visible: observation.surface.visible.clone(),
        };
        let root = project_root.to_path_buf();
        let run_intent = Arc::clone(&self.run_intent);
        let authority = focus_owner.authority_for(&observation.client_id);
        let joined = !roots.contains_key(&key);
        let entry = roots.entry(key).or_insert_with(|| {
            let state = EditorSurfaceState::new_in_with_authority(scope, authority);
            let outcome = Arc::new(Mutex::new(None));
            let consequence = {
                let outcome = Arc::clone(&outcome);
                let root = root.clone();
                state.on_intent(move |intent| {
                    let result = run_intent(&root, intent).map_err(|error| format!("{error:#}"));
                    *outcome.lock() = Some(result);
                })
            };
            ControllerEditorSurfaceRoot {
                generation: observation.generation,
                sequence: 0,
                retired: false,
                retired_monitor: RetiredEndpointMonitor::default(),
                state,
                consequence,
                outcome,
            }
        });

        entry.generation = observation.generation;
        entry.sequence = observation.sequence;
        entry.retired_monitor.record(None);
        *entry.outcome.lock() = None;
        match tmux {
            Some(layout) => entry
                .state
                .observe_with_tmux(observation.surface, Some(layout)),
            None => entry.state.observe(observation.surface),
        }
        let intent = entry.state.intent();
        let deferred_to = entry.state.fold().deferred_to;
        let consequence = entry.outcome.lock().clone();
        drop(roots);
        if joined {
            self.publish_installation_liveness(project_root);
        }
        let (outcome, error) = match consequence {
            Some(Ok(output)) => (Some(output), None),
            Some(Err(message)) => (None, Some(message)),
            None => (None, None),
        };
        let terminal_decision = self
            .terminal_ownership
            .lock()
            .entry(project_root.to_path_buf())
            .or_default()
            .observe(terminal_observation);
        (
            None,
            SurfaceObservationReceipt {
                idle: intent.is_idle(),
                intent,
                outcome,
                error,
                terminal_decision,
                deferred_to,
                rejected: None,
                reregister_above_generation: None,
            },
            None,
        )
    }

    /// Publish the controller's actual tmux observation to every active editor
    /// client for a project (`#tmuxautosyncreactive`).
    ///
    /// Each lane's `pane_layout_effect_worker` now calls
    /// [`Self::observe_tmux_for_lane`]; this every-lane form is the shared-mode
    /// equivalent kept for tests. The worker calls it after it converges
    /// a structural effect so the surface graph's retained `tmux` `Source`
    /// refreshes without the editor socket request waiting for the survey. Each
    /// client's `EditorSurfaceState::observe_tmux` re-folds against its own
    /// editor surface, so a matching layout settles to `Idle` and a drifted one
    /// re-derives `Sync` — the decision lives in the graph, not the caller.
    #[cfg(test)]
    pub(super) fn observe_tmux_for_project(&self, project_root: &Path, tmux: Option<TmuxLayout>) {
        let roots = self.roots.lock();
        for ((root, _client_id, _surface_id), entry) in roots.iter() {
            if root == project_root && !entry.retired {
                entry.state.observe_tmux(tmux.clone());
            }
        }
    }

    /// Publish one navigation lane's actual tmux observation to the active
    /// editor clients of that lane only (`#ideriderindependentnav` P2b).
    ///
    /// Each lane's effect worker surveys its own session, so its layout is a
    /// fact about that lane: refolding another lane's clients against it would
    /// make them re-derive `Sync` toward a session they do not navigate. In
    /// shared mode every client is on the shared lane, so this is exactly
    /// [`Self::observe_tmux_for_project`].
    pub(super) fn observe_tmux_for_lane(
        &self,
        project_root: &Path,
        lane: &agent_doc_editor_surface::NavigationLane,
        tmux: Option<TmuxLayout>,
    ) {
        let roots = self.roots.lock();
        for ((root, client_id, _surface_id), entry) in roots.iter() {
            if root == project_root
                && !entry.retired
                && agent_doc_editor_surface::NavigationLane::for_client(
                    self.navigation_mode,
                    client_id,
                ) == *lane
            {
                entry.state.observe_tmux(tmux.clone());
            }
        }
    }

    /// The navigation lane `client_id` publishes into under this graph's mode.
    pub(super) fn navigation_lane_for_client(
        &self,
        client_id: &str,
    ) -> agent_doc_editor_surface::NavigationLane {
        agent_doc_editor_surface::NavigationLane::for_client(self.navigation_mode, client_id)
    }

    /// The retained surface `Source` of one `(client, surface)` endpoint, for
    /// a command that acts by reference to it (`surface_layout_reference_v1`).
    pub(super) fn retained_surface(
        &self,
        project_root: &Path,
        client_id: &str,
        surface_id: &str,
    ) -> Option<agent_doc_editor_surface::RetainedEditorSurface> {
        let roots = self.roots.lock();
        roots
            .get(&(
                project_root.to_path_buf(),
                client_id.to_string(),
                surface_id.to_string(),
            ))
            .map(|root| agent_doc_editor_surface::RetainedEditorSurface {
                surface: root.state.surface(),
                generation: root.generation,
                sequence: root.sequence,
                retired: root.retired,
            })
    }

    fn forget(&self, project_root: &Path, client_id: &str, generation: u64) -> bool {
        let mut roots = self.roots.lock();
        let mut retired_surfaces = Vec::new();
        let mut fenced = false;
        for ((root, retained_client_id, surface_id), current) in roots.iter_mut() {
            if root != project_root || retained_client_id != client_id {
                continue;
            }
            match retire_editor_surface_root(current, generation) {
                RootRetirement::Unchanged => {}
                RootRetirement::FenceRaised => fenced = true,
                RootRetirement::Retired {
                    registered_generation,
                } => {
                    fenced = true;
                    retired_surfaces.push((
                        retained_client_id.clone(),
                        surface_id.clone(),
                        registered_generation,
                    ));
                }
            }
        }
        drop(roots);
        if !retired_surfaces.is_empty() {
            let mut ownerships = self.terminal_ownership.lock();
            if let Some(ownership) = ownerships.get_mut(project_root) {
                for (source_id, surface_id, surface_generation) in &retired_surfaces {
                    ownership.retire(source_id, surface_id, *surface_generation);
                }
            }
            drop(ownerships);
            self.retain_live_installations(project_root);
        }
        fenced
    }

    fn forget_surface(
        &self,
        project_root: &Path,
        client_id: &str,
        surface_id: &str,
        generation: u64,
    ) -> (bool, SurfaceTerminalDecision) {
        let key = (
            project_root.to_path_buf(),
            client_id.to_string(),
            surface_id.to_string(),
        );
        let mut roots = self.roots.lock();
        let Some(current) = roots.get_mut(&key) else {
            return (false, SurfaceTerminalDecision::Stale);
        };
        let registered_generation = match retire_editor_surface_root(current, generation) {
            RootRetirement::Unchanged => return (false, SurfaceTerminalDecision::Stale),
            RootRetirement::FenceRaised => return (true, SurfaceTerminalDecision::Stale),
            RootRetirement::Retired {
                registered_generation,
            } => registered_generation,
        };
        drop(roots);
        let decision = self
            .terminal_ownership
            .lock()
            .entry(project_root.to_path_buf())
            .or_default()
            .retire(client_id, surface_id, registered_generation);
        self.retain_live_installations(project_root);
        (true, decision)
    }

    fn forget_client_family(&self, project_root: &Path, client_id: &str, generation: u64) -> usize {
        let Some(client_family) = editor_surface_client_family(client_id) else {
            return usize::from(self.forget(project_root, client_id, generation));
        };
        let mut roots = self.roots.lock();
        let mut forgotten = 0;
        let mut retired_surfaces = Vec::new();
        for ((root, retained_client_id, surface_id), current) in roots.iter_mut() {
            if root != project_root
                || !editor_surface_client_family(retained_client_id).is_some_and(
                    |retained_family| editor_surface_family_retires(client_family, retained_family),
                )
            {
                continue;
            }
            match retire_editor_surface_root(current, generation) {
                RootRetirement::Unchanged => {}
                // A root this family already retired at an older generation:
                // the fence moves up, but it was already counted as forgotten.
                RootRetirement::FenceRaised => {}
                RootRetirement::Retired {
                    registered_generation,
                } => {
                    retired_surfaces.push((
                        retained_client_id.clone(),
                        surface_id.clone(),
                        registered_generation,
                    ));
                    forgotten += 1;
                }
            }
        }
        drop(roots);
        if !retired_surfaces.is_empty() {
            let mut ownerships = self.terminal_ownership.lock();
            if let Some(ownership) = ownerships.get_mut(project_root) {
                for (source_id, surface_id, surface_generation) in retired_surfaces {
                    ownership.retire(&source_id, &surface_id, surface_generation);
                }
            }
            drop(ownerships);
            self.retain_live_installations(project_root);
        }
        forgotten
    }

    fn active_observation_generations(&self, project_root: &Path) -> Vec<(String, u64, u64)> {
        self.roots
            .lock()
            .iter()
            .filter(|((root, _, _), observation)| root == project_root && !observation.retired)
            .map(|((_, client_id, _), observation)| {
                (
                    client_id.clone(),
                    observation.generation,
                    observation.sequence,
                )
            })
            .collect()
    }
}
/// A CP-owned git commit (barrier + stage + commit + boundary reposition) can run
/// several seconds — well past the 5s default RPC timeout — so `commit_document`
/// gets a generous ceiling.
const CONTROLLER_COMMIT_DOCUMENT_TIMEOUT: Duration = Duration::from_secs(120);
/// Compact may include archive and commit effects after editor/disk state
/// converges; the initiating RPC only admits that work and may therefore span
/// archive construction without polling for an editor receipt.
const CONTROLLER_COMPACT_DOCUMENT_TIMEOUT: Duration = Duration::from_secs(300);
static EMBEDDED_NATIVE_HOST: AtomicBool = AtomicBool::new(false);
thread_local! {
    /// Controller runtime installed on the thread that owns the process-local
    /// relay hub.
    ///
    /// The embedded delivery-await path used to pass `None` into the rolling
    /// upgrade policy even though it was executing inside the controller. That
    /// made build-skewed editor listeners miss projection recovery without
    /// either side of the skew being replaced. Keep this weak and thread-local:
    /// the runtime owns the relay and must not be kept alive by a recovery
    /// callback, while test actors may replace it between threads.
    static LOCAL_CONTROLLER_RUNTIME:
        std::cell::RefCell<Option<std::sync::Weak<ControllerRuntime>>> =
        const { std::cell::RefCell::new(None) };
}
#[cfg(not(any(test, feature = "test-support")))]
const CONTROLLER_SYNC_TMUX_LAYOUT_TIMEOUT: Duration = Duration::from_secs(35);
#[cfg(any(test, feature = "test-support"))]
const CONTROLLER_SYNC_TMUX_LAYOUT_TIMEOUT: Duration = CONTROLLER_RPC_TIMEOUT;

/// Mark this process as a reloadable native-library host.
///
/// A JVM-hosted cdylib must not spawn a controller-lifetime child-reaper thread,
/// because that thread would pin the old generation across `dlclose`. Controller
/// launch instead goes through a short-lived external `agent-doc` helper.
pub fn mark_embedded_native_host() {
    EMBEDDED_NATIVE_HOST.store(true, Ordering::SeqCst);
}

pub(crate) fn connect(project_root: &Path) -> Result<interprocess::local_socket::Stream> {
    connect_path(&socket_path(project_root))
}

fn controller_model_pressure_now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0)
}

fn controller_model_pressure_jitter_secs(doc: &Path) -> u64 {
    let hash = agent_doc_hash::content_hash(&doc.to_string_lossy());
    u64::from_str_radix(hash.get(..2).unwrap_or("00"), 16).unwrap_or(0) % 8
}

fn log_controller_model_pressure_persist_deferred(doc: &Path, stage: &str, error: &anyhow::Error) {
    agent_doc_ops_log_io::log_op(
        doc,
        &format!(
            "controller_model_pressure_persist_deferred file={} stage={} error={}",
            doc.display(),
            stage,
            format!("{error:#}").replace('\n', "\\n"),
        ),
    );
}

fn read_controller_model_pressure_deadline(project_root: &Path) -> Result<Option<u64>> {
    let conn = agent_doc_sqlite::state_store::open_state_db(project_root)?;
    agent_doc_sqlite::state_store::load_project_runtime_state_from_db(
        &conn,
        CONTROLLER_MODEL_PRESSURE_STATE_KEY,
    )?
    .map(|raw| {
        raw.parse::<u64>()
            .context("invalid controller model pressure deadline in state.db")
    })
    .transpose()
}

fn record_controller_model_pressure(project_root: &Path, doc: &Path, source: &str, error: &str) {
    let conn = match agent_doc_sqlite::state_store::open_state_db_with_timeout(
        project_root,
        CONTROLLER_MODEL_PRESSURE_PERSIST_TIMEOUT,
    ) {
        Ok(conn) => conn,
        Err(err) => {
            log_controller_model_pressure_persist_deferred(doc, "open", &err);
            return;
        }
    };
    let now = controller_model_pressure_now_secs();
    let deadline = now.saturating_add(CONTROLLER_MODEL_PRESSURE_COOLDOWN.as_secs());
    let existing_deadline = agent_doc_sqlite::state_store::load_project_runtime_state_from_db(
        &conn,
        CONTROLLER_MODEL_PRESSURE_STATE_KEY,
    )
    .ok()
    .flatten()
    .and_then(|raw| raw.parse::<u64>().ok())
    .unwrap_or(0);
    let episode_started = existing_deadline <= now;
    // Do not rewrite/log the same project-wide marker on every foreground
    // retry. Refresh only after half its cooldown has elapsed.
    let refresh_after = now.saturating_add(CONTROLLER_MODEL_PRESSURE_COOLDOWN.as_secs() / 2);
    if existing_deadline > refresh_after {
        return;
    }
    let retained_deadline =
        match agent_doc_sqlite::state_store::upsert_max_u64_project_runtime_state_in_db(
            &conn,
            CONTROLLER_MODEL_PRESSURE_STATE_KEY,
            deadline,
            now.saturating_mul(1000),
        ) {
            Ok(retained) => retained,
            Err(err) => {
                log_controller_model_pressure_persist_deferred(doc, "upsert", &err);
                return;
            }
        };
    // The retained deadline may refresh during one continuous pressure episode,
    // but the episode itself is the operator-relevant event. Logging every
    // refresh made this self-limiting backpressure recorder dominate ops.log.
    if episode_started {
        agent_doc_ops_log_io::log_op(
            doc,
            &format!(
                "controller_model_pressure_recorded file={} source={} cooldown_secs={} deadline={} error={}",
                doc.display(),
                source,
                CONTROLLER_MODEL_PRESSURE_COOLDOWN.as_secs(),
                retained_deadline,
                error.replace('\n', "\\n")
            ),
        );
    }
}

fn clear_expired_controller_model_pressure(project_root: &Path) {
    let deadline = match read_controller_model_pressure_deadline(project_root) {
        Ok(Some(deadline)) => deadline,
        Ok(None) => return,
        Err(err) => {
            eprintln!(
                "[agent-doc] failed to read controller model pressure from state.db: {err:#}"
            );
            return;
        }
    };
    if controller_model_pressure_now_secs() < deadline {
        return;
    }
    let result = agent_doc_sqlite::state_store::open_state_db(project_root).and_then(|conn| {
        agent_doc_sqlite::state_store::clear_project_runtime_state_in_db(
            &conn,
            CONTROLLER_MODEL_PRESSURE_STATE_KEY,
        )
    });
    if let Err(err) = result {
        eprintln!("[agent-doc] failed to clear controller model pressure from state.db: {err:#}");
    }
}

/// Project-wide idle-observation cooldown. A single failed controller-model
/// read quiets every supervisor in the project; foreground write/finalize RPCs
/// deliberately do not consult this gate.
pub fn controller_model_pressure_cooldown_active_for_doc(doc: &Path) -> bool {
    let Some(project_root) = agent_doc_project_root_io::project_root_containing(doc) else {
        return false;
    };
    let deadline = match read_controller_model_pressure_deadline(&project_root) {
        Ok(Some(deadline)) => deadline,
        Ok(None) => return false,
        Err(err) => {
            eprintln!("[agent-doc] controller model pressure state unavailable: {err:#}");
            return true;
        }
    };
    controller_model_pressure_now_secs()
        < deadline.saturating_add(controller_model_pressure_jitter_secs(doc))
}

/// `#testisolationleaks`: a test process may not connect to a live controller
/// socket outside its runtime scope. Only a socket that exists is checked: a
/// path with no listener cannot reach a live runtime, and fixtures probe
/// fabricated paths (`#ctrlsockpathtoolong`).
fn guard_test_controller_socket(path: &Path) {
    if path.exists() {
        agent_doc_fs::guard_test_runtime_target(path, "a project controller socket connect");
    }
}

pub(crate) fn connect_path(path: &Path) -> Result<interprocess::local_socket::Stream> {
    // Without this the OS reports a bare ENOENT/EINVAL, which is
    // indistinguishable from "the controller has not started yet" — so callers
    // retry a path that can never work (`#ctrlsockpathtoolong`).
    if let Some(reason) = agent_doc_controller::paths::resolved_socket_path_rejection(path) {
        anyhow::bail!(reason);
    }
    guard_test_controller_socket(path);
    let name = path.to_fs_name::<GenericFilePath>()?;
    interprocess::local_socket::ConnectOptions::new()
        .name(name)
        .connect_sync()
        .context("failed to connect to project controller")
}

async fn connect_path_async(path: &Path) -> Result<interprocess::local_socket::tokio::Stream> {
    if let Some(reason) = agent_doc_controller::paths::resolved_socket_path_rejection(path) {
        anyhow::bail!(reason);
    }
    guard_test_controller_socket(path);
    let name = path.to_fs_name::<GenericFilePath>()?;
    interprocess::local_socket::ConnectOptions::new()
        .name(name)
        .connect_tokio()
        .await
        .context("failed to connect asynchronously to project controller")
}

pub(crate) fn request(project_root: &Path, command: &str) -> Result<String> {
    request_path(&socket_path(project_root), command)
}

pub(crate) fn request_path(path: &Path, command: &str) -> Result<String> {
    request_path_json(path, serde_json::json!({ "command": command }))
}

pub(crate) fn request_with_reason(
    project_root: &Path,
    command: &str,
    reason: &str,
) -> Result<String> {
    request_path_with_reason(&socket_path(project_root), command, reason)
}

pub(crate) fn request_path_with_reason(path: &Path, command: &str, reason: &str) -> Result<String> {
    request_path_json(
        path,
        serde_json::json!({ "command": command, "reason": reason }),
    )
}

thread_local! {
    static CONTROLLER_ROUND_TRIPS: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
}

/// `#netadv5` RTT budget probe: serial controller-socket round trips issued by
/// the calling thread (every request written and awaited through either
/// request funnel). Hot-path tests diff this around one operation.
pub fn controller_round_trips_on_this_thread() -> u64 {
    CONTROLLER_ROUND_TRIPS.with(std::cell::Cell::get)
}

fn note_controller_round_trip() {
    CONTROLLER_ROUND_TRIPS.with(|count| count.set(count.get() + 1));
}

fn request_path_json(path: &Path, request_value: serde_json::Value) -> Result<String> {
    note_controller_round_trip();
    // `#preflightdeadline`: inside a preflight admission, no RPC may wait past
    // the admission deadline, and none may start once it is spent.
    let timeout = agent_doc_debounce::admission_deadline::clamp_or_exhausted(
        "project_controller_rpc",
        controller_response_timeout(path, CONTROLLER_RPC_TIMEOUT),
    )?;
    let stream = connect_path(path)?;
    stream
        .set_recv_timeout(Some(timeout))
        .context("failed to set project controller response timeout")?;
    let (reader_half, mut writer_half) = stream.split();
    let mut request = serde_json::to_string(&request_value)?;
    request.push('\n');
    writer_half.write_all(request.as_bytes())?;
    writer_half.flush()?;

    let mut reader = BufReader::new(reader_half);
    let mut response = String::new();
    read_controller_response_line_with_timeout(&mut reader, &mut response, timeout)?;
    Ok(response.trim().to_string())
}

/// The response deadline for one controller RPC on `socket`.
///
/// `#remainingwallclock`: the test-mode `CONTROLLER_RPC_TIMEOUT` (2s) exists so a
/// genuinely absent or silent controller fails fast. A socket served by an
/// in-process test state actor ([`start_state_actor_for_tests`]) is known to be
/// live, so a slow answer there is host load, not absence, and the deadline is
/// only a hang ceiling. Without this, a full `make check` at load average
/// 60-100 failed fixtures with `timed out after 2.0s waiting for project
/// controller response` while they asserted nothing about timing.
fn controller_response_timeout(socket: &Path, timeout: Duration) -> Duration {
    agent_doc_state_wire::actor_response_timeout(socket, timeout)
}

/// Test-support view of [`controller_response_timeout`].
#[cfg(feature = "test-support")]
pub fn controller_response_timeout_for_tests(socket: &Path, timeout: Duration) -> Duration {
    controller_response_timeout(socket, timeout)
}

/// Wait up to `timeout` for a client to be pending on a nonblocking
/// controller `listener` (`#flakyreceipthelpers` accept wake).
///
/// The serve loops accept nonblockingly so their idle tick can run maintenance,
/// and used to `sleep(CONNECT_POLL)` after every `WouldBlock`. A client that
/// connected during that sleep waited for it to end, so every controller RPC
/// paid up to 50ms of accept latency -- twice, since `connect_or_launch` probes
/// `status` on its own connection before the request. A short-lived CLI issues
/// hundreds of RPCs: a four-invocation `finalize_integration` test spent most of
/// its 64s in these waits (closeout phases measured as exact multiples of
/// ~100ms). Polling the listener fd keeps the tick's cadence while returning as
/// soon as a client is pending. A listener in an error state (or a platform
/// without `poll`) falls back to the plain sleep, so this can never spin.
fn wait_for_pending_controller_client(
    listener: &interprocess::local_socket::Listener,
    timeout: Duration,
) {
    #[cfg(unix)]
    {
        use std::os::fd::{AsFd, AsRawFd};
        let interprocess::local_socket::Listener::UdSocket(inner) = listener;
        let mut pollfd = libc::pollfd {
            fd: inner.as_fd().as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        let timeout_ms = i32::try_from(timeout.as_millis()).unwrap_or(i32::MAX);
        // SAFETY: one valid, initialized pollfd for a descriptor `listener`
        // keeps open for the duration of the call.
        let ready = unsafe { libc::poll(&mut pollfd, 1, timeout_ms) };
        let failed = pollfd.revents & (libc::POLLERR | libc::POLLHUP | libc::POLLNVAL) != 0;
        if ready >= 0 && !failed {
            return;
        }
    }
    std::thread::sleep(timeout);
}

/// How long until the serve loop's idle maintenance is due again
/// (`#flakyreceipthelpers` accept wake): `None` when it is due now. Waking on a pending
/// client must not make maintenance run once per connection under a burst, so
/// it keeps the fixed `CONNECT_POLL` cadence the sleep used to give it.
fn controller_idle_tick_remaining(last_tick: Option<Instant>, now: Instant) -> Option<Duration> {
    let elapsed = now.duration_since(last_tick?);
    (elapsed < CONNECT_POLL).then(|| CONNECT_POLL - elapsed)
}

/// Sockets currently served by an in-process test state actor. The registry
/// lives in `agent-doc-state-wire` so its direct actor transport applies the
/// same live-peer deadline as this RPC client.
#[cfg(feature = "test-support")]
use agent_doc_state_wire::warm_test_actor_sockets;

/// Opt in to cold-launching a real detached `agent-doc controller serve`
/// process for `project_root` from a workspace test harness, lib or
/// integration (`#coldlaunchflakes`, `#integrationtesttargets`).
///
/// Without this marker a test harness never starts a controller process:
/// [`connect_or_launch`] serves the root from this process's warm state actor
/// ([`ensure_state_actor_for_tests`]) instead, and any other launch path
/// panics. Only a test whose subject IS the process launch (spawn, socket
/// publication, handoff to a replacement process) should call this.
#[cfg(feature = "test-support")]
pub fn allow_cold_controller_launch_for_tests(project_root: &Path) {
    cold_launch_test_policy::allow(project_root);
}

/// `#coldlaunchflakes`: which lib-test launches may start a real controller
/// process (see the module docs).
#[cfg(feature = "test-support")]
#[path = "cold_launch_test_policy.rs"]
mod cold_launch_test_policy;

/// The env opt-in an integration test sets on the `agent-doc` command it spawns
/// when that command may cold-launch a real controller (`#integrationtesttargets`).
#[cfg(feature = "test-support")]
pub use cold_launch_test_policy::TEST_CONTROLLER_LAUNCH_REASON_ENV;

/// `#coldlaunchflakes` / `#integrationtesttargets` guard: a test harness may
/// only spawn a controller process after
/// [`allow_cold_controller_launch_for_tests`], and a process a test harness
/// spawned (the CLI an integration test drives) only when the test set
/// `AGENT_DOC_TEST_CONTROLLER_LAUNCH_REASON`. [`connect_or_launch`] already
/// serves unopted harnesses in-process, so reaching a spawn here means a new
/// launch path (handoff, recycle, helper) or a new target would reintroduce
/// the process-startup race; fail the test that took it instead.
fn refuse_unopted_test_controller_launch(project_root: &Path) {
    #[cfg(feature = "test-support")]
    if let Some(reason) = cold_launch_test_policy::refused_test_launch(project_root) {
        panic!(
            "refusing a controller launch for {} (#coldlaunchflakes #integrationtesttargets): {reason}",
            project_root.display()
        );
    }
    let _ = project_root;
}

fn read_controller_response_line_with_timeout<R: BufRead>(
    reader: &mut R,
    response: &mut String,
    timeout: Duration,
) -> Result<()> {
    match reader.read_line(response) {
        Ok(0) => anyhow::bail!("project controller closed connection without a response"),
        Ok(_) => Ok(()),
        Err(err) if is_timeout_error(&err) => Err(std::io::Error::new(
            ErrorKind::TimedOut,
            format!(
                "timed out after {:.1}s waiting for project controller response",
                timeout.as_secs_f32()
            ),
        )
        .into()),
        Err(err) => Err(err).context("failed to read project controller response"),
    }
}

fn controller_request_deadline_exceeded(error: &anyhow::Error) -> bool {
    error.chain().any(|cause| {
        cause
            .downcast_ref::<std::io::Error>()
            .is_some_and(is_timeout_error)
    })
}

/// Retry one idempotent state-event publication after the controller receive
/// deadline expires.
///
/// State events carry stable event ids and the controller deduplicates them at
/// ingress, so a response lost after apply is safe to re-submit. This is a
/// single boundary retry, not polling: a second expiry is returned to the
/// caller with both attempts recorded in the error chain.
fn retry_state_event_deadline<T>(
    retry_log_path: &Path,
    mut attempt: impl FnMut() -> Result<T>,
) -> Result<T> {
    match attempt() {
        Err(first) if controller_request_deadline_exceeded(&first) => {
            agent_doc_ops_log_io::log_op(
                retry_log_path,
                &format!(
                    "controller_state_event_deadline_retry attempt=2 first_error={}",
                    compact_controller_error(&first)
                ),
            );
            attempt().with_context(|| {
                format!(
                    "idempotent state-event retry failed after controller deadline: {}",
                    compact_controller_error(&first)
                )
            })
        }
        result => result,
    }
}

/// Whether `err` is a controller transport drop — the connection went away
/// before the controller answered — rather than a refusal the controller
/// authored.
///
/// A drop says nothing about the request's merits: the usual cause is a
/// controller that was recycled or replaced by a newer build mid-request. Every
/// caller that can afford to re-ask should, which is why this is public: the
/// preflight admission hook classifies with the same predicate rather than
/// re-spelling the message (`#admissiontransportretry`).
pub fn controller_transport_drop_is_retryable(err: &anyhow::Error) -> bool {
    if err.chain().any(|cause| {
        cause.downcast_ref::<std::io::Error>().is_some_and(|io| {
            matches!(
                io.kind(),
                ErrorKind::ConnectionReset
                    | ErrorKind::ConnectionAborted
                    | ErrorKind::BrokenPipe
                    | ErrorKind::UnexpectedEof
            )
        })
    }) {
        return true;
    }
    format!("{err:#}").contains("project controller closed connection without a response")
}

fn compact_controller_error(err: &anyhow::Error) -> String {
    format!("{err:#}")
        .replace('\n', " | ")
        .chars()
        .take(240)
        .collect()
}

fn retry_controller_transport_drop<T>(
    retry_log_path: &Path,
    command: &str,
    mut request_once: impl FnMut() -> Result<T>,
) -> Result<T> {
    match request_once() {
        Err(err) if controller_transport_drop_is_retryable(&err) => {
            let detail = compact_controller_error(&err);
            agent_doc_ops_log_io::log_op(
                retry_log_path,
                &format!(
                    "controller_rpc_transport_retry command={} reason=stale_or_recycled_controller detail={}",
                    command, detail
                ),
            );
            request_once()
        }
        other => other,
    }
}

/// (`#handoffrefusalretry`) How long a client waits out a controller handoff
/// before surfacing a not-authoritative refusal, and how often it re-asks.
///
/// A handoff promotes (or the replacement self-reaps) in well under a second in
/// the normal case. The budget is NOT sized for that case: it is derived from
/// the handoff's own bound. One self-handoff attempt waits up to
/// [`HANDOFF_CONNECT_WAIT`] for its successor before aborting (rolling the
/// predecessor back) and retrying, so the window a refusal can land in is
/// `attempts x HANDOFF_CONNECT_WAIT`.
///
/// GH #122: an operator recycle on btakita-dev 2026-10-03 18:32:35 timed out
/// its successor three times and promoted on the fourth attempt — a 141s
/// `Preparing` window — while the old fixed 10s budget exhausted four times
/// without ever settling. The budget covers [`CONTROLLER_HANDOFF_SETTLE_ATTEMPTS`]
/// full attempts, so it still bounds a handoff that never promotes.
const CONTROLLER_HANDOFF_SETTLE_ATTEMPTS: u32 = 6;
const CONTROLLER_HANDOFF_SETTLE_BUDGET: Duration =
    HANDOFF_CONNECT_WAIT.saturating_mul(CONTROLLER_HANDOFF_SETTLE_ATTEMPTS);
const CONTROLLER_HANDOFF_SETTLE_INTERVAL: Duration = Duration::from_millis(200);

/// (`#handoffrefusalretry`) Did the controller refuse because it is not yet
/// authoritative — rather than fail?
///
/// Every `controller not authoritative` refusal bails at the top of its handler,
/// before touching pane state, the CRDT, or the dispatch record, so the request
/// provably did nothing. And the state it refused from is transient by
/// construction: a `Preparing` generation either promotes to `Stable` or is
/// reaped by the handoff watchdog. The refusal is therefore a "not yet", and
/// re-issuing it against the promoted generation is the whole recovery.
fn controller_handoff_refusal_is_retryable(err: &anyhow::Error) -> bool {
    format!("{err:#}").contains("controller not authoritative")
}

/// Pure retry policy: the delay before attempt `attempt` (1-based) of a request
/// that has now been refused `attempt` times, or `None` once the budget is spent.
fn controller_handoff_retry_delay(
    attempt: usize,
    elapsed: Duration,
    budget: Duration,
    interval: Duration,
) -> Option<Duration> {
    if attempt == 0 || elapsed >= budget {
        return None;
    }
    Some(interval.min(budget.saturating_sub(elapsed)))
}

/// (`#handoffrefusalretry`) Re-issue a request that a mid-handoff controller
/// refused, until one generation answers it or the settle budget is spent.
///
/// Reported live 2026-09-11 against `src/haiven-dev/tasks/docs.md`: a `make
/// install` recycled every live controller, churning that project through
/// controller generations 1176 → 1178 inside 24 seconds, and a "Run Agent Doc"
/// layout observation that landed in the window surfaced the raw
/// `pane layout observation refused: controller not authoritative
/// (handoff_state=Preparing)` to the operator — a failure message for a
/// condition that cleared on its own a moment later. Each attempt reconnects, so
/// the retry reaches the newly promoted generation rather than re-asking the
/// process that already said no.
fn retry_controller_handoff_refusal<T>(
    retry_log_path: &Path,
    command: &str,
    budget: Duration,
    interval: Duration,
    mut sleep: impl FnMut(Duration),
    mut request_once: impl FnMut() -> Result<T>,
) -> Result<T> {
    let started = Instant::now();
    let mut refusals = 0usize;
    loop {
        match request_once() {
            Err(err) if controller_handoff_refusal_is_retryable(&err) => {
                refusals += 1;
                let Some(delay) =
                    controller_handoff_retry_delay(refusals, started.elapsed(), budget, interval)
                else {
                    agent_doc_ops_log_io::log_op(
                        retry_log_path,
                        &format!(
                            "controller_rpc_handoff_retry_exhausted command={} refusals={} budget_ms={} detail={}",
                            command,
                            refusals,
                            budget.as_millis(),
                            compact_controller_error(&err)
                        ),
                    );
                    return Err(err);
                };
                if refusals == 1 {
                    agent_doc_ops_log_io::log_op(
                        retry_log_path,
                        &format!(
                            "controller_rpc_handoff_retry command={} reason=controller_not_authoritative detail={}",
                            command,
                            compact_controller_error(&err)
                        ),
                    );
                }
                sleep(delay);
            }
            other => {
                if refusals > 0 && other.is_ok() {
                    agent_doc_ops_log_io::log_op(
                        retry_log_path,
                        &format!(
                            "controller_rpc_handoff_retry_settled command={} refusals={} waited_ms={}",
                            command,
                            refusals,
                            started.elapsed().as_millis()
                        ),
                    );
                }
                return other;
            }
        }
    }
}

pub(crate) fn request_controller<T: DeserializeOwned>(
    project_root: &Path,
    request: ControllerRequest,
) -> Result<T> {
    request_controller_with_timeout(project_root, request, CONTROLLER_RPC_TIMEOUT)
}

pub(super) fn document_turn_authority_channel(document_hash: &str) -> String {
    format!("{DOCUMENT_AUTHORITY_STATE_CHANNEL_PREFIX}{document_hash}")
}

fn document_delivery_wake_channel(document_hash: &str) -> String {
    format!("{DOCUMENT_DELIVERY_WAKE_STATE_CHANNEL_PREFIX}{document_hash}")
}

fn operator_clear_wake_channel(document_hash: &str) -> String {
    format!("{OPERATOR_CLEAR_WAKE_STATE_CHANNEL_PREFIX}{document_hash}")
}

/// Observe the controller's Lazily document-turn authority projection over one
/// retained socket.
///
/// The client writes one subscription declaration. The controller then pushes a
/// frame whenever the Computed changes. `keep_open` supplies editor membership,
/// so closing a tab drops the stream without waiting for a heartbeat.
#[derive(Debug, Default)]
struct DocumentTurnAuthorityReconnectGuard {
    cursor: Option<ControllerStatePlaneCursor>,
    advanced_on_connection: bool,
    consecutive_stalled_disconnects: u8,
}

impl DocumentTurnAuthorityReconnectGuard {
    fn begin_connection(&mut self) {
        self.advanced_on_connection = false;
    }

    fn observe(&mut self, frame: &DocumentTurnAuthorityStreamFrame) -> bool {
        let next = ControllerStatePlaneCursor {
            controller_generation: frame.controller_generation,
            plane_version: frame.plane_version,
        };
        let advanced = match self.cursor {
            None => true,
            Some(current) if next.controller_generation != current.controller_generation => true,
            Some(current) => next.plane_version > current.plane_version,
        };
        if advanced {
            self.cursor = Some(next);
            self.advanced_on_connection = true;
            self.consecutive_stalled_disconnects = 0;
        }
        advanced
    }

    /// Permit one immediate compatibility reconnect when a stale controller
    /// closes a subscription without advancing its reactive cursor. A second
    /// identical close is proof that no dependency changed; stop the task
    /// instead of turning unavailable authority into a CPU-bound poll loop.
    fn should_reconnect_after_disconnect(&mut self) -> bool {
        if self.advanced_on_connection {
            self.consecutive_stalled_disconnects = 0;
            return true;
        }
        self.consecutive_stalled_disconnects =
            self.consecutive_stalled_disconnects.saturating_add(1);
        self.consecutive_stalled_disconnects <= 1
    }
}

/// Editor-facing wire projection for the retained document-turn stream.
///
/// State-plane snapshots remain the controller's internal transport. Editors
/// consume this typed projection directly so they never need to reconstruct a
/// Lazily envelope or issue a turn-state request/ack pair.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct DocumentTurnAuthorityStreamFrame {
    pub controller_generation: u64,
    pub plane_version: u64,
    pub timed_out: bool,
    pub projection: Option<agent_doc_turn::cp_projection::TurnProjection>,
}

fn document_turn_authority_stream_request(
    file: &Path,
    channel: &str,
    cursor: Option<ControllerStatePlaneCursor>,
) -> Result<(ControllerRequest, String)> {
    let invocation = ControllerStatePlaneSubscribeInvocation {
        channel: channel.to_string(),
        after_controller_generation: cursor.map(|value| value.controller_generation),
        after_version: cursor.map(|value| value.plane_version).unwrap_or(0),
        timeout_ms: STATE_PLANE_SUBSCRIBE_MAX.as_millis() as u64,
        client_id: None,
    };
    let request = ControllerRequest {
        command: "document_turn_authority_stream".to_string(),
        file: Some(file.to_path_buf()),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("native_editor_authority".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&invocation)?),
        sequence: None,
    };
    let mut request_value = serde_json::to_value(&request)?;
    if let Some(object) = request_value.as_object_mut() {
        object.insert(
            "binary_version".to_string(),
            serde_json::Value::String(identity_version()),
        );
    }
    let mut raw = serde_json::to_string(&request_value)?;
    raw.push('\n');
    Ok((request, raw))
}

pub async fn observe_document_turn_authority_stream(
    project_root: &Path,
    file: &Path,
    mut observe: impl FnMut(agent_doc_turn::cp_projection::TurnProjection) + Send,
    mut membership: tokio::sync::watch::Receiver<bool>,
) -> Result<()> {
    let authority_root = agent_doc_project_root_io::project_root_containing(file)
        .unwrap_or_else(|| project_root.to_path_buf());
    let document_hash = agent_doc_hash::document_id_for_path(file);
    let channel = document_turn_authority_channel(&document_hash);
    let mut reconnect = DocumentTurnAuthorityReconnectGuard::default();

    while *membership.borrow() {
        let (request, raw) =
            document_turn_authority_stream_request(file, &channel, reconnect.cursor)?;
        // Editor authority observation is passive. A missing controller means
        // authority is temporarily unavailable; it must never make the editor
        // process bootstrap controller state (and therefore SQLite).
        let stream = connect_path_async(&socket_path(&authority_root)).await?;
        reconnect.begin_connection();
        let (reader_half, mut writer_half) = tokio::io::split(stream);
        if let Err(error) = writer_half.write_all(raw.as_bytes()).await {
            if document_authority_transport_interrupted(&error) {
                if reconnect.should_reconnect_after_disconnect() {
                    continue;
                }
                anyhow::bail!(
                    "document-authority stream repeatedly disconnected before its reactive cursor advanced"
                );
            }
            return Err(error).context("write document-authority stream declaration");
        }
        if let Err(error) = writer_half.flush().await {
            if document_authority_transport_interrupted(&error) {
                if reconnect.should_reconnect_after_disconnect() {
                    continue;
                }
                anyhow::bail!(
                    "document-authority stream repeatedly disconnected before its reactive cursor advanced"
                );
            }
            return Err(error).context("flush document-authority stream declaration");
        }

        let mut reader = tokio::io::BufReader::new(reader_half);
        let mut response = String::new();
        loop {
            response.clear();
            tokio::select! {
                membership_result = membership.changed() => {
                    if membership_result.is_err() || !*membership.borrow() {
                        return Ok(());
                    }
                }
                result = reader.read_line(&mut response) => {
                    match result {
                        Ok(0) => break,
                        Ok(_) => {}
                        Err(error) if document_authority_transport_interrupted(&error) => break,
                        Err(error) => {
                        return Err(error).context("read document-authority stream frame");
                        }
                    }
                }
            }
            let frame: DocumentTurnAuthorityStreamFrame =
                decode_controller_response(&authority_root, &request, response.trim())?;
            if reconnect.observe(&frame)
                && let Some(projection) = frame.projection
            {
                observe(projection);
            }
        }
        if !reconnect.should_reconnect_after_disconnect() {
            anyhow::bail!(
                "document-authority stream repeatedly closed without advancing its reactive cursor"
            );
        }
    }
    Ok(())
}

fn document_authority_transport_interrupted(error: &std::io::Error) -> bool {
    matches!(
        error.kind(),
        ErrorKind::BrokenPipe
            | ErrorKind::ConnectionAborted
            | ErrorKind::ConnectionReset
            | ErrorKind::NotConnected
            | ErrorKind::UnexpectedEof
    )
}

