#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ControllerStatePlaneCursor {
    pub controller_generation: u64,
    pub plane_version: u64,
}

/// Await a changed retained CRDT delivery frontier for one document. The
/// controller parks this request on the document-scoped Lazily state channel;
/// an idle supervisor therefore consumes no document/controller work while the
/// frontier is stable.
pub fn subscribe_document_delivery_wakes_for_file(
    file: &Path,
    after: Option<ControllerStatePlaneCursor>,
    timeout: Duration,
) -> Result<DocumentDeliveryWakeSubscription> {
    let project_root = agent_doc_project_root_io::project_root_containing(file)
        .with_context(|| format!("no project root found for {}", file.display()))?;
    let canonical = file.canonicalize().unwrap_or_else(|_| file.to_path_buf());
    let document_hash = agent_doc_hash::document_id_for_path(&canonical);
    let channel = document_delivery_wake_channel(&document_hash);
    let timeout = timeout.min(STATE_PLANE_SUBSCRIBE_MAX);
    let invocation = ControllerStatePlaneSubscribeInvocation {
        channel: channel.clone(),
        after_controller_generation: after.map(|cursor| cursor.controller_generation),
        after_version: after.map(|cursor| cursor.plane_version).unwrap_or(0),
        timeout_ms: timeout.as_millis().min(u64::MAX as u128) as u64,
        client_id: None,
    };
    let request = ControllerRequest {
        command: "state_plane_subscribe".to_string(),
        file: Some(file.to_path_buf()),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("idle_watch_document_delivery_subscription".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&invocation)?),
        sequence: None,
    };
    let subscription: ControllerStatePlaneSubscription = request_controller_with_timeout(
        &project_root,
        request,
        timeout.saturating_add(Duration::from_secs(2)),
    )?;
    let projection = subscription.frames.iter().rev().find_map(|frame| {
        let Ok(message) = serde_json::from_str::<lazily::IpcMessage>(&frame.message_json) else {
            return None;
        };
        let Ok(payload) =
            state_plane_snapshot_payload(&message, &channel, DOCUMENT_DELIVERY_WAKE_TYPE_TAG)
        else {
            return None;
        };
        serde_json::from_slice::<DocumentDeliveryWakeProjection>(&payload)
            .ok()
            .filter(|wake| wake.document_hash == document_hash)
    });
    Ok(DocumentDeliveryWakeSubscription {
        controller_generation: subscription.controller_generation,
        latest_version: subscription.latest_version,
        timed_out: subscription.timed_out,
        changed: projection.is_some(),
        content_hash: projection
            .as_ref()
            .and_then(|projection| projection.content_hash.clone()),
        visible_delivery_projected: projection
            .is_some_and(|projection| projection.visible_delivery_projected),
    })
}

/// Await a queued (deferred) operator clear for one document
/// (`#idleclearrestart`). A Ready, quiescent supervisor idle watch re-derives
/// nothing until a document revision or delivery edge, and recording a deferred
/// clear changes neither, so without this edge the clear queued behind a
/// route-dispatched (actor never moves) or abandoned turn sat until the next
/// document edit. The controller publishes one frame per deferral on a
/// document-scoped Lazily state channel; the watch parks on it.
pub fn subscribe_operator_clear_wakes_for_file(
    file: &Path,
    after: Option<ControllerStatePlaneCursor>,
    timeout: Duration,
) -> Result<OperatorClearWakeSubscription> {
    let project_root = agent_doc_project_root_io::project_root_containing(file)
        .with_context(|| format!("no project root found for {}", file.display()))?;
    let canonical = file.canonicalize().unwrap_or_else(|_| file.to_path_buf());
    let document_hash = agent_doc_hash::document_id_for_path(&canonical);
    let channel = operator_clear_wake_channel(&document_hash);
    let timeout = timeout.min(STATE_PLANE_SUBSCRIBE_MAX);
    let invocation = ControllerStatePlaneSubscribeInvocation {
        channel: channel.clone(),
        after_controller_generation: after.map(|cursor| cursor.controller_generation),
        after_version: after.map(|cursor| cursor.plane_version).unwrap_or(0),
        timeout_ms: timeout.as_millis().min(u64::MAX as u128) as u64,
        client_id: None,
    };
    let request = ControllerRequest {
        command: "state_plane_subscribe".to_string(),
        file: Some(file.to_path_buf()),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("idle_watch_operator_clear_subscription".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&invocation)?),
        sequence: None,
    };
    let subscription: ControllerStatePlaneSubscription = request_controller_with_timeout(
        &project_root,
        request,
        timeout.saturating_add(Duration::from_secs(2)),
    )?;
    let projection = subscription.frames.iter().rev().find_map(|frame| {
        let message = serde_json::from_str::<lazily::IpcMessage>(&frame.message_json).ok()?;
        let payload =
            state_plane_snapshot_payload(&message, &channel, OPERATOR_CLEAR_WAKE_TYPE_TAG).ok()?;
        serde_json::from_slice::<OperatorClearWakeProjection>(&payload)
            .ok()
            .filter(|wake| wake.document_hash == document_hash)
    });
    Ok(OperatorClearWakeSubscription {
        controller_generation: subscription.controller_generation,
        latest_version: subscription.latest_version,
        timed_out: subscription.timed_out,
        changed: projection.is_some(),
        clear_epoch: projection.map(|projection| projection.clear_epoch),
    })
}

/// Await controller-published captured-finalize state edges. The RPC is only a
/// long-poll byte transport for the Lazily state plane; callers do not
/// manufacture convergence by repeatedly invoking finalize/session-check.
pub fn subscribe_captured_finalize_wakes_for_file(
    file: &Path,
    after: Option<ControllerStatePlaneCursor>,
    timeout: Duration,
) -> Result<CapturedFinalizeWakeSubscription> {
    let project_root = agent_doc_project_root_io::project_root_containing(file)
        .with_context(|| format!("no project root found for {}", file.display()))?;
    let timeout = timeout.min(STATE_PLANE_SUBSCRIBE_MAX);
    let invocation = ControllerStatePlaneSubscribeInvocation {
        channel: CAPTURED_FINALIZE_WAKE_STATE_CHANNEL.to_string(),
        after_controller_generation: after.map(|cursor| cursor.controller_generation),
        after_version: after.map(|cursor| cursor.plane_version).unwrap_or(0),
        timeout_ms: timeout.as_millis().min(u64::MAX as u128) as u64,
        client_id: None,
    };
    let request = ControllerRequest {
        command: "state_plane_subscribe".to_string(),
        file: Some(file.to_path_buf()),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("captured_finalize_resume_subscription".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&invocation)?),
        sequence: None,
    };
    let subscription: ControllerStatePlaneSubscription = request_controller_with_timeout(
        &project_root,
        request,
        timeout.saturating_add(Duration::from_secs(2)),
    )?;
    let wakes = captured_finalize_wakes_from_frames(&subscription.frames);
    Ok(CapturedFinalizeWakeSubscription {
        controller_generation: subscription.controller_generation,
        latest_version: subscription.latest_version,
        timed_out: subscription.timed_out,
        wakes,
    })
}

pub(super) fn captured_finalize_wakes_from_frames(
    frames: &[ControllerStatePlaneFrame],
) -> Vec<CapturedFinalizeWakeProjection> {
    frames
        .iter()
        .filter_map(|frame| {
            let message: lazily::IpcMessage = serde_json::from_str(&frame.message_json).ok()?;
            let payload = state_plane_snapshot_payload(
                &message,
                CAPTURED_FINALIZE_WAKE_STATE_CHANNEL,
                CAPTURED_FINALIZE_WAKE_TYPE_TAG,
            )
            .ok()?;
            serde_json::from_slice::<CapturedFinalizeWakeSnapshot>(&payload).ok()
        })
        .flat_map(|snapshot| snapshot.wakes.into_values())
        .collect()
}

/// Send one editor-replica request through the project controller.
///
/// This is the focused client seam used by editor sidecars. Standalone callers
/// may lazily launch the controller; an embedded editor host is existing-only
/// and reports unavailability to the adapter.
pub fn request_crdt_replica(
    project_root: &Path,
    file: &Path,
    diagnostic_payload: serde_json::Value,
) -> Result<serde_json::Value> {
    request_controller_with_timeout(
        project_root,
        ControllerRequest {
            command: "crdt_replica".to_string(),
            file: Some(file.to_path_buf()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: Some(diagnostic_payload.to_string()),
            sequence: None,
        },
        CONTROLLER_RPC_TIMEOUT,
    )
}

/// Publish one editor's complete visible projection.
///
/// This is state ingress, not a delivery receipt: the controller derives both
/// cumulative relay delivery and retained-write settlement from the projected
/// content hash. `disk_persisted` is true only when the editor has observed the
/// same revision after its native save completed.
pub fn observe_editor_document_projection(
    project_root: &Path,
    file: &Path,
    identity: &str,
    content_hash: &str,
    disk_persisted: bool,
    source: &str,
) -> Result<bool> {
    let response = request_crdt_replica(
        project_root,
        file,
        serde_json::json!({
            "method": "replica_projection",
            "identity": identity,
            "content_hash": content_hash,
            "disk_persisted": disk_persisted,
            "source": source,
        }),
    )?;
    Ok(response
        .get("projected")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false))
}

