fn request_controller_with_timeout<T: DeserializeOwned>(
    project_root: &Path,
    request: ControllerRequest,
    timeout: Duration,
) -> Result<T> {
    request_across_controller_handoff(project_root, &request, || {
        // A reloadable editor library is a passive client, never a controller
        // lifecycle owner. In particular it must not run `status`/bootstrap
        // recovery, because those paths open the controller's SQLite store and can
        // retain WAL mappings across a native-library reload.
        let stream = if EMBEDDED_NATIVE_HOST.load(Ordering::SeqCst) {
            connect(project_root)?
        } else {
            connect_or_launch(project_root, LaunchMode::Lazy)?
        };
        request_controller_on_stream_with_timeout(project_root, request.clone(), timeout, stream)
    })
}

fn request_existing_controller_with_timeout<T: DeserializeOwned>(
    project_root: &Path,
    request: ControllerRequest,
    timeout: Duration,
) -> Result<T> {
    request_across_controller_handoff(project_root, &request, || {
        let stream = connect(project_root)?;
        request_controller_on_stream_with_timeout(project_root, request.clone(), timeout, stream)
    })
}

/// (`#handoffrefusalretry`) Run one client RPC under the handoff settle policy.
///
/// Each attempt reconnects from scratch, so a retry lands on whichever
/// generation now owns the public socket.
fn request_across_controller_handoff<T>(
    project_root: &Path,
    request: &ControllerRequest,
    attempt: impl FnMut() -> Result<T>,
) -> Result<T> {
    retry_controller_handoff_refusal(
        request.file.as_deref().unwrap_or(project_root),
        &request.command,
        // `#preflightdeadline`: a handoff settle never outlives the admission
        // deadline; a zero budget surfaces the first refusal unretried.
        agent_doc_debounce::admission_deadline::clamp(CONTROLLER_HANDOFF_SETTLE_BUDGET),
        CONTROLLER_HANDOFF_SETTLE_INTERVAL,
        std::thread::sleep,
        attempt,
    )
}

fn request_controller_on_stream_with_timeout<T: DeserializeOwned>(
    project_root: &Path,
    request: ControllerRequest,
    timeout: Duration,
    stream: interprocess::local_socket::Stream,
) -> Result<T> {
    note_controller_round_trip();
    // `#preflightdeadline`: every per-call timeout is clamped to the preflight
    // admission deadline (unchanged outside an admission), and a request is
    // refused before it is sent once that deadline is spent.
    let timeout = agent_doc_debounce::admission_deadline::clamp_or_exhausted(
        "project_controller_rpc",
        controller_response_timeout(&socket_path(project_root), timeout),
    )?;
    stream
        .set_recv_timeout(Some(timeout))
        .context("failed to set project controller response timeout")?;
    let (reader_half, mut writer_half) = stream.split();
    // #af88 B enforcement: stamp the caller's own binary identity onto the wire as
    // skew-safe extra JSON keys (ControllerRequest has no `deny_unknown_fields`, so
    // older controllers ignore them). The full identity lets a same-version newer
    // install prove that it may replace an older long-lived process without letting
    // an older caller tear down a newer controller.
    let mut request_value = serde_json::to_value(&request)?;
    if let Some(obj) = request_value.as_object_mut() {
        obj.insert(
            "binary_version".to_string(),
            serde_json::Value::String(identity_version()),
        );
        if let Ok(identity) = current_binary_identity() {
            obj.insert(
                "binary_identity".to_string(),
                serde_json::to_value(identity)?,
            );
        }
    }
    let mut raw = serde_json::to_string(&request_value)?;
    raw.push('\n');
    writer_half.write_all(raw.as_bytes())?;
    writer_half.flush()?;

    let mut reader = BufReader::new(reader_half);
    let mut response = String::new();
    read_controller_response_line_with_timeout(&mut reader, &mut response, timeout)?;
    decode_controller_response(project_root, &request, response.trim())
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn request_controller_with_transport_retry<T: DeserializeOwned>(
    project_root: &Path,
    request: ControllerRequest,
    retry_log_path: &Path,
) -> Result<T> {
    let command = request.command.clone();
    retry_controller_transport_drop(retry_log_path, &command, || {
        request_controller(project_root, request.clone())
    })
}

pub(crate) fn decode_controller_response<T: DeserializeOwned>(
    project_root: &Path,
    request: &ControllerRequest,
    raw_response: &str,
) -> Result<T> {
    let envelope: ControllerEnvelope<T> =
        serde_json::from_str(raw_response).with_context(|| {
            format!(
                "failed to parse project controller response envelope for command `{}`: raw={}",
                request.command, raw_response
            )
        })?;
    if envelope.ok {
        match envelope.data {
            Some(data) => Ok(data),
            None => {
                if let Some(file) = request.file.as_ref() {
                    let log_file = if file.is_absolute() {
                        file.clone()
                    } else {
                        project_root.join(file)
                    };
                    agent_doc_ops_log_io::log_op(
                        &log_file,
                        &format!(
                            "controller_response_missing_data command={} raw={}",
                            request.command, raw_response
                        ),
                    );
                }
                anyhow::bail!(
                    "project controller command `{}` returned ok response without data: raw={}",
                    request.command,
                    raw_response
                )
            }
        }
    } else {
        anyhow::bail!(
            "project controller command `{}` failed: {}",
            request.command,
            envelope
                .error
                .unwrap_or_else(|| "project controller request failed".to_string())
        )
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct CoordinationClaimResponse {
    pub acquired: bool,
}

/// Atomically claim a set of ephemeral coordination scopes from the live
/// controller's Lazily graph.
pub fn try_claim_coordination(
    project_root: &Path,
    scopes: &[String],
    owner_token: &str,
    owner_pid: u32,
) -> Result<bool> {
    anyhow::ensure!(!scopes.is_empty(), "coordination scopes must not be empty");
    anyhow::ensure!(
        !owner_token.trim().is_empty(),
        "coordination owner token must not be empty"
    );
    let response: CoordinationClaimResponse = request_controller_with_transport_retry(
        project_root,
        ControllerRequest {
            command: "coordination_claim".to_string(),
            file: None,
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: Some(serde_json::to_string(scopes)?),
            caller: Some(owner_token.to_string()),
            reason: None,
            supervisor_pid: Some(owner_pid),
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: None,
            sequence: None,
        },
        project_root,
    )?;
    Ok(response.acquired)
}

/// Release scopes previously acquired by [`try_claim_coordination`].
pub fn release_coordination(
    project_root: &Path,
    scopes: &[String],
    owner_token: &str,
) -> Result<()> {
    let _: serde_json::Value = request_controller_with_transport_retry(
        project_root,
        ControllerRequest {
            command: "coordination_release".to_string(),
            file: None,
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: Some(serde_json::to_string(scopes)?),
            caller: Some(owner_token.to_string()),
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: None,
            sequence: None,
        },
        project_root,
    )?;
    Ok(())
}

