pub fn new_document_path_transition_observation(
    old_path: &Path,
    new_path: &Path,
    client_id: &str,
) -> DocumentPathTransitionObservation {
    let old_path = old_path.to_string_lossy().to_string();
    let new_path = new_path.to_string_lossy().to_string();
    let digest = agent_doc_hash::content_hash(&format!("{old_path}\0{new_path}"));
    let suffix = digest.get(..32).unwrap_or(&digest);
    DocumentPathTransitionObservation {
        transition_id: format!("path-{suffix}"),
        client_id: client_id.to_string(),
        generation: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis()
            .try_into()
            .unwrap_or(u64::MAX),
        sequence: 1,
        old_path,
        new_path,
    }
}

fn document_path_transition_request(
    observation: &DocumentPathTransitionObservation,
) -> Result<ControllerRequest> {
    Ok(ControllerRequest {
        command: "document_path_transition_observe".to_string(),
        file: Some(PathBuf::from(&observation.new_path)),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: Some(observation.generation),
        state: None,
        caller: Some(observation.client_id.clone()),
        reason: Some("editor_vfs_path_transition".to_string()),
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(observation)?),
        sequence: None,
    })
}

/// Publish one state fact through the controller-owned reactive projection.
///
/// Automatic runtime producers must use this ingress instead of appending the
/// durable ledger directly. The controller appends and applies the event in one
/// serialized turn. Controller-local producers enter that same typed boundary
/// directly, so publication never requires self-IPC or a whole-project replay.
pub fn publish_state_event(
    project_root: &Path,
    event: &agent_doc_state_backbone::StateEvent,
) -> Result<bool> {
    if agent_doc_state_wire::in_controller_request()
        && let Some(runtime) = local_controller_runtime_for_project(project_root)?
    {
        let bootstrap = runtime.bootstrap_snapshot()?;
        return ingest_state_event(&bootstrap, &runtime, event.clone());
    }
    let request = ControllerRequest {
        command: "state_event_append".to_string(),
        file: None,
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("automatic_state_source".to_string()),
        reason: Some("reactive_state_publication".to_string()),
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(event)?),
        sequence: None,
    };
    retry_state_event_deadline(project_root, || {
        request_controller_with_timeout(project_root, request.clone(), CONTROLLER_RPC_TIMEOUT)
    })
}

