/// The command-plane response when its terminal result is success, or an error
/// carrying the handler's output (which [`retry_controller_handoff_refusal`]
/// inspects for a mid-handoff refusal).
#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn command_submit_response_accepted(
    name: &str,
    response: serde_json::Value,
) -> Result<serde_json::Value> {
    let exit_code = response
        .get("exit_code")
        .and_then(|value| value.as_i64())
        .unwrap_or(1);
    if exit_code != 0 {
        let output = response
            .get("output")
            .and_then(|value| value.as_str())
            .unwrap_or("command-plane request failed");
        anyhow::bail!("command-plane {name} rejected: {output}");
    }
    Ok(response)
}

#[cfg(not(any(test, feature = "test-support")))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ControllerConnectionPolicy {
    LaunchIfMissing,
    ExistingOnly,
}

#[cfg(not(any(test, feature = "test-support")))]
#[allow(clippy::too_many_arguments)]
fn request_command_submit_payload_via<T, P>(
    project_root: &Path,
    file: Option<PathBuf>,
    name: &str,
    payload_type: &str,
    idempotency_key: &str,
    timeout: Duration,
    payload: &P,
    controller_command: &str,
    connection_policy: ControllerConnectionPolicy,
) -> Result<T>
where
    T: DeserializeOwned,
    P: Serialize,
{
    let payload_json = serde_json::to_string(payload)
        .with_context(|| format!("failed to serialize {name} command payload"))?;
    let payload_hash = agent_doc_hash::content_hash(&payload_json);
    let command_nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_else(|_| u128::from(timestamp_secs()));
    let command_id = format!(
        "cmd-{}-{}-{}",
        name.replace('_', "-"),
        command_nonce,
        &payload_hash[..payload_hash.len().min(12)]
    );
    let submit = lazily::CommandSubmit {
        command_id: command_id.clone(),
        causation_id: command_id.clone(),
        source: "agent-doc-native".to_string(),
        target: "project-controller".to_string(),
        namespace: "agent-doc".to_string(),
        name: name.to_string(),
        authority_generation: 0,
        idempotency_key: idempotency_key.to_string(),
        deadline_ms: timeout.as_millis().try_into().unwrap_or(u64::MAX),
        policy: lazily::CommandPolicy {
            dedupe: lazily::DedupePolicy::SameIdempotencyKey,
            supersede: true,
            cancel_on_preempt: true,
        },
        payload_type: payload_type.to_string(),
        payload_hash: format!("sha256:{payload_hash}"),
        payload: lazily::IpcValue::Inline(payload_json.into_bytes()),
        required_features: vec!["causal-receipts".to_string(), "command-events".to_string()],
    };
    let message = lazily::CommandMessage::CommandSubmit(Box::new(submit));
    let request = ControllerRequest {
        command: controller_command.to_string(),
        file,
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: None,
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&message)?),
        sequence: None,
    };
    // `#layoutobservehandoff`: a command admitted by a controller that is mid-handoff
    // comes back as a terminal rejection carrying `controller not authoritative`,
    // not as an RPC error, so the transport-level handoff retry never saw it. On
    // src/haiven-dev/tasks/api.md 2026-09-29 18:57 the route's layout sync landed in
    // that window and Run Agent Doc surfaced the raw refusal. The rejected handler
    // bailed before touching any state, so re-submitting until a stable generation
    // answers is the whole recovery.
    let log_path = request
        .file
        .clone()
        .unwrap_or_else(|| project_root.to_path_buf());
    let response = retry_controller_handoff_refusal(
        &log_path,
        name,
        CONTROLLER_HANDOFF_SETTLE_BUDGET,
        CONTROLLER_HANDOFF_SETTLE_INTERVAL,
        std::thread::sleep,
        || {
            let response: serde_json::Value = match connection_policy {
                ControllerConnectionPolicy::LaunchIfMissing => {
                    request_controller_with_timeout(project_root, request.clone(), timeout)
                }
                ControllerConnectionPolicy::ExistingOnly => {
                    request_existing_controller_with_timeout(project_root, request.clone(), timeout)
                }
            }?;
            command_submit_response_accepted(name, response)
        },
    )?;
    let payload = response
        .get("payload")
        .cloned()
        .context("command-plane response missing payload")?;
    serde_json::from_value(payload).with_context(|| format!("decode {name} command payload"))
}

pub fn control_queue(
    project_root: &Path,
    file: Option<&Path>,
    action: &str,
    observed_generation: Option<u64>,
    reason: Option<&str>,
    item_id: Option<&str>,
) -> Result<ControllerAdminReceipt> {
    let stamp = level_update_send_stamp();
    #[cfg(any(test, feature = "test-support"))]
    {
        let bootstrap = ControllerBootstrap {
            project_root: project_root.to_path_buf(),
            socket_path: socket_path(project_root),
            launch_mode: LaunchMode::Lazy,
            bootstrap_epoch: 0,
            pid: std::process::id(),
            controller_binary: Some(current_binary_identity()?),
            controller_generation: 1,
            handoff_state: ControllerHandoffState::Stable,
            handoff_started_at: None,
            previous_controller_pid: None,
        };
        handle_queue_control(
            &bootstrap,
            ControllerRequest {
                command: "queue_control".to_string(),
                file: file.map(Path::to_path_buf),
                session_id: None,
                pane_id: None,
                window_id: None,
                generation: observed_generation,
                state: Some(action.to_string()),
                caller: Some("admin".to_string()),
                reason: reason.map(ToOwned::to_owned),
                supervisor_pid: None,
                supervisor_socket: None,
                command_kind: Some(action.to_string()),
                diagnostic_payload: item_id.map(ToOwned::to_owned),
                sequence: stamp,
            },
        )
    }

    #[cfg(not(any(test, feature = "test-support")))]
    request_controller(
        project_root,
        ControllerRequest {
            command: "queue_control".to_string(),
            file: file.map(Path::to_path_buf),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: observed_generation,
            state: Some(action.to_string()),
            caller: Some("admin".to_string()),
            reason: reason.map(ToOwned::to_owned),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some(action.to_string()),
            diagnostic_payload: item_id.map(ToOwned::to_owned),
            sequence: stamp,
        },
    )
}

