pub fn clear_queue_context_clear_in_flight_for_file(file: &Path) -> Result<bool> {
    let projection = queue_context_clear_status_for_file(file)?;
    if !matches!(
        projection.phase,
        agent_doc_state_backbone::QueueContextClearPhase::InFlight
    ) {
        return Ok(false);
    }
    queue_context_clear_settled_for_file(
        file,
        &projection.target,
        &projection.harness,
        &projection.command,
        projection.source.as_deref(),
        projection.clear_epoch,
    )?;
    Ok(true)
}

pub fn clear_queue_context_clear_manual_cooldown_for_file(file: &Path) -> Result<bool> {
    let projection = queue_context_clear_status_for_file(file)?;
    if !projection.is_manual_operator_clear_cooldown() {
        return Ok(false);
    }
    queue_context_clear_settled_for_file(
        file,
        &projection.target,
        &projection.harness,
        &projection.command,
        projection.source.as_deref(),
        projection.clear_epoch,
    )?;
    Ok(true)
}

/// (`#clearsupersedenotice`) Retire a still-deferred clear WITHOUT delivering
/// it because it was superseded (`reason`, e.g. `newer_prompt`). Unlike
/// [`clear_queue_context_clear_deferred_for_file`], the settle carries the
/// reason, so the controller projects a `superseded` notice that reaches the
/// editor over the document-turn authority stream.
pub fn retire_superseded_queue_context_clear_deferred_for_file(
    file: &Path,
    reason: &str,
) -> Result<bool> {
    let projection = queue_context_clear_status_for_file(file)?;
    if !matches!(
        projection.phase,
        agent_doc_state_backbone::QueueContextClearPhase::Deferred
    ) {
        return Ok(false);
    }
    queue_context_clear_settled_with_reason_for_file(
        file,
        &projection.target,
        &projection.harness,
        &projection.command,
        projection.source.as_deref(),
        projection.clear_epoch,
        Some(reason),
    )?;
    Ok(true)
}

pub fn clear_queue_context_clear_deferred_for_file(file: &Path) -> Result<bool> {
    let projection = queue_context_clear_status_for_file(file)?;
    if !matches!(
        projection.phase,
        agent_doc_state_backbone::QueueContextClearPhase::Deferred
    ) {
        return Ok(false);
    }
    queue_context_clear_settled_for_file(
        file,
        &projection.target,
        &projection.harness,
        &projection.command,
        projection.source.as_deref(),
        projection.clear_epoch,
    )?;
    Ok(true)
}

