struct DocumentTurnAuthorityStreamLease<'a> {
    runtime: &'a ControllerRuntime,
    document_hash: String,
    document_id: String,
}

impl Drop for DocumentTurnAuthorityStreamLease<'_> {
    fn drop(&mut self) {
        self.runtime
            .release_document_turn_authority_subscription(&self.document_hash, &self.document_id);
    }
}

fn serve_document_turn_authority_stream(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
    should_stop: &AtomicBool,
    writer: &mut impl Write,
) -> Result<()> {
    let file = request_file(&request)?;
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let invocation: ControllerStatePlaneSubscribeInvocation =
        serde_json::from_str(&payload_json)
            .context("parse document-turn authority subscription")?;
    let project_root = runtime.bootstrap_snapshot()?.project_root;
    let document_hash = agent_doc_hash::document_id_for_path(&file);
    // The requested file is the authority boundary; the channel is a derived
    // transport key, not an independent client assertion.  In particular, an
    // editor can open a file and compute its canonical-path hash before the
    // file is deleted.  Rust's documented missing-path identity is then the
    // display path, so rejecting the stale derived key makes the editor retry
    // the same permanently-invalid request forever.  Re-derive the channel
    // from the request file on every connection and record the reconciliation.
    let channel = document_turn_authority_channel(&document_hash);
    if invocation.channel != channel {
        agent_doc_ops_log_io::log_op(
            &file,
            &format!(
                "document_turn_authority_channel_reconciled requested={} derived={} reason=server_file_authority",
                invocation.channel, channel
            ),
        );
    }
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &project_root,
        &file.to_string_lossy(),
    );
    runtime.acquire_document_turn_authority_subscription(&document_hash, &document_id);
    let _lease = DocumentTurnAuthorityStreamLease {
        runtime,
        document_hash,
        document_id,
    };
    let timeout = Duration::from_millis(invocation.timeout_ms).min(STATE_PLANE_SUBSCRIBE_MAX);
    let mut after_controller_generation = invocation.after_controller_generation;
    let mut after_version = invocation.after_version;
    // `#drainingpredecessor` (GH #261): end the stream once a successor is
    // promoted. It used to end only at `should_stop`, which a draining
    // predecessor sets only after its accepted clients close — this stream
    // among them — so every open editor document pinned the predecessor alive.
    // Closing it makes the editor reconnect to the successor.
    while !should_stop.load(Ordering::SeqCst) && !runtime.successor_promoted() {
        let subscription = runtime.subscribe_state_plane(
            &channel,
            after_controller_generation,
            after_version,
            timeout,
        );
        after_controller_generation = Some(subscription.controller_generation);
        after_version = subscription.latest_version;
        let frame = document_turn_authority_stream_frame(&subscription)?;
        let mut response = controller_envelope(Ok(frame))?;
        response.push('\n');
        if let Err(error) = writer.write_all(response.as_bytes()) {
            if matches!(
                error.kind(),
                ErrorKind::BrokenPipe
                    | ErrorKind::ConnectionAborted
                    | ErrorKind::ConnectionReset
                    | ErrorKind::UnexpectedEof
            ) {
                return Ok(());
            }
            return Err(error).context("write document-authority stream frame");
        }
        writer
            .flush()
            .context("flush document-authority stream frame")?;
    }
    Ok(())
}

fn document_turn_authority_stream_frame(
    subscription: &ControllerStatePlaneSubscription,
) -> Result<DocumentTurnAuthorityStreamFrame> {
    let projection = subscription
        .frames
        .last()
        .map(|frame| {
            let message: lazily::IpcMessage = serde_json::from_str(&frame.message_json)
                .context("decode document-turn authority state-plane message")?;
            let payload = state_plane_snapshot_payload(
                &message,
                &subscription.channel,
                DOCUMENT_TURN_AUTHORITY_TYPE_TAG,
            )?;
            serde_json::from_slice(&payload).context("decode document-turn authority projection")
        })
        .transpose()?;
    Ok(DocumentTurnAuthorityStreamFrame {
        controller_generation: subscription.controller_generation,
        plane_version: subscription.latest_version,
        timed_out: subscription.timed_out,
        projection,
    })
}

fn stale_mutating_client_binary(client_version: Option<&str>) -> Option<&str> {
    client_version.filter(|version| *version != identity_version())
}

/// A closeout-owner release is safe across binary skew because it cannot grant
/// authority or mutate document content: the live controller decodes the
/// payload and releases only an exact `(cycle_id, owner_id)` capability it
/// already issued. All other command-plane mutations retain the stale-binary
/// refusal and promote/reconnect behavior.
fn stale_client_may_release_closeout_owner(request: &ControllerRequest) -> bool {
    use super::command_plane::{
        CLOSEOUT_OWNER_RELEASE_NAME, NAMESPACE, decode_closeout_owner_release_payload,
    };

    let Some(submit_json) = request.diagnostic_payload.as_deref() else {
        return false;
    };
    let Ok(submit) = serde_json::from_str::<lazily::CommandSubmit>(submit_json) else {
        return false;
    };
    submit.namespace == NAMESPACE
        && submit.name == CLOSEOUT_OWNER_RELEASE_NAME
        && decode_closeout_owner_release_payload(&submit).is_ok()
}

pub(crate) fn controller_envelope<T: Serialize>(result: Result<T>) -> Result<String> {
    match result {
        Ok(data) => Ok(serde_json::to_string(&serde_json::json!({
            "ok": true,
            "data": data
        }))?),
        Err(err) => Ok(serde_json::to_string(&serde_json::json!({
            "ok": false,
            "error": format!("{err:#}")
        }))?),
    }
}

#[derive(Debug, Serialize)]
struct ControllerStateSubscribeResponse {
    document_hash: String,
    message: serde_json::Value,
    /// Durable `state_events.document_version` represented by this response.
    ///
    /// This is not the Lazily graph epoch: it remains monotonic across
    /// count-cap retention and is the cursor peers acknowledge on their next
    /// subscription.
    document_version: u64,
    /// Whether the preceding cursor supplied by this peer was accepted.
    peer_ack_recorded: bool,
}

#[derive(Debug, Default, Deserialize)]
struct ControllerStateSubscribePayload {
    document_hash: Option<String>,
    peer_pid: Option<u64>,
    editor_id: Option<String>,
    acked_version: Option<u64>,
}

fn handle_state_subscribe(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<ControllerStateSubscribeResponse> {
    let file = request_file(&request)?;
    let payload = request
        .diagnostic_payload
        .as_deref()
        .and_then(|payload| serde_json::from_str::<ControllerStateSubscribePayload>(payload).ok())
        .unwrap_or_default();
    let document_hash = payload
        .document_hash
        .unwrap_or_else(|| agent_doc_hash::document_id_for_path(&file));
    let last_epoch = request.generation.unwrap_or(0);

    // Closeout writers still append state-backbone facts directly to the durable
    // store in a few recovery-oriented paths. Refresh before serving editor
    // state so the Project Controller projection remains the hot-path source and
    // editor integrations never need to inspect sidecar files.
    runtime.refresh_memory()?;
    // `#lzsync` 3B wire cutover (flipped): emit the canonical native lazily wire
    // (`IpcMessage` Snapshot/Delta, `NodeId`/`IpcValue`) instead of the bespoke
    // base64-`WireDelta` `WireSubscribe` JSON. The plugins fold this through a
    // generic lazily `GraphView` and layer their own `AgentDocProjection` on top;
    // there is intentionally no fallback (the plugin rewrites land in the same flip).
    // `build_delta` still produces the internal `WireDelta` producer form; the
    // state-wire bridge converts it here (fully porting `build_delta` to native is a
    // follow-up).
    let (wire, document_version) = runtime.state_subscribe(&document_hash, last_epoch)?;
    let message = serde_json::to_value(
        agent_doc_state_wire::lazily_convert::wire_subscribe_to_ipc_message(&wire)?,
    )
    .context("serialize native IpcMessage for state_subscribe")?;

    let live_registrations = controller_liveness_plane()
        .lock()
        .projection()
        .live_registrations(&document_hash);
    let project_root = runtime.bootstrap_snapshot()?.project_root;
    let state_db = agent_doc_sqlite::state_store::open_state_db(&project_root)?;

    // The cursor reports the PREVIOUS response, so it is safe only after the
    // editor successfully folded that snapshot/delta. Bind it to the exact
    // live PID-scoped registration; never let a synthetic socket client create
    // a retention peer. Failure to collect an ack must not make the read path
    // unavailable — a missing cursor contributes zero to the live-peer minimum.
    let peer_ack_recorded = match (
        payload.peer_pid,
        payload.editor_id.as_deref(),
        payload.acked_version.filter(|version| *version > 0),
    ) {
        (Some(peer_pid), Some(editor_id), Some(acked_version))
            if live_registrations.iter().any(|registration| {
                registration.pid == peer_pid && registration.editor_id == editor_id
            }) =>
        {
            match agent_doc_sqlite::state_store::record_state_event_peer_ack_in_db(
                &state_db,
                &document_hash,
                peer_pid,
                editor_id,
                acked_version,
            ) {
                Ok(_) => true,
                Err(err) => {
                    eprintln!(
                        "[agent-doc] warning: state replay ack rejected \
                         document_hash={document_hash} pid={peer_pid} editor_id={editor_id}: {err:#}"
                    );
                    false
                }
            }
        }
        _ => false,
    };
    let live_peers = live_registrations
        .iter()
        .map(|registration| (registration.pid, registration.editor_id.clone()))
        .collect::<Vec<_>>();
    match agent_doc_sqlite::state_store::prune_state_events_to_live_peer_watermark_in_db(
        &state_db,
        &document_hash,
        &live_peers,
    ) {
        Ok(outcome) if outcome.evicted_peer_rows > 0 || outcome.deleted_event_rows > 0 => {
            eprintln!(
                "[state-retention] document_hash={document_hash} \
                 live_peers={} evicted_peers={} minimum_acked_version={:?} deleted_events={}",
                outcome.live_peer_count,
                outcome.evicted_peer_rows,
                outcome.minimum_acked_version,
                outcome.deleted_event_rows,
            );
        }
        Ok(_) => {}
        Err(err) => {
            eprintln!(
                "[agent-doc] warning: live-peer state retention failed \
                 document_hash={document_hash}: {err:#}"
            );
        }
    }
    Ok(ControllerStateSubscribeResponse {
        document_hash,
        message,
        document_version,
        peer_ack_recorded,
    })
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ControllerReliableSyncResponse {
    pub document_hash: String,
    /// Ack cursor the pushing plugin uses to prune / resume its outbox.
    pub ack_through: u64,
    /// Lazily accepted the frame into the authoritative plane.
    pub accepted: bool,
}

#[derive(Debug, Serialize, Deserialize)]
struct ControllerReliableSyncOutboxPayload {
    document_hash: String,
    /// A raw Lazily frame to durably append. `None` means flush only.
    frame: Option<lazily::IpcMessage>,
    /// Flush the retained suffix after an optional append.
    flush: bool,
}

/// Ask the project controller to own the durable sender outbox for one raw
/// reliable-sync frame. The caller is deliberately stateless: epoch allocation,
/// append-before-apply, replay, and pruning all occur in the controller process.
pub fn enqueue_reliable_sync_frame(
    project_root: &Path,
    file: Option<&Path>,
    document_hash: &str,
    frame: lazily::IpcMessage,
    flush: bool,
) -> Result<ControllerReliableSyncResponse> {
    request_reliable_sync_outbox(
        project_root,
        file,
        ControllerReliableSyncOutboxPayload {
            document_hash: document_hash.to_string(),
            frame: Some(frame),
            flush,
        },
    )
}

/// Flush a controller-owned reliable-sync sender channel without appending.
pub fn flush_reliable_sync_channel(
    project_root: &Path,
    file: Option<&Path>,
    document_hash: &str,
) -> Result<ControllerReliableSyncResponse> {
    request_reliable_sync_outbox(
        project_root,
        file,
        ControllerReliableSyncOutboxPayload {
            document_hash: document_hash.to_string(),
            frame: None,
            flush: true,
        },
    )
}

fn request_reliable_sync_outbox(
    project_root: &Path,
    file: Option<&Path>,
    payload: ControllerReliableSyncOutboxPayload,
) -> Result<ControllerReliableSyncResponse> {
    let request = ControllerRequest {
        command: "reliable_sync_outbox".to_string(),
        file: file.map(Path::to_path_buf),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some("reliable_sync_outbox_client".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(serde_json::to_string(&payload)?),
        sequence: None,
    };
    request_controller::<ControllerReliableSyncResponse>(project_root, request)
}

/// Client side of the `reliable_sync` RPC: push one liveness envelope to the
/// controller and return its response (ack cursor + acceptance).
///
/// The plugin-push endpoint's [`agent_doc_reliable_sync_io::push::LivenessPushTransport`]
/// wraps this. `envelope` is an [`agent_doc_reliable_sync_io::encode_envelope`] value;
/// `epoch` is the outbox retention key.
pub fn push_reliable_sync_liveness(
    project_root: &Path,
    epoch: u64,
    envelope: &serde_json::Value,
) -> Result<ControllerReliableSyncResponse> {
    let request = ControllerRequest {
        command: "reliable_sync".to_string(),
        file: None,
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: Some(epoch),
        state: None,
        caller: Some("reliable_sync_push".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(envelope.to_string()),
        sequence: None,
    };
    request_controller::<ControllerReliableSyncResponse>(project_root, request)
}

/// Client side of the `reliable_sync` RPC that ALSO carries the document `file` so the
/// controller can route document-op / full-state-adopt frames (`#docop-plane` /
/// `#reattach-adopt`) to the right relay canonical (the liveness path is hash-keyed and
/// leaves `file` unset). `envelope` wraps the frame; `epoch` is the outbox retention key.
pub fn push_reliable_sync_frame_for_file(
    project_root: &Path,
    file: &Path,
    epoch: u64,
    envelope: &serde_json::Value,
) -> Result<ControllerReliableSyncResponse> {
    let request = ControllerRequest {
        command: "reliable_sync".to_string(),
        file: Some(file.to_path_buf()),
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: Some(epoch),
        state: None,
        caller: Some("reliable_sync_frame_push".to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: Some(envelope.to_string()),
        sequence: None,
    };
    request_controller::<ControllerReliableSyncResponse>(project_root, request)
}

/// [`agent_doc_reliable_sync_io::push::LivenessPushTransport`] over the controller
/// `reliable_sync` RPC — the production transport the plugin-push endpoint flushes
/// through. One per project root.
pub struct RpcLivenessPushTransport {
    project_root: std::path::PathBuf,
}

impl RpcLivenessPushTransport {
    pub fn new(project_root: impl Into<std::path::PathBuf>) -> Self {
        Self {
            project_root: project_root.into(),
        }
    }
}

impl agent_doc_reliable_sync_io::push::LivenessPushTransport for RpcLivenessPushTransport {
    fn push(&self, _document_hash: &str, epoch: u64, envelope: &serde_json::Value) -> Result<u64> {
        let response = push_reliable_sync_liveness(&self.project_root, epoch, envelope)?;
        Ok(response.ack_through)
    }
}

/// Reliable-sync transport for document-scoped frames. Unlike liveness, the
/// request carries `file`, allowing the controller to fold the frame into the
/// correct relay canonical.
pub struct RpcDocumentPushTransport {
    project_root: std::path::PathBuf,
    file: std::path::PathBuf,
}

impl RpcDocumentPushTransport {
    pub fn new(
        project_root: impl Into<std::path::PathBuf>,
        file: impl Into<std::path::PathBuf>,
    ) -> Self {
        Self {
            project_root: project_root.into(),
            file: file.into(),
        }
    }
}

impl agent_doc_reliable_sync_io::push::LivenessPushTransport for RpcDocumentPushTransport {
    fn push(&self, _document_hash: &str, epoch: u64, envelope: &serde_json::Value) -> Result<u64> {
        let response =
            push_reliable_sync_frame_for_file(&self.project_root, &self.file, epoch, envelope)?;
        Ok(response.ack_through)
    }
}

/// The reliable-sync liveness plane the controller feeds and reads (sidecar-retirement
/// Phase 3C + step 3). The global lives in `agent-doc-reliable-sync-io`
/// ([`agent_doc_reliable_sync_io::global_liveness_plane`]) so the same instance the
/// controller feeds is the one [`crdt_authority_for_file`] reads — the plane is the
/// sole live-editor metadata authority.
fn controller_liveness_plane()
-> &'static parking_lot::Mutex<agent_doc_reliable_sync_io::plane::ControllerLivenessPlane> {
    agent_doc_reliable_sync_io::global_liveness_plane()
}

fn retain_state_events_for_live_registrations(
    project_root: &Path,
    document_hash: &str,
    registrations: &[agent_doc_reliable_sync_io::liveness::EditorRegistration],
) -> Result<agent_doc_sqlite::state_store::StateEventWatermarkRetention> {
    let state_db = agent_doc_sqlite::state_store::open_state_db(project_root)?;
    let live_peers = registrations
        .iter()
        .map(|registration| (registration.pid, registration.editor_id.clone()))
        .collect::<Vec<_>>();
    agent_doc_sqlite::state_store::prune_state_events_to_live_peer_watermark_in_db(
        &state_db,
        document_hash,
        &live_peers,
    )
}

fn restored_reliable_sync_projects() -> &'static parking_lot::Mutex<BTreeSet<PathBuf>> {
    static RESTORED: std::sync::LazyLock<parking_lot::Mutex<BTreeSet<PathBuf>>> =
        std::sync::LazyLock::new(|| parking_lot::Mutex::new(BTreeSet::new()));
    &RESTORED
}

/// Rebuild the in-memory liveness plane from facts the receiver committed before
/// acknowledging them. This is intentionally idempotent: CRDT joins and cursor
/// maxima make duplicate hydration harmless.
/// Fold the durable reliable-sync liveness journal into the in-memory plane.
///
/// `#ctrlbindbeforeserve`: this runs BEFORE the controller binds its socket. It
/// is a SQLite read plus a JSON decode of a journal with no bound on its size
/// (59,671 rows / 6.5 MB on `agent-loop` at 2026-09-11), against a `state.db`
/// that a departing controller may still be writing through WAL during a
/// handoff. Anything unbounded between `create_sync()` and the first `accept()`
/// leaves a client CONNECTED and silent — it already wrote its request — until
/// the client's own timeout fires. That is indistinguishable at the editor from
/// a wedged controller, and it is what `Project Controller did not respond
/// within 60000ms` reports.
///
/// Returns `None` when this project was already restored in this process, and
/// otherwise the editor pids whose deaths still need projecting — which the
/// caller hands to [`spawn_reliable_sync_recovery_effects`] only once the
/// listener is accepting.
fn hydrate_reliable_sync_liveness(
    project_root: &Path,
) -> Result<Option<Vec<agent_doc_reliable_sync_io::liveness::Pid>>> {
    let project_key = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());
    if restored_reliable_sync_projects()
        .lock()
        .contains(&project_key)
    {
        return Ok(None);
    }

    let snapshot = agent_doc_sqlite::reliable_sync_inbox::load(
        &agent_doc_sqlite::state_store::state_db_path(project_root),
    )?;
    let batches = snapshot
        .liveness
        .iter()
        .map(|record| {
            serde_json::from_str::<Vec<agent_doc_reliable_sync_io::liveness::LivenessOp>>(
                &record.ops_json,
            )
            .with_context(|| {
                format!(
                    "decode durable reliable-sync liveness source={} epoch={}",
                    record.source_key, record.epoch
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let dead_open_pids = {
        let mut plane = controller_liveness_plane().lock();
        for batch in &batches {
            plane.restore_liveness(batch);
        }
        for cursor in &snapshot.cursors {
            plane.restore_cursor(&cursor.document_hash, cursor.ack_through);
        }
        plane
            .projection()
            .all_open_pids()
            .into_iter()
            .filter(|pid| {
                u32::try_from(*pid)
                    .ok()
                    .is_none_or(|pid| !agent_doc_reliable_sync_io::process_pid_is_live(pid))
            })
            .collect::<Vec<_>>()
    };
    restored_reliable_sync_projects().lock().insert(project_key);
    Ok(Some(dead_open_pids))
}

/// Journal appends between background compactions of the reliable-sync
/// liveness journal (`#sdkingressstall`). Heartbeats append one row per editor
/// document every few seconds, so this keeps the journal within a few thousand
/// rows without compacting on every append.
const LIVENESS_JOURNAL_COMPACTION_APPEND_INTERVAL: u64 = 2_048;

static LIVENESS_JOURNAL_APPENDS: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static LIVENESS_JOURNAL_COMPACTION_RUNNING: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Count one durable liveness append and, every
/// [`LIVENESS_JOURNAL_COMPACTION_APPEND_INTERVAL`] appends, compact the journal
/// on a single-flight background thread — never on the RPC thread that
/// appended, which may be serving an editor or holding ingress.
fn note_liveness_journal_append(project_root: &Path) {
    let appended = LIVENESS_JOURNAL_APPENDS.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
    if !appended.is_multiple_of(LIVENESS_JOURNAL_COMPACTION_APPEND_INTERVAL) {
        return;
    }
    let root = project_root.to_path_buf();
    std::thread::spawn(move || compact_reliable_sync_liveness_journal(&root, "append_interval"));
}

/// One unconditional compaction pass; [`compact_reliable_sync_liveness_journal`]
/// adds the single-flight guard and the ops-log receipt.
fn compact_reliable_sync_liveness_journal_now(
    project_root: &Path,
) -> Result<agent_doc_sqlite::reliable_sync_inbox::LivenessJournalCompaction> {
    agent_doc_sqlite::reliable_sync_inbox::compact_liveness_journal(
        &agent_doc_sqlite::state_store::state_db_path(project_root),
        |records, pinned| {
            let batches = records
                .iter()
                .map(|record| {
                    serde_json::from_str::<Vec<agent_doc_reliable_sync_io::liveness::LivenessOp>>(
                        &record.ops_json,
                    )
                    .with_context(|| {
                        format!(
                            "decode durable reliable-sync liveness source={} epoch={}",
                            record.source_key, record.epoch
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            Ok(agent_doc_reliable_sync_io::liveness::superseded_liveness_batches(&batches, pinned))
        },
    )
}

/// Drop liveness-journal rows whose every op is dominated by a retained write
/// (`#sdkingressstall`). The journal was append-only: `haiven-dev` reached
/// 497,353 rows / 305 MB carrying 1,037 live cells, and every cold hydration
/// (controller start, and each untracked-document liveness read) re-decoded all
/// of it. Replaying the retained rows folds to the identical projection
/// ([`agent_doc_reliable_sync_io::liveness::superseded_liveness_batches`]).
///
/// The plan is read from a WAL snapshot and rows are deleted in short bounded
/// transactions, so this never holds the `state.db` write lock across the scan
/// that state-event ingress waits on.
pub(crate) fn compact_reliable_sync_liveness_journal(project_root: &Path, trigger: &str) {
    if LIVENESS_JOURNAL_COMPACTION_RUNNING
        .compare_exchange(
            false,
            true,
            std::sync::atomic::Ordering::SeqCst,
            std::sync::atomic::Ordering::SeqCst,
        )
        .is_err()
    {
        return;
    }
    let started = Instant::now();
    let outcome = compact_reliable_sync_liveness_journal_now(project_root);
    LIVENESS_JOURNAL_COMPACTION_RUNNING.store(false, std::sync::atomic::Ordering::SeqCst);
    match outcome {
        Ok(report) => {
            if report.rows_removed > 0 {
                agent_doc_ops_log_io::log_op(
                    project_root,
                    &format!(
                        "reliable_sync_liveness_journal_compacted trigger={trigger} rows_before={} rows_removed={} elapsed_ms={}",
                        report.rows_before,
                        report.rows_removed,
                        started.elapsed().as_millis(),
                    ),
                );
            }
        }
        Err(error) => agent_doc_ops_log_io::log_op(
            project_root,
            &format!(
                "reliable_sync_liveness_journal_compaction_failed trigger={trigger} error={error:#}"
            ),
        ),
    }
}

/// Project the recovery effects the durable fold discovered.
///
/// The fold is the readiness boundary. These effects can contact every retained
/// editor route, and one stale IPC endpoint may consume a timeout. Running them
/// before the accept loop made a newly-bound socket look alive while its backlog
/// was never serviced; concurrent route supervisors then cold-launched duplicate
/// controllers. They are spawned, and only after the listener is accepting, so
/// `status`/handoff RPCs are immediately serviceable while the already-hydrated
/// liveness plane drives recovery — and so an editor answering the missing-replica
/// projection reaches a controller that can receive it.
fn spawn_reliable_sync_recovery_effects(
    project_root: &Path,
    handoff_state: ControllerHandoffState,
    dead_open_pids: Vec<agent_doc_reliable_sync_io::liveness::Pid>,
) {
    let recovery_root = project_root.to_path_buf();
    std::thread::spawn(move || {
        // A process can die while the controller is down, so its exit watcher
        // never gets a chance to publish Alive(false). Record those deaths
        // through the same durable LWW path as a live exit event.
        for pid in dead_open_pids {
            record_reliable_sync_editor_exit(&recovery_root, pid);
        }
        if handoff_state == ControllerHandoffState::Stable {
            project_editor_replica_rebuilds(&recovery_root);
        } else {
            agent_doc_ops_log_io::log_op(
                &recovery_root,
                "controller_restart_editor_replica_rebuild_deferred reason=handoff_not_public",
            );
        }
        // `#sdkingressstall`: bound the journal this process just replayed. It
        // runs last, after the recovery effects, and only once the listener is
        // accepting — never between bind and accept.
        compact_reliable_sync_liveness_journal(&recovery_root, "controller_start");
    });
}

fn project_editor_replica_rebuilds(project_root: &Path) {
    // Publish the restored missing-replica edge once. The same edge dispatcher
    // also covers registrations that arrive later; keeping restart and liveness
    // on one single-flight path prevents duplicate startup signals.
    publish_editor_replica_rebuild_targets(project_root, "restart");
}

fn public_controller_matches_generation(
    status: &ControllerStatus,
    expected_pid: u32,
    expected_generation: u64,
) -> bool {
    status.active
        && status.pid == Some(expected_pid)
        && status.controller_generation == Some(expected_generation)
        && status
            .handoff_state
            .unwrap_or(ControllerHandoffState::Stable)
            == ControllerHandoffState::Stable
}

fn schedule_editor_replica_rebuild_after_promotion(
    project_root: PathBuf,
    expected_pid: u32,
    expected_generation: u64,
) {
    std::thread::spawn(move || {
        let deadline = Instant::now() + HANDOFF_CONNECT_WAIT;
        loop {
            let status = request(&project_root, "handoff_status")
                .ok()
                .and_then(|response| serde_json::from_str::<ControllerStatus>(&response).ok());
            if status.as_ref().is_some_and(|status| {
                public_controller_matches_generation(status, expected_pid, expected_generation)
            }) {
                agent_doc_ops_log_io::log_op(
                    &project_root,
                    &format!(
                        "controller_promotion_editor_replica_rebuild_ready pid={expected_pid} generation={expected_generation}"
                    ),
                );
                project_editor_replica_rebuilds(&project_root);
                return;
            }
            if Instant::now() >= deadline {
                agent_doc_ops_log_io::log_op(
                    &project_root,
                    &format!(
                        "controller_promotion_editor_replica_rebuild_deferred pid={expected_pid} generation={expected_generation} reason=public_generation_not_observed"
                    ),
                );
                return;
            }
            std::thread::sleep(CONNECT_POLL);
        }
    });
}

/// `#ctrlkillreregister` — ask every surviving editor to rebuild its replica once the
/// controller is back.
///
/// Hydration above restores the durable liveness plane, so after a controller
/// restart the editor still reads as *registered*. But the relay hub that holds each
/// replica's CRDT membership is a **process-local** static: it died with the previous
/// controller and nothing rehydrates it. The document therefore resolves as
/// attached-with-missing-replica — an editor the plane says is live, with no replica
/// behind it — until the plugin happens to re-register on its own.
///
/// That gap is why killing the controller strands a live IDE: operators see the
/// document stop converging and reach for an IDE restart to force re-registration.
/// The controller already knows exactly who to ask, so ask them instead of waiting.
///
/// Best-effort and non-destructive: this only requests a refresh. An editor that
/// cannot be reached is left to the existing missing-replica recovery, and a failure
/// here must never block the controller from finishing startup — so failures are
/// logged, never propagated.
/// `#ctrlkillreregister` Tier 2 — the rebuild request as a single-flight effect of
/// the replicated missing-replica edge, so it fires whenever an editor becomes
/// registered-without-a-replica rather than only at the restart instant.
///
/// Tier 1 is a one-shot call at boot: an editor that registers later, or reconnects
/// while the controller is up, hits the same missing-replica state with nobody left
/// to ask. That is the shape this codebase keeps getting burned by — a side effect
/// someone must remember to invoke at the right moment (`#stategraphjoin`).
///
/// Tier 3 (the editor pulling `peer_replicas_missing` about itself) is the better
/// mechanism and needs no push at all. This tier remains because it covers editors
/// whose plugin does not yet call that pull: the controller keeps them working
/// without either side being upgraded first. It is a compatibility layer with an
/// explicit retirement condition, not the destination.
///
/// The published set is claimed before editor IPC and released when a target leaves
/// the missing set (or delivery fails). Editor IPC can synchronously publish another
/// liveness frame, so running that IPC inside a Lazily Effect creates a dependency
/// cycle: the callback sets the Effect's Source while `flush_effects` is still
/// invalidating it. The explicit edge receipt preserves reactive late-registration
/// behavior without allowing that re-entrant CPU loop.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct EditorReplicaRebuildTarget {
    path: String,
    pid: u64,
    editor_id: String,
    strategy: EditorReplicaRepairStrategy,
}

#[derive(Default)]
struct EditorReplicaRebuildPlane {
    published: Mutex<BTreeSet<EditorReplicaRebuildTarget>>,
}

fn editor_replica_rebuild_plane() -> &'static EditorReplicaRebuildPlane {
    static PLANE: std::sync::OnceLock<EditorReplicaRebuildPlane> = std::sync::OnceLock::new();
    PLANE.get_or_init(EditorReplicaRebuildPlane::default)
}

fn claim_editor_replica_rebuild_edges(
    plane: &EditorReplicaRebuildPlane,
    targets: &BTreeSet<EditorReplicaRebuildTarget>,
) -> Vec<EditorReplicaRebuildTarget> {
    let mut published = plane.published.lock();
    published.retain(|target| targets.contains(target));
    let claimed = targets.difference(&published).cloned().collect::<Vec<_>>();
    published.extend(claimed.iter().cloned());
    claimed
}

fn observe_editor_replica_rebuild_healthy_with(
    plane: &EditorReplicaRebuildPlane,
    file: &Path,
) -> bool {
    let canonical = file.canonicalize().unwrap_or_else(|_| file.to_path_buf());
    let canonical = canonical.to_string_lossy();
    let mut published = plane.published.lock();
    let previous_len = published.len();
    published.retain(|target| target.path != canonical);
    published.len() != previous_len
}

/// A successful replica registration is the typed health receipt for a prior
/// rebuild edge. Rearm that path immediately so a later, genuinely distinct hub
/// loss at the same reliable-sync registration can request recovery again.
fn observe_editor_replica_rebuild_healthy(file: &Path) {
    observe_editor_replica_rebuild_healthy_with(editor_replica_rebuild_plane(), file);
}

fn dispatch_editor_replica_rebuild_targets_with(
    project_root: &Path,
    plane: &EditorReplicaRebuildPlane,
    targets: &BTreeSet<EditorReplicaRebuildTarget>,
    driver: &str,
    mut signal: impl FnMut(&Path) -> Result<()>,
) {
    for target in claim_editor_replica_rebuild_edges(plane, targets) {
        let file = std::path::PathBuf::from(&target.path);
        match signal(&file) {
            Ok(()) => agent_doc_ops_log_io::log_op(
                project_root,
                &format!(
                    "editor_replica_rebuild_requested file={} pid={} editor_id={} strategy={} driver={driver}",
                    target.path,
                    target.pid,
                    target.editor_id,
                    target.strategy.label(),
                ),
            ),
            Err(err) => {
                // A future liveness edge may retry a failed transport, but this
                // dispatch never retries inline and therefore cannot spin.
                plane.published.lock().remove(&target);
                agent_doc_ops_log_io::log_op(
                    project_root,
                    &format!(
                        "editor_replica_rebuild_failed file={} pid={} editor_id={} strategy={} driver={driver} error={}",
                        target.path,
                        target.pid,
                        target.editor_id,
                        target.strategy.label(),
                        format!("{err:#}")
                            .replace('\n', " | ")
                            .chars()
                            .take(160)
                            .collect::<String>()
                    ),
                );
            }
        }
    }
}

/// Publish the current missing-replica set through the Tier 2 edge dispatcher.
///
/// Idempotent: an unchanged set does not re-fire, and an empty set retires prior
/// receipts without sending IPC.
/// Called at controller start and whenever folded liveness ops may have changed the
/// registration set.
fn publish_editor_replica_rebuild_targets(project_root: &Path, driver: &str) {
    // The hub is process-local, so anything the plane says is registered but this
    // process cannot serve is stranded. Peer pull is a complementary recovery
    // path, not a reason to suppress this targeted push: a controller restart can
    // be transport-transparent to the editor, so no peer pull is triggered.
    let held: BTreeSet<String> = BTreeSet::new();
    let registrations = controller_liveness_plane()
        .lock()
        .projection()
        .registrations_missing_replica(&held)
        .into_iter();
    // One document needs one rebuild signal even if stale liveness contains more
    // than one registration for the same path.
    let mut by_path = BTreeMap::<String, EditorReplicaRebuildTarget>::new();
    for registration in registrations {
        if controller_serves_replica(&registration.path) {
            continue;
        }
        let strategy = editor_replica_repair_strategy(&registration);
        by_path
            .entry(registration.path.clone())
            .or_insert_with(|| EditorReplicaRebuildTarget {
                path: registration.path,
                pid: registration.pid,
                editor_id: registration.editor_id,
                strategy,
            });
    }
    let targets = by_path.into_values().collect::<BTreeSet<_>>();
    dispatch_editor_replica_rebuild_targets_with(
        project_root,
        editor_replica_rebuild_plane(),
        &targets,
        driver,
        |file| {
            agent_doc_crdt_relay_io::signal_crdt_replica_event(
                file,
                agent_doc_crdt_relay_io::CrdtReplicaEventReason::CanonicalProjection,
                1,
            )
        },
    );
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum EditorReplicaRepairStrategy {
    ControllerPush,
    ControllerPushWithPeerPull,
}

impl EditorReplicaRepairStrategy {
    fn label(self) -> &'static str {
        match self {
            Self::ControllerPush => "controller_push",
            Self::ControllerPushWithPeerPull => "controller_push_with_peer_pull",
        }
    }
}

/// Select the restart repair strategy for this peer.
///
/// A peer-pull-capable editor still requires the targeted controller push. The
/// controller socket may restart without a transport error at the editor, in which
/// case startup/reconnect pull hooks do not run. Peer pull remains useful for plugin
/// startup and detected transport recovery, but it complements rather than retires
/// the controller-owned missing-replica signal.
fn editor_replica_repair_strategy(
    registration: &agent_doc_reliable_sync_io::liveness::EditorRegistration,
) -> EditorReplicaRepairStrategy {
    if agent_doc_document_realtime::editor_contract::has_capability(
        &registration.capabilities,
        agent_doc_document_realtime::editor_contract::PEER_REPLICA_PULL_CAPABILITY,
    ) {
        EditorReplicaRepairStrategy::ControllerPushWithPeerPull
    } else {
        EditorReplicaRepairStrategy::ControllerPush
    }
}

fn reliable_sync_status_request(caller: &str) -> ControllerRequest {
    ControllerRequest {
        command: "reliable_sync_status".to_string(),
        file: None,
        session_id: None,
        pane_id: None,
        window_id: None,
        generation: None,
        state: None,
        caller: Some(caller.to_string()),
        reason: None,
        supervisor_pid: None,
        supervisor_socket: None,
        command_kind: None,
        diagnostic_payload: None,
        sequence: None,
    }
}

fn reliable_sync_status_reports_file_live(
    status: &ControllerReliableSyncStatusResponse,
    document_hash: &str,
) -> bool {
    !status.allocated_model_projection_complete
        || status
            .plane_live_docs
            .iter()
            .any(|hash| hash == document_hash)
        || status
            .registrations
            .iter()
            .any(|registration| registration.document_hash == document_hash)
        || status
            .allocated_model_docs
            .iter()
            .any(|hash| hash == document_hash)
}

/// Default-on liveness authority with a durable cold path. The hot path is one
/// in-memory CRDT projection read. A cold process replays the receiver journal
/// plus the sender's retained suffix. Short-lived clients additionally reconcile
/// a cold/stale local projection against the already-running controller's Lazily
/// projection before declaring disk authoritative.
pub fn reliable_sync_editor_live_for_file(file: &Path) -> bool {
    if agent_doc_crdt_relay_io::reliable_sync_editor_live_for_file(file) {
        return true;
    }
    // The controller owns the authoritative projection. Never ask its socket
    // from the controller process itself.
    if agent_doc_crdt_relay_io::process_serves_relay_hub() {
        return false;
    }
    // `#coldlaunchflakes`: a test harness that routes this document's relay
    // in-process (`seed_embedded_relay_for_file` / a replica registration) is
    // modelling the controller-hosted topology, in which this process owns the
    // document's relay and, like the controller above, answers from its own
    // plane. Before lib tests were served by an in-process state actor, the
    // socket here belonged to a separately launched controller that hosted no
    // model for the document, so the answer was the same "not live" -- unless
    // that launch lost its startup race under load. The in-process actor shares
    // this process's relay registry and would report the test's own hub as a
    // second, controller-side allocation, which no production topology has.
    #[cfg(feature = "test-support")]
    if cold_launch_test_policy::running_in_workspace_test_harness()
        && agent_doc_crdt_relay_io::embedded_relay_route_is_registered_for_file(file)
    {
        return false;
    }
    let Some(project_root) = agent_doc_project_root_io::project_root_containing(file) else {
        return false;
    };
    let stream = match connect(&project_root) {
        Ok(stream) => stream,
        // `#netadv5` R5: a connect failure is evidence about the controller,
        // not the editor. During a handoff/recycle the socket refuses while a
        // controller process still exists and the editor is still attached.
        Err(error) => {
            // A socket path the OS can never bind is permanent, not transient:
            // no editor can reach a controller there either.
            if agent_doc_controller::paths::resolved_socket_path_rejection(&socket_path(
                &project_root,
            ))
            .is_some()
            {
                return false;
            }
            return editor_live_on_controller_connect_failure(&error, || {
                !crate::process::project_controller_pids(&project_root).is_empty()
            });
        }
    };
    let document_hash = agent_doc_hash::document_id_for_path(file);
    match request_controller_on_stream_with_timeout::<ControllerReliableSyncStatusResponse>(
        &project_root,
        reliable_sync_status_request("reliable_sync_editor_live_for_file"),
        CONTROLLER_CRDT_REVISION_READ_TIMEOUT,
        stream,
    ) {
        Ok(status) => reliable_sync_status_reports_file_live(&status, &document_hash),
        Err(_) => {
            // A connected controller whose authority cannot be observed is
            // unknown, not proof that the editor closed. Fail closed so a
            // transient recycle/skew cannot authorize a direct disk replace. This
            // predicate is called by high-frequency authority probes (often from
            // short-lived processes), so it deliberately does not append a
            // success/error line to ops.log on every reconciliation.
            true
        }
    }
}

/// `#netadv5` R5: the editor-liveness answer when the controller socket could
/// not be connected after the local durable plane missed.
///
/// Only positive evidence that no controller exists at all — the kernel refused
/// the connect (or the socket is missing) **and** no same-project controller
/// process is running — lets the durable plane's "not live" stand. Anything
/// else (a slow connect, a refusal while a controller process is mid-handoff)
/// is unknown, and unknown fails closed as "live" so no disk replace is
/// authorized behind an attached editor.
pub(crate) fn editor_live_on_controller_connect_failure(
    error: &anyhow::Error,
    controller_process_present: impl FnOnce() -> bool,
) -> bool {
    let nothing_bound = error.chain().any(|cause| {
        cause.downcast_ref::<std::io::Error>().is_some_and(|io| {
            matches!(
                io.kind(),
                ErrorKind::ConnectionRefused | ErrorKind::NotFound
            )
        })
    });
    !nothing_bound || controller_process_present()
}

/// The hot-path CRDT authority for `file` (sidecar-retirement P3/P4).
///
/// The relay owns this policy. Durable reliable-sync liveness is its cold-start
/// source, while an already-routed controller model is the atomic continuation of
/// a process-scoped `replica_register`. Consulting liveness alone here used to
/// demote that freshly registered model to Git authority when the separately
/// scheduled `Open` frame was delayed or lost, authorizing a disk write behind the
/// editor that had just registered. Filesystem leases and live-buffer sidecars are
/// not read.
pub fn crdt_authority_for_file(
    file: &str,
) -> agent_doc_document_realtime::crdt_authority::CrdtAuthority {
    let file = Path::new(file);
    let local = agent_doc_crdt_relay_io::crdt_authority_for_file(file);
    if local.editor_attached() || reliable_sync_editor_live_for_file(file) {
        agent_doc_document_realtime::crdt_authority::CrdtAuthority::MultiReplica
    } else {
        agent_doc_document_realtime::crdt_authority::CrdtAuthority::GitAuthoritative
    }
}

/// Status response for the `reliable_sync_status` diagnostic RPC. Lazily
/// liveness and the controller-local canonical model are the two reactive
/// inputs; no filesystem live-buffer model participates in this response.
#[derive(Debug, Serialize, Deserialize)]
pub struct ControllerReliableSyncStatusResponse {
    /// Document hashes the plane derives as open (from pushed liveness frames).
    pub plane_open_docs: Vec<String>,
    /// Each plane-open hash resolved through a live editor registration.
    pub plane_open_paths: Vec<(String, Option<String>)>,
    /// Document hashes the plane derives as live (open minus the whole-editor-death cascade).
    pub plane_live_docs: Vec<String>,
    /// Live editor identity/version/capability registrations carried on the same
    /// monotone reliable-sync channel as open/close state.
    pub registrations: Vec<agent_doc_reliable_sync_io::liveness::EditorRegistration>,
    /// Controller-local canonical models that still own document authority.
    ///
    /// This is deliberately independent of endpoint registration: delivery can
    /// disappear briefly while the model remains live.
    #[serde(default)]
    pub allocated_model_docs: Vec<String>,
    /// Whether `allocated_model_docs` is an authoritative complete projection.
    /// A new client speaking to an older controller observes the default false
    /// and therefore fails closed instead of treating the missing field as an
    /// empty model registry.
    #[serde(default)]
    pub allocated_model_projection_complete: bool,
    /// Volatile in-process registry, retained as a diagnostic only.
    pub registry_open_docs: Vec<String>,
    /// Per open document: the live editor pids the plane sees.
    pub per_doc_pids: Vec<(String, Vec<u64>)>,
    /// Last editor-surface observation and pane-layout outcome (GH #62).
    /// `None` means the controller predates this diagnostic — NOT that no
    /// surface was observed.
    #[serde(default)]
    pub surface_sync: Option<ControllerSurfaceSyncDiagnostics>,
}

/// Handle the `reliable_sync_status` diagnostic RPC from the controller-owned
/// reliable liveness projection.
fn handle_reliable_sync_status(
    bootstrap: &ControllerBootstrap,
) -> Result<ControllerReliableSyncStatusResponse> {
    // Read the model registry before the liveness plane, matching the relay
    // authority lock order used by `crdt_authority_for_file`.
    let allocated_model_docs = agent_doc_crdt_relay_io::allocated_routed_relay_document_hashes();
    let plane = controller_liveness_plane().lock();
    let projection = plane.projection();
    let plane_open = projection.open_docs();
    let plane_live = projection.live_docs();
    let per_doc_pids: Vec<(String, Vec<u64>)> = plane_open
        .iter()
        .map(|doc| {
            (
                doc.clone(),
                projection
                    .open_pids(doc)
                    .into_iter()
                    .filter(|pid| projection.pid_alive(*pid))
                    .collect(),
            )
        })
        .collect();
    let registrations = projection.all_live_registrations();
    let plane_open_paths: Vec<(String, Option<String>)> = plane_open
        .iter()
        .map(|hash| {
            let path = registrations
                .iter()
                .filter(|registration| &registration.document_hash == hash)
                .max_by_key(|registration| {
                    (
                        registration.timestamp_ms,
                        registration.pid,
                        registration.editor_id.as_str(),
                    )
                })
                .map(|registration| registration.path.clone());
            (hash.clone(), path)
        })
        .collect();
    // Volatile in-memory registry — secondary diagnostic only.
    let registry_open: std::collections::BTreeSet<String> =
        agent_doc_document_realtime::editor_open_docs::editor_open_docs()
            .open_agent_docs()
            .into_iter()
            .map(|path| agent_doc_hash::document_id_for_path(std::path::Path::new(&path)))
            .collect();
    Ok(ControllerReliableSyncStatusResponse {
        plane_open_docs: plane_open.into_iter().collect(),
        plane_open_paths,
        plane_live_docs: plane_live.into_iter().collect(),
        registrations,
        allocated_model_docs,
        allocated_model_projection_complete: true,
        registry_open_docs: registry_open.into_iter().collect(),
        per_doc_pids,
        surface_sync: Some(surface_sync_diagnostics_for(&bootstrap.project_root)),
    })
}

/// Client side of the `reliable_sync_status` diagnostic RPC.
pub fn reliable_sync_status(project_root: &Path) -> Result<ControllerReliableSyncStatusResponse> {
    request_controller::<ControllerReliableSyncStatusResponse>(
        project_root,
        reliable_sync_status_request("reliable_sync_status"),
    )
}

/// Resolve live editor registrations for one document from the controller-owned
/// Lazily liveness projection. The result is ordered deterministically for
/// diagnostics; single-target selection explicitly orders by registration time.
pub fn live_editor_registrations_for_file(
    file: &Path,
) -> Result<Vec<agent_doc_reliable_sync_io::liveness::EditorRegistration>> {
    // Registration diagnostics are meaningful only when Lazily says an editor
    // replica is actually attached. Starting or polling a project controller
    // to prove an already-detached document adds a 45s retry ladder to repair
    // and can steal focus from unrelated operator activity.
    if !reliable_sync_editor_live_for_file(file) {
        return Ok(Vec::new());
    }
    let project_root = agent_doc_project_root_io::project_root_containing(file)
        .ok_or_else(|| anyhow::anyhow!("no agent-doc project root for {}", file.display()))?;
    let document_hash = agent_doc_hash::document_id_for_path(file);
    let mut registrations = if agent_doc_crdt_relay_io::embedded_relay_is_available_for_file(file) {
        controller_liveness_plane()
            .lock()
            .projection()
            .live_registrations(&document_hash)
    } else {
        reliable_sync_status(&project_root)?
            .registrations
            .into_iter()
            .filter(|registration| registration.document_hash == document_hash)
            .collect::<Vec<_>>()
    };
    registrations.sort();
    Ok(registrations)
}

pub fn live_editor_registration_for_file(
    file: &Path,
) -> Result<Option<agent_doc_reliable_sync_io::liveness::EditorRegistration>> {
    Ok(live_editor_registrations_for_file(file)?
        .into_iter()
        .max_by(|left, right| {
            (left.timestamp_ms, left.pid, left.editor_id.as_str()).cmp(&(
                right.timestamp_ms,
                right.pid,
                right.editor_id.as_str(),
            ))
        }))
}

/// Feed the shadow liveness plane the controller's own OS-exit-watcher death
/// signal (`#s4b`, Phase 3C): a dead editor `pid` writes `Alive{value:false}` at a
/// fresh stamp, so the derived live-doc aggregate cascades every doc that pid held
/// to not-live.
pub fn record_reliable_sync_editor_exit(project_root: &Path, pid: u64) {
    let wall_time = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_micros() as u64)
        .unwrap_or(0);
    let op = agent_doc_reliable_sync_io::liveness::LivenessOp::Alive {
        pid,
        value: false,
        stamp: lazily::WireStamp {
            wall_time,
            logical: 0,
            peer: 0,
        },
    };
    let ops_json = match serde_json::to_string(&vec![op.clone()]) {
        Ok(value) => value,
        Err(error) => {
            eprintln!(
                "[reliable-sync] record_reliable_sync_editor_exit: serialize failed: {error}"
            );
            return;
        }
    };
    let source_key = format!("controller-alive:{pid}");
    if let Err(error) = agent_doc_sqlite::reliable_sync_inbox::record_local_liveness(
        &agent_doc_sqlite::state_store::state_db_path(project_root),
        &source_key,
        wall_time,
        &ops_json,
    ) {
        eprintln!(
            "[reliable-sync] record_reliable_sync_editor_exit: durable write failed: {error:#}"
        );
        return;
    }
    note_liveness_journal_append(project_root);
    // `#ghostrelaymember`: the durable plane now says this pid is dead, so the
    // live relay must agree. `RelayHub` liveness is keyed by opaque CRDT client
    // id and otherwise only sheds a dead editor's member on the NEXT
    // registration, so an editor that never comes back holds `live_editors >= 1`
    // forever — wedging closeout on a delivery ack that cannot arrive and
    // keeping `authority=editor_buffer` pinned to the ghost's stale canonical
    // instead of the operator's newer disk text.
    if let Ok(editor_pid) = u32::try_from(pid) {
        for reaped in agent_doc_crdt_relay_io::reap_exited_editor_replicas(editor_pid) {
            agent_doc_ops_log_io::log_op(
                project_root,
                &format!(
                    "crdt_replica_reaped_on_editor_exit editor_pid={editor_pid} \
document_hash={} client_id={} identity={} removed={} live_editors_after={}",
                    reaped.document_hash,
                    reaped.client_id,
                    reaped.identity,
                    reaped.removed,
                    reaped.live_editors_after,
                ),
            );
        }
    }
    // The affected set is every document `pid` holds a registration for, read
    // independently of `pid`'s alive register. The durable `Alive{false}` written
    // above is already visible to every durable-journal reader in this process
    // (`agent_doc_crdt_relay_io`'s incremental liveness refresh folds it into this
    // same global plane before each replica signal), so the death can reach the
    // plane through that path before this function takes the lock. Deriving the
    // affected set from *live* registrations made the retention eviction below
    // depend on winning that race: losing it skipped the eviction entirely and
    // left the crashed registration's peer ack pinning the retention floor.
    let affected_documents = {
        let mut plane = controller_liveness_plane().lock();
        let affected_documents = plane.projection().documents_registered_by_pid(pid);
        plane.apply_local(&op);
        affected_documents
            .into_iter()
            .map(|document_hash| {
                let registrations = plane.projection().live_registrations(&document_hash);
                (document_hash, registrations)
            })
            .collect::<Vec<_>>()
    };
    for (document_hash, registrations) in affected_documents {
        match retain_state_events_for_live_registrations(
            project_root,
            &document_hash,
            &registrations,
        ) {
            Ok(outcome) if outcome.evicted_peer_rows > 0 || outcome.deleted_event_rows > 0 => {
                eprintln!(
                    "[state-retention] editor_exit_pid={pid} document_hash={document_hash} \
                     live_peers={} evicted_peers={} minimum_acked_version={:?} deleted_events={}",
                    outcome.live_peer_count,
                    outcome.evicted_peer_rows,
                    outcome.minimum_acked_version,
                    outcome.deleted_event_rows,
                );
            }
            Ok(_) => {}
            Err(error) => {
                eprintln!(
                    "[reliable-sync] record_reliable_sync_editor_exit: \
                     state retention failed document_hash={document_hash}: {error:#}"
                );
            }
        }
    }
}

/// `plugin → controller` reliable-sync liveness push (`#lzsync`, Phase 3C).
///
/// The plugin sends the 3A `reliable_sync` envelope (from
/// `agent_doc_reliable_sync_io::encode_envelope`) as the `diagnostic_payload` and
/// the outbox epoch as `generation`. The frame folds into the
/// `ControllerLivenessPlane` and the returned
/// `ack_through` lets the plugin outbox prune / resume from the frontier.
struct InProcessReliableSyncTransport<'a> {
    project_root: &'a Path,
    file: Option<&'a Path>,
}

impl agent_doc_reliable_sync_io::push::LivenessPushTransport
    for InProcessReliableSyncTransport<'_>
{
    fn push(&self, _document_hash: &str, epoch: u64, envelope: &serde_json::Value) -> Result<u64> {
        let response = handle_reliable_sync(
            self.project_root,
            ControllerRequest {
                command: "reliable_sync".to_string(),
                file: self.file.map(Path::to_path_buf),
                session_id: None,
                pane_id: None,
                window_id: None,
                generation: Some(epoch),
                state: None,
                caller: Some("controller_owned_reliable_sync_outbox".to_string()),
                reason: None,
                supervisor_pid: None,
                supervisor_socket: None,
                command_kind: None,
                diagnostic_payload: Some(envelope.to_string()),
                sequence: None,
            },
        )?;
        Ok(response.ack_through)
    }
}

type ReliableSyncOutboxChannelLocks =
    BTreeMap<(PathBuf, String), std::sync::Arc<parking_lot::Mutex<()>>>;

/// Per-channel serialization for [`handle_reliable_sync_outbox`]
/// (`#runfrontendissue`). Keyed by project root and document hash so one
/// channel's long backlog flush never blocks another channel.
fn reliable_sync_outbox_channel_lock(
    project_root: &Path,
    document_hash: &str,
) -> std::sync::Arc<parking_lot::Mutex<()>> {
    static LOCKS: std::sync::LazyLock<parking_lot::Mutex<ReliableSyncOutboxChannelLocks>> =
        std::sync::LazyLock::new(|| parking_lot::Mutex::new(BTreeMap::new()));
    LOCKS
        .lock()
        .entry((project_root.to_path_buf(), document_hash.to_string()))
        .or_default()
        .clone()
}

fn handle_reliable_sync_outbox(
    project_root: &Path,
    request: ControllerRequest,
) -> Result<ControllerReliableSyncResponse> {
    let payload: ControllerReliableSyncOutboxPayload = serde_json::from_str(
        request
            .diagnostic_payload
            .as_deref()
            .context("reliable_sync_outbox request missing diagnostic_payload")?,
    )
    .context("parse reliable_sync_outbox payload")?;
    // `#runfrontendissue`: epoch allocation reads durable state and then
    // appends with `INSERT OR REPLACE`, so two concurrent requests for one
    // channel could allocate (and overwrite) the same epoch. Serialize the
    // read-allocate-append-flush sequence per channel.
    let channel_lock = reliable_sync_outbox_channel_lock(project_root, &payload.document_hash);
    let _channel_guard = channel_lock.lock();
    let database_path = agent_doc_sqlite::state_store::state_db_path(project_root);
    let outbox = lazily::SqliteOutbox::open(&database_path, payload.document_hash.clone())?;
    let acked_through = outbox.acked_through();
    // The receiver journal shares this database. Allocate strictly above every
    // epoch it has observed, not just above the sender's own ACK cursor: a lost
    // ACK leaves the sender cursor behind a frame the receiver already holds,
    // and re-using that epoch for a new batch is what wedged
    // haiven-dev `frontend.md`'s liveness channel (`#runfrontendissue`).
    let receiver_frontier = agent_doc_sqlite::reliable_sync_inbox::receiver_epoch_frontier(
        &database_path,
        &payload.document_hash,
    )?;
    let mut endpoint = agent_doc_reliable_sync_io::push::FramePushEndpoint::resuming(
        payload.document_hash.clone(),
        outbox,
        acked_through.max(receiver_frontier),
    );
    if let Some(frame) = payload.frame {
        endpoint.enqueue_frame(frame);
    }
    let ack_through = if payload.flush {
        endpoint
            .flush(&InProcessReliableSyncTransport {
                project_root,
                file: request.file.as_deref(),
            })?
            .acked_through
            .max(acked_through)
    } else {
        acked_through
    };
    Ok(ControllerReliableSyncResponse {
        document_hash: payload.document_hash,
        ack_through,
        accepted: true,
    })
}

fn handle_reliable_sync(
    project_root: &Path,
    request: ControllerRequest,
) -> Result<ControllerReliableSyncResponse> {
    let payload_str = request
        .diagnostic_payload
        .as_deref()
        .ok_or_else(|| anyhow::anyhow!("reliable_sync request missing diagnostic_payload"))?;
    let payload: serde_json::Value =
        serde_json::from_str(payload_str).context("parse reliable_sync envelope")?;
    let (document_hash, message) = agent_doc_reliable_sync_io::decode_envelope(&payload)
        .ok_or_else(|| {
            anyhow::anyhow!("reliable_sync payload is not a reliable-sync envelope")
        })??;
    let epoch = request.generation.unwrap_or(0);

    let liveness_ops =
        agent_doc_reliable_sync_io::liveness::decode_liveness_frame(&message).transpose()?;

    // `#docop-plane` P2b: a document-op frame folds into the relay canonical so a
    // connected editor's ops feed it even when its CRDT member registration lapsed
    // (`live_editors == 0`). Inert for liveness-only frames (no document-op node) and
    // when no path is supplied. A frame is idempotent + commutative only inside its
    // registered whole-document lineage; obsolete lineages are terminally quarantined
    // before the durable receiver cursor advances. Serving the fed canonical (removing
    // the frozen-canonical read) is the separate P3 authority flip — this only keeps the
    // canonical fed.
    // Legacy whole-editor adoption frames are decode-only compatibility input.
    // They wake the controller-owned canonical projection and never mutate it.
    if let Some(file) = request.file.as_deref()
        && let Some(decoded) =
            agent_doc_reliable_sync_io::document_op::decode_text_adopt_frame(&message)
    {
        let text = decoded
            .with_context(|| format!("reliable_sync_text_adopt_malformed hash={document_hash}"))?;
        agent_doc_ops_log_io::log_op(
            file,
            &format!(
                "reliable_sync_text_adopt_ignored hash={} editor_hash={} recovery=lazy_controller_canonical_projection",
                document_hash,
                agent_doc_hash::content_hash(&text),
            ),
        );
        let _ = agent_doc_crdt_relay_io::signal_crdt_replica_event(
            file,
            agent_doc_crdt_relay_io::CrdtReplicaEventReason::CanonicalProjection,
            1,
        );
    }

    // Legacy full-state adoption frames are also decode-only compatibility input.
    if let Some(file) = request.file.as_deref()
        && let Some(decoded) =
            agent_doc_reliable_sync_io::document_op::decode_full_state_adopt_frame(&message)
    {
        let ops = decoded.with_context(|| {
            format!("reliable_sync_full_state_adopt_malformed hash={document_hash}")
        })?;
        agent_doc_ops_log_io::log_op(
            file,
            &format!(
                "reliable_sync_full_state_adopt_ignored hash={} ops={} recovery=lazy_controller_canonical_projection",
                document_hash,
                ops.len(),
            ),
        );
        let _ = agent_doc_crdt_relay_io::signal_crdt_replica_event(
            file,
            agent_doc_crdt_relay_io::CrdtReplicaEventReason::CanonicalProjection,
            1,
        );
    }

    if let Some(file) = request.file.as_deref()
        && let Some(decoded) =
            agent_doc_reliable_sync_io::document_op::decode_document_op_frame(&message)
    {
        let batch = decoded.with_context(|| {
            format!("reliable_sync_document_op_frame_malformed hash={document_hash}")
        })?;
        let delta =
            agent_doc_merge::crdt_sync::encode_update_ops(&batch.ops).with_context(|| {
                format!("reliable_sync_document_op_reencode_failed hash={document_hash}")
            })?;
        agent_doc_crdt_relay_io::apply_document_op_delta_for_file_in_lineage(
            file,
            batch.lineage.as_deref(),
            &delta,
        )
        .with_context(|| format!("reliable_sync_document_op_fold_failed hash={document_hash}"))?;
    }

    // P4 receive durability boundary: every document-side effect above completes
    // before the receiver cursor advances. The liveness batch and cursor then
    // commit in one SQLite transaction before the ACK becomes observable. A crash
    // before this point leaves the sender frame retained; a crash after it can
    // rebuild the projection from the receiver journal.
    let liveness_ops_json = liveness_ops
        .as_ref()
        .map(serde_json::to_string)
        .transpose()?;
    let receipt = agent_doc_sqlite::reliable_sync_inbox::record_remote_frame_reconciling(
        &agent_doc_sqlite::state_store::state_db_path(project_root),
        &document_hash,
        epoch,
        liveness_ops_json.as_deref(),
    )?;
    let ack_through = receipt.ack_through;
    if let Some(reconciled_key) = receipt.epoch_reuse_reconciled.as_deref() {
        // `#runfrontendissue`: the sender re-used an epoch the receiver had
        // already journaled with a different batch. Refusing it blocked the
        // channel forever; both CRDT batches are now journaled and folded.
        let message = format!(
            "reliable_sync_epoch_reuse_reconciled document_hash={document_hash} epoch={epoch} \
journal_key={reconciled_key} ack_through={ack_through} (#runfrontendissue)"
        );
        match request.file.as_deref() {
            Some(file) => agent_doc_ops_log_io::log_op(file, &message),
            None => agent_doc_ops_log_io::log_op(project_root, &message),
        }
    }
    let folded_liveness = liveness_ops.is_some();
    if folded_liveness {
        note_liveness_journal_append(project_root);
    }
    {
        let mut plane = controller_liveness_plane().lock();
        if let Some(ops) = &liveness_ops {
            plane.restore_liveness(ops);
        }
        plane.restore_cursor(&document_hash, ack_through);
    }
    // `#ctrlkillreregister` Tier 2 — registrations just changed, so republish the
    // derived missing-replica set. This is what covers an editor that registers or
    // reconnects *after* the restart fan-out already ran; the effect no-ops when the
    // set is unchanged or empty. Done after the plane lock is released so the effect
    // never runs while holding it.
    if folded_liveness {
        publish_editor_replica_rebuild_targets(project_root, "liveness_edge");
    }

    Ok(ControllerReliableSyncResponse {
        document_hash,
        ack_through,
        accepted: true,
    })
}

pub(crate) fn actor_record_from_authority(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    document_id: &str,
) -> Result<Option<agent_doc_controller::actor::ActorRecord>> {
    if let Some(runtime) = runtime {
        runtime.actor_record(document_id)
    } else {
        load_actor_record(&bootstrap.project_root, document_id)
    }
}

pub(crate) fn publish_runtime_after_actor_write(
    runtime: Option<&ControllerRuntime>,
    write: &agent_doc_controller::actor::ActorStoreWrite,
) {
    if let Some(runtime) = runtime {
        runtime.apply_actor_store_write(write);
    }
}

fn store_actor_record_for_runtime(
    project_root: &Path,
    expected_prior_generation: Option<u64>,
    record: &agent_doc_controller::actor::ActorRecord,
    runtime: Option<&ControllerRuntime>,
) -> Result<agent_doc_controller::actor::ActorRecord> {
    let write = store_actor_record_write(project_root, expected_prior_generation, record)?;
    publish_runtime_after_actor_write(runtime, &write);
    Ok(write.record)
}

/// `#queuedclearflake`: [`store_actor_record_for_runtime`] for a lifecycle
/// transition. A `Ready` record releases its turn's dispatch receipt in the
/// same transaction that projects `ready`; returns the record and the number
/// of receipts released.
fn store_lifecycle_actor_record_for_runtime(
    project_root: &Path,
    expected_prior_generation: Option<u64>,
    record: &agent_doc_controller::actor::ActorRecord,
    runtime: Option<&ControllerRuntime>,
) -> Result<(agent_doc_controller::actor::ActorRecord, usize)> {
    let (write, released) =
        store_actor_lifecycle_record_write(project_root, expected_prior_generation, record)?;
    publish_runtime_after_actor_write(runtime, &write);
    Ok((write.record, released))
}

pub(crate) fn request_file(request: &ControllerRequest) -> Result<PathBuf> {
    request
        .file
        .clone()
        .context("controller request missing file")
}

pub(crate) fn request_string(value: &Option<String>, name: &str) -> Result<String> {
    value
        .clone()
        .with_context(|| format!("controller request missing {name}"))
}

pub(crate) fn request_u64(value: Option<u64>, name: &str) -> Result<u64> {
    value.with_context(|| format!("controller request missing {name}"))
}

fn closeout_owner_event_nonce() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default()
}

pub(crate) fn handle_state_event_append(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<bool> {
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let event: agent_doc_state_backbone::StateEvent =
        serde_json::from_str(&payload_json).context("parse state actor append payload")?;
    ingest_state_event(bootstrap, runtime, event)
}

/// Shared authority for external RPC and controller-local event producers.
fn ingest_state_event(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    event: agent_doc_state_backbone::StateEvent,
) -> Result<bool> {
    let incoming_cycle = match &event.fact {
        agent_doc_state_backbone::StateFact::TurnIntentCheckpointed { cycle_id, .. }
        | agent_doc_state_backbone::StateFact::PreflightStarted { cycle_id, .. } => Some(cycle_id),
        _ => None,
    };
    if let Some(incoming_cycle) = incoming_cycle {
        let document = runtime.document_state_projection(event.document_hash())?;
        if document.as_ref().is_some_and(|document| {
            document.closeout.cycle_id.as_deref() != Some(incoming_cycle.as_str())
                && document.retained_captured_response_write().is_some()
        }) {
            anyhow::bail!(
                "state actor rejected cycle `{incoming_cycle}`: a retained document-write effect still owns the prior captured response"
            );
        }
    }
    append_apply_state_event(bootstrap, runtime, event)
}

#[derive(Debug, serde::Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
enum EditorOpCaptureUpdate {
    Append {
        base_hash: String,
        ops_json: String,
        updated_ms: u64,
        event_nonce: String,
        /// `#keylogrebase`: the editor's attestation of the text the burst was
        /// typed into and the text it produced. Absent for producers that
        /// supply none (they keep the legacy stamped-base rule).
        #[serde(default)]
        lineage: Option<agent_doc_state_backbone::EditorOpBurstLineage>,
    },
    Clear {
        event_nonce: String,
    },
    Touch {
        updated_ms: u64,
        event_nonce: String,
    },
}

/// Atomically derive and append the next complete editor-op epoch checkpoint.
///
/// The controller serializes the read/derive/append boundary per process. Each
/// fact is a complete snapshot, so ledger retention can discard superseded
/// checkpoints without losing operations and controller restart replay remains
/// independent of the former `editor_op_captures` table.
fn handle_editor_op_capture_update(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<bool> {
    let file = request_file(&request)?;
    let document_hash = agent_doc_hash::document_id_for_path(&file);
    let payload = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let update: EditorOpCaptureUpdate =
        serde_json::from_str(&payload).context("decode editor-op capture update")?;
    let mut applied_nonces = runtime.editor_op_capture_writes.lock();
    // `#editoropscheckpointfail`: a client whose first append attempt timed out
    // while it waited here re-sends the identical batch. Acknowledge it without
    // a second append so retry never duplicates typed operations.
    let append_nonce = match &update {
        EditorOpCaptureUpdate::Append { event_nonce, .. } => {
            if applied_nonces.contains(&document_hash, event_nonce) {
                return Ok(false);
            }
            Some((document_hash.clone(), event_nonce.clone()))
        }
        _ => None,
    };
    let current = runtime.document_state_projection(&document_hash)?;
    let generation = current
        .as_ref()
        .map(|document| document.document.editor_op_capture_generation)
        .unwrap_or_default();

    let (event_id, fact) = match update {
        EditorOpCaptureUpdate::Append {
            base_hash,
            ops_json,
            updated_ms,
            event_nonce,
            lineage,
        } => {
            let mut incoming: Vec<serde_json::Value> =
                serde_json::from_str(&ops_json).context("decode incoming editor-op batch")?;
            if incoming.is_empty() {
                return Ok(false);
            }
            let active = current
                .as_ref()
                .and_then(|document| document.document.editor_op_capture.as_ref());
            // `#keylogrebase`: the epoch's base is the text the burst's offsets
            // are relative to, decided by one shared rule for the controller and
            // the cold path.
            let plan = agent_doc_state_backbone::plan_editor_op_epoch_append(
                active.map(|active| (active.base_hash.as_str(), active.tip_hash.as_str())),
                &base_hash,
                lineage.as_ref(),
            );
            let (epoch, complete_ops, base_hash, tip_hash) = match (plan, active) {
                (
                    agent_doc_state_backbone::EditorOpEpochAppend::Continue {
                        base_hash,
                        tip_hash,
                    },
                    Some(active),
                ) => {
                    let mut complete: Vec<serde_json::Value> =
                        serde_json::from_str(&active.ops_json)
                            .context("decode active editor-op epoch")?;
                    complete.append(&mut incoming);
                    (active.epoch, complete, base_hash, tip_hash)
                }
                (
                    agent_doc_state_backbone::EditorOpEpochAppend::Continue {
                        base_hash,
                        tip_hash,
                    }
                    | agent_doc_state_backbone::EditorOpEpochAppend::Open {
                        base_hash,
                        tip_hash,
                    },
                    _,
                ) => (generation.saturating_add(1), incoming, base_hash, tip_hash),
            };
            let event_id =
                format!("editor-op-capture-checkpoint:{document_hash}:{epoch}:{event_nonce}");
            (
                event_id,
                agent_doc_state_backbone::StateFact::EditorOpCaptureCheckpointed {
                    document_hash,
                    canonical_path: file.to_string_lossy().into_owned(),
                    epoch,
                    base_hash,
                    ops_json: serde_json::to_string(&complete_ops)
                        .context("encode complete editor-op epoch")?,
                    updated_ms,
                    tip_hash,
                },
            )
        }
        EditorOpCaptureUpdate::Clear { event_nonce } => {
            let epoch = generation.saturating_add(1);
            let event_id =
                format!("editor-op-capture-cleared:{document_hash}:{epoch}:{event_nonce}");
            (
                event_id,
                agent_doc_state_backbone::StateFact::EditorOpCaptureCleared {
                    document_hash,
                    epoch,
                },
            )
        }
        EditorOpCaptureUpdate::Touch {
            updated_ms,
            event_nonce,
        } => {
            let Some(active) = current
                .as_ref()
                .and_then(|document| document.document.editor_op_capture.as_ref())
            else {
                return Ok(false);
            };
            let event_id = format!(
                "editor-op-capture-activity:{document_hash}:{}:{event_nonce}",
                active.epoch
            );
            (
                event_id,
                agent_doc_state_backbone::StateFact::EditorOpCaptureCheckpointed {
                    document_hash,
                    canonical_path: file.to_string_lossy().into_owned(),
                    epoch: active.epoch,
                    base_hash: active.base_hash.clone(),
                    ops_json: active.ops_json.clone(),
                    updated_ms,
                    tip_hash: active.tip_hash.clone(),
                },
            )
        }
    };
    let inserted = append_apply_state_event(
        bootstrap,
        runtime,
        agent_doc_state_backbone::StateEvent::new(event_id, fact),
    )?;
    if let Some((document_hash, nonce)) = append_nonce {
        // Recorded whether or not this call inserted: an ignored insert means the
        // durable ledger already holds this exact event id, i.e. the batch is
        // applied.
        applied_nonces.record(&document_hash, &nonce);
    }
    Ok(inserted)
}

/// Read-only live-projection query (`#lazily-hot-path`): return the controller's
/// authoritative in-memory [`DocumentStateProjection`] for the request file, so a
/// client inspects live state instead of replaying cold `state.db`. Counterpart
/// to `agent_doc_cycle_state_io::load_document_projection`, which prefers this
/// verb when a controller is live and falls back to `state.db` otherwise.
pub(crate) fn handle_document_state_projection(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<Option<agent_doc_state_backbone::DocumentStateProjection>> {
    let file = request_file(&request)?;
    let document_hash = agent_doc_hash::document_id_for_path(&file);
    runtime.document_state_projection(&document_hash)
}

pub(crate) fn handle_document_closeout_projection(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<Option<agent_doc_state_backbone::CloseoutProjection>> {
    let file = request_file(&request)?;
    let document_hash = agent_doc_hash::document_id_for_path(&file);
    runtime.document_closeout_projection(&document_hash)
}

/// Shared core of closeout owner claim: decide the CAS from the live
/// in-memory projection (`decide_owner_claim`), emit the `CloseoutOwnerClaimed`
/// fact when acquired, and update the supervisor-recycle graph. Pure authority
/// logic reused by the bespoke `closeout_owner_claim` verb and the command-plane
/// `service_closeout_owner_claim` (`#lzdurablesink`).
fn run_closeout_owner_claim(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    file: &Path,
    claim: agent_doc_state_backbone::CloseoutOwnerClaimRequest,
) -> Result<agent_doc_state_backbone::CloseoutOwnerClaimOutcome> {
    use agent_doc_state_backbone::{
        CloseoutOwnerClaimAuthorization, CloseoutOwnerClaimOutcome, StateFact,
    };
    let document_hash = agent_doc_hash::document_id_for_path(file);
    // Serialize the decision with every controller-owned state ingress, but do
    // not retain the projection lock across durable I/O. Ordinary ingress is
    // SQLite -> memory; the former memory -> SQLite order here deadlocked
    // finalize against concurrent editor/state publication.
    let _state_event_ingress = runtime.lock_state_event_ingress(
        &bootstrap.project_root,
        "closeout_owner_claim",
        "closeout_owner_claimed",
    );
    // The wake is a Lazily state-plane projection produced only after exact
    // retained Base -> Target convergence. Read it before the state-memory
    // lock, then validate its full capture identity inside the pure backbone
    // transition. Ordinary response-captured wakes never authorize a handoff.
    let authorization =
        if claim.role == agent_doc_state_backbone::CLOSEOUT_OWNER_ROLE_CAPTURED_FINALIZE_RESUME {
            runtime
                .captured_finalize_wakes
                .lock()
                .get(&document_hash)
                .filter(|wake| wake.reason == super::RETAINED_SETTLED_DELIVERY_REACTIVE_REASON)
                .map(
                    |wake| CloseoutOwnerClaimAuthorization::RetainedContinuation {
                        cycle_id: wake.cycle_id.clone(),
                        capture_id: wake.capture_id.clone(),
                        response_sha256: wake.response_sha256.clone(),
                    },
                )
                .unwrap_or_default()
        } else {
            CloseoutOwnerClaimAuthorization::Exclusive
        };

    let current = {
        let memory = runtime.memory.lock();
        memory
            .state_projection
            .document(&document_hash)
            .map(|document| document.closeout.clone())
            .unwrap_or_default()
    };
    let current_owner_alive = current.owner.as_ref().and_then(|owner| {
        (owner.owner_id != claim.owner_id
            && owner.is_active_at(claim.now_secs)
            && claim.allow_dead_owner_takeover)
            .then(|| super::closeout_owner_alive(owner))
    });
    // `#closeoutterminalreactive`: the same derived gate the controller's
    // reactive `ControllerDocumentGraphs::closeout_gate` computes, fed the same
    // liveness probe (`closeout_owner_alive`, GH #130), so the live path and the
    // graph cannot drift. Its value is the *reason* the incumbent stopped blocking.
    let displaced = agent_doc_state_backbone::closeout_gate::closeout_gate(
        current.cycle_id.as_deref(),
        current.owner.as_ref(),
        claim.now_secs,
        current_owner_alive,
        claim.allow_dead_owner_takeover,
    );
    if displaced.released_by_stopgap()
        && let Some(owner) = displaced.owner()
    {
        agent_doc_ops_log_io::log_op(
            file,
            &format!(
                "closeout_owner_released_by_stopgap file={} cycle_id={} owner_id={} owner_pid={} role={} reason=lease_expired",
                file.display(),
                owner.cycle_id,
                owner.owner_id,
                owner.owner_pid,
                owner.role,
            ),
        );
    }
    let ordinary_outcome = current.decide_owner_claim(&claim, current_owner_alive);
    let outcome =
        current.decide_owner_claim_with_authorization(&claim, current_owner_alive, &authorization);
    let retained_handoff = matches!(ordinary_outcome, CloseoutOwnerClaimOutcome::HeldByOther(_))
        && matches!(&outcome, CloseoutOwnerClaimOutcome::Acquired(_));
    if let CloseoutOwnerClaimOutcome::Acquired(owner) = &outcome {
        let event = agent_doc_state_backbone::StateEvent::new(
            format!(
                "closeout-owner-claimed:{document_hash}:{}:{}:{}",
                owner.cycle_id,
                owner.owner_id,
                closeout_owner_event_nonce()
            ),
            StateFact::CloseoutOwnerClaimed {
                document_hash: document_hash.clone(),
                cycle_id: owner.cycle_id.clone(),
                owner_id: owner.owner_id.clone(),
                owner_pid: owner.owner_pid,
                role: owner.role.clone(),
                claimed_secs: owner.claimed_secs,
                expires_secs: owner.expires_secs,
            },
        );
        if append_state_event(&bootstrap.project_root, &event)? {
            runtime.apply_state_event(&event)?;
        }
        if retained_handoff {
            agent_doc_ops_log_io::log_op(
                file,
                &format!(
                    "closeout_owner_transition_projected file={} cycle_id={} owner_id={} role={} source=exact_retained_continuation",
                    file.display(),
                    owner.cycle_id,
                    owner.owner_id,
                    owner.role,
                ),
            );
        }
    }

    agent_doc_ops_log_io::log_op(
        file,
        &format!(
            "closeout_owner_actor_claim file={} owner_id={} expected_cycle={} outcome={outcome:?}",
            file.display(),
            claim.owner_id,
            claim.expected_cycle_id.as_deref().unwrap_or("current"),
        ),
    );
    Ok(outcome)
}

/// Shared core of closeout owner release: decide from the live projection
/// whether the caller still owns the cycle, emit `CloseoutOwnerReleased` when it
/// does, and update the supervisor-recycle graph. Reused by the bespoke verb
/// and the command-plane service.
fn run_closeout_owner_release(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    file: &Path,
    release: CloseoutOwnerReleaseRequest,
) -> Result<bool> {
    use agent_doc_state_backbone::StateFact;
    let document_hash = agent_doc_hash::document_id_for_path(file);
    let _state_event_ingress = runtime.lock_state_event_ingress(
        &bootstrap.project_root,
        "closeout_owner_release",
        "closeout_owner_released",
    );

    let (released, released_role) = {
        let memory = runtime.memory.lock();
        memory
            .state_projection
            .document(&document_hash)
            .filter(|document| {
                document
                    .closeout
                    .owner_release_matches(&release.cycle_id, &release.owner_id)
            })
            .map_or((false, None), |document| {
                (
                    true,
                    document
                        .closeout
                        .owner
                        .as_ref()
                        .map(|owner| owner.role.clone()),
                )
            })
    };
    if released {
        let event = agent_doc_state_backbone::StateEvent::new(
            format!(
                "closeout-owner-released:{document_hash}:{}:{}:{}",
                release.cycle_id,
                release.owner_id,
                closeout_owner_event_nonce()
            ),
            StateFact::CloseoutOwnerReleased {
                document_hash: document_hash.clone(),
                cycle_id: release.cycle_id.clone(),
                owner_id: release.owner_id.clone(),
                reason: release.reason.clone(),
                released_secs: release.released_secs,
            },
        );
        if append_state_event(&bootstrap.project_root, &event)? {
            runtime.apply_state_event(&event)?;
            // `#closeoutleaseresume`: a captured-finalize resume refused by this
            // owner's lease is waiting on it. Releasing the lease is the edge
            // that makes the resume admissible, so publish it instead of
            // leaving the resume on its lease deadline. A resume's own release
            // is not an edge for itself: republishing it would turn one failed
            // attempt into a retry loop.
            if closeout_owner_release_wakes_captured_finalize(released_role.as_deref()) {
                // Clone out of the memory lock: publishing sets state-plane
                // cells and must not run under the projection lock.
                let projection = {
                    let memory = runtime.memory.lock();
                    memory.state_projection.document(&document_hash).cloned()
                };
                // A committed cycle keeps its capture in the projection until
                // the next preflight; only an open cycle has a resume to wake.
                if let Some(projection) = projection.filter(|projection| {
                    projection
                        .closeout
                        .phase
                        .is_some_and(agent_doc_turn::CyclePhase::is_open)
                }) {
                    publish_captured_finalize_wake(
                        runtime,
                        &projection,
                        CLOSEOUT_OWNER_RELEASED_WAKE_REASON,
                    );
                }
            }
        }
    }
    Ok(released)
}

/// Captured-finalize wake reason for a released foreground closeout lease.
pub(super) const CLOSEOUT_OWNER_RELEASED_WAKE_REASON: &str = "closeout_owner_released";

/// Whether releasing an owner of `role` is a captured-finalize wake edge.
fn closeout_owner_release_wakes_captured_finalize(role: Option<&str>) -> bool {
    role.is_some_and(|role| role != CLOSEOUT_OWNER_ROLE_CAPTURED_FINALIZE_RESUME)
}

pub(crate) fn handle_closeout_cycle_progress_await(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<CloseoutCycleWaitOutcome> {
    let file = request_file(&request)?;
    let canonical = file.canonicalize().unwrap_or(file);
    let document_hash = agent_doc_hash::document_id_for_path(&canonical);
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let payload: serde_json::Value =
        serde_json::from_str(&payload_json).context("parse closeout cycle await payload")?;
    let cycle_id = payload
        .get("cycle_id")
        .and_then(|value| value.as_str())
        .context("closeout cycle await missing cycle_id")?;
    let wait = payload
        .get("wait_ms")
        .and_then(|value| value.as_u64())
        .map(Duration::from_millis)
        .unwrap_or(CONTROLLER_CLOSEOUT_CYCLE_AWAIT_MAX)
        .min(CONTROLLER_CLOSEOUT_CYCLE_AWAIT_MAX);
    Ok(runtime.wait_for_closeout_cycle_progress(&document_hash, cycle_id, wait))
}

pub(crate) fn handle_turn_admission_projection(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<Option<agent_doc_state_backbone::TurnAdmissionProjection>> {
    let file = request_file(&request)?;
    let canonical = file.canonicalize().unwrap_or(file);
    let document_hash = agent_doc_hash::document_id_for_path(&canonical);
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let operation: TurnAdmissionProjectionOperation =
        serde_json::from_str(&payload_json).context("parse turn admission projection operation")?;
    match operation {
        TurnAdmissionProjectionOperation::Current => Ok(runtime
            .document_state_projection(&document_hash)?
            .and_then(|document| document.turn_admission_after(None))),
        TurnAdmissionProjectionOperation::Await {
            baseline_cycle_id,
            wait_ms,
        } => {
            let wait = Duration::from_millis(wait_ms).min(CONTROLLER_TURN_ADMISSION_AWAIT_MAX);
            Ok(runtime.wait_for_turn_admission_projection(
                &document_hash,
                baseline_cycle_id.as_deref(),
                wait,
            ))
        }
    }
}

pub(crate) fn handle_closeout_owner_claim(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<agent_doc_state_backbone::CloseoutOwnerClaimOutcome> {
    let file = request_file(&request)?;
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let mut claim: agent_doc_state_backbone::CloseoutOwnerClaimRequest =
        serde_json::from_str(&payload_json).context("parse closeout owner claim")?;
    // The controller owns the serialized CAS and therefore its lease clock.
    // A client timestamp can be several seconds old after socket/SQLite
    // contention, shortening (or immediately expiring) the acquired lease.
    claim.now_secs = timestamp_secs();
    run_closeout_owner_claim(bootstrap, runtime, &file, claim)
}

/// Command-plane service for a `closeout_owner_claim` (`#lzdurablesink`). Decodes
/// the [`lazily::CommandSubmit`], runs the shared claim core from the live
/// projection, and returns the typed outcome — the authority result for this
/// coordination CAS (Acquired / HeldByOther / CycleSuperseded).
fn service_closeout_owner_claim(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    submit: &lazily::CommandSubmit,
) -> Result<agent_doc_state_backbone::CloseoutOwnerClaimOutcome> {
    use super::command_plane::decode_closeout_owner_claim_payload;
    let mut payload = decode_closeout_owner_claim_payload(submit)?;
    let file = std::path::PathBuf::from(&payload.document_path);
    payload.request.now_secs = timestamp_secs();
    run_closeout_owner_claim(bootstrap, runtime, &file, payload.request)
}

pub(crate) fn handle_closeout_owner_release(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<bool> {
    let file = request_file(&request)?;
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let release: CloseoutOwnerReleaseRequest =
        serde_json::from_str(&payload_json).context("parse closeout owner release")?;
    run_closeout_owner_release(bootstrap, runtime, &file, release)
}

/// Owner-pane wedge counter RMW (`#lazily-hot-path`): the controller is the
/// SQLite authority for this runtime state, so the read-modify-write runs
/// server-side here. The client (`agent_doc_owner_pane_io::record`) calls this
/// when a controller is live and falls back to its own direct SQLite path only
/// for the actorless/bootstrap boundary. See `#recguard-wedge-escape`.
#[derive(Debug, Deserialize)]
struct OwnerPaneWedgePayload {
    document_hash: String,
    #[allow(dead_code)]
    head: String,
}

pub(crate) fn handle_record_owner_pane_wedge(
    bootstrap: &ControllerBootstrap,
    _runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<u32> {
    use agent_doc_turn::owner_pane_recursion::{
        OwnerPaneWedgeRecord, record_owner_pane_wedge_fire,
    };
    const OWNER_PANE_WEDGE_STATE_KIND: &str = "owner_pane_wedge";
    let canonical_path = request_file(&request)?;
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let payload: OwnerPaneWedgePayload =
        serde_json::from_str(&payload_json).context("parse owner_pane_wedge payload")?;
    let mut conn = agent_doc_sqlite::state_store::open_state_db(&bootstrap.project_root)?;
    let tx = conn.transaction()?;
    let prior = agent_doc_sqlite::state_store::load_document_runtime_state_from_db(
        &tx,
        &payload.document_hash,
        OWNER_PANE_WEDGE_STATE_KIND,
    )?
    .and_then(|state| serde_json::from_str::<OwnerPaneWedgeRecord>(&state.payload_json).ok());
    let record = record_owner_pane_wedge_fire(prior.as_ref(), &payload.head);
    let count = record.count;
    agent_doc_sqlite::state_store::upsert_document_runtime_state_in_db(
        &tx,
        &agent_doc_sqlite::state_store::DocumentRuntimeStateRecord {
            document_hash: payload.document_hash,
            state_kind: OWNER_PANE_WEDGE_STATE_KIND.to_string(),
            canonical_path: canonical_path.to_string_lossy().into_owned(),
            payload_json: serde_json::to_string(&record)?,
            updated_at_ms: controller_now_ms(),
        },
    )?;
    tx.commit()?;
    Ok(count)
}

pub(crate) fn handle_clear_owner_pane_wedge(
    bootstrap: &ControllerBootstrap,
    _runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<bool> {
    const OWNER_PANE_WEDGE_STATE_KIND: &str = "owner_pane_wedge";
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let payload: OwnerPaneWedgePayload =
        serde_json::from_str(&payload_json).context("parse owner_pane_wedge payload")?;
    let conn = agent_doc_sqlite::state_store::open_state_db(&bootstrap.project_root)?;
    agent_doc_sqlite::state_store::clear_document_runtime_state_in_db(
        &conn,
        &payload.document_hash,
        OWNER_PANE_WEDGE_STATE_KIND,
    )?;
    Ok(true)
}

fn controller_now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0)
}

/// Command-plane service for a `closeout_owner_release`. Decodes the submit and
/// runs the shared release core from the live projection; returns whether the
/// caller still owned (and so released) the cycle.
fn service_closeout_owner_release(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    submit: &lazily::CommandSubmit,
) -> Result<bool> {
    use super::command_plane::decode_closeout_owner_release_payload;
    let payload = decode_closeout_owner_release_payload(submit)?;
    let file = std::path::PathBuf::from(&payload.document_path);
    run_closeout_owner_release(
        bootstrap,
        runtime,
        &file,
        CloseoutOwnerReleaseRequest {
            cycle_id: payload.cycle_id,
            owner_id: payload.owner_id,
            reason: payload.reason,
            released_secs: payload.released_secs,
        },
    )
}

