/// The drift survey of one navigation lane (`#ideriderindependentnav` P2b).
///
/// `lane_session` is the installation lane's own session; `None` is the shared
/// lane, whose survey keeps the project-pin rule unchanged. An installation
/// lane is never surveyed through the pin, or it would observe the wrong
/// session's `agent-doc` window.
fn tmux_layout_sync_state_for_lane_invocation(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    invocation: &ControllerTmuxLayoutSyncStateInvocation,
    effect_file_panes: &[(String, String)],
    lane_session: Option<&str>,
) -> Result<ControllerTmuxLayoutSyncStateReport> {
    let tmux = agent_doc_tmux_io::configured_tmux();
    tmux_layout_sync_state_for_invocation_in_session(
        bootstrap,
        runtime,
        invocation,
        effect_file_panes,
        &[],
        &tmux,
        lane_session,
    )
    .map(|(report, _)| report)
}

fn tmux_layout_sync_state_for_invocation_with_effect_assignment_and_tmux(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    invocation: &ControllerTmuxLayoutSyncStateInvocation,
    effect_file_panes: &[(String, String)],
    registered_supervisor_file_panes: &[(String, String)],
    tmux: &tmux_router::Tmux,
) -> Result<(
    ControllerTmuxLayoutSyncStateReport,
    Option<PaneLayoutObservationSessionSource>,
)> {
    tmux_layout_sync_state_for_invocation_in_session(
        bootstrap,
        runtime,
        invocation,
        effect_file_panes,
        registered_supervisor_file_panes,
        tmux,
        None,
    )
}

fn tmux_layout_sync_state_for_invocation_in_session(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    invocation: &ControllerTmuxLayoutSyncStateInvocation,
    effect_file_panes: &[(String, String)],
    registered_supervisor_file_panes: &[(String, String)],
    tmux: &tmux_router::Tmux,
    lane_session: Option<&str>,
) -> Result<(
    ControllerTmuxLayoutSyncStateReport,
    Option<PaneLayoutObservationSessionSource>,
)> {
    let _survey_timing = PaneLayoutSurveyTimingGuard {
        project_root: bootstrap.project_root.clone(),
        start: Instant::now(),
    };
    // `#tmuxautosyncreactive`: the survey's per-pane `active_pane_process_owner_document`
    // resolves via the process-owner `/proc` graph. Without a scope each new pane
    // root pid took a fresh full `/proc` walk; opening the scope here lets every
    // pane in this survey share ONE memoized walk (see `owner_graph::children_handle`).
    let _process_observation = agent_doc_process_owner_io::begin_process_observation_scope();
    let expected_documents =
        layout_sync_state_expected_documents(&bootstrap.project_root, invocation);
    let focus = invocation.focus.clone();
    if expected_documents.is_empty() {
        return Ok((
            layout_sync_state_report(
                false,
                "empty_layout_model",
                expected_documents,
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    window_id: invocation.window.clone(),
                    focus,
                    ..LayoutSyncStateTarget::default()
                },
            ),
            None,
        ));
    }

    // `#panesessionsnapshot`: open an observation scope so the per-pane
    // `pane_session` probes (via `pane_layout_observation_session` below) and
    // every liveness read in this drift survey share ONE `list-panes -a`
    // listing instead of one `display-message` spawn per candidate pane. This
    // is a read-only survey, so no pane mutation invalidates the snapshot
    // mid-pass. The scope is thread-local and dropped at the function return.
    let _pane_snapshot = tmux_router::begin_pane_snapshot_scope();
    let observed_session = match lane_session {
        Some(lane_session) => Some((
            lane_session.to_string(),
            PaneLayoutObservationSessionSource::NavigationLaneSession,
        )),
        None => pane_layout_observation_session(
            configured_tmux_session_for_project(&bootstrap.project_root),
            project_is_multi_tmux_session(&bootstrap.project_root),
            effect_file_panes,
            registered_supervisor_file_panes,
            |pane| tmux.pane_session(pane).ok(),
        ),
    };
    let Some((configured_session, session_source)) = observed_session else {
        return Ok((
            layout_sync_state_report(
                false,
                "missing_tmux_session",
                expected_documents,
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    window_id: invocation.window.clone(),
                    focus,
                    ..LayoutSyncStateTarget::default()
                },
            ),
            None,
        ));
    };
    if !tmux.session_alive(&configured_session) {
        return Ok((
            layout_sync_state_report(
                false,
                "tmux_session_not_alive",
                expected_documents,
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    session_name: Some(configured_session),
                    window_id: invocation.window.clone(),
                    focus,
                    ..LayoutSyncStateTarget::default()
                },
            ),
            Some(session_source),
        ));
    }

    let window_id = invocation
        .window
        .clone()
        .or_else(|| resolve_agent_doc_window_id_for_session(tmux, &configured_session));
    let Some(window_id_value) = window_id.clone() else {
        return Ok((
            layout_sync_state_report(
                false,
                "missing_agent_doc_window",
                expected_documents,
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    session_name: Some(configured_session),
                    focus,
                    ..LayoutSyncStateTarget::default()
                },
            ),
            Some(session_source),
        ));
    };
    let window_name = agent_doc_tmux_io::target_window_name(tmux, &window_id_value);
    if window_name.as_deref() != Some("agent-doc") {
        return Ok((
            layout_sync_state_report(
                false,
                "target_window_not_agent_doc",
                expected_documents,
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    session_name: Some(configured_session),
                    window_id: Some(window_id_value),
                    window_name,
                    focus,
                },
            ),
            Some(session_source),
        ));
    }

    let panes = tmux
        .list_panes_ordered(&window_id_value)
        .unwrap_or_default();
    // Layout inspection is a hot read path. The controller's lazily-held actor
    // projection is authoritative here; SQLite and the registry are durable
    // effect sinks, not competing read models.
    let actor_store = runtime.actor_store_snapshot();
    let actual_documents = panes
        .iter()
        .map(|pane_id| {
            layout_sync_state_actual_document_for_pane(
                &bootstrap.project_root,
                tmux,
                &actor_store,
                effect_file_panes,
                pane_id,
            )
        })
        .collect::<Vec<_>>();
    // `#stalecontrollerhotupdate` (c): while ANOTHER project root holds this
    // window's layout claim, a pane owned by a foreign root that this layout
    // does not name is that controller's column. The layout effect does not
    // stash it then, so convergence must not demand its removal (that demand
    // is what made a nested controller retry forever). When this controller
    // holds the claim (the editor's newest frame is its own, e.g. the operator
    // went from 2 panes to 1), the foreign pane is an ordinary extra.
    let (panes, actual_documents) =
        if window_layout_driven_by_other_root(tmux, &window_id_value, &bootstrap.project_root) {
            layout_sync_state_without_foreign_extras(
                &bootstrap.project_root,
                &expected_documents,
                panes,
                actual_documents,
                |document| {
                    agent_doc_project_root_io::project_root_containing(Path::new(document))
                        .map(|root| root.canonicalize().unwrap_or(root))
                },
            )
        } else {
            (panes, actual_documents)
        };
    // `#panewindowdrift`: an effect/reuse assignment is a record of where a pane
    // was placed, and it keeps naming that pane after the operator stashes it.
    // `panes` is the target window's own ordered pane list, so an assignment
    // outside it is not a visible column — it must not satisfy a layout slot or
    // stand in as the focus target, or a stashed pane counts toward `synced`.
    let visible_effect_file_panes = effect_file_panes
        .iter()
        .filter(|(_, assigned_pane)| panes.iter().any(|pane| pane == assigned_pane))
        .cloned()
        .collect::<Vec<_>>();
    let expected_panes = layout_sync_state_expected_panes(
        &bootstrap.project_root,
        &expected_documents,
        &visible_effect_file_panes,
    );
    let expected_focus_pane = layout_sync_state_expected_focus_pane(
        &bootstrap.project_root,
        focus.as_deref(),
        &visible_effect_file_panes,
    );
    let active_pane = agent_doc_tmux_io::target_pane_id(tmux, &window_id_value);
    let operator_owned_documents = layout_sync_state_operator_owned_documents(
        &bootstrap.project_root,
        &expected_documents,
        &panes,
        &actor_store,
        &visible_effect_file_panes,
        registered_supervisor_file_panes,
    );
    let (synced, reason) = layout_sync_state_result(
        &expected_documents,
        &actual_documents,
        &expected_panes,
        &panes,
        focus.is_some(),
        expected_focus_pane.as_deref(),
        active_pane.as_deref(),
    );
    let mut report = layout_sync_state_report(
        synced,
        reason,
        expected_documents,
        actual_documents,
        panes,
        LayoutSyncStateTarget {
            session_name: Some(configured_session),
            window_id: Some(window_id_value),
            window_name,
            focus,
        },
    );
    report.expected_panes = expected_panes;
    report.operator_owned_documents = operator_owned_documents;
    report.expected_focus_pane = expected_focus_pane;
    report.active_pane = active_pane;
    Ok((report, Some(session_source)))
}

fn state_plane_message_metadata(message: &lazily::IpcMessage) -> Result<(u64, Option<u64>)> {
    match message {
        lazily::IpcMessage::Snapshot(snapshot) => Ok((snapshot.epoch, None)),
        lazily::IpcMessage::Delta(delta) => Ok((delta.epoch, Some(delta.base_epoch))),
        _ => anyhow::bail!(
            "state plane accepts Lazily graph-state Snapshot/Delta messages, not control or CRDT frames"
        ),
    }
}

fn state_plane_snapshot_payload(
    message: &lazily::IpcMessage,
    channel: &str,
    expected_type_tag: &str,
) -> Result<Vec<u8>> {
    let lazily::IpcMessage::Snapshot(snapshot) = message else {
        anyhow::bail!("{channel} requires a covering Lazily Snapshot");
    };
    let node = snapshot
        .nodes
        .iter()
        .find(|node| {
            node.type_tag == expected_type_tag
                && node.key.as_ref().is_some_and(|key| key.as_str() == channel)
        })
        .with_context(|| {
            format!("{channel} Snapshot is missing keyed node with type_tag={expected_type_tag}")
        })?;
    match &node.state {
        lazily::NodeState::Payload(payload) => Ok(payload.clone()),
        lazily::NodeState::SharedBlob(_) => {
            anyhow::bail!("{channel} does not accept process-local shared-blob payloads")
        }
        lazily::NodeState::Opaque => anyhow::bail!("{channel} payload is opaque"),
    }
}

fn pane_layout_invocation_from_state_frame(
    frame: &ControllerStatePlaneFrame,
) -> Result<ControllerTmuxLayoutSyncInvocation> {
    let message: lazily::IpcMessage = serde_json::from_str(&frame.message_json)
        .context("decode pane-layout Lazily IpcMessage")?;
    let payload = state_plane_snapshot_payload(
        &message,
        PANE_LAYOUT_DESIRED_STATE_CHANNEL,
        PANE_LAYOUT_DESIRED_TYPE_TAG,
    )?;
    serde_json::from_slice(&payload).context("decode pane-layout desired target")
}

fn state_plane_snapshot_message_json<T: Serialize>(
    epoch: u64,
    channel: &str,
    type_tag: &str,
    payload: &T,
) -> Result<String> {
    let node = lazily::NodeSnapshot::payload(
        lazily::NodeId(1),
        type_tag,
        serde_json::to_vec(payload).context("encode state-plane node payload")?,
    )
    .with_key(lazily::NodeKey::new(channel).context("validate state-plane NodeKey")?);
    let message = lazily::IpcMessage::Snapshot(lazily::Snapshot {
        epoch,
        nodes: vec![node],
        edges: Vec::new(),
        roots: vec![lazily::NodeId(1)],
    });
    serde_json::to_string(&message).context("encode Lazily state-plane Snapshot")
}

pub(super) fn publish_document_turn_authority(
    runtime: &ControllerRuntime,
    document_hash: &str,
    epoch: u64,
    projection: &agent_doc_turn::cp_projection::TurnProjection,
) {
    let Ok(bootstrap) = runtime.bootstrap_snapshot() else {
        return;
    };
    let channel = document_turn_authority_channel(document_hash);
    let producer_id = format!(
        "agent-doc-controller:{}:{}",
        std::process::id(),
        bootstrap.controller_generation
    );
    let result = state_plane_snapshot_message_json(
        epoch,
        &channel,
        DOCUMENT_TURN_AUTHORITY_TYPE_TAG,
        projection,
    )
    .and_then(|message_json| {
        runtime.publish_state_plane_frame(channel, producer_id, message_json, epoch, None)
    });
    if let Err(error) = result {
        agent_doc_ops_log_io::log_op(
            &bootstrap.project_root,
            &format!(
                "document_turn_authority_publish_deferred document_hash={document_hash} error={error:#}"
            ),
        );
    }
}

pub(super) fn publish_captured_finalize_wake(
    runtime: &ControllerRuntime,
    projection: &agent_doc_state_backbone::DocumentStateProjection,
    reason: &str,
) -> bool {
    let Some(capture) = projection.closeout.captured_response.as_ref() else {
        return false;
    };
    let Some(cycle_id) = projection.closeout.cycle_id.as_deref() else {
        return false;
    };
    publish_pinned_captured_finalize_wake(
        runtime,
        &projection.document_hash,
        cycle_id,
        &capture.capture_id,
        &capture.response_sha256,
        reason,
    )
}

pub(super) fn publish_pinned_captured_finalize_wake(
    runtime: &ControllerRuntime,
    document_hash: &str,
    cycle_id: &str,
    capture_id: &str,
    response_sha256: &str,
    reason: &str,
) -> bool {
    publish_pinned_captured_finalize_wake_with_hook(
        runtime,
        document_hash,
        cycle_id,
        capture_id,
        response_sha256,
        reason,
        || {},
    )
}

fn publish_pinned_captured_finalize_wake_with_hook(
    runtime: &ControllerRuntime,
    document_hash: &str,
    cycle_id: &str,
    capture_id: &str,
    response_sha256: &str,
    reason: &str,
    before_publish: impl FnOnce(),
) -> bool {
    let _publication = runtime.captured_finalize_wake_publication.lock();
    let payload = CapturedFinalizeWakeProjection {
        document_hash: document_hash.to_string(),
        cycle_id: cycle_id.to_string(),
        capture_id: capture_id.to_string(),
        response_sha256: response_sha256.to_string(),
        reason: reason.to_string(),
    };
    let snapshot = {
        let mut wakes = runtime.captured_finalize_wakes.lock();
        if wakes
            .get(document_hash)
            .is_some_and(|current| !captured_finalize_wake_should_replace(current, &payload))
        {
            return true;
        }
        wakes.insert(document_hash.to_string(), payload);
        CapturedFinalizeWakeSnapshot {
            wakes: wakes.clone(),
        }
    };
    before_publish();
    let epoch = CAPTURED_FINALIZE_WAKE_EPOCH.fetch_add(1, Ordering::SeqCst);
    let producer_id = match runtime.bootstrap_snapshot() {
        Ok(bootstrap) => format!(
            "agent-doc-controller:{}:{}",
            std::process::id(),
            bootstrap.controller_generation
        ),
        Err(_) => format!("agent-doc-controller:{}", std::process::id()),
    };
    let result = state_plane_snapshot_message_json(
        epoch,
        CAPTURED_FINALIZE_WAKE_STATE_CHANNEL,
        CAPTURED_FINALIZE_WAKE_TYPE_TAG,
        &snapshot,
    )
    .and_then(|message_json| {
        runtime.publish_state_plane_frame(
            CAPTURED_FINALIZE_WAKE_STATE_CHANNEL.to_string(),
            producer_id,
            message_json,
            epoch,
            None,
        )
    });
    if let Err(error) = result {
        eprintln!(
            "[controller] captured-finalize wake projection failed for {}: {error:#}",
            document_hash
        );
        return false;
    }
    true
}

fn captured_finalize_wake_should_replace(
    current: &CapturedFinalizeWakeProjection,
    incoming: &CapturedFinalizeWakeProjection,
) -> bool {
    if current == incoming {
        return false;
    }
    let same_capture = current.document_hash == incoming.document_hash
        && current.cycle_id == incoming.cycle_id
        && current.capture_id == incoming.capture_id
        && current.response_sha256 == incoming.response_sha256;
    !same_capture
        || current.reason != super::RETAINED_SETTLED_DELIVERY_REACTIVE_REASON
        || incoming.reason == super::RETAINED_SETTLED_DELIVERY_REACTIVE_REASON
}

pub(super) fn clear_captured_finalize_wake(runtime: &ControllerRuntime, document_hash: &str) {
    let _publication = runtime.captured_finalize_wake_publication.lock();
    runtime.captured_finalize_wakes.lock().remove(document_hash);
}

/// Publish the pane-layout status of `lane` on that lane's own channel
/// (`#ideriderindependentnav` P6). The shared lane publishes on
/// `agent-doc/pane-layout/status/v1` exactly as before lanes existed; an
/// installation lane publishes its own graph's projection on
/// `agent-doc/pane-layout/status/v1/lane/<installation>`, so one lane's sync
/// progress or failure never reaches another lane's subscriber.
fn publish_pane_layout_lane_status(
    runtime: &ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
) {
    if lane.is_shared() {
        publish_pane_layout_status(runtime);
    } else {
        publish_pane_layout_graph_status(runtime, &runtime.pane_layout_graph_for_lane(lane));
    }
}

/// Publish the shared lane's pane-layout status.
fn publish_pane_layout_status(runtime: &ControllerRuntime) {
    publish_pane_layout_graph_status(runtime, runtime.pane_layout_graph());
}

fn publish_pane_layout_graph_status(
    runtime: &ControllerRuntime,
    graph: &super::ControllerPaneLayoutGraph,
) {
    let Some(status) = graph.effect_status() else {
        return;
    };
    let Ok(bootstrap) = runtime.bootstrap_snapshot() else {
        return;
    };
    let channel = graph.status_channel();
    let epoch = graph.next_status_epoch();
    let producer_id = format!(
        "agent-doc-controller:{}:{}",
        std::process::id(),
        bootstrap.controller_generation
    );
    let result =
        state_plane_snapshot_message_json(epoch, &channel, PANE_LAYOUT_STATUS_TYPE_TAG, &status)
            .and_then(|message_json| {
                runtime.publish_state_plane_frame(
                    channel.clone(),
                    producer_id,
                    message_json,
                    epoch,
                    None,
                )
            });
    if let Err(error) = result {
        let lane = if graph.lane.is_shared() {
            String::new()
        } else {
            format!(" navigation_lane={}", graph.lane.label())
        };
        agent_doc_ops_log_io::log_op(
            &bootstrap.project_root,
            &format!("pane_layout_status_publish_deferred{lane} error={error:#}"),
        );
    }
}

pub(crate) fn handle_state_plane_publish(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<ControllerStatePlanePublishReceipt> {
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let invocation: ControllerStatePlanePublishInvocation =
        serde_json::from_str(&payload_json).context("parse state-plane publish invocation")?;
    let message: lazily::IpcMessage = serde_json::from_str(&invocation.message_json)
        .context("decode state-plane Lazily IpcMessage")?;
    let (epoch, base_epoch) = state_plane_message_metadata(&message)?;
    if let lazily::IpcMessage::Snapshot(snapshot) = &message {
        anyhow::ensure!(
            snapshot.nodes.iter().any(|node| {
                node.key
                    .as_ref()
                    .is_some_and(|key| key.as_str() == invocation.channel.as_str())
            }),
            "state-plane Snapshot is missing a node keyed to channel {}",
            invocation.channel
        );
    }
    if invocation.channel == PANE_LAYOUT_DESIRED_STATE_CHANNEL {
        let payload = state_plane_snapshot_payload(
            &message,
            PANE_LAYOUT_DESIRED_STATE_CHANNEL,
            PANE_LAYOUT_DESIRED_TYPE_TAG,
        )?;
        let _: ControllerTmuxLayoutSyncInvocation =
            serde_json::from_slice(&payload).context("validate pane-layout desired target")?;
    }
    let (frame, duplicate) = runtime.publish_state_plane_frame(
        invocation.channel,
        invocation.producer_id,
        invocation.message_json,
        epoch,
        base_epoch,
    )?;
    Ok(ControllerStatePlanePublishReceipt {
        accepted: true,
        reason: if duplicate {
            "duplicate_projection"
        } else {
            "target_published"
        }
        .to_string(),
        channel: frame.channel,
        producer_id: frame.producer_id,
        epoch: frame.epoch,
        plane_version: frame.plane_version,
    })
}

pub(crate) fn handle_state_plane_subscribe(
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<ControllerStatePlaneSubscription> {
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let invocation: ControllerStatePlaneSubscribeInvocation =
        serde_json::from_str(&payload_json).context("parse state-plane subscribe invocation")?;
    anyhow::ensure!(
        !invocation.channel.trim().is_empty(),
        "state-plane subscribe channel is empty"
    );
    let timeout = Duration::from_millis(invocation.timeout_ms).min(STATE_PLANE_SUBSCRIBE_MAX);
    let channel = state_plane_subscription_channel(
        runtime.editor_surface_graph.navigation_mode(),
        &invocation.channel,
        invocation.client_id.as_deref(),
    );
    Ok(runtime.subscribe_state_plane(
        &channel,
        invocation.after_controller_generation,
        invocation.after_version,
        timeout,
    ))
}

/// The channel a `state_plane_subscribe` for `channel` by `client_id` reads.
///
/// The pane-layout status channel is per navigation lane
/// (`#ideriderindependentnav` P6): a subscriber naming its client id reads its
/// own lane's channel, so an installation lane's status never shows in another
/// lane. Every other channel, every subscriber without a client id, every
/// unscoped client, and every client in `shared` mode reads `channel`
/// unchanged, which is the pre-lane behavior.
fn state_plane_subscription_channel(
    navigation_mode: agent_doc_editor_surface::NavigationMode,
    channel: &str,
    client_id: Option<&str>,
) -> String {
    match client_id {
        Some(client_id) if channel == PANE_LAYOUT_STATUS_STATE_CHANNEL => {
            super::pane_layout_status_channel(
                &agent_doc_editor_surface::NavigationLane::for_client(navigation_mode, client_id),
            )
        }
        _ => channel.to_string(),
    }
}

#[derive(Default)]
struct PaneLayoutDesiredEffectState {
    pending_frame: Option<ControllerStatePlaneFrame>,
    worker_active: bool,
}

/// The `pane_layout_desired` state-plane sink (`#ideriderindependentnav` P3).
///
/// Every editor plugin publishes its desired layout on the one channel. A
/// frame names its publisher's surface client id (`client_id`); the frame is
/// projected into that client's navigation lane graph. Each lane has its own
/// latest-wins projector, so one installation's newer publication never
/// coalesces away another installation's. In the default `shared` mode, and
/// for every frame without a scoped `client_id`, there is exactly one lane,
/// the shared lane, and the projector is the pre-lane one.
struct PaneLayoutDesiredStatePlaneSink {
    runtime: std::sync::Weak<ControllerRuntime>,
    lanes: Mutex<
        std::collections::BTreeMap<
            agent_doc_editor_surface::NavigationLane,
            Arc<PaneLayoutDesiredLaneEffectSink>,
        >,
    >,
}

impl PaneLayoutDesiredStatePlaneSink {
    fn new(runtime: &Arc<ControllerRuntime>) -> Self {
        Self {
            runtime: Arc::downgrade(runtime),
            lanes: Mutex::new(std::collections::BTreeMap::new()),
        }
    }

    fn projector(
        &self,
        lane: agent_doc_editor_surface::NavigationLane,
    ) -> Arc<PaneLayoutDesiredLaneEffectSink> {
        let mut lanes = self.lanes.lock();
        Arc::clone(lanes.entry(lane.clone()).or_insert_with(|| {
            Arc::new(PaneLayoutDesiredLaneEffectSink {
                lane,
                runtime: self.runtime.clone(),
                state: Arc::new(Mutex::new(PaneLayoutDesiredEffectState::default())),
                wake: Arc::new(Condvar::new()),
                last_applied_version: Arc::new(AtomicU64::new(0)),
            })
        }))
    }
}

impl ControllerStatePlaneSink for PaneLayoutDesiredStatePlaneSink {
    fn project(&self, frame: ControllerStatePlaneFrame) {
        let navigation_mode = self
            .runtime
            .upgrade()
            .map(|runtime| runtime.editor_surface_graph.navigation_mode())
            .unwrap_or_default();
        let lane = pane_layout_state_frame_lane(navigation_mode, &frame);
        if !lane.is_shared()
            && let Some(runtime) = self.runtime.upgrade()
        {
            // `#laneplaneflake`: an installation lane's frame never reaches the
            // shared graph, so the shared lane's plane catch-up counts it as
            // seen here, at dispatch, not after the lane's projector thread
            // applies it. Noting it there left a window where the lane's
            // projection was observable but the shared route still waited, and
            // a lane projector retrying a failed publication held every shared
            // route for its full catch-up budget.
            runtime.note_pane_layout_plane_seen_in_other_lane(frame.plane_version);
        }
        self.projector(lane).project(frame);
    }
}

/// The navigation lane a `pane_layout_desired` frame publishes into: its
/// `client_id`'s lane under `navigation_mode`. A frame without a (decodable)
/// `client_id` is a pre-P3 publisher or a non-editor producer, and stays on
/// the shared lane.
fn pane_layout_state_frame_lane(
    navigation_mode: agent_doc_editor_surface::NavigationMode,
    frame: &ControllerStatePlaneFrame,
) -> agent_doc_editor_surface::NavigationLane {
    #[derive(Deserialize)]
    struct DesiredPublisher {
        #[serde(default)]
        client_id: Option<String>,
    }
    if navigation_mode == agent_doc_editor_surface::NavigationMode::Shared {
        return agent_doc_editor_surface::NavigationLane::Shared;
    }
    let client_id = serde_json::from_str::<lazily::IpcMessage>(&frame.message_json)
        .ok()
        .and_then(|message| {
            state_plane_snapshot_payload(
                &message,
                PANE_LAYOUT_DESIRED_STATE_CHANNEL,
                PANE_LAYOUT_DESIRED_TYPE_TAG,
            )
            .ok()
        })
        .and_then(|payload| serde_json::from_slice::<DesiredPublisher>(&payload).ok())
        .and_then(|publisher| publisher.client_id)
        .unwrap_or_default();
    agent_doc_editor_surface::NavigationLane::for_client(navigation_mode, &client_id)
}

/// One navigation lane's latest-wins `pane_layout_desired` projector.
struct PaneLayoutDesiredLaneEffectSink {
    lane: agent_doc_editor_surface::NavigationLane,
    runtime: std::sync::Weak<ControllerRuntime>,
    state: Arc<Mutex<PaneLayoutDesiredEffectState>>,
    wake: Arc<Condvar>,
    last_applied_version: Arc<AtomicU64>,
}

impl PaneLayoutDesiredLaneEffectSink {
    fn project(&self, frame: ControllerStatePlaneFrame) {
        if frame.plane_version <= self.last_applied_version.load(Ordering::SeqCst) {
            return;
        }
        let should_spawn = {
            let mut state = self.state.lock();
            if state
                .pending_frame
                .as_ref()
                .is_some_and(|current| current.plane_version >= frame.plane_version)
            {
                return;
            }
            state.pending_frame = Some(frame);
            if state.worker_active {
                false
            } else {
                state.worker_active = true;
                true
            }
        };
        self.wake.notify_one();
        if !should_spawn {
            return;
        }
        let runtime = self.runtime.clone();
        let lane = self.lane.clone();
        let state = Arc::clone(&self.state);
        let wake = Arc::clone(&self.wake);
        let last_applied_version = Arc::clone(&self.last_applied_version);
        let spawn = std::thread::Builder::new()
            .name("agent-doc-state-plane-projector".to_string())
            .spawn(move || {
                pane_layout_desired_effect_worker(runtime, lane, state, wake, last_applied_version);
            });
        if let Err(error) = spawn {
            self.state.lock().worker_active = false;
            eprintln!("[controller] failed to spawn state-plane projector: {error}");
        }
    }
}

fn pane_layout_desired_effect_worker(
    runtime: std::sync::Weak<ControllerRuntime>,
    lane: agent_doc_editor_surface::NavigationLane,
    state: Arc<Mutex<PaneLayoutDesiredEffectState>>,
    wake: Arc<Condvar>,
    last_applied_version: Arc<AtomicU64>,
) {
    let mut attempt = 0_u64;
    loop {
        let Some(runtime) = runtime.upgrade() else {
            state.lock().worker_active = false;
            return;
        };
        let frame = {
            let mut state = state.lock();
            let Some(frame) = state.pending_frame.clone() else {
                state.worker_active = false;
                return;
            };
            frame
        };
        if frame.plane_version <= last_applied_version.load(Ordering::SeqCst) {
            let mut state = state.lock();
            if state
                .pending_frame
                .as_ref()
                .is_some_and(|current| current.plane_version <= frame.plane_version)
            {
                state.pending_frame.take();
            }
            attempt = 0;
            continue;
        }

        let result = pane_layout_invocation_from_state_frame(&frame).and_then(|invocation| {
            let bootstrap = runtime.bootstrap_snapshot()?;
            let publication = pane_layout_publication_for_invocation(&invocation);
            publish_pane_layout_desired_invocation_in_lane(
                &bootstrap,
                &runtime,
                &lane,
                invocation,
                Some(frame.plane_version),
                publication,
                PaneLayoutPublisher::PluginPublication,
            )?;
            Ok(bootstrap)
        });
        match result {
            Ok(bootstrap) => {
                last_applied_version.store(frame.plane_version, Ordering::SeqCst);
                let mut state = state.lock();
                if state
                    .pending_frame
                    .as_ref()
                    .is_some_and(|current| current.plane_version <= frame.plane_version)
                {
                    state.pending_frame.take();
                }
                agent_doc_ops_log_io::log_op(
                    &bootstrap.project_root,
                    &format!(
                        "pane_layout_desired_accepted plane_version={} producer={} epoch={}{}",
                        frame.plane_version,
                        frame.producer_id,
                        frame.epoch,
                        lane.installation()
                            .map(|installation| format!(" navigation_lane={installation}"))
                            .unwrap_or_default(),
                    ),
                );
                attempt = 0;
            }
            Err(error) => {
                attempt = attempt.saturating_add(1);
                if let Ok(bootstrap) = runtime.bootstrap_snapshot() {
                    agent_doc_ops_log_io::log_op(
                        &bootstrap.project_root,
                        &format!(
                            "pane_layout_desired_effect_retry_scheduled plane_version={} attempt={} error={error:#}",
                            frame.plane_version, attempt
                        ),
                    );
                }
                let retry_delay = tmux_layout_effect_state_retry_delay(attempt);
                let mut effect_state = state.lock();
                if effect_state
                    .pending_frame
                    .as_ref()
                    .is_some_and(|current| current.plane_version > frame.plane_version)
                {
                    attempt = 0;
                    continue;
                }
                wake.wait_for(&mut effect_state, retry_delay);
                if effect_state
                    .pending_frame
                    .as_ref()
                    .is_some_and(|current| current.plane_version > frame.plane_version)
                {
                    attempt = 0;
                }
            }
        }
    }
}

fn tmux_layout_effect_state_retry_delay(attempt: u64) -> Duration {
    let shift = attempt.saturating_sub(1).min(5) as u32;
    TMUX_LAYOUT_EFFECT_RETRY_MIN
        .saturating_mul(1_u32 << shift)
        .min(TMUX_LAYOUT_EFFECT_RETRY_MAX)
}

pub(crate) fn install_state_plane_effect_sinks(runtime: &Arc<ControllerRuntime>) {
    runtime.install_state_plane_sink(
        PANE_LAYOUT_DESIRED_STATE_CHANNEL,
        Arc::new(PaneLayoutDesiredStatePlaneSink::new(runtime)),
    );
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
struct ControllerTmuxLayoutEffectSink {
    runtime: std::sync::Weak<ControllerRuntime>,
    /// The navigation lane whose graph this sink (and its worker) serves.
    lane: agent_doc_editor_surface::NavigationLane,
    state: Arc<Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>>,
    wake: Arc<Condvar>,
    next_work_revision: AtomicU64,
}

impl TmuxLayoutEffectSink for ControllerTmuxLayoutEffectSink {
    fn reconcile(&self, _desired: PaneLayoutDesired) {
        let work_revision = self.next_work_revision.fetch_add(1, Ordering::SeqCst);
        let should_spawn = {
            let mut state = self.state.lock();
            state.schedule(work_revision)
        };
        self.wake.notify_all();
        if !should_spawn {
            return;
        }
        spawn_pane_layout_effect_worker(
            self.runtime.clone(),
            self.lane.clone(),
            Arc::clone(&self.state),
            Arc::clone(&self.wake),
        );
    }
}

/// Start the single latest-wins worker behind an unwind boundary.
///
/// An effect panic used to terminate this detached thread while leaving
/// `LatestTmuxEffectWorkerState::active` latched. Every later editor selection
/// then updated `pending_revision` but declined to spawn, permanently disabling
/// tmux auto-sync until the controller restarted. Retire the failed revision
/// atomically, then poison this controller generation so a clean graph owns any
/// revision that raced with the panic (GH #354).
#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn spawn_pane_layout_effect_worker(
    runtime: std::sync::Weak<ControllerRuntime>,
    lane: agent_doc_editor_surface::NavigationLane,
    state: Arc<Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>>,
    wake: Arc<Condvar>,
) {
    let worker_runtime = runtime.clone();
    let worker_lane = lane.clone();
    let worker_state = Arc::clone(&state);
    let worker_wake = Arc::clone(&wake);
    let spawn = std::thread::Builder::new()
        .name("agent-doc-pane-layout-effect".to_string())
        .spawn(move || {
            let executing_revision = AtomicU64::new(0);
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                pane_layout_effect_worker(
                    worker_runtime,
                    worker_lane,
                    Arc::clone(&worker_state),
                    worker_wake,
                    &executing_revision,
                );
            }));
            if outcome.is_ok() {
                return;
            }

            let failed_revision = executing_revision.load(Ordering::SeqCst);
            let pending_revision_waiting =
                worker_state.lock().recover_after_failure(failed_revision);
            if let Some(runtime) = runtime.upgrade() {
                runtime.poison_controller_generation();
            }
            eprintln!(
                "[controller] pane-layout effect worker panicked at revision {failed_revision}; controller_generation_poisoned=true pending_revision_waiting={pending_revision_waiting}"
            );
        });
    if let Err(error) = spawn {
        state.lock().deactivate();
        eprintln!("[controller] failed to spawn pane-layout effect worker: {error}");
    }
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
pub(super) fn install_tmux_layout_effect_state_sink(runtime: &Arc<ControllerRuntime>) {
    // `#ideriderindependentnav` P2b: one sink, latest-wins worker state, and
    // structural-effect cancellation generation per navigation lane, so one
    // lane's newer layout never supersedes or cancels another lane's sync.
    let weak = Arc::downgrade(runtime);
    runtime.install_pane_layout_sink_factory(Arc::new(move |lane| {
        Arc::new(ControllerTmuxLayoutEffectSink {
            runtime: weak.clone(),
            lane: lane.clone(),
            state: Arc::new(Mutex::new(
                agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default(),
            )),
            wake: Arc::new(Condvar::new()),
            next_work_revision: AtomicU64::new(1),
        }) as Arc<dyn TmuxLayoutEffectSink>
    }));
}

fn pane_layout_state_invocation(
    desired: &PaneLayoutDesired,
) -> ControllerTmuxLayoutSyncStateInvocation {
    ControllerTmuxLayoutSyncStateInvocation {
        columns: desired.invocation.columns.clone(),
        window: desired.invocation.window.clone(),
        focus: desired.invocation.focus.clone(),
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct PaneLayoutFocusEffectReceipt {
    required: bool,
    applied: bool,
    reason: String,
}

/// A missing file→pane assignment cannot become true by replaying the same
/// automatic editor-surface generation. The next editor observation owns any
/// structural change that could make the focused document visible. Retire the
/// current generation after proving its structure instead of letting an
/// impossible focus target hold the single pane-effect worker in its retry
/// ladder. Manual commands and live-pane/co-visibility failures retain their
/// existing fail-closed retry semantics.
fn focus_required_for_pane_layout_generation(
    caller_kind: &str,
    receipt: &PaneLayoutFocusEffectReceipt,
) -> bool {
    receipt.required
        && !(caller_kind == "automatic" && receipt.reason.starts_with("focus_pane_not_found:"))
}

/// Convergence is an *observation*, never a receipt for the effect this pass
/// happened to run.
///
/// `#tmuxautosyncwedge`: the observation invocation carries the focus target
/// exactly when focus is required, and `layout_sync_state_result` then refuses
/// `synced` unless `expected_focus_pane == active_pane`. A synced report that
/// observed focus has therefore already proven the focused pane is active. Also
/// demanding `focus_receipt.applied` re-gates that proof on *which generation*
/// called `select-pane`, and a project under continuous editor-revision churn
/// never satisfies it: every pass is superseded before its focus effect,
/// returns `focus_superseded_by_newer_layout_state` with `applied: false`, and
/// the projection stays `retry_pending` while documents, panes and focus pane
/// all match. The supersede guard still keeps a stale generation from *moving*
/// focus; it just no longer denies what the live layout already shows.
///
/// `focus_applied` remains the fallback for the one case where the observation
/// could not speak for focus — a required focus the observation invocation did
/// not carry.
fn tmux_layout_effect_state_converged(
    report_synced: bool,
    focus_required: bool,
    focus_target_observed: bool,
    focus_applied: bool,
) -> bool {
    report_synced && (!focus_required || focus_target_observed || focus_applied)
}

/// A durable ownership conflict cannot change by replaying the same layout
/// effect. A later document/session edit publishes a new generation instead.
fn pane_layout_effect_failure_is_terminal(error: &anyhow::Error) -> bool {
    error
        .downcast_ref::<agent_doc_session_registry_io::SessionIdentityConflict>()
        .is_some()
}

/// Resolve the window this pane-layout generation is arranging its columns in.
///
/// `#panewindowdrift`: the focus guard needs an explicit *visible window*
/// reference, and this is the one the model already owns — the same resolution
/// [`tmux_layout_sync_state_for_invocation_with_effect_assignment`] performs
/// before it lists the layout's panes. It is per-invocation, so a legitimate
/// multi-window layout keeps its own reference; nothing is inferred from where
/// the active pane, the first column, or the majority of panes happen to be.
///
/// Only a window **id** is returned, because the live side of the comparison is
/// `#{window_id}`. An `invocation.window` that is a name (`agent-doc`) resolves
/// through the by-name lookup rather than being compared against an id. An
/// unresolvable window yields `None`, which
/// [`pane_window_binding_drifted`](agent_doc_controller::pane_layout::pane_window_binding_drifted)
/// never treats as drift.
/// Read the window a pane currently lives in. Best-effort: a tmux that cannot
/// answer yields `None`, which `pane_window_binding_drifted` never treats as
/// drift. Mirrors `session_actor_cmd::observe_live_pane_window`.
/// Live `(window_id, window_name)` for a pane, or `None` when tmux cannot say.
///
/// `#stashfocusleg`: the NAME half is what lets the focus guard refuse a stashed
/// pane without first resolving the layout's target window.
fn observe_pane_window_id(tmux: &tmux_router::Tmux, pane_id: &str) -> Option<LivePaneWindow> {
    observed_live_pane_window(tmux.raw_cmd(&[
        "display-message",
        "-t",
        pane_id,
        "-p",
        "#{window_id}\t#{window_active}\t#{window_name}",
    ]))
}

/// One live tmux observation of the window a pane is in: id, name and
/// whether it is its session's active window (`None` when tmux did not say).
#[derive(Clone, Debug, PartialEq, Eq)]
struct LivePaneWindow {
    id: String,
    name: String,
    active: Option<bool>,
}

impl From<(String, String)> for LivePaneWindow {
    fn from((id, name): (String, String)) -> Self {
        Self {
            id,
            name,
            active: None,
        }
    }
}

/// Parse a `#{window_id}\t#{window_active}\t#{window_name}` read, read in one
/// query so the three halves cannot disagree across a concurrent
/// `move-window`. The id/name normalization is [`observed_pane_window`]'s.
fn observed_live_pane_window(line: Result<String>) -> Option<LivePaneWindow> {
    let line = line.ok()?;
    let mut fields = line.trim_end_matches(['\r', '\n']).splitn(3, '\t');
    let id = fields.next().unwrap_or_default().to_string();
    let active = match fields.next().map(str::trim) {
        Some("1") => Some(true),
        Some("0") => Some(false),
        _ => None,
    };
    let name = fields.next().unwrap_or_default().to_string();
    let (id, name) = observed_pane_window(Ok((id, name)))?;
    Some(LivePaneWindow { id, name, active })
}

/// Normalize a `pane_window_identity` read into the guard's observation.
///
/// `#stashfocusleg`: split out from the tmux call so the NAME half is covered.
/// The stash refusal leg is only as good as this mapping — an adapter that
/// quietly dropped the name would disable that leg in production while every
/// test over the pure guard stayed green.
///
/// An unreadable pane or an empty window id is "tmux could not say", which both
/// refusal legs treat as never-a-refusal.
fn observed_pane_window(identity: Result<(String, String)>) -> Option<(String, String)> {
    identity
        .ok()
        .map(|(id, name)| (id.trim().to_string(), name.trim().to_string()))
        .filter(|(id, _)| !id.is_empty())
}

/// tmux user option that marks a session agent-doc created as a navigation lane
/// (`#ideriderindependentnav` P2b). Its value is the project root. A session with
/// the lane's name but without this mark was not started by agent-doc, so it is
/// never adopted (`#bare-foreign-session-guard`); P5's lane GC reaps only marked
/// sessions.
const NAVIGATION_LANE_SESSION_OPTION: &str = "@agent_doc_navigation_lane";

/// tmux pane option that marks a shell pane agent-doc itself created inside a
/// navigation lane session: the lane's initial `agent-doc` pane, its `stash`
/// shell, and a handoff placeholder (`#lanegcflake`). Its value is the project
/// root.
///
/// The lane GC cannot read "idle" from `#{pane_current_command}` on such a pane
/// while its shell is still starting: before `exec` the pane reports `tmux`,
/// and the shell's rc files run foreground children (`grep`, `mkdir`, `diff`,
/// prompt helpers) that each read as a running program. A marked pane in a
/// lane session no client has ever attached to cannot hold anything the
/// operator started, so [`navigation_lane_pane_busy`] treats it as idle
/// whatever its startup is running. Once a client has attached, the mark no
/// longer applies and the pane's foreground command decides again.
const NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION: &str = "@agent_doc_navigation_lane_placeholder";

/// Mark `pane` as a shell agent-doc created in a navigation lane of
/// `project_root` ([`NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION`]). Best effort:
/// an unmarked placeholder is only ever classified by its foreground command,
/// which errs toward keeping the lane.
fn mark_navigation_lane_placeholder_pane(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    pane: &str,
) {
    let root = project_root.to_string_lossy().to_string();
    let marked = tmux
        .cmd()
        .args([
            "set-option",
            "-p",
            "-q",
            "-t",
            pane,
            NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION,
            &root,
        ])
        .output();
    if !marked.as_ref().is_ok_and(|output| output.status.success()) {
        agent_doc_ops_log_io::log_op(
            project_root,
            &format!("navigation_lane_placeholder_mark_failed pane={pane}"),
        );
    }
}

/// Clear [`NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION`] from a lane placeholder
/// that agent-doc hands to a document (`#ideriderindependentnav` P6: an
/// outside-tmux `agent-doc start --client-id` takes over a new lane's idle
/// `agent-doc` pane). From then on the pane's foreground command decides
/// whether it keeps the lane, so a gc never closes a lane under a starting
/// harness. Best effort, like the mark.
pub fn release_navigation_lane_placeholder_pane(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    pane: &str,
) {
    let released = tmux
        .cmd()
        .args([
            "set-option",
            "-p",
            "-q",
            "-u",
            "-t",
            pane,
            NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION,
        ])
        .output();
    if !released
        .as_ref()
        .is_ok_and(|output| output.status.success())
    {
        agent_doc_ops_log_io::log_op(
            project_root,
            &format!("navigation_lane_placeholder_release_failed pane={pane}"),
        );
    }
}

/// Whether one pane of a marked navigation lane session keeps the lane alive
/// as the operator's work (`#lanegcflake`).
///
/// `untouched_placeholder`: the pane carries
/// [`NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION`] for this root and no tmux
/// client has ever attached to its session (`#{session_last_attached}` is
/// empty). Such a pane is idle by construction, so its shell's startup
/// commands never make it busy. Every other pane is busy unless its
/// foreground command is a known bare shell (false-alive over false-dead).
fn navigation_lane_pane_busy(untouched_placeholder: bool, current_command: &str) -> bool {
    !untouched_placeholder
        && agent_doc_supervisor_process::session_liveness::pane_owns_live_agent_from_signals(
            true,
            Some(current_command),
        )
}

/// The `(project session, lane session)` pair one navigation lane arranges, when
/// lane membership applies at all.
///
/// `None` in shared navigation mode (every lane check is skipped, which is the
/// pre-lane behavior) and when the project has no `tmux_session` pin to derive
/// lane sessions from. In per-installation mode the shared lane is
/// `(pin, pin)`, and an installation lane is `(pin, <pin>-<installation>)`.
fn navigation_lane_sessions(
    project_root: &Path,
    navigation_mode: agent_doc_editor_surface::NavigationMode,
    lane: &agent_doc_editor_surface::NavigationLane,
) -> Option<(String, String)> {
    if navigation_mode != agent_doc_editor_surface::NavigationMode::PerInstallation {
        return None;
    }
    let project_session = configured_tmux_session_for_project(project_root)?;
    let lane_session = lane.tmux_session_name(&project_session);
    Some((project_session, lane_session))
}

/// Where one lane's pane-layout effect lands (`#ideriderindependentnav` P2b).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct PaneLayoutLaneRoute {
    /// `(project session, lane session)` when lane membership applies.
    sessions: Option<(String, String)>,
    /// The installation lane session's `agent-doc` window id. `None` for the
    /// shared lane, which keeps its existing window resolution.
    window: Option<String>,
    /// The installation lane session was created by this pass.
    provisioned: bool,
}

impl PaneLayoutLaneRoute {
    /// The session an installation lane's drift survey observes. The shared
    /// lane keeps the project-pin survey (`None`).
    fn observation_session(&self) -> Option<&str> {
        self.window.as_ref()?;
        self.sessions
            .as_ref()
            .map(|(_, lane_session)| lane_session.as_str())
    }
}

/// Resolve (and on first use provision) the tmux surface of `lane`.
///
/// Shared mode and the shared lane never provision: they return the existing
/// route unchanged. An installation lane requires a project `tmux_session` pin
/// to derive its session from; its session is created on its first driving
/// layout, with the canonical `agent-doc` and `stash` windows. A failure is a
/// terminal refusal reason, not a retry: the next editor observation re-derives.
fn pane_layout_lane_route(
    project_root: &Path,
    navigation_mode: agent_doc_editor_surface::NavigationMode,
    lane: &agent_doc_editor_surface::NavigationLane,
    tmux: &tmux_router::Tmux,
) -> std::result::Result<PaneLayoutLaneRoute, String> {
    if navigation_mode != agent_doc_editor_surface::NavigationMode::PerInstallation {
        return Ok(PaneLayoutLaneRoute::default());
    }
    let sessions = navigation_lane_sessions(project_root, navigation_mode, lane);
    if lane.is_shared() {
        return Ok(PaneLayoutLaneRoute {
            sessions,
            ..PaneLayoutLaneRoute::default()
        });
    }
    let Some((project_session, lane_session)) = sessions else {
        return Err("navigation_lane_requires_tmux_session".to_string());
    };
    let provisioned = ensure_navigation_lane_session(tmux, project_root, &lane_session)?;
    let Some(window) = resolve_agent_doc_window_id_for_session(tmux, &lane_session) else {
        return Err(format!(
            "navigation_lane_session_missing_agent_doc_window:{lane_session}"
        ));
    };
    Ok(PaneLayoutLaneRoute {
        sessions: Some((project_session, lane_session)),
        window: Some(window),
        provisioned,
    })
}

/// The tmux session one editor client's own navigation lane lives in, created
/// on first use (`#ideriderindependentnav` P3).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NavigationLaneSession {
    /// The installation id of the lane.
    pub installation: String,
    /// `<project session>-<installation>`.
    pub session: String,
    /// This call created the session.
    pub provisioned: bool,
}

/// Resolve, and on first use provision, the lane session `client_id`
/// navigates, for a caller outside the controller (the IDE terminal attach).
///
/// `Ok(None)` means the client navigates the shared lane: the project's
/// `editor_navigation` is `shared` (the default), the client is not
/// installation-scoped, or the project has no `tmux_session` pin to derive a
/// lane session from. Each of those keeps the pre-lane attach target. An
/// installation lane is provisioned exactly like the controller's first
/// driving layout does ([`pane_layout_lane_route`]); a same-named session that
/// agent-doc did not create is an error, never adopted.
pub fn navigation_lane_session_for_client(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    client_id: &str,
) -> Result<Option<NavigationLaneSession>> {
    let (navigation_mode, _) =
        agent_doc_project_config_io::editor_navigation_mode_for_root(project_root);
    let lane = agent_doc_editor_surface::NavigationLane::for_client(navigation_mode, client_id);
    let Some(installation) = lane.installation().map(str::to_string) else {
        return Ok(None);
    };
    let Some((_, session)) = navigation_lane_sessions(project_root, navigation_mode, &lane) else {
        return Ok(None);
    };
    let provisioned = ensure_navigation_lane_session(tmux, project_root, &session)
        .map_err(|reason| anyhow::anyhow!("{reason}"))?;
    Ok(Some(NavigationLaneSession {
        installation,
        session,
        provisioned,
    }))
}

/// The `(project session, lane session)` `client_id`'s own installation lane
/// would use for `project_root`, without creating it (`#ideriderindependentnav`
/// P6). `None` exactly when [`navigation_lane_session_for_client`] returns
/// `Ok(None)`: `shared` mode, an unscoped client, or no `tmux_session` pin.
pub fn navigation_lane_session_name_for_client(
    project_root: &Path,
    client_id: &str,
) -> Option<(String, String)> {
    let (navigation_mode, _) =
        agent_doc_project_config_io::editor_navigation_mode_for_root(project_root);
    let lane = agent_doc_editor_surface::NavigationLane::for_client(navigation_mode, client_id);
    lane.installation()?;
    navigation_lane_sessions(project_root, navigation_mode, &lane)
}

/// Whether `session` is an installation navigation lane session agent-doc
/// created for `project_root` (`#ideriderindependentnav` P6). A session that
/// merely carries a lane's name, and the project's own session, are not.
pub fn is_owned_navigation_lane_session(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    session: &str,
) -> bool {
    !session.trim().is_empty() && navigation_lane_session_marked(tmux, project_root, session)
}

/// Create `lane_session` with `agent-doc` + `stash` windows unless agent-doc
/// already created it. Returns whether this call created it.
///
/// An existing session is reused only when it carries
/// [`NAVIGATION_LANE_SESSION_OPTION`] for this project root; any other session
/// with the lane's name is refused, never adopted or killed.
fn ensure_navigation_lane_session(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    lane_session: &str,
) -> std::result::Result<bool, String> {
    let root = project_root.to_string_lossy().to_string();
    if tmux.session_alive(lane_session) {
        return if navigation_lane_session_marked(tmux, project_root, lane_session) {
            Ok(false)
        } else {
            Err(format!("navigation_lane_session_not_owned:{lane_session}"))
        };
    }
    tmux_router::invalidate_pane_snapshot();
    let created = tmux
        .cmd()
        .args([
            "new-session",
            "-d",
            "-s",
            lane_session,
            "-n",
            "agent-doc",
            "-c",
            &root,
            "-P",
            "-F",
            "#{pane_id}",
        ])
        .output()
        .map_err(|error| format!("navigation_lane_session_create_failed:{error}"))?;
    if !created.status.success() {
        return Err(format!(
            "navigation_lane_session_create_failed:{}",
            String::from_utf8_lossy(&created.stderr).trim()
        ));
    }
    let marked = tmux
        .cmd()
        .args([
            "set-option",
            "-q",
            "-t",
            &format!("{lane_session}:"),
            NAVIGATION_LANE_SESSION_OPTION,
            &root,
        ])
        .output()
        .map_err(|error| format!("navigation_lane_session_mark_failed:{error}"))?;
    if !marked.status.success() {
        return Err(format!(
            "navigation_lane_session_mark_failed:{}",
            String::from_utf8_lossy(&marked.stderr).trim()
        ));
    }
    let initial_pane = String::from_utf8_lossy(&created.stdout).trim().to_string();
    if !initial_pane.is_empty() {
        mark_navigation_lane_placeholder_pane(tmux, project_root, &initial_pane);
    }
    let stash_window = tmux
        .ensure_stash_window(lane_session)
        .map_err(|error| format!("navigation_lane_stash_create_failed:{error:#}"))?;
    // The stash window was created just now, so its only pane is its shell.
    for stash_pane in tmux.list_window_panes(&stash_window).unwrap_or_default() {
        mark_navigation_lane_placeholder_pane(tmux, project_root, &stash_pane);
    }
    agent_doc_ops_log_io::log_op(
        project_root,
        &format!("navigation_lane_session_created session={lane_session} windows=agent-doc,stash"),
    );
    Ok(true)
}

/// One pane an explicit claim hands over to the requesting navigation lane
/// (`#ideriderindependentnav` P4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NavigationLaneHandoff {
    /// The layout document whose pane moves.
    pub document: String,
    /// The document's pane (its actor binding).
    pub pane: String,
    /// The lane session the pane lived in when the claim was routed.
    pub from_session: String,
}

/// One lane's desired layout after its lane route was applied.
#[derive(Clone, Debug, PartialEq, Eq)]
struct LaneRoutedLayout {
    desired: PaneLayoutDesired,
    /// `(document, owner session)` left in the lane that owns its pane.
    dropped: Vec<(String, String)>,
    /// Panes an explicit claim hands over to this lane before it projects.
    handoffs: Vec<NavigationLaneHandoff>,
}

/// Apply one lane's route to the desired layout it is about to project.
///
/// A passive publication (every `caller_kind` but `manual`) drops each document
/// whose live pane belongs to another lane of this project from this lane's
/// columns (`cross_lane_layout_dropped`), so the structural effect can never
/// `join-pane` it across sessions; a focus target among them is dropped too.
/// An explicit claim (`manual`: `Sync Tmux Layout`, the sync that follows
/// `Claim for Tmux Pane`) keeps those documents and lists their panes as
/// handoffs for the worker to move into this lane first (P4). An installation
/// lane targets its own session's `agent-doc` window explicitly. Without lane
/// sessions (shared navigation mode) this is identity.
fn route_pane_layout_desired_to_lane(
    project_root: &Path,
    route: &PaneLayoutLaneRoute,
    mut desired: PaneLayoutDesired,
    actor_bindings: &[ControllerTmuxActorBinding],
    mut pane_session: impl FnMut(&str) -> Option<String>,
) -> LaneRoutedLayout {
    let Some((project_session, lane_session)) = route.sessions.as_ref() else {
        return LaneRoutedLayout {
            desired,
            dropped: Vec::new(),
            handoffs: Vec::new(),
        };
    };
    let claim =
        agent_doc_editor_surface::LaneClaim::for_caller_kind(&desired.invocation.caller_kind);
    let mut panes = BTreeMap::<String, String>::new();
    let partition = agent_doc_editor_surface::partition_lane_layout_columns_for_claim(
        &desired.invocation.columns,
        project_session,
        lane_session,
        claim,
        |file| {
            let document = canonical_layout_document_id(project_root, file);
            let pane = actor_bindings
                .iter()
                .find(|binding| {
                    canonical_layout_document_id(project_root, &binding.document_path) == document
                })
                .map(|binding| binding.pane_id.clone())?;
            panes.insert(file.to_string(), pane.clone());
            pane_session(&pane)
        },
    );
    if let Some(focus) = desired.invocation.focus.as_deref() {
        let focus_id = canonical_layout_document_id(project_root, focus);
        if partition
            .dropped
            .iter()
            .any(|(document, _)| canonical_layout_document_id(project_root, document) == focus_id)
        {
            desired.invocation.focus = None;
        }
    }
    desired.invocation.columns = partition.kept;
    if let Some(window) = route.window.as_ref() {
        desired.invocation.window = Some(window.clone());
    }
    let handoffs = partition
        .handoffs
        .into_iter()
        .filter_map(|(document, from_session)| {
            let pane = panes.get(&document)?.clone();
            Some(NavigationLaneHandoff {
                document,
                pane,
                from_session,
            })
        })
        .collect();
    LaneRoutedLayout {
        desired,
        dropped: partition.dropped,
        handoffs,
    }
}

/// Remove `document` (and a focus on it) from a lane's routed invocation after
/// its handoff was refused, so the structural effect never joins the pane
/// across sessions.
fn drop_document_from_lane_invocation(
    project_root: &Path,
    invocation: &mut ControllerTmuxLayoutSyncInvocation,
    document: &str,
) {
    let document_id = canonical_layout_document_id(project_root, document);
    let is_document = |file: &str| canonical_layout_document_id(project_root, file) == document_id;
    invocation.columns = invocation
        .columns
        .iter()
        .filter_map(|column| {
            let kept = column
                .split(',')
                .map(str::trim)
                .filter(|file| !file.is_empty() && !is_document(file))
                .collect::<Vec<_>>();
            (!kept.is_empty()).then(|| kept.join(","))
        })
        .collect();
    if invocation.focus.as_deref().is_some_and(is_document) {
        invocation.focus = None;
    }
}

/// What one explicit handoff did.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NavigationLaneHandoffOutcome {
    /// The pane moved into the requesting lane session's `stash` window, from
    /// where the lane's structural sync places it. `placeholder` is the empty
    /// shell pane left behind when the pane was the last one in its lane's
    /// `agent-doc` window, so that window survives for the old lane.
    Moved { placeholder: Option<String> },
    /// The pane already lives in the requesting lane (an earlier attempt of
    /// the same claim moved it).
    AlreadyInLane,
}

/// Whether agent-doc created `session` as a navigation lane of `project_root`
/// (it carries [`NAVIGATION_LANE_SESSION_OPTION`] with this root). The sync
/// body reads it to retarget a shared-mode sync away from a stale lane
/// (`#ridernavp6switchback`).
pub fn navigation_lane_session_marked(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    session: &str,
) -> bool {
    let root = project_root.to_string_lossy();
    tmux.cmd()
        .args([
            "show-options",
            "-qv",
            "-t",
            &format!("{session}:"),
            NAVIGATION_LANE_SESSION_OPTION,
        ])
        .output()
        .ok()
        .filter(|output| output.status.success())
        .is_some_and(|output| String::from_utf8_lossy(&output.stdout).trim() == root)
}

/// Move one pane between two lane sessions of this project for an explicit
/// claim (`#ideriderindependentnav` P4).
///
/// Both sessions must be lanes agent-doc owns: the project's configured
/// session, or an installation lane session marked for this root. A session
/// that merely carries a lane's name is refused, never touched
/// (`#bare-foreign-session-guard`). The pane must still live in the session
/// the claim was routed against; if it already lives in `lane_session` this is
/// a no-op. When the pane is the last one in its lane's `agent-doc` window, an
/// empty shell pane is left in its place so the old lane keeps its window (its
/// next sync stashes that shell inside its own session). The pane lands in the
/// lane session's `stash` window and its id is unchanged, so its actor binding
/// stays valid; ownership is where the pane lives, so no other record moves.
pub fn hand_over_navigation_lane_pane(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    project_session: &str,
    lane_session: &str,
    handoff: &NavigationLaneHandoff,
) -> std::result::Result<NavigationLaneHandoffOutcome, String> {
    let owned = |session: &str| {
        session == project_session
            || (agent_doc_editor_surface::is_lane_session_of(project_session, session)
                && navigation_lane_session_marked(tmux, project_root, session))
    };
    if !owned(lane_session) {
        return Err(format!(
            "navigation_lane_handoff_target_not_owned:{lane_session}"
        ));
    }
    if !owned(&handoff.from_session) {
        return Err(format!(
            "navigation_lane_handoff_source_not_owned:{}",
            handoff.from_session
        ));
    }
    tmux_router::invalidate_pane_snapshot();
    let current = tmux
        .pane_session(&handoff.pane)
        .map_err(|_| format!("navigation_lane_handoff_pane_missing:{}", handoff.pane))?;
    if current == lane_session {
        return Ok(NavigationLaneHandoffOutcome::AlreadyInLane);
    }
    if current != handoff.from_session {
        return Err(format!(
            "navigation_lane_handoff_pane_moved:{}:{current}",
            handoff.pane
        ));
    }
    let window = tmux
        .raw_cmd(&[
            "display-message",
            "-p",
            "-t",
            &handoff.pane,
            "#{window_panes} #{window_name}",
        ])
        .map_err(|error| format!("navigation_lane_handoff_window_unreadable:{error:#}"))?;
    let (pane_count, window_name) = window.trim().split_once(' ').unwrap_or((window.trim(), ""));
    let placeholder = if pane_count == "1" && window_name == "agent-doc" {
        let root = project_root.to_string_lossy().to_string();
        let placeholder = tmux
            .raw_cmd(&[
                "split-window",
                "-d",
                "-t",
                &handoff.pane,
                "-c",
                &root,
                "-P",
                "-F",
                "#{pane_id}",
            ])
            .map_err(|error| format!("navigation_lane_handoff_placeholder_failed:{error:#}"))?;
        let placeholder = placeholder.trim().to_string();
        mark_navigation_lane_placeholder_pane(tmux, project_root, &placeholder);
        Some(placeholder)
    } else {
        None
    };
    let moved = tmux.stash_pane(&handoff.pane, lane_session);
    tmux_router::invalidate_pane_snapshot();
    match tmux.pane_session(&handoff.pane) {
        Ok(session) if session == lane_session => {
            Ok(NavigationLaneHandoffOutcome::Moved { placeholder })
        }
        Ok(session) => Err(format!(
            "navigation_lane_handoff_move_failed:{}:{session}:{}",
            handoff.pane,
            moved
                .err()
                .map(|error| format!("{error:#}"))
                .unwrap_or_default()
        )),
        Err(_) => Err(format!(
            "navigation_lane_handoff_pane_missing:{}",
            handoff.pane
        )),
    }
}

/// What the navigation-lane reconcile did for one project
/// (`#ideriderindependentnav` P5).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct NavigationLaneReconcileReport {
    /// The project's navigation mode the plan was made for.
    pub mode: agent_doc_editor_surface::NavigationMode,
    /// The planned actions (all of them, also under `dry_run`).
    pub actions: Vec<agent_doc_editor_surface::LaneReconcileAction>,
    /// `(lane session, pane)` folded back into the project session.
    pub folded: Vec<(String, String)>,
    /// Lane sessions closed.
    pub closed: Vec<String>,
    /// Actions that were planned but refused or failed when applied.
    pub failures: Vec<String>,
}

/// Observe every installation lane session of `project_session` on `tmux`.
fn observe_navigation_lane_sessions(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    project_session: &str,
    liveness: &agent_doc_editor_surface::LaneLiveness,
) -> Vec<agent_doc_editor_surface::LaneSessionObservation> {
    let Ok(sessions) = tmux.raw_cmd(&[
        "list-sessions",
        "-F",
        // `last:` keeps an empty (never attached) value from being trimmed
        // off the end of the output.
        "#{session_name}\t#{session_attached}\tlast:#{session_last_attached}",
    ]) else {
        return Vec::new();
    };
    // Without the registry no pane can be proven unowned, so observe nothing
    // (nothing is folded or closed) rather than mistake a document for a shell.
    let Ok(registry) = agent_doc_session_registry_io::load_in(project_root) else {
        return Vec::new();
    };
    let owned_panes = registry
        .values()
        .map(|entry| entry.pane.trim().to_string())
        .filter(|pane| !pane.is_empty())
        .collect::<BTreeSet<_>>();
    sessions
        .lines()
        .filter_map(|line| {
            let mut fields = line.splitn(3, '\t');
            let session = fields.next()?;
            let attached = fields.next().unwrap_or("");
            // An unreadable attach history counts as attached once, so the
            // placeholder rule never applies on a read it cannot trust.
            let ever_attached = fields
                .next()
                .and_then(|last| last.strip_prefix("last:"))
                .is_none_or(|last| !last.trim().is_empty());
            agent_doc_editor_surface::is_lane_session_of(project_session, session).then(|| {
                (
                    session.to_string(),
                    attached.trim().parse::<usize>().unwrap_or(1),
                    ever_attached,
                )
            })
        })
        .map(|(session, attached, ever_attached)| {
            let marked = navigation_lane_session_marked(tmux, project_root, &session);
            let panes = if marked {
                tmux.raw_cmd(&[
                    "list-panes",
                    "-s",
                    "-t",
                    &format!("={session}:"),
                    "-F",
                    &format!(
                        "#{{pane_id}}\t#{{pane_current_command}}\t#{{{NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION}}}"
                    ),
                ])
                .map(|panes| {
                    let root = project_root.to_string_lossy();
                    panes
                        .lines()
                        .filter_map(|line| {
                            let mut fields = line.splitn(3, '\t');
                            let pane = fields.next().unwrap_or("").trim();
                            let command = fields.next().unwrap_or("");
                            let placeholder = fields.next().is_some_and(|mark| mark == root);
                            (!pane.is_empty()).then(|| agent_doc_editor_surface::LanePaneObservation {
                                pane: pane.to_string(),
                                document_owned: owned_panes.contains(pane),
                                busy: navigation_lane_pane_busy(
                                    placeholder && !ever_attached,
                                    command,
                                ),
                            })
                        })
                        .collect()
                })
                // A session whose panes cannot be read is treated as busy, so
                // it is never closed on a failed read.
                .unwrap_or_else(|_| {
                    vec![agent_doc_editor_surface::LanePaneObservation {
                        pane: String::new(),
                        document_owned: false,
                        busy: true,
                    }]
                })
            } else {
                Vec::new()
            };
            agent_doc_editor_surface::LaneSessionObservation {
                live_surface: attached > 0
                    || liveness.lane_session_live(project_session, &session),
                session,
                marked,
                panes,
            }
        })
        .collect()
}

/// Reconcile a project's installation lane sessions with its configured
/// `editor_navigation` (`#ideriderindependentnav` P5): the enable/disable
/// migration and the cleanup of empty lane sessions agent-doc created.
///
/// `agent-doc gc` runs this with the mode configured in
/// `.agent-doc/config.toml`; the project controller runs
/// [`reconcile_navigation_lane_sessions_in_mode`] on its own
/// ([`NavigationLaneReconcileGraph`]). The plan is
/// [`agent_doc_editor_surface::plan_navigation_lane_reconcile`]:
/// - `per_installation` (enable): no pane moves; a lane session agent-doc
///   created is closed only when no document pane, busy pane, attached tmux
///   client, or live installation (`live_installations`; empty from the CLI)
///   uses it.
/// - `shared` (disable): each document pane of each lane folds back into the
///   project session's `stash` window (same pane, same actor binding), then
///   the lane closes unless a busy unowned pane or a live surface keeps it.
///
/// A session that only carries a lane's name, without the
/// `@agent_doc_navigation_lane` mark for this root, is never touched
/// (`#bare-foreign-session-guard`). Before closing, the session is observed
/// again and closed only if the fresh plan still closes it. A project without
/// a `tmux_session` pin has no lanes, so this is a no-op.
pub fn reconcile_navigation_lane_sessions(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    live_installations: &BTreeSet<String>,
    dry_run: bool,
) -> NavigationLaneReconcileReport {
    let (mode, _) = agent_doc_project_config_io::editor_navigation_mode_for_root(project_root);
    reconcile_navigation_lane_sessions_in_mode(
        tmux,
        project_root,
        mode,
        &agent_doc_editor_surface::LaneLiveness::Live(live_installations.clone()),
        dry_run,
    )
}

/// Take the project's sync lock for a lane reconcile. Blocks until the sync
/// holding it finishes: the reconcile runs on `agent-doc gc` or the
/// controller's dedicated reconcile worker, never on a request path.
fn lock_navigation_lane_reconcile(project_root: &Path) -> std::io::Result<std::fs::File> {
    let dir = project_root.join(".agent-doc");
    std::fs::create_dir_all(&dir)?;
    let file = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(false)
        .open(dir.join("sync.lock"))?;
    fs2::FileExt::lock_exclusive(&file)?;
    Ok(file)
}

/// [`reconcile_navigation_lane_sessions`] under an explicit `mode` and
/// installation liveness.
///
/// The project controller passes the mode it runs under (read once at its
/// start), never a re-read of the config: a config edit that this controller
/// has not started under must not fold or close lanes it still routes into.
pub fn reconcile_navigation_lane_sessions_in_mode(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    mode: agent_doc_editor_surface::NavigationMode,
    liveness: &agent_doc_editor_surface::LaneLiveness,
    dry_run: bool,
) -> NavigationLaneReconcileReport {
    use agent_doc_editor_surface::LaneReconcileAction;
    let mut report = NavigationLaneReconcileReport {
        mode,
        ..NavigationLaneReconcileReport::default()
    };
    let Some(project_session) = configured_tmux_session_for_project(project_root) else {
        return report;
    };
    let project_session = project_session.trim().to_string();
    // `#ridernavp6gc`: observe and apply under the project's sync lock (the
    // `.agent-doc/sync.lock` flock every tmux sync body holds). In `shared`
    // mode a sync adopts the stale lane panes its layout shows
    // (`#ridernavp6switchback`) while this reconcile folds every lane pane;
    // with both serialized, whichever runs first moves a pane and the other
    // observes it already home, so no pane is moved twice. A dry run moves
    // nothing and takes no lock.
    let _sync_lock = if dry_run {
        None
    } else {
        match lock_navigation_lane_reconcile(project_root) {
            Ok(lock) => Some(lock),
            Err(error) => {
                report
                    .failures
                    .push(format!("sync_lock_unavailable:{error}"));
                return report;
            }
        }
    };
    tmux_router::invalidate_pane_snapshot();
    let observed = observe_navigation_lane_sessions(tmux, project_root, &project_session, liveness);
    report.actions = agent_doc_editor_surface::plan_navigation_lane_reconcile(
        mode,
        &project_session,
        tmux.session_alive(&project_session),
        &observed,
    );
    if dry_run {
        return report;
    }
    for action in report.actions.clone() {
        match action {
            LaneReconcileAction::FoldPane { session, pane } => {
                tmux_router::invalidate_pane_snapshot();
                match tmux.pane_session(&pane) {
                    Ok(current) if current == session => {}
                    // Already home (a shared sync adopted it first): nothing
                    // to move, and not a failure.
                    Ok(current) if current == project_session => continue,
                    Ok(current) => {
                        report
                            .failures
                            .push(format!("fold_pane_moved:{pane}:{session}:{current}"));
                        continue;
                    }
                    Err(_) => {
                        report
                            .failures
                            .push(format!("fold_pane_missing:{pane}:{session}"));
                        continue;
                    }
                }
                let moved = tmux.stash_pane(&pane, &project_session);
                tmux_router::invalidate_pane_snapshot();
                match tmux.pane_session(&pane) {
                    Ok(current) if current == project_session => {
                        agent_doc_ops_log_io::log_op(
                            project_root,
                            &format!(
                                "navigation_lane_pane_folded pane={pane} from_session={session} to_session={project_session}"
                            ),
                        );
                        report.folded.push((session, pane));
                    }
                    _ => report.failures.push(format!(
                        "fold_pane_failed:{pane}:{session}:{}",
                        moved
                            .err()
                            .map(|error| format!("{error:#}"))
                            .unwrap_or_default()
                    )),
                }
            }
            LaneReconcileAction::Close { session } => {
                tmux_router::invalidate_pane_snapshot();
                if !tmux.session_alive(&session) {
                    // Folding its last pane already ended it.
                    report.closed.push(session);
                    continue;
                }
                let fresh = observe_navigation_lane_sessions(
                    tmux,
                    project_root,
                    &project_session,
                    liveness,
                )
                .into_iter()
                .filter(|lane| lane.session == session)
                .collect::<Vec<_>>();
                let still_closes = agent_doc_editor_surface::plan_navigation_lane_reconcile(
                    mode,
                    &project_session,
                    tmux.session_alive(&project_session),
                    &fresh,
                )
                .iter()
                .any(|action| matches!(action, LaneReconcileAction::Close { session: closing } if closing == &session))
                    && fresh.iter().all(|lane| lane.panes.iter().all(|pane| !pane.document_owned && !pane.busy));
                if !still_closes {
                    report
                        .failures
                        .push(format!("close_refused_on_reobserve:{session}"));
                    continue;
                }
                match tmux.raw_cmd(&["kill-session", "-t", &format!("={session}")]) {
                    Ok(_) => {
                        agent_doc_ops_log_io::log_op(
                            project_root,
                            &format!(
                                "navigation_lane_session_closed session={session} mode={}",
                                mode.as_str()
                            ),
                        );
                        report.closed.push(session);
                    }
                    Err(error) => report
                        .failures
                        .push(format!("close_failed:{session}:{error:#}")),
                }
            }
            LaneReconcileAction::Retain { .. } => {}
        }
    }
    tmux_router::invalidate_pane_snapshot();
    report
}

/// One controller-triggered lane reconcile, published back into
/// [`NavigationLaneReconcileGraph`] (`#ridernavp6gc`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NavigationLaneReconcileReceipt {
    /// The request the reconcile ran for.
    pub trigger: agent_doc_editor_surface::LaneReconcileTrigger,
    /// How many requests this graph has served, this one included.
    pub sequence: u64,
    pub actions: Vec<agent_doc_editor_surface::LaneReconcileAction>,
    pub folded: Vec<(String, String)>,
    pub closed: Vec<String>,
    pub failures: Vec<String>,
}

/// The IO a [`NavigationLaneReconcileGraph`] request runs: production passes
/// [`reconcile_navigation_lane_sessions_in_mode`] over the configured tmux
/// server; tests pass an isolated server or a recorder.
pub type NavigationLaneReconcileRunner = Arc<
    dyn Fn(&Path, &agent_doc_editor_surface::LaneReconcileTrigger) -> NavigationLaneReconcileReport
        + Send
        + Sync,
>;

/// The project controller's trigger for the navigation-lane reconcile
/// (`#ideriderindependentnav` P5 follow-up, `#ridernavp6gc`).
///
/// `agent-doc gc` can only use an attached terminal as liveness evidence. The
/// controller knows which editor installations are live, because every editor
/// surface registers and retires through its [`ControllerEditorSurfaceGraph`],
/// which publishes the installations it holds live into `live` (and the union
/// into `seen`). The request is a `Computed`
/// ([`agent_doc_editor_surface::derive_lane_reconcile_trigger`]) over those and
/// the controller's navigation mode, and an `Effect` hands every new request
/// to one worker thread that runs the reconcile and publishes its receipt.
/// So an IDE that quits has its empty lane closed, and a controller started
/// under `shared` after lanes were in use folds their panes back, without the
/// operator running `gc`.
///
/// Every P5 safety rule holds because the worker runs the same reconcile `gc`
/// runs: only marked sessions are planned, a busy unowned pane or an attached
/// client keeps a lane, an unreadable registry observes nothing, and each
/// close is re-observed first. Only a retired installation's lane counts as
/// not live ([`agent_doc_editor_surface::LaneLiveness::RetiredOnly`]), so a
/// lane whose installation this controller never saw is left to `gc`.
pub struct NavigationLaneReconcileGraph {
    ctx: ThreadSafeContext,
    project_root: PathBuf,
    mode: agent_doc_editor_surface::NavigationMode,
    /// `(seen, live)` as one Source, so the `Computed` never observes a
    /// grown `seen` beside a stale `live` (a transient retirement).
    installations: Source<(BTreeSet<String>, BTreeSet<String>)>,
    trigger: Computed<Option<agent_doc_editor_surface::LaneReconcileTrigger>>,
    receipt: Source<Option<NavigationLaneReconcileReceipt>>,
    worker_ready: Source<bool>,
    sender: Arc<OnceLock<std::sync::mpsc::Sender<agent_doc_editor_surface::LaneReconcileTrigger>>>,
    _effect: Mutex<Option<lazily::Effect>>,
    /// Guards `seen`/`live` read-modify-write against concurrent editor
    /// observations.
    publication: Mutex<()>,
    receipts_published: Mutex<u64>,
    receipt_waiters: Condvar,
}

impl NavigationLaneReconcileGraph {
    pub fn new_in(
        scope: &agent_doc_state_scope::ProcessScope,
        project_root: &Path,
        mode: agent_doc_editor_surface::NavigationMode,
    ) -> Arc<Self> {
        let ctx = scope.ctx().clone();
        let installations = ctx.source((BTreeSet::new(), BTreeSet::new()));
        let trigger = ctx.computed(move |ctx| {
            let (seen, live) = ctx.get(&installations);
            agent_doc_editor_surface::derive_lane_reconcile_trigger(mode, &seen, &live)
        });
        let receipt = ctx.source(None);
        let worker_ready = ctx.source(false);
        let sender = Arc::new(OnceLock::<
            std::sync::mpsc::Sender<agent_doc_editor_surface::LaneReconcileTrigger>,
        >::new());
        let sender_for_effect = Arc::clone(&sender);
        let dispatched = Mutex::new(None::<agent_doc_editor_surface::LaneReconcileTrigger>);
        let effect = ctx.effect(move |ctx| {
            // Worker availability is a lifecycle edge of its own: a request
            // derived before the worker started must still reach it.
            if !ctx.get(&worker_ready) {
                return;
            }
            let Some(trigger) = ctx.get(&trigger) else {
                return;
            };
            let Some(sender) = sender_for_effect.get() else {
                return;
            };
            let mut dispatched = dispatched.lock();
            if dispatched.as_ref() == Some(&trigger) {
                return;
            }
            if let Err(error) = sender.send(trigger.clone()) {
                eprintln!("[controller] navigation-lane reconcile enqueue failed: {error}");
                return;
            }
            *dispatched = Some(trigger);
        });
        Arc::new(Self {
            ctx,
            project_root: project_root.to_path_buf(),
            mode,
            installations,
            trigger,
            receipt,
            worker_ready,
            sender,
            _effect: Mutex::new(Some(effect)),
            publication: Mutex::new(()),
            receipts_published: Mutex::new(0),
            receipt_waiters: Condvar::new(),
        })
    }

    pub fn project_root(&self) -> &Path {
        &self.project_root
    }

    pub fn mode(&self) -> agent_doc_editor_surface::NavigationMode {
        self.mode
    }

    /// Publish the editor installations live on this project right now.
    /// Installations accumulate into `seen`, so one that is missing from a
    /// later publication has retired.
    pub fn observe_live_installations(&self, live: BTreeSet<String>) {
        let _publication = self.publication.lock();
        let current = self.ctx.get(&self.installations);
        let mut seen = current.0.clone();
        seen.extend(live.iter().cloned());
        let next = (seen, live);
        if next != current {
            self.ctx.set(&self.installations, next);
        }
    }

    /// The current derived request.
    pub fn trigger(&self) -> Option<agent_doc_editor_surface::LaneReconcileTrigger> {
        self.ctx.get(&self.trigger)
    }

    /// The last reconcile's receipt.
    pub fn receipt(&self) -> Option<NavigationLaneReconcileReceipt> {
        self.ctx.get(&self.receipt)
    }

    /// Block until the worker has published at least `sequence` receipts, or
    /// `timeout` passes; returns the latest receipt.
    pub fn wait_for_receipt(
        &self,
        sequence: u64,
        timeout: Duration,
    ) -> Option<NavigationLaneReconcileReceipt> {
        let deadline = Instant::now() + timeout;
        let mut published = self.receipts_published.lock();
        while *published < sequence {
            if self
                .receipt_waiters
                .wait_until(&mut published, deadline)
                .timed_out()
            {
                break;
            }
        }
        drop(published);
        self.receipt()
    }

    /// Start the worker that runs each request. Requests derived while the
    /// previous run was still busy coalesce to the newest one.
    pub fn install_worker(self: &Arc<Self>, run: NavigationLaneReconcileRunner) {
        if self.sender.get().is_some() {
            return;
        }
        let (sender, receiver) =
            std::sync::mpsc::channel::<agent_doc_editor_surface::LaneReconcileTrigger>();
        let graph = Arc::downgrade(self);
        let spawned = std::thread::Builder::new()
            .name("agent-doc-navigation-lane-reconcile".to_string())
            .spawn(move || {
                while let Ok(mut trigger) = receiver.recv() {
                    while let Ok(newer) = receiver.try_recv() {
                        trigger = newer;
                    }
                    let Some(graph) = graph.upgrade() else {
                        break;
                    };
                    let report = run(&graph.project_root, &trigger);
                    graph.publish_receipt(trigger, report);
                }
            });
        match spawned {
            Ok(_) => {
                if self.sender.set(sender).is_err() {
                    eprintln!(
                        "[controller] navigation-lane reconcile worker was installed concurrently"
                    );
                    return;
                }
                self.ctx.set(&self.worker_ready, true);
            }
            Err(error) => {
                eprintln!("[controller] failed to start navigation-lane reconcile worker: {error}");
            }
        }
    }

    fn publish_receipt(
        &self,
        trigger: agent_doc_editor_surface::LaneReconcileTrigger,
        report: NavigationLaneReconcileReport,
    ) {
        // Only the worker thread publishes, so the next sequence is stable
        // between this read and the count update below.
        let sequence = *self.receipts_published.lock() + 1;
        agent_doc_ops_log_io::log_op(
            &self.project_root,
            &format!(
                "navigation_lane_reconcile_triggered {} folded={} closed={} failures={}",
                trigger.describe(),
                report.folded.len(),
                report.closed.len(),
                report.failures.join(",")
            ),
        );
        // Publish the receipt before the count, so a waiter woken by the
        // count always reads this receipt; no lock is held across the
        // reactive context.
        self.ctx.set(
            &self.receipt,
            Some(NavigationLaneReconcileReceipt {
                trigger,
                sequence,
                actions: report.actions,
                folded: report.folded,
                closed: report.closed,
                failures: report.failures,
            }),
        );
        *self.receipts_published.lock() = sequence;
        self.receipt_waiters.notify_all();
    }
}

/// The production runner: the reconcile on the configured tmux server.
#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
pub(super) fn configured_navigation_lane_reconcile_runner() -> NavigationLaneReconcileRunner {
    Arc::new(|project_root, trigger| {
        // A controller handing off to a successor started under another
        // `editor_navigation` must not fold or close lanes the successor
        // routes into: run only while the config still names this mode.
        let (configured, _) =
            agent_doc_project_config_io::editor_navigation_mode_for_root(project_root);
        if configured != trigger.mode {
            return NavigationLaneReconcileReport {
                mode: trigger.mode,
                failures: vec![format!(
                    "mode_changed:{}->{}",
                    trigger.mode.as_str(),
                    configured.as_str()
                )],
                ..NavigationLaneReconcileReport::default()
            };
        }
        reconcile_navigation_lane_sessions_in_mode(
            &agent_doc_tmux_io::configured_tmux(),
            project_root,
            trigger.mode,
            &trigger.liveness(),
            false,
        )
    })
}

/// Republish the lane an explicit handoff took a pane from, so it re-projects
/// without that document (`#ideriderindependentnav` P4).
///
/// The republish is the lane's retained invocation as a fresh generation with
/// the passive [`agent_doc_editor_surface::LANE_HANDOFF_CALLER_KIND`] and no
/// autostart, so it can only drop the document (`cross_lane_layout_dropped`),
/// never take the pane back or start a new one. A lane this runtime holds no
/// retained layout for has nothing on screen to correct.
fn republish_navigation_lane_after_handoff(
    runtime: &ControllerRuntime,
    project_root: &Path,
    requester: &agent_doc_editor_surface::NavigationLane,
    project_session: &str,
    from_session: &str,
    generation: u64,
) {
    let lanes = runtime.pane_layout_lane_ids();
    let Some(owner) =
        agent_doc_editor_surface::lane_owning_session(&lanes, project_session, from_session)
    else {
        return;
    };
    if &owner == requester {
        return;
    }
    let Some(retained) = runtime.pane_layout_graph_for_lane(&owner).desired() else {
        return;
    };
    let mut invocation = retained.invocation;
    invocation.caller_kind = agent_doc_editor_surface::LANE_HANDOFF_CALLER_KIND.to_string();
    invocation.no_autostart = true;
    let result = runtime.bootstrap_snapshot().and_then(|bootstrap| {
        publish_pane_layout_desired_invocation_in_lane(
            &bootstrap,
            runtime,
            &owner,
            invocation,
            retained.source_plane_version,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::LaneHandoff,
        )
    });
    agent_doc_ops_log_io::log_op(
        project_root,
        &match result {
            Ok((republished, _)) => format!(
                "navigation_lane_handoff_republished owner_lane={} navigation_lane={} handoff_generation={generation} generation={}",
                owner.label(),
                requester.label(),
                republished.generation,
            ),
            Err(error) => format!(
                "navigation_lane_handoff_republish_failed owner_lane={} navigation_lane={} handoff_generation={generation} error={error:#}",
                owner.label(),
                requester.label(),
            ),
        },
    );
}

/// [`pane_layout_target_window_id`] for one navigation lane: an installation
/// lane's fallback is its own session's `agent-doc` window, never the pin's.
fn pane_layout_target_window_id_for_lane(
    project_root: &Path,
    tmux: &tmux_router::Tmux,
    invocation_window: Option<&str>,
    lane_session: Option<&str>,
) -> Option<String> {
    match lane_session {
        Some(lane_session) => invocation_window
            .map(str::trim)
            .filter(|window| window.starts_with('@'))
            .map(str::to_string)
            .or_else(|| resolve_agent_doc_window_id_for_session(tmux, lane_session)),
        None => pane_layout_target_window_id(project_root, tmux, invocation_window),
    }
}

fn pane_layout_target_window_id(
    project_root: &Path,
    tmux: &tmux_router::Tmux,
    invocation_window: Option<&str>,
) -> Option<String> {
    if let Some(window_id) = invocation_window
        .map(str::trim)
        .filter(|window| window.starts_with('@'))
    {
        return Some(window_id.to_string());
    }
    let configured_session = configured_tmux_session_for_project(project_root)?;
    resolve_agent_doc_window_id_for_session(tmux, &configured_session)
}

/// The co-visibility inputs of the pane-layout focus effect (`#panewindowdrift`):
/// the window this layout generation is arranging its columns in, plus the live
/// `#{window_id}` observation for a candidate pane.
struct PaneLayoutFocusCoVisibility<'a, F: FnOnce(&str) -> Option<LivePaneWindow>> {
    layout_window: Option<&'a str>,
    /// Live window observation for a candidate pane (id, name, activity),
    /// read in one query so its halves cannot disagree across a concurrent
    /// `move-window`.
    observe_pane_window: F,
}

/// Apply the focus half of a tmux layout effect state after its structural
/// reconcile has made the requested pane visible.
///
/// The latest-generation mutex is held across the final effect. A newer editor
/// observation therefore either supersedes this generation before
/// `select-pane`, or is admitted immediately after it and deterministically
/// follows it. This is the pane-layout counterpart of
/// [`ControllerAsyncEditorCommandGraph::apply_focus_effect`], keyed by reactive
/// generation rather than by an imperative command id.
///
/// `#panewindowdrift`: the file→pane assignment is a *record* of where the pane
/// was bound, and records agree with each other even after the pane is moved
/// into the stash window. Before selecting, compare the layout's target window
/// against where the pane actually lives now and refuse a pane the operator
/// cannot see — mirroring editor focus onto a stashed pane is the reported bug.
/// A refusal keeps `applied: false`, so the caller neither converges nor counts
/// it toward `observation=synced`; the structural reconcile runs and the retry
/// focuses the pane once it is back in the layout window.
fn apply_pane_layout_focus_effect(
    worker_state: &Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>,
    generation: u64,
    focus: Option<&str>,
    focus_suppressed: bool,
    file_panes: &[(String, String)],
    co_visibility: PaneLayoutFocusCoVisibility<'_, impl FnOnce(&str) -> Option<LivePaneWindow>>,
    select_pane: impl FnOnce(&str) -> Result<()>,
) -> PaneLayoutFocusEffectReceipt {
    let PaneLayoutFocusCoVisibility {
        layout_window,
        observe_pane_window,
    } = co_visibility;
    let Some(focus) = focus else {
        return PaneLayoutFocusEffectReceipt {
            required: false,
            applied: false,
            reason: if focus_suppressed {
                "focus_suppressed_desktop_editor_inactive".to_string()
            } else {
                "focus_not_requested".to_string()
            },
        };
    };
    let Some((_, pane)) = file_panes
        .iter()
        .find(|(document, _)| Path::new(document) == Path::new(focus))
    else {
        return PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: format!("focus_pane_not_found:{focus}"),
        };
    };

    // Observed outside the worker mutex: this is a tmux read, and an unknown
    // answer must never be treated as drift.
    //
    // ONE read, TWO independent refusals. The drift leg needs a known layout
    // window; the stash leg (`#stashfocusleg`) does not, and it is the one that
    // still answers when `pane_layout_target_window_id` resolves to `None` —
    // which is exactly when this guard used to be skipped altogether and focus
    // landed on a stashed pane.
    let live = observe_pane_window(pane);
    let (live_window, live_window_name, live_window_active) = match &live {
        Some(LivePaneWindow { id, name, active }) => {
            (Some(id.as_str()), Some(name.as_str()), *active)
        }
        None => (None, None, None),
    };
    if agent_doc_controller::pane_layout::pane_is_stashed(live_window_name) {
        return PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: format!(
                "focus_pane_stashed:{focus}:{pane}:live_window_name={}",
                live_window_name.unwrap_or_default()
            ),
        };
    }
    let layout_window = layout_window.map(str::trim).filter(|w| !w.is_empty());
    // `layoutpublisherarbiter` (GH #120): a pane in a non-active window is
    // never a focus target. `select_pane` also runs `select-window`, so
    // selecting a pane outside the layout window switches the operator's
    // client to a window they did not pick. With a known layout window the
    // drift leg below already refuses any other window; without one, the only
    // proof the pane is in the working window is that its window is the
    // session's active window. An unknown activity answer is never a refusal.
    if layout_window.is_none() && live_window_active == Some(false) {
        return PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: format!(
                "focus_pane_window_inactive:{focus}:{pane}:live_window={}:live_window_name={}",
                live_window.unwrap_or_default(),
                live_window_name.unwrap_or_default()
            ),
        };
    }
    if let Some(layout_window) = layout_window
        && agent_doc_controller::pane_layout::pane_window_binding_drifted(
            layout_window,
            live_window,
        )
    {
        return PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: format!(
                "focus_pane_not_co_visible:{focus}:{pane}:live_window={}:layout_window={layout_window}",
                live_window.unwrap_or_default()
            ),
        };
    }

    let state = worker_state.lock();
    if state.is_superseded(generation) {
        return PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: "focus_superseded_by_newer_layout_state".to_string(),
        };
    }
    match select_pane(pane) {
        Ok(()) => PaneLayoutFocusEffectReceipt {
            required: true,
            applied: true,
            reason: format!("focus_applied:{focus}:{pane}"),
        },
        Err(error) => {
            eprintln!(
                "[controller] pane-layout focus effect failed for {focus} in {pane}: {error:#}"
            );
            PaneLayoutFocusEffectReceipt {
                required: true,
                applied: false,
                reason: format!("focus_effect_failed:{error:#}"),
            }
        }
    }
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn pane_layout_effect_worker(
    runtime: std::sync::Weak<ControllerRuntime>,
    lane: agent_doc_editor_surface::NavigationLane,
    state: Arc<Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>>,
    wake: Arc<Condvar>,
    executing_revision: &AtomicU64,
) {
    loop {
        let work_revision = state.lock().pending_revision();
        executing_revision.store(work_revision, Ordering::SeqCst);
        let Some(runtime) = runtime.upgrade() else {
            state.lock().deactivate();
            return;
        };
        // The pane-layout worker executes controller-owned effects on its own
        // thread. Install the local runtime there so nested route/start effects
        // publish actor transitions directly instead of self-RPCing through the
        // controller socket.
        install_controller_request_thread_context(&runtime);
        // This worker serves exactly one navigation lane's graph; the shared
        // lane's graph is the one every non-lane caller uses.
        let graph = runtime.pane_layout_graph_for_lane(&lane);
        let Some(desired) = graph.desired() else {
            state.lock().deactivate();
            return;
        };
        let already_terminal = matches!(
            graph.effect_state(),
            TmuxLayoutEffectState::Refused(ref terminal)
                | TmuxLayoutEffectState::OperatorOwned(ref terminal)
                | TmuxLayoutEffectState::Converged(ref terminal)
                if terminal.generation == desired.generation
        );
        if already_terminal {
            if pane_layout_effect_worker_complete(&graph, &state, work_revision, desired.generation)
                == PaneLayoutAttemptCompletion::Retire
            {
                return;
            }
            continue;
        }
        if state.lock().is_superseded(work_revision) {
            continue;
        }
        // `#stalecontrollerhotupdate` (b)/(d): the attempt count and any
        // retirement are per generation and survive a worker restart, so a
        // generation that spent its retry budget or yielded its window is never
        // re-applied until a newer generation replaces it.
        let attempt = match graph.begin_tmux_effect_attempt(desired.generation) {
            agent_doc_controller::pane_layout::TmuxEffectAttemptAdmission::Attempt { number } => {
                number
            }
            agent_doc_controller::pane_layout::TmuxEffectAttemptAdmission::Retired(_) => {
                if state.lock().retire_if_current(work_revision) {
                    return;
                }
                continue;
            }
        };

        let bootstrap = match runtime.bootstrap_snapshot() {
            Ok(bootstrap) => bootstrap,
            Err(error) => {
                eprintln!("[controller] pane-layout bootstrap observation failed: {error:#}");
                state.lock().deactivate();
                return;
            }
        };
        // Actor-store bindings and prior structural file→pane receipts are one
        // retained Computed. A receipt update invalidates this value and wakes
        // the effect; the worker does not imperatively reconstruct authority.
        let actor_bindings = graph.actor_bindings();
        // `#ideriderindependentnav` P2b: route this lane's layout to its own
        // tmux session. Shared navigation mode is the identity route (no tmux
        // reads, no provisioning). In per-installation mode an installation
        // lane's session is provisioned on its first driving layout, and every
        // document whose pane lives in another lane is dropped from this
        // lane's columns so no pane ever moves across lanes.
        let lane_tmux = agent_doc_tmux_io::configured_tmux();
        let lane_route = match pane_layout_lane_route(
            &bootstrap.project_root,
            runtime.editor_surface_graph.navigation_mode(),
            &lane,
            &lane_tmux,
        ) {
            Ok(route) => route,
            Err(reason) => {
                graph.record_receipt(PaneLayoutEffectReceipt {
                    generation: desired.generation,
                    actor_bindings: actor_bindings.clone(),
                    attempt,
                    phase: PaneLayoutEffectPhase::Refused,
                    reason: reason.clone(),
                    file_panes: Vec::new(),
                    focus_required: false,
                    focus_applied: false,
                });
                publish_pane_layout_lane_status(&runtime, &lane);
                agent_doc_ops_log_io::log_op(
                    &bootstrap.project_root,
                    &format!(
                        "tmux_layout_effect_state generation={} attempt={} navigation_lane={} phase=refused reason={reason}",
                        desired.generation,
                        attempt,
                        lane.label(),
                    ),
                );
                match pane_layout_effect_worker_complete(
                    &graph,
                    &state,
                    work_revision,
                    desired.generation,
                ) {
                    PaneLayoutAttemptCompletion::Retire => return,
                    PaneLayoutAttemptCompletion::RetryCurrent
                    | PaneLayoutAttemptCompletion::Superseded => {
                        continue;
                    }
                }
            }
        };
        let LaneRoutedLayout {
            mut desired,
            dropped: mut cross_lane_dropped,
            handoffs,
        } = route_pane_layout_desired_to_lane(
            &bootstrap.project_root,
            &lane_route,
            desired,
            &actor_bindings,
            |pane| lane_tmux.pane_session(pane).ok(),
        );
        // `#ideriderindependentnav` P4: an explicit claim from this lane hands
        // each contended pane over before the structural sync places it. A
        // refused handoff leaves the pane where it is and drops the document,
        // exactly as a passive publication would.
        if let (false, Some((project_session, lane_session))) =
            (handoffs.is_empty(), lane_route.sessions.as_ref())
        {
            let mut moved_from = BTreeSet::new();
            for handoff in &handoffs {
                let from_lane = agent_doc_editor_surface::lane_label_for_session(
                    project_session,
                    &handoff.from_session,
                );
                match hand_over_navigation_lane_pane(
                    &lane_tmux,
                    &bootstrap.project_root,
                    project_session,
                    lane_session,
                    handoff,
                ) {
                    Ok(outcome) => {
                        let placeholder = match &outcome {
                            NavigationLaneHandoffOutcome::Moved {
                                placeholder: Some(placeholder),
                            } => placeholder.as_str(),
                            NavigationLaneHandoffOutcome::Moved { placeholder: None } => "none",
                            NavigationLaneHandoffOutcome::AlreadyInLane => "already_in_lane",
                        };
                        if matches!(outcome, NavigationLaneHandoffOutcome::Moved { .. }) {
                            moved_from.insert(handoff.from_session.clone());
                        }
                        agent_doc_ops_log_io::log_op(
                            &bootstrap.project_root,
                            &format!(
                                "navigation_lane_handoff document={} pane={} from_lane={from_lane} from_session={} navigation_lane={} to_session={lane_session} placeholder={placeholder} generation={}",
                                handoff.document,
                                handoff.pane,
                                handoff.from_session,
                                lane.label(),
                                desired.generation,
                            ),
                        );
                    }
                    Err(reason) => {
                        drop_document_from_lane_invocation(
                            &bootstrap.project_root,
                            &mut desired.invocation,
                            &handoff.document,
                        );
                        agent_doc_ops_log_io::log_op(
                            &bootstrap.project_root,
                            &format!(
                                "navigation_lane_handoff_refused document={} pane={} from_lane={from_lane} navigation_lane={} reason={reason} generation={}",
                                handoff.document,
                                handoff.pane,
                                lane.label(),
                                desired.generation,
                            ),
                        );
                        cross_lane_dropped
                            .push((handoff.document.clone(), handoff.from_session.clone()));
                    }
                }
            }
            for from_session in &moved_from {
                republish_navigation_lane_after_handoff(
                    &runtime,
                    &bootstrap.project_root,
                    &lane,
                    project_session,
                    from_session,
                    desired.generation,
                );
            }
        }
        for (document, owner_session) in &cross_lane_dropped {
            let project_session = lane_route
                .sessions
                .as_ref()
                .map(|(project_session, _)| project_session.as_str())
                .unwrap_or_default();
            agent_doc_ops_log_io::log_op(
                &bootstrap.project_root,
                &format!(
                    "cross_lane_layout_dropped document={document} owner_lane={} owner_session={owner_session} navigation_lane={} generation={}",
                    agent_doc_editor_surface::lane_label_for_session(
                        project_session,
                        owner_session
                    ),
                    lane.label(),
                    desired.generation,
                ),
            );
        }
        if desired.invocation.columns.is_empty() && !cross_lane_dropped.is_empty() {
            // Every column belongs to another lane: this lane has nothing it may
            // arrange, which is exactly the converged answer for it.
            graph.record_observation(PaneLayoutObservation {
                generation: desired.generation,
                actor_bindings: actor_bindings.clone(),
                report: layout_sync_state_report(
                    true,
                    "all_columns_owned_by_other_lanes",
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    LayoutSyncStateTarget {
                        window_id: desired.invocation.window.clone(),
                        ..LayoutSyncStateTarget::default()
                    },
                ),
            });
            graph.record_receipt(PaneLayoutEffectReceipt {
                generation: desired.generation,
                actor_bindings: actor_bindings.clone(),
                attempt,
                phase: PaneLayoutEffectPhase::Converged,
                reason: "all_columns_owned_by_other_lanes".to_string(),
                file_panes: Vec::new(),
                focus_required: false,
                focus_applied: false,
            });
            publish_pane_layout_lane_status(&runtime, &lane);
            match pane_layout_effect_worker_complete(
                &graph,
                &state,
                work_revision,
                desired.generation,
            ) {
                PaneLayoutAttemptCompletion::Retire => return,
                PaneLayoutAttemptCompletion::RetryCurrent
                | PaneLayoutAttemptCompletion::Superseded => {
                    continue;
                }
            }
        }
        let lane_observation_session = lane_route.observation_session().map(str::to_string);
        // `#stalecontrollerhotupdate` (c)/(d): one tmux window, one driver. The
        // newest publication to drive the window owns it; a controller whose
        // generation is older than another root's claim yields instead of
        // re-applying (two controllers sharing a window used to stash each
        // other's panes on every retry).
        if let Some(claim_window) = pane_layout_target_window_id_for_lane(
            &bootstrap.project_root,
            &lane_tmux,
            desired.invocation.window.as_deref(),
            lane_observation_session.as_deref(),
        ) && let Some(newer) = pane_layout_window_claim_gate(
            &bootstrap.project_root,
            &lane_tmux,
            &claim_window,
            &graph,
            desired.generation,
            pane_layout_now_ms(),
        ) {
            retire_pane_layout_generation(
                &bootstrap.project_root,
                &runtime,
                &lane,
                &graph,
                &desired,
                attempt,
                agent_doc_controller::pane_layout::TmuxEffectRetirement::YieldedToNewerWindowClaim,
                &format!(
                    "window={claim_window} owner_root={} owner_generation={} owner_stamp_ms={}",
                    newer.project_root.display(),
                    newer.generation,
                    newer.stamp_ms,
                ),
            );
            match pane_layout_effect_worker_complete(
                &graph,
                &state,
                work_revision,
                desired.generation,
            ) {
                PaneLayoutAttemptCompletion::Retire => return,
                PaneLayoutAttemptCompletion::RetryCurrent
                | PaneLayoutAttemptCompletion::Superseded => {
                    continue;
                }
            }
        }
        if desired.invocation.caller_kind == "automatic" {
            let observation_invocation = pane_layout_state_invocation(&desired);
            // Ownership is a retained join over effect receipts and live actors,
            // independent of current-layout reuse and nonempty session IDs.
            let structural_file_panes = graph.ctx.get(&graph.owned_assignments);
            if let Ok(report) = tmux_layout_sync_state_for_lane_invocation(
                &bootstrap,
                &runtime,
                &observation_invocation,
                &structural_file_panes,
                lane_observation_session.as_deref(),
            ) && !report.operator_owned_documents.is_empty()
            {
                if state.lock().is_superseded(work_revision) {
                    continue;
                }
                let operator_owned_documents = report.operator_owned_documents.clone();
                let surface_tmux = tmux_layout_from_sync_report(&report, &desired);
                graph.record_observation(PaneLayoutObservation {
                    generation: desired.generation,
                    actor_bindings: actor_bindings.clone(),
                    report,
                });
                graph.record_receipt(PaneLayoutEffectReceipt {
                    generation: desired.generation,
                    actor_bindings: actor_bindings.clone(),
                    attempt,
                    phase: PaneLayoutEffectPhase::Converged,
                    reason: "operator_owned_layout".to_string(),
                    file_panes: Vec::new(),
                    focus_required: false,
                    focus_applied: false,
                });
                publish_pane_layout_lane_status(&runtime, &lane);
                if let Some(layout) = surface_tmux {
                    runtime.editor_surface_graph.observe_tmux_for_lane(
                        &bootstrap.project_root,
                        &lane,
                        Some(layout),
                    );
                }
                record_pane_layout_outcome_diagnostic(
                    &bootstrap.project_root,
                    desired.generation,
                    attempt,
                    "operator_owned",
                    &[],
                    &operator_owned_documents,
                );
                agent_doc_ops_log_io::log_op(
                    &bootstrap.project_root,
                    &format!(
                        "tmux_layout_effect_state generation={} attempt={} {} phase=operator_owned operator_owned_documents={:?}",
                        desired.generation,
                        attempt,
                        tmux_layout_effect_state_provenance(&desired),
                        operator_owned_documents,
                    ),
                );
                match pane_layout_effect_worker_complete(
                    &graph,
                    &state,
                    work_revision,
                    desired.generation,
                ) {
                    PaneLayoutAttemptCompletion::Retire => return,
                    PaneLayoutAttemptCompletion::RetryCurrent
                    | PaneLayoutAttemptCompletion::Superseded => {
                        continue;
                    }
                }
            }
        }
        let mut guarded_invocation = desired.invocation.clone();
        guarded_invocation.actor_bindings = actor_bindings.clone();
        // pane-count drift: the effect arranges the window this generation's
        // observer reads, never the window the focused pane happens to live in.
        guarded_invocation.window = agent_doc_controller::pane_layout::structural_effect_window(
            desired.invocation.window.as_deref(),
            lane_observation_session.is_some(),
            project_is_multi_tmux_session(&bootstrap.project_root),
            || {
                pane_layout_target_window_id_for_lane(
                    &bootstrap.project_root,
                    &lane_tmux,
                    None,
                    lane_observation_session.as_deref(),
                )
            },
        );
        let focus_suppressed = suppress_inactive_automatic_layout_focus(
            &mut guarded_invocation,
            desktop_editor_focus_state(),
        );
        if focus_suppressed {
            agent_doc_ops_log_io::log_op(
                &bootstrap.project_root,
                &format!(
                    "controller_automatic_layout_focus_suppressed generation={} reason=desktop_editor_inactive",
                    desired.generation
                ),
            );
        }
        let projected_focus = guarded_invocation.focus.clone();
        let reusable_structure =
            pane_layout_invocation_allows_structural_reuse(&desired.invocation)
                .then(|| graph.reusable_structural_receipt(&desired, &actor_bindings))
                .flatten();
        let reusable_file_panes = reusable_structure
            .as_ref()
            .map(|receipt| receipt.file_panes.clone())
            .unwrap_or_default();
        graph.record_receipt(PaneLayoutEffectReceipt {
            generation: desired.generation,
            actor_bindings: actor_bindings.clone(),
            attempt,
            phase: PaneLayoutEffectPhase::InFlight,
            reason: if reusable_structure.is_some() {
                "reusable_layout_focus_effect_in_flight".to_string()
            } else {
                "tmux_effect_in_flight".to_string()
            },
            file_panes: reusable_file_panes,
            focus_required: projected_focus.is_some(),
            focus_applied: false,
        });
        publish_pane_layout_lane_status(&runtime, &lane);

        if let Some(reusable) = reusable_structure {
            let tmux = agent_doc_tmux_io::configured_tmux();
            let layout_window = pane_layout_target_window_id_for_lane(
                &bootstrap.project_root,
                &tmux,
                desired.invocation.window.as_deref(),
                lane_observation_session.as_deref(),
            );
            let focus_receipt = apply_pane_layout_focus_effect(
                &state,
                work_revision,
                projected_focus.as_deref(),
                focus_suppressed,
                &reusable.file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window: layout_window.as_deref(),
                    observe_pane_window: |pane| observe_pane_window_id(&tmux, pane),
                },
                |pane| tmux.select_pane(pane),
            );
            // `#tmuxautosyncwedge`: a supersede must not short-circuit the
            // observation. Fall through and let the fresh report speak; a
            // still-unconverged generation drops out of this block into the
            // shared pre-structural supersede cancel below.
            let focus_required = focus_required_for_pane_layout_generation(
                &desired.invocation.caller_kind,
                &focus_receipt,
            );
            let mut observation_invocation = pane_layout_state_invocation(&desired);
            observation_invocation.focus =
                focus_required.then(|| projected_focus.clone()).flatten();
            let fresh_report = tmux_layout_sync_state_for_lane_invocation(
                &bootstrap,
                &runtime,
                &observation_invocation,
                &reusable.file_panes,
                lane_observation_session.as_deref(),
            );
            if let Ok(report) = fresh_report
                && tmux_layout_effect_state_converged(
                    report.synced,
                    focus_required,
                    observation_invocation.focus.is_some(),
                    focus_receipt.applied,
                )
            {
                let focus_reason = focus_receipt.reason.clone();
                let logged_expected_documents = report.expected_documents.clone();
                let logged_actual_documents = report.actual_documents.clone();
                let logged_panes = report.panes.clone();
                let logged_expected_focus_pane = report.expected_focus_pane.clone();
                let logged_active_pane = report.active_pane.clone();
                let surface_tmux = tmux_layout_from_sync_report(&report, &desired);
                graph.record_observation(PaneLayoutObservation {
                    generation: desired.generation,
                    actor_bindings: actor_bindings.clone(),
                    report,
                });
                graph.record_receipt(PaneLayoutEffectReceipt {
                    generation: desired.generation,
                    actor_bindings: actor_bindings.clone(),
                    attempt,
                    phase: PaneLayoutEffectPhase::Converged,
                    reason: format!("reused_structural_layout; {focus_reason}"),
                    file_panes: reusable.file_panes,
                    focus_required,
                    focus_applied: focus_receipt.applied,
                });
                publish_pane_layout_lane_status(&runtime, &lane);
                if let Some(layout) = surface_tmux {
                    runtime.editor_surface_graph.observe_tmux_for_lane(
                        &bootstrap.project_root,
                        &lane,
                        Some(layout),
                    );
                }
                record_pane_layout_outcome_diagnostic(
                    &bootstrap.project_root,
                    desired.generation,
                    attempt,
                    "converged_focus_only",
                    &logged_expected_documents,
                    &logged_actual_documents,
                );
                agent_doc_ops_log_io::log_op(
                    &bootstrap.project_root,
                    &format!(
                        "tmux_layout_effect_state generation={} attempt={} {} phase=converged observation=reused_structural_layout effect=focus_only focus={} expected={:?} actual={:?} panes={:?} expected_focus_pane={:?} active_pane={:?} caller_kind={} column_order={}",
                        desired.generation,
                        attempt,
                        tmux_layout_effect_state_provenance(&desired),
                        focus_reason,
                        logged_expected_documents,
                        logged_actual_documents,
                        logged_panes,
                        logged_expected_focus_pane,
                        logged_active_pane,
                        desired.invocation.caller_kind,
                        desired.invocation.column_order,
                    ),
                );
                match pane_layout_effect_worker_complete(
                    &graph,
                    &state,
                    work_revision,
                    desired.generation,
                ) {
                    PaneLayoutAttemptCompletion::Retire => return,
                    PaneLayoutAttemptCompletion::Superseded => {}
                    PaneLayoutAttemptCompletion::RetryCurrent => {
                        let _superseded = pane_layout_effect_worker_wait_for_retry(
                            &bootstrap.project_root,
                            &state,
                            &wake,
                            work_revision,
                            desired.generation,
                            attempt,
                        );
                    }
                }
                continue;
            }
        }

        if state.lock().is_superseded(work_revision) {
            agent_doc_ops_log_io::log_op(
                &bootstrap.project_root,
                &format!(
                    "tmux_layout_effect_state_cancelled generation={} phase=before_structural_effect reason=superseded",
                    desired.generation
                ),
            );
            continue;
        }
        agent_doc_process_owner_io::set_structural_effect_generation(
            desired.generation,
            graph.published_generation_handle(),
        );
        let _effect_cancel_guard = StructuralEffectCancelGuard;
        let effect_result = match runtime_effects() {
            Ok(effects) => effects.sync_tmux_layout(
                &bootstrap.project_root,
                guarded_invocation,
                &runtime.main_layout_eligibility(),
            ),
            Err(error) => Err(error),
        };
        let effect_file_panes = effect_result
            .as_ref()
            .map(|receipt| receipt.file_panes.clone())
            .unwrap_or_default();
        // GH #136: the effect acknowledges the columns it deliberately did not
        // build (stale-supervisor gate). Convergence is measured against what
        // it promised, and focus is not demanded of a gated document, so a
        // gated column converges in ONE attempt instead of a retry loop that
        // cannot converge while the supervisor stays stale.
        let gated_documents = effect_result
            .as_ref()
            .map(|receipt| receipt.gated_documents.clone())
            .unwrap_or_default();
        let projected_focus = focus_outside_gated_documents(
            &bootstrap.project_root,
            projected_focus,
            &gated_documents,
        );
        if effect_result.is_ok() {
            // GH #136 follow-up (a)/(d): retain what this pass gated so the
            // width bound counts it as accounted for and a recycle of one of
            // these documents republishes the layout.
            graph.record_gated(desired.generation, gated_documents.clone());
        }
        if effect_result.is_ok() {
            graph.record_structural_assignment(
                &desired,
                actor_bindings.clone(),
                None,
                effect_file_panes.clone(),
            );
        }
        if state.lock().is_superseded(work_revision) {
            agent_doc_ops_log_io::log_op(
                &bootstrap.project_root,
                &format!(
                    "tmux_layout_effect_state_cancelled generation={} phase=after_structural_effect reason=superseded",
                    desired.generation
                ),
            );
            continue;
        }
        let focus_receipt = if effect_result.is_ok() {
            let tmux = agent_doc_tmux_io::configured_tmux();
            let layout_window = pane_layout_target_window_id_for_lane(
                &bootstrap.project_root,
                &tmux,
                desired.invocation.window.as_deref(),
                lane_observation_session.as_deref(),
            );
            apply_pane_layout_focus_effect(
                &state,
                work_revision,
                projected_focus.as_deref(),
                focus_suppressed,
                &effect_file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window: layout_window.as_deref(),
                    observe_pane_window: |pane| observe_pane_window_id(&tmux, pane),
                },
                |pane| tmux.select_pane(pane),
            )
        } else {
            PaneLayoutFocusEffectReceipt {
                required: projected_focus.is_some(),
                applied: false,
                reason: if focus_suppressed {
                    "focus_suppressed_desktop_editor_inactive".to_string()
                } else if projected_focus.is_some() {
                    "layout_effect_failed_before_focus".to_string()
                } else {
                    "focus_not_requested".to_string()
                },
            }
        };
        let focus_required = focus_required_for_pane_layout_generation(
            &desired.invocation.caller_kind,
            &focus_receipt,
        );
        let mut observation_invocation = pane_layout_state_invocation(&desired);
        observation_invocation.focus = focus_required.then(|| projected_focus.clone()).flatten();
        observation_invocation.columns = layout_columns_without_gated_documents(
            &bootstrap.project_root,
            &observation_invocation.columns,
            &gated_documents,
        );
        let report = if observation_invocation.columns.is_empty() && !gated_documents.is_empty() {
            // Every column was gated: the effect preserved the current layout
            // by design, which is exactly what it acknowledged.
            Ok(layout_sync_state_report(
                true,
                "all_columns_gated_layout_preserved",
                Vec::new(),
                Vec::new(),
                Vec::new(),
                LayoutSyncStateTarget {
                    window_id: desired.invocation.window.clone(),
                    ..LayoutSyncStateTarget::default()
                },
            ))
        } else {
            tmux_layout_sync_state_for_lane_invocation(
                &bootstrap,
                &runtime,
                &observation_invocation,
                &effect_file_panes,
                lane_observation_session.as_deref(),
            )
        };
        let terminal_effect_refusal = effect_result
            .as_ref()
            .err()
            .is_some_and(pane_layout_effect_failure_is_terminal);
        let (report, effect_reason) = match (report, effect_result) {
            (Ok(report), Ok(receipt)) => (report, receipt.reason),
            (Ok(report), Err(error)) => (report, format!("tmux_effect_failed:{error:#}")),
            (Err(error), Ok(receipt)) => (
                layout_sync_state_report(
                    false,
                    "tmux_observation_failed",
                    desired.invocation.columns.clone(),
                    Vec::new(),
                    Vec::new(),
                    LayoutSyncStateTarget {
                        window_id: desired.invocation.window.clone(),
                        focus: desired.invocation.focus.clone(),
                        ..LayoutSyncStateTarget::default()
                    },
                ),
                format!("{}; observation_failed:{error:#}", receipt.reason),
            ),
            (Err(observation_error), Err(effect_error)) => (
                layout_sync_state_report(
                    false,
                    "tmux_effect_and_observation_failed",
                    desired.invocation.columns.clone(),
                    Vec::new(),
                    Vec::new(),
                    LayoutSyncStateTarget {
                        window_id: desired.invocation.window.clone(),
                        focus: desired.invocation.focus.clone(),
                        ..LayoutSyncStateTarget::default()
                    },
                ),
                format!(
                    "tmux_effect_failed:{effect_error:#}; observation_failed:{observation_error:#}"
                ),
            ),
        };
        let synced = tmux_layout_effect_state_converged(
            report.synced,
            focus_required,
            observation_invocation.focus.is_some(),
            focus_receipt.applied,
        );
        let effect_refused = !synced && terminal_effect_refusal;
        let observation_reason = report.reason.clone();
        let focus_reason = focus_receipt.reason.clone();
        let logged_expected_documents = report.expected_documents.clone();
        let logged_actual_documents = report.actual_documents.clone();
        let logged_expected_panes = report.expected_panes.clone();
        let logged_panes = report.panes.clone();
        let logged_operator_owned_documents = report.operator_owned_documents.clone();
        let logged_expected_focus_pane = report.expected_focus_pane.clone();
        let logged_active_pane = report.active_pane.clone();
        let geometry_target = report.session_name.clone().zip(report.window_id.clone());
        if report.synced {
            graph.record_structural_assignment(
                &desired,
                actor_bindings.clone(),
                Some(report.clone()),
                effect_file_panes.clone(),
            );
        }
        let surface_tmux = if synced {
            tmux_layout_from_sync_report(&report, &desired)
        } else {
            None
        };
        graph.record_observation(PaneLayoutObservation {
            generation: desired.generation,
            actor_bindings: actor_bindings.clone(),
            report,
        });
        graph.record_receipt(PaneLayoutEffectReceipt {
            generation: desired.generation,
            actor_bindings,
            attempt,
            phase: if synced {
                PaneLayoutEffectPhase::Converged
            } else if effect_refused {
                PaneLayoutEffectPhase::Refused
            } else {
                PaneLayoutEffectPhase::RetryPending
            },
            reason: if synced {
                format!("observed_layout_and_focus_convergence; {focus_reason}")
            } else {
                format!("{observation_reason}; {effect_reason}; {focus_reason}")
            },
            file_panes: effect_file_panes,
            focus_required,
            focus_applied: focus_receipt.applied,
        });
        publish_pane_layout_lane_status(&runtime, &lane);
        if let Some(layout) = surface_tmux {
            runtime.editor_surface_graph.observe_tmux_for_lane(
                &bootstrap.project_root,
                &lane,
                Some(layout),
            );
        }
        record_pane_layout_outcome_diagnostic(
            &bootstrap.project_root,
            desired.generation,
            attempt,
            if synced {
                "converged"
            } else if effect_refused {
                "refused"
            } else {
                "retry_pending"
            },
            &logged_expected_documents,
            &logged_actual_documents,
        );
        agent_doc_ops_log_io::log_op(
            &bootstrap.project_root,
            &format!(
                "tmux_layout_effect_state generation={} attempt={} {} phase={} observation={} effect={} focus={} expected={:?} actual={:?} expected_panes={:?} panes={:?} operator_owned_documents={:?} expected_focus_pane={:?} active_pane={:?} caller_kind={} column_order={}",
                desired.generation,
                attempt,
                tmux_layout_effect_state_provenance(&desired),
                if synced {
                    "converged"
                } else if effect_refused {
                    "refused"
                } else {
                    "retry_pending"
                },
                observation_reason,
                effect_reason,
                focus_reason,
                logged_expected_documents,
                logged_actual_documents,
                logged_expected_panes,
                logged_panes,
                logged_operator_owned_documents,
                logged_expected_focus_pane,
                logged_active_pane,
                desired.invocation.caller_kind,
                desired.invocation.column_order,
            ),
        );
        if let Some((session, window)) = geometry_target {
            log_tmux_client_geometry(&bootstrap.project_root, &session, &window);
        }
        match pane_layout_effect_worker_complete(&graph, &state, work_revision, desired.generation)
        {
            PaneLayoutAttemptCompletion::Retire => return,
            PaneLayoutAttemptCompletion::Superseded => {
                continue;
            }
            PaneLayoutAttemptCompletion::RetryCurrent => {
                // `#stalecontrollerhotupdate` (b): a generation that has not
                // converged within its retry budget cannot be satisfied by
                // re-applying the same effect. Retire it (logged once); the
                // next publication is a new generation and re-arms the worker.
                if graph.tmux_effect_retry_budget_spent(desired.generation) {
                    retire_pane_layout_generation(
                        &bootstrap.project_root,
                        &runtime,
                        &lane,
                        &graph,
                        &desired,
                        attempt,
                        agent_doc_controller::pane_layout::TmuxEffectRetirement::RetryBudgetExhausted,
                        &format!(
                            "observation={observation_reason} effect={effect_reason} focus={focus_reason}"
                        ),
                    );
                    match pane_layout_effect_worker_complete(
                        &graph,
                        &state,
                        work_revision,
                        desired.generation,
                    ) {
                        PaneLayoutAttemptCompletion::Retire => return,
                        PaneLayoutAttemptCompletion::RetryCurrent
                        | PaneLayoutAttemptCompletion::Superseded => {
                            continue;
                        }
                    }
                }
                let _superseded = pane_layout_effect_worker_wait_for_retry(
                    &bootstrap.project_root,
                    &state,
                    &wake,
                    work_revision,
                    desired.generation,
                    attempt,
                );
            }
        }
    }
}

fn pane_layout_now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_millis().try_into().unwrap_or(u64::MAX))
        .unwrap_or_default()
}

/// `#stalecontrollerhotupdate` (c)/(d): stamp `window` with this controller's
/// claim for `generation`, or return the newer claim of another project root
/// that this generation must yield to
/// ([`agent_doc_controller::layout_owner::window_claim_requires_yield`]).
///
/// The stamp is minted once per generation (its first attempt), so a retry or
/// a restarted worker never re-stamps an old generation as the newest.
fn pane_layout_window_claim_gate(
    project_root: &Path,
    tmux: &tmux_router::Tmux,
    window: &str,
    graph: &ControllerPaneLayoutGraph,
    generation: u64,
    now_ms: u64,
) -> Option<agent_doc_controller::layout_owner::WindowLayoutClaim> {
    use agent_doc_controller::layout_owner::{
        WINDOW_LAYOUT_CLAIM_OPTION, WindowLayoutClaim, window_claim_requires_yield,
    };
    let own_root = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());
    let own_stamp_ms = graph.tmux_effect_claim_stamp_ms(generation, now_ms);
    let own_publication = graph.tmux_effect_publication(generation);
    let current = agent_doc_tmux_io::window_user_option(tmux, window, WINDOW_LAYOUT_CLAIM_OPTION)
        .and_then(|value| WindowLayoutClaim::decode(&value));
    if window_claim_requires_yield(
        &own_root,
        own_stamp_ms,
        own_publication.as_ref(),
        current.as_ref(),
    ) {
        return current;
    }
    let own = WindowLayoutClaim {
        project_root: own_root,
        stamp_ms: own_stamp_ms,
        generation,
        publication: own_publication,
    };
    if current.as_ref() != Some(&own)
        && let Err(error) = agent_doc_tmux_io::set_window_user_option(
            tmux,
            window,
            WINDOW_LAYOUT_CLAIM_OPTION,
            &own.encode(),
        )
    {
        eprintln!("[controller] pane-layout window claim on {window} failed: {error}");
    }
    None
}

/// `#stalecontrollerhotupdate` (b)/(d): retire one desired generation without
/// converging it. The retirement is sticky in the graph's attempt ledger, the
/// receipt is terminal (`Refused`) so the worker retires, and the
/// `tmux_layout_effect_state_retired` line is written once per generation.
#[allow(clippy::too_many_arguments)]
fn retire_pane_layout_generation(
    project_root: &Path,
    runtime: &ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
    graph: &ControllerPaneLayoutGraph,
    desired: &PaneLayoutDesired,
    attempt: u64,
    retirement: agent_doc_controller::pane_layout::TmuxEffectRetirement,
    detail: &str,
) {
    let first = graph.retire_tmux_effect(desired.generation, retirement);
    graph.record_receipt(PaneLayoutEffectReceipt {
        generation: desired.generation,
        actor_bindings: graph.actor_bindings(),
        attempt,
        phase: PaneLayoutEffectPhase::Refused,
        reason: format!("{}; {detail}", retirement.as_str()),
        file_panes: Vec::new(),
        focus_required: false,
        focus_applied: false,
    });
    publish_pane_layout_lane_status(runtime, lane);
    if first {
        agent_doc_ops_log_io::log_op(
            project_root,
            &format!(
                "tmux_layout_effect_state_retired generation={} attempts={} reason={} {} {detail} (#stalecontrollerhotupdate)",
                desired.generation,
                attempt,
                retirement.as_str(),
                tmux_layout_effect_state_provenance(desired),
            ),
        );
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PaneLayoutAttemptCompletion {
    Retire,
    RetryCurrent,
    Superseded,
}

fn pane_layout_attempt_completion(
    desired_generation: Option<u64>,
    effect_state: &TmuxLayoutEffectState,
    completed_generation: u64,
) -> PaneLayoutAttemptCompletion {
    if desired_generation != Some(completed_generation) {
        return PaneLayoutAttemptCompletion::Superseded;
    }
    match effect_state {
        TmuxLayoutEffectState::Refused(desired)
        | TmuxLayoutEffectState::OperatorOwned(desired)
        | TmuxLayoutEffectState::Converged(desired)
            if desired.generation == completed_generation =>
        {
            PaneLayoutAttemptCompletion::Retire
        }
        TmuxLayoutEffectState::RetryPending(desired)
            if desired.generation == completed_generation =>
        {
            PaneLayoutAttemptCompletion::RetryCurrent
        }
        _ => PaneLayoutAttemptCompletion::Superseded,
    }
}

fn pane_layout_effect_worker_complete(
    graph: &ControllerPaneLayoutGraph,
    state: &Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>,
    completed_work_revision: u64,
    completed_generation: u64,
) -> PaneLayoutAttemptCompletion {
    let desired_generation = graph.desired().map(|desired| desired.generation);
    let effect_state = graph.effect_state();
    let completion =
        pane_layout_attempt_completion(desired_generation, &effect_state, completed_generation);
    let mut worker = state.lock();
    if worker.is_superseded(completed_work_revision) {
        return PaneLayoutAttemptCompletion::Superseded;
    }
    if completion == PaneLayoutAttemptCompletion::Retire
        && worker.retire_if_current(completed_work_revision)
    {
        return PaneLayoutAttemptCompletion::Retire;
    }
    completion
}

fn pane_layout_effect_worker_wait_for_retry(
    project_root: &std::path::Path,
    state: &Mutex<agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState>,
    wake: &Condvar,
    work_revision: u64,
    generation: u64,
    attempt: u64,
) -> bool {
    let retry_delay = tmux_layout_effect_state_retry_delay(attempt);
    agent_doc_ops_log_io::log_op(
        project_root,
        &format!(
            "tmux_layout_effect_state_retry_scheduled generation={} attempt={} delay_ms={}",
            generation,
            attempt,
            retry_delay.as_millis(),
        ),
    );
    let mut worker = state.lock();
    if worker.is_superseded(work_revision) {
        return true;
    }
    wake.wait_for(&mut worker, retry_delay);
    worker.is_superseded(work_revision)
}

pub(crate) fn handle_tmux_focus_state(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    client_id: Option<&str>,
) -> Result<ControllerTmuxFocusState> {
    // `#ideriderindependentnav`: the reverse tmux-to-editor mirror reads the
    // focus of the requesting client's own navigation lane. In shared mode (the
    // default `editor_navigation`) every client resolves
    // to the shared lane, i.e. the project's configured session, exactly as
    // before lanes existed.
    // Without a runtime (a cold read, the test-support transport) the mode is
    // the project's configured `editor_navigation`, which is exactly what a
    // runtime would have read at start.
    let navigation_mode = runtime
        .map(|runtime| runtime.editor_surface_graph.navigation_mode())
        .unwrap_or_else(|| {
            agent_doc_project_config_io::editor_navigation_mode_for_root(&bootstrap.project_root).0
        });
    let lane = agent_doc_editor_surface::NavigationLane::for_client(
        navigation_mode,
        client_id.unwrap_or_default(),
    );
    let tmux = agent_doc_tmux_io::configured_tmux();
    tmux_focus_state_for_lane(
        &tmux,
        &bootstrap.project_root,
        &lane,
        runtime.map(|runtime| runtime.main_layout_eligibility()),
        || match runtime {
            Some(runtime) => Ok(runtime.actor_store_snapshot()),
            None => {
                let conn = open_state_db(&bootstrap.project_root)?;
                load_actor_store_from_db(&conn)
            }
        },
    )
}

/// The tmux focus projection of one navigation lane of `project_root`.
///
/// The lane's session is derived from the project's configured session
/// ([`agent_doc_editor_surface::NavigationLane::tmux_session_name`]); a lane
/// reports a document only while ITS session's current window is `agent-doc`,
/// so a navigation in another lane's session never recalls a selection in this
/// lane's editor. `actor_store` is read only once the active pane is known.
fn tmux_focus_state_for_lane(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    lane: &agent_doc_editor_surface::NavigationLane,
    main_layout_eligibility: Option<MainLayoutEligibility>,
    actor_store: impl FnOnce() -> Result<ControllerActorStore>,
) -> Result<ControllerTmuxFocusState> {
    let mut state = tmux_focus_state_in_lane_session(
        tmux,
        project_root,
        lane,
        main_layout_eligibility,
        actor_store,
    )?;
    state.navigation_lane = lane.installation().map(str::to_string);
    Ok(state)
}

fn tmux_focus_state_in_lane_session(
    tmux: &tmux_router::Tmux,
    project_root: &Path,
    lane: &agent_doc_editor_surface::NavigationLane,
    main_layout_eligibility: Option<MainLayoutEligibility>,
    actor_store: impl FnOnce() -> Result<ControllerActorStore>,
) -> Result<ControllerTmuxFocusState> {
    let Some(project_session) = configured_tmux_session_for_project(project_root) else {
        return Ok(inactive_tmux_focus_state(
            "missing_tmux_session",
            None,
            None,
            None,
            None,
        ));
    };
    let session_name = lane.tmux_session_name(&project_session);
    if !tmux.session_alive(&session_name) {
        return Ok(inactive_tmux_focus_state(
            "tmux_session_not_alive",
            Some(session_name),
            None,
            None,
            None,
        ));
    }
    let (window_id, window_name, pane_id) = active_tmux_window_for_session(tmux, &session_name);
    if window_name.as_deref() != Some("agent-doc") {
        return Ok(inactive_tmux_focus_state(
            "outside_agent_doc_window",
            Some(session_name),
            window_id,
            window_name,
            pane_id,
        ));
    }
    let Some(pane_id_value) = pane_id.clone() else {
        return Ok(inactive_tmux_focus_state(
            "missing_active_pane",
            Some(session_name),
            window_id,
            window_name,
            None,
        ));
    };
    // `#tmuxautosyncreactive` / `#lazily-hot-path`: the controller runtime owns
    // actor bindings reactively; the SQLite store is a durable sink, not the
    // hot-path authority. The JetBrains reverse-mirror polls this RPC every
    // 500ms, so the caller supplies the in-memory reactive actor store when a
    // runtime is available instead of reopening SQLite on every poll. Cold start
    // (no runtime) still hydrates from SQLite.
    let store = actor_store()?;
    let record = actor_record_for_active_pane(&store, &pane_id_value).cloned();
    let process_owner_document = record
        .is_none()
        .then(|| active_pane_process_owner_document(tmux, &pane_id_value, project_root))
        .flatten();
    let document_id = record
        .as_ref()
        .map(|record| record.document_id.clone())
        .or(process_owner_document);
    if let (Some(eligibility), Some(document)) = (main_layout_eligibility, document_id.as_deref())
        && !document_is_main_layout_eligible(project_root, &eligibility, document)
    {
        return Ok(inactive_tmux_focus_state(
            "document_bound_to_editor_view",
            Some(session_name),
            window_id,
            window_name,
            pane_id,
        ));
    }
    Ok(ControllerTmuxFocusState {
        active: document_id.is_some(),
        reason: if record.is_some() {
            "focused_agent_doc_actor".to_string()
        } else if document_id.is_some() {
            "focused_live_process_owner".to_string()
        } else {
            "active_pane_unbound".to_string()
        },
        session_name: Some(session_name),
        window_id,
        window_name,
        pane_id,
        document_id,
        record,
        navigation_lane: None,
    })
}

/// Find the live (non-blocked, non-closed) actor record whose pane matches the
/// active tmux pane. Pure so the reactive (runtime) and durable (SQLite) reads
/// share one lookup rule — the `#lazily-hot-path` invariant that the authority
/// is the same regardless of which surface serves it.
fn actor_record_for_active_pane<'a>(
    store: &'a ControllerActorStore,
    pane_id: &str,
) -> Option<&'a agent_doc_controller::actor::ActorRecord> {
    store.values().find(|record| {
        record.pane_id == pane_id
            && !matches!(
                record.state,
                agent_doc_controller::actor::ActorState::Blocked
                    | agent_doc_controller::actor::ActorState::Closed
            )
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FocusPaneCandidateDecision<'a> {
    Candidate {
        pane_id: &'a str,
        focused_reason: &'static str,
        not_alive_reason: &'static str,
    },
    Reject {
        reason: FocusPaneRejectReason,
        pane_id: Option<&'a str>,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FocusPaneRejectReason {
    ActorNotFocusable,
    ActorOwnershipUnproven,
    MissingActorRecord,
}

impl FocusPaneRejectReason {
    const fn as_str(self) -> &'static str {
        match self {
            Self::ActorNotFocusable => "actor_not_focusable",
            Self::ActorOwnershipUnproven => "actor_ownership_unproven",
            Self::MissingActorRecord => "missing_actor_record",
        }
    }
}

/// The document's bound actor pane, plus the two facts that decide whether the
/// binding is still usable for a focus handoff.
///
/// `#fpeselectstashpane`: `still_owns_document` is a *guard on the bound pane*,
/// not a search for an alternative one. It is proven from the bound pane's own
/// live process tree, so it can only ever demote the binding — it can never
/// nominate some other pane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FocusActorCandidate<'a> {
    pane_id: &'a str,
    /// The durable actor projection is not `Blocked`/`Closed`.
    focusable: bool,
    /// This pane's live process tree still runs an agent-doc owner session for
    /// this document.
    still_owns_document: bool,
}

/// Reconcile the durable actor/registry projections against a pane whose
/// current process tree proves ownership of the selected document. Focus is a
/// non-mutating UI handoff, so a closed/blocked projection must not hide a
/// still-running route-owned agent. The proof wins only when it is exact; the
/// I/O adapter below rejects dead, bare-shell, and cross-document pane reuse.
///
/// `#fpeselectstashpane`: the bound actor pane outranks a *differing*
/// session-log-derived live owner whenever that bound pane still owns the
/// document. `proven_session_log_focus_owner` reads `latest_start_pane` — where
/// the session was last **started**, not where it currently lives — so after a
/// reroute / resume / rebind it can still name a superseded pane whose stale
/// owner process is alive and parked in the `stash` window. Letting that
/// historical record outrank the generation-fenced actor binding is what focused
/// a stash pane on a document whose actor *and* registry both named the correct
/// visible pane. A selection effect uses the bound pane; a live probe may only
/// invalidate that binding, never replace it.
fn decide_focus_pane_candidate<'a>(
    actor: Option<FocusActorCandidate<'a>>,
    registry_pane: Option<&'a str>,
    proven_live_owner: Option<&'a str>,
) -> FocusPaneCandidateDecision<'a> {
    if let Some(candidate) = actor
        && candidate.focusable
        && candidate.still_owns_document
    {
        return FocusPaneCandidateDecision::Candidate {
            pane_id: candidate.pane_id,
            focused_reason: "focused_agent_doc_actor",
            not_alive_reason: "actor_pane_not_alive",
        };
    }

    if let Some(owner) = proven_live_owner {
        if actor.is_some_and(|candidate| candidate.focusable && candidate.pane_id == owner) {
            return FocusPaneCandidateDecision::Candidate {
                pane_id: owner,
                focused_reason: "focused_agent_doc_actor",
                not_alive_reason: "actor_pane_not_alive",
            };
        }
        return FocusPaneCandidateDecision::Candidate {
            pane_id: owner,
            focused_reason: "focused_live_process_owner",
            not_alive_reason: "live_owner_pane_not_alive",
        };
    }

    if let Some(FocusActorCandidate {
        pane_id,
        focusable: false,
        ..
    }) = actor
    {
        return FocusPaneCandidateDecision::Reject {
            reason: FocusPaneRejectReason::ActorNotFocusable,
            pane_id: Some(pane_id),
        };
    }

    if let Some(pane_id) = registry_pane {
        return FocusPaneCandidateDecision::Candidate {
            pane_id,
            focused_reason: "focused_durable_registry",
            not_alive_reason: "registry_pane_not_alive",
        };
    }

    if let Some(candidate) = actor {
        return FocusPaneCandidateDecision::Reject {
            reason: FocusPaneRejectReason::ActorOwnershipUnproven,
            pane_id: Some(candidate.pane_id),
        };
    }

    FocusPaneCandidateDecision::Reject {
        reason: FocusPaneRejectReason::MissingActorRecord,
        pane_id: None,
    }
}

/// A `Blocked`/`Closed` *durable* actor projection must not veto a pure,
/// non-mutating UI focus handoff when the pane's live process tree still exactly
/// owns this document (a finished/blocked session whose pane is still open and
/// showing that document). Focus is non-mutating and the alive/visible guards
/// still apply downstream. Ownership is proven from the *live process tree*
/// (`pane_process_owner_document`), never the stale durable state, so a pane
/// reused by a different document stays refused (`actor_not_focusable`) and
/// cross-document focus steal cannot happen. Returns the rescued pane when the
/// reject is safe to override.
fn focus_reject_rescued_by_live_pane_owner<'a>(
    reject_reason: FocusPaneRejectReason,
    pane_id: Option<&'a str>,
    pane_process_owner_document: Option<&str>,
    document_id: &str,
) -> Option<&'a str> {
    if reject_reason != FocusPaneRejectReason::ActorNotFocusable {
        return None;
    }
    let pane = pane_id?;
    (pane_process_owner_document == Some(document_id)).then_some(pane)
}

fn rejected_focus_should_resume_latest(
    missing_pane_policy: MissingFocusPanePolicy,
    reject_reason: FocusPaneRejectReason,
    session_id: Option<&str>,
) -> bool {
    // A durable actor row whose pane no longer proves ownership is unusable in
    // exactly the same way as a closed actor or a missing row. ObserveOnly
    // still refuses it (and therefore can never focus the wrong pane), while
    // the explicit recovery/layout policies may provision a fresh owner for
    // the known session. Omitting ActorOwnershipUnproven here leaves a dead
    // cross-root actor binding permanently wedged: the parent layout asks the
    // owning controller to provision, but the owning controller returns the
    // stale binding as a terminal focus rejection before reaching auto-start.
    missing_pane_policy.provisions_missing()
        && session_id.is_some()
        && matches!(
            reject_reason,
            FocusPaneRejectReason::ActorNotFocusable
                | FocusPaneRejectReason::ActorOwnershipUnproven
                | FocusPaneRejectReason::MissingActorRecord
        )
}

fn missing_focus_pane_observation<'a>(
    missing_pane_policy: MissingFocusPanePolicy,
    pane_id: &'a str,
    last_known_window: Option<&'a str>,
) -> Option<ControllerMissingPaneObservation<'a>> {
    (missing_pane_policy.provisions_missing() && !pane_id.is_empty()).then_some(
        ControllerMissingPaneObservation {
            pane_id,
            last_known_window: last_known_window.filter(|window| !window.is_empty()),
        },
    )
}

fn current_document_session_id(
    canonical: &Path,
    actor_record: Option<&agent_doc_controller::actor::ActorRecord>,
    registry_entry: Option<&tmux_router::RegistryEntry>,
) -> Option<String> {
    // This runs inside the controller that owns the relay; consume its
    // in-memory source directly. An attached editor with no settled replica is
    // an unresolved source, not permission to fall back to stale disk.
    let current = agent_doc_crdt_relay_io::current_text_for_file_nonblocking(canonical)
        .unwrap_or(agent_doc_crdt_relay_io::CurrentText::EditorSyncPending);
    let disk_content = matches!(&current, agent_doc_crdt_relay_io::CurrentText::Detached)
        .then(|| std::fs::read_to_string(canonical).ok())
        .flatten();
    current_document_session_id_from_authority(
        &current,
        disk_content.as_deref(),
        actor_record.map(|record| record.session_id.as_str()),
        registry_entry.map(|entry| entry.session_id.as_str()),
    )
}

fn current_document_session_id_from_authority(
    current: &agent_doc_crdt_relay_io::CurrentText,
    detached_disk_content: Option<&str>,
    actor_session_id: Option<&str>,
    registry_session_id: Option<&str>,
) -> Option<String> {
    fn nonempty(value: Option<&str>) -> Option<String> {
        value
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    }

    fn session_from_content(content: &str) -> Option<String> {
        let (frontmatter, _) = agent_doc_frontmatter::frontmatter::parse(content).ok()?;
        nonempty(frontmatter.session.as_deref())
    }

    let authority_session = match current {
        agent_doc_crdt_relay_io::CurrentText::Current { text, .. } => session_from_content(text),
        agent_doc_crdt_relay_io::CurrentText::Detached => {
            detached_disk_content.and_then(session_from_content)
        }
        agent_doc_crdt_relay_io::CurrentText::EditorAttachedMissingReplica
        | agent_doc_crdt_relay_io::CurrentText::EditorSyncPending => None,
    };
    authority_session
        .or_else(|| nonempty(registry_session_id))
        .or_else(|| nonempty(actor_session_id))
}

#[cfg(test)]
mod navigation_lane_focus_state_tests {
    //! `#ideriderindependentnav`: the tmux focus projection is split per
    //! navigation lane, so each editor installation's reverse mirror reads only
    //! its own lane session.
    use super::*;
    use agent_doc_editor_surface::NavigationLane;

    const IDEA: &str = "IU.0a1b2c3d";
    const RIDER: &str = "RD.9f8e7d6c";

    fn actor(document: &str, pane_id: &str) -> agent_doc_controller::actor::ActorRecord {
        agent_doc_controller::actor::ActorRecord {
            document_id: document.to_string(),
            session_id: format!("session-{pane_id}"),
            generation: 3,
            pane_id: pane_id.to_string(),
            window_id: "@1".to_string(),
            harness: "codex".to_string(),
            state: agent_doc_controller::actor::ActorState::Ready,
            last_transition: agent_doc_controller::actor::ActorLastTransition {
                caller: "test".to_string(),
                reason: "lane focus state".to_string(),
                timestamp: 1,
                prior_generation: 2,
                new_generation: 3,
            },
        }
    }

    fn new_agent_doc_session(tmux: &tmux_router::Tmux, session: &str) -> String {
        tmux.raw_cmd(&["new-session", "-d", "-s", session, "-n", "agent-doc"])
            .unwrap_or_else(|error| panic!("new-session {session}: {error:#}"));
        tmux.active_pane(session)
            .unwrap_or_else(|| panic!("{session} has an active pane"))
    }

    #[test]
    fn each_lane_reports_only_its_own_sessions_focused_document() {
        let tmux = agent_doc_tmux_io::isolated_test_tmux("ideriderindependentnav-focus");
        let project = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(project.path().join(".agent-doc")).unwrap();
        std::fs::write(
            project.path().join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\n",
        )
        .unwrap();
        let idea_lane = NavigationLane::Installation(IDEA.to_string());
        let rider_lane = NavigationLane::Installation(RIDER.to_string());
        assert_eq!(idea_lane.tmux_session_name("proj"), "proj-IU-0a1b2c3d");

        let shared_pane = new_agent_doc_session(&tmux, "proj");
        let idea_pane = new_agent_doc_session(&tmux, "proj-IU-0a1b2c3d");
        // Rider's lane session exists but its current window is not agent-doc.
        let rider_pane = new_agent_doc_session(&tmux, "proj-RD-9f8e7d6c");
        tmux.raw_cmd(&["new-window", "-t", "proj-RD-9f8e7d6c:", "-n", "notes"])
            .unwrap();

        let shared_doc = project.path().join("tasks/shared.md");
        let idea_doc = project.path().join("tasks/idea.md");
        let rider_doc = project.path().join("tasks/rider.md");
        let store: ControllerActorStore = [
            (&shared_doc, &shared_pane),
            (&idea_doc, &idea_pane),
            (&rider_doc, &rider_pane),
        ]
        .into_iter()
        .map(|(document, pane)| {
            let document = document.to_string_lossy().to_string();
            (document.clone(), actor(&document, pane))
        })
        .collect();
        let read = |lane: &NavigationLane| {
            tmux_focus_state_for_lane(&tmux, project.path(), lane, None, || Ok(store.clone()))
                .unwrap()
        };

        let shared = read(&NavigationLane::Shared);
        assert!(shared.active, "{shared:?}");
        assert_eq!(shared.session_name.as_deref(), Some("proj"));
        assert_eq!(shared.pane_id.as_deref(), Some(shared_pane.as_str()));
        assert_eq!(
            shared.document_id.as_deref(),
            Some(shared_doc.to_string_lossy().as_ref())
        );
        assert_eq!(shared.navigation_lane, None);
        assert!(
            !serde_json::to_string(&shared)
                .unwrap()
                .contains("navigation_lane"),
            "the shared projection keeps its pre-lane wire shape"
        );

        let idea = read(&idea_lane);
        assert!(idea.active, "{idea:?}");
        assert_eq!(idea.session_name.as_deref(), Some("proj-IU-0a1b2c3d"));
        assert_eq!(idea.pane_id.as_deref(), Some(idea_pane.as_str()));
        assert_eq!(
            idea.document_id.as_deref(),
            Some(idea_doc.to_string_lossy().as_ref())
        );
        assert_eq!(idea.navigation_lane.as_deref(), Some(IDEA));

        // Navigating Rider's lane session to another window recalls nothing in
        // Rider, and it never leaks another lane's selection.
        let rider = read(&rider_lane);
        assert!(!rider.active, "{rider:?}");
        assert_eq!(rider.reason, "outside_agent_doc_window");
        assert_eq!(rider.session_name.as_deref(), Some("proj-RD-9f8e7d6c"));
        assert_eq!(rider.document_id, None);
        assert_eq!(rider.navigation_lane.as_deref(), Some(RIDER));

        // A lane whose session was never provisioned is inactive, not a
        // fallback onto the shared session.
        let absent = read(&NavigationLane::Installation("CL.00000000".to_string()));
        assert!(!absent.active);
        assert_eq!(absent.reason, "tmux_session_not_alive");
        assert_eq!(absent.session_name.as_deref(), Some("proj-CL-00000000"));

        // Selecting a pane in one lane's session moves only that lane.
        tmux.raw_cmd(&["split-window", "-d", "-t", "proj-IU-0a1b2c3d:agent-doc"])
            .unwrap();
        tmux.raw_cmd(&["select-pane", "-t", "proj-IU-0a1b2c3d:agent-doc.1"])
            .unwrap();
        let idea_after = read(&idea_lane);
        assert_ne!(idea_after.pane_id.as_deref(), Some(idea_pane.as_str()));
        assert_eq!(idea_after.reason, "active_pane_unbound");
        assert_eq!(read(&NavigationLane::Shared), shared);
    }

    #[test]
    fn a_missing_configured_session_is_inactive_for_every_lane() {
        let tmux = agent_doc_tmux_io::isolated_test_tmux("ideriderindependentnav-nocfg");
        // A live server, so a regression that reached tmux would observe it.
        tmux.raw_cmd(&["new-session", "-d", "-s", "proj", "-n", "agent-doc"])
            .unwrap();
        let project = tempfile::tempdir().unwrap();
        for lane in [
            NavigationLane::Shared,
            NavigationLane::Installation(IDEA.to_string()),
        ] {
            let state = tmux_focus_state_for_lane(&tmux, project.path(), &lane, None, || {
                panic!("no session: the actor store must not be read")
            })
            .unwrap();
            assert_eq!(state.reason, "missing_tmux_session");
            assert_eq!(state.navigation_lane.as_deref(), lane.installation());
        }
    }
}

#[cfg(test)]
mod current_document_session_tests {
    use super::*;

    fn current(text: &str) -> agent_doc_crdt_relay_io::CurrentText {
        agent_doc_crdt_relay_io::CurrentText::Current {
            text: text.to_string(),
            live_editors: 1,
            delivery_converged: true,
            delivery_version: 1,
            semantics: None,
        }
    }

    #[test]
    fn editor_projection_wins_over_stale_disk_and_durable_rows() {
        let editor = current("---\nagent_doc_session: editor-session\n---\n");
        let disk = "---\nagent_doc_session: disk-session\n---\n";
        assert_eq!(
            current_document_session_id_from_authority(
                &editor,
                Some(disk),
                Some("actor-session"),
                Some("registry-session"),
            )
            .as_deref(),
            Some("editor-session")
        );
    }

    #[test]
    fn attached_missing_replica_never_uses_disk_as_authority() {
        let current = agent_doc_crdt_relay_io::CurrentText::EditorAttachedMissingReplica;
        let disk = "---\nagent_doc_session: stale-disk-session\n---\n";
        assert_eq!(
            current_document_session_id_from_authority(
                &current,
                Some(disk),
                Some("actor-session"),
                Some("registry-session"),
            )
            .as_deref(),
            Some("registry-session")
        );
    }

    #[test]
    fn detached_document_may_use_disk_and_empty_rows_do_not_mask_fallbacks() {
        let detached = agent_doc_crdt_relay_io::CurrentText::Detached;
        let disk = "---\nagent_doc_session: disk-session\n---\n";
        assert_eq!(
            current_document_session_id_from_authority(
                &detached,
                Some(disk),
                Some("actor-session"),
                Some(""),
            )
            .as_deref(),
            Some("disk-session")
        );
        assert_eq!(
            current_document_session_id_from_authority(
                &agent_doc_crdt_relay_io::CurrentText::EditorSyncPending,
                Some(disk),
                Some("actor-session"),
                Some(" "),
            )
            .as_deref(),
            Some("actor-session")
        );
    }
}

fn process_tree_exactly_owns_document(
    tmux: &tmux_router::Tmux,
    pane_id: &str,
    file: &Path,
) -> bool {
    let Some(pane_pid) = agent_doc_tmux_io::pane_pid(tmux, pane_id) else {
        return false;
    };
    agent_doc_process_owner_io::process_tree_has_agent_doc_owner_for_file(
        &pane_pid.to_string(),
        &file.to_string_lossy(),
    )
}

fn session_log_owner_signals_prove_focus(
    latest_session_open: bool,
    pane_owns_live_agent: bool,
    process_tree_exactly_owns_document: bool,
) -> bool {
    latest_session_open && pane_owns_live_agent && process_tree_exactly_owns_document
}

fn proven_session_log_focus_owner(
    tmux: &tmux_router::Tmux,
    file: &Path,
    session_id: &str,
) -> Option<String> {
    let status = agent_doc_supervisor_io::startup_miss::session_log_status(file, session_id)
        .ok()
        .flatten()?;
    let latest_session_open = status.latest_session_open();
    let pane_id = status.latest_start_pane?;
    if !session_log_owner_signals_prove_focus(
        latest_session_open,
        agent_doc_supervisor_process::session_liveness::pane_owns_live_agent(tmux, &pane_id),
        process_tree_exactly_owns_document(tmux, &pane_id, file),
    ) {
        return None;
    }
    Some(pane_id)
}

fn active_pane_process_owner_document(
    tmux: &tmux_router::Tmux,
    pane_id: &str,
    project_root: &Path,
) -> Option<String> {
    let canonical = live_pane_process_owner_document(tmux, pane_id, project_root)?;
    let owner_root = agent_doc_project_root_io::project_root_containing(&canonical)?;
    if owner_root != project_root {
        return None;
    }
    Some(agent_doc_session_actor_io::canonical_document_id_in(
        project_root,
        &canonical.to_string_lossy(),
    ))
}

/// `#stalecontrollerhotupdate` (c): the live owner document of `pane_id` when
/// that document belongs to a project root FOREIGN to `controller_root`
/// ([`agent_doc_controller::layout_owner::pane_owner_is_foreign`]): neither the
/// controller's own root nor nested beneath it. Such a pane is another
/// controller's to arrange, so this controller never stashes or swaps it out
/// and does not count it toward convergence. `None` when the pane has no live
/// agent-doc owner or its root is unknown.
pub fn foreign_pane_owner_document(
    tmux: &tmux_router::Tmux,
    pane_id: &str,
    controller_root: &Path,
) -> Option<PathBuf> {
    let document = live_pane_process_owner_document(tmux, pane_id, controller_root)?;
    let controller_root = controller_root
        .canonicalize()
        .unwrap_or_else(|_| controller_root.to_path_buf());
    let owner_root = agent_doc_project_root_io::project_root_containing(&document)
        .map(|root| root.canonicalize().unwrap_or(root));
    agent_doc_controller::layout_owner::pane_owner_is_foreign(
        &controller_root,
        owner_root.as_deref(),
    )
    .then_some(document)
}

/// `#stalecontrollerhotupdate` (c): true when `window`'s layout claim
/// ([`agent_doc_controller::layout_owner::WindowLayoutClaim`]) is held by a
/// project root other than `project_root`, i.e. another controller's
/// publication is the newest to drive this window. Foreign-pane protection
/// applies only then: once this controller holds the claim, the editor's newest
/// frame is its own and a foreign pane it does not name is an ordinary extra
/// (the editor going from 2 panes to 1 must still be able to drop it).
pub fn window_layout_driven_by_other_root(
    tmux: &tmux_router::Tmux,
    window: &str,
    project_root: &Path,
) -> bool {
    use agent_doc_controller::layout_owner::{WINDOW_LAYOUT_CLAIM_OPTION, WindowLayoutClaim};
    let own_root = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());
    agent_doc_tmux_io::window_user_option(tmux, window, WINDOW_LAYOUT_CLAIM_OPTION)
        .and_then(|value| WindowLayoutClaim::decode(&value))
        .is_some_and(|claim| claim.project_root != own_root)
}

fn live_pane_process_owner_document(
    tmux: &tmux_router::Tmux,
    pane_id: &str,
    fallback_root: &Path,
) -> Option<PathBuf> {
    if !agent_doc_supervisor_process::session_liveness::pane_owns_live_agent(tmux, pane_id) {
        return None;
    }
    let pane_pid = agent_doc_tmux_io::pane_pid(tmux, pane_id)?;
    let raw_document =
        agent_doc_process_owner_io::process_tree_agent_doc_owner_document(&pane_pid.to_string())?;
    let raw_path = PathBuf::from(raw_document);
    let candidate = if raw_path.is_absolute() {
        raw_path
    } else {
        agent_doc_tmux_io::pane_current_path(tmux, pane_id)
            .unwrap_or_else(|| fallback_root.to_path_buf())
            .join(raw_path)
    };
    candidate.canonicalize().ok()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FocusDocumentPaneEffect {
    Focused,
    DesktopEditorInactive,
    PaneNotVisible,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FocusPanePlacementDecision {
    Ready,
    PaneNotVisible,
    OutsideAgentDocWindow,
}

fn decide_focus_pane_placement(
    active_window_id: Option<&str>,
    active_window_name: Option<&str>,
    agent_doc_window_id: Option<&str>,
    pane_window_id: Option<&str>,
) -> FocusPanePlacementDecision {
    let Some(agent_doc_window_id) = agent_doc_window_id else {
        return FocusPanePlacementDecision::OutsideAgentDocWindow;
    };
    if pane_window_id != Some(agent_doc_window_id) {
        return FocusPanePlacementDecision::PaneNotVisible;
    }
    if active_window_name != Some("agent-doc") || active_window_id != Some(agent_doc_window_id) {
        return FocusPanePlacementDecision::OutsideAgentDocWindow;
    }
    FocusPanePlacementDecision::Ready
}

/// Apply the tmux half of a selected-document focus intent.
///
/// Selection-only editor focus leaves stashed panes to the structural layout
/// owner. An explicit recovery policy may surface a stashed pane inside this
/// fenced effect, then re-observe its window before selecting. Re-observation
/// prevents a failed or racing promotion from selecting inside the stash.
fn apply_focus_document_pane_effect(
    pane_id: &str,
    expected_window: Option<&str>,
    desktop_editor_active: bool,
    allow_promotion: bool,
    observe_pane_window: impl Fn(&str) -> Option<String>,
    promote_pane: impl FnOnce(&str) -> Result<bool>,
    select_pane: impl FnOnce(&str) -> Result<()>,
) -> Result<FocusDocumentPaneEffect> {
    if !desktop_editor_active {
        return Ok(FocusDocumentPaneEffect::DesktopEditorInactive);
    }

    let pane_is_visible = |pane_window: Option<String>| {
        pane_window.as_deref() == expected_window && expected_window.is_some()
    };
    if !pane_is_visible(observe_pane_window(pane_id))
        && (!allow_promotion
            || !promote_pane(pane_id)?
            || !pane_is_visible(observe_pane_window(pane_id)))
    {
        return Ok(FocusDocumentPaneEffect::PaneNotVisible);
    }

    select_pane(pane_id)?;
    Ok(FocusDocumentPaneEffect::Focused)
}

pub(crate) fn handle_focus_document_pane(
    bootstrap: &ControllerBootstrap,
    request: ControllerRequest,
) -> Result<ControllerTmuxFocusReceipt> {
    let policy = request
        .diagnostic_payload
        .as_deref()
        .map(serde_json::from_str::<MissingFocusPanePolicy>)
        .transpose()?
        .unwrap_or(MissingFocusPanePolicy::ObserveOnly);
    handle_focus_document_pane_with_policy(bootstrap, None, request, policy, None)
}

/// Ask the controller that actually owns `document` to focus it.
///
/// `#focuscrossroot`: a failure here is reported as its own reason rather than
/// collapsed back into `missing_actor_record`. "The owning controller could not
/// be reached" and "this controller has no actor for the document" are
/// different faults, and reporting the second for the first is what made the
/// original bug invisible.
fn delegate_focus_to_owning_controller(
    controller_root: &Path,
    owner_root: &Path,
    document: &Path,
    missing_pane_policy: MissingFocusPanePolicy,
) -> ControllerTmuxFocusReceipt {
    // Preserve the caller's structural authority across the project-root hop.
    // In particular, manual/full layout sync reaches this seam with
    // `ProvisionForLayout`; degrading that request to the public focus-only
    // helper leaves a killed subproject pane unresolved forever even though
    // the owning controller is exactly the component allowed to recreate it.
    match request_document_pane(owner_root, document, missing_pane_policy) {
        Ok(receipt) => {
            agent_doc_ops_log_io::log_op(
                controller_root,
                &format!(
                    "controller_focus_delegated document={} owner_root={} policy={missing_pane_policy:?} focused={} reason={}",
                    document.display(),
                    owner_root.display(),
                    receipt.focused,
                    receipt.reason,
                ),
            );
            receipt
        }
        Err(error) => {
            agent_doc_ops_log_io::log_op(
                controller_root,
                &format!(
                    "controller_focus_delegation_failed document={} owner_root={} policy={missing_pane_policy:?} error={error:#}",
                    document.display(),
                    owner_root.display(),
                ),
            );
            tmux_focus_receipt(
                false,
                "cross_root_controller_unavailable",
                Some(document.to_string_lossy().to_string()),
                None,
                None,
                None,
                None,
            )
        }
    }
}

fn handle_focus_document_pane_with_policy(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    request: ControllerRequest,
    missing_pane_policy: MissingFocusPanePolicy,
    focus_fence: Option<&AsyncEditorFocusFence>,
) -> Result<ControllerTmuxFocusReceipt> {
    let requested_file = request_file(&request)?;
    let canonical = canonical_controller_request_file(bootstrap, &requested_file);
    // `#focuscrossroot`: an IDE rooted at the superproject publishes one editor
    // surface, so selecting a tab inside a submodule that owns its own
    // `.agent-doc/` sends that focus intent here. This controller's actor store
    // is keyed on its own root and has no row for it, so the honest local
    // answer was `missing_actor_record` and nothing focused — while the
    // submodule's controller held the live binding and was never asked.
    // Re-address the request instead of refusing it.
    if let agent_doc_controller::focus_routing::FocusOwner::Delegate(owner_root) =
        agent_doc_controller::focus_routing::focus_owner(
            &bootstrap.project_root,
            agent_doc_project_root_io::project_root_containing(&canonical).as_deref(),
        )
    {
        return Ok(delegate_focus_to_owning_controller(
            &bootstrap.project_root,
            owner_root,
            &canonical,
            missing_pane_policy,
        ));
    }
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &bootstrap.project_root,
        &canonical.to_string_lossy(),
    );
    let actor_record = actor_record_from_authority(bootstrap, runtime, &document_id)?;
    let registry_entry =
        agent_doc_session_registry_io::lookup_file_entry_in(&bootstrap.project_root, &canonical)?;
    let tmux = agent_doc_tmux_io::configured_tmux();
    let session_id =
        current_document_session_id(&canonical, actor_record.as_ref(), registry_entry.as_ref());
    let proven_live_owner = session_id
        .as_deref()
        .and_then(|session_id| proven_session_log_focus_owner(&tmux, &canonical, session_id));
    let actor = actor_record.as_ref().map(|record| {
        let focusable = !matches!(
            record.state,
            agent_doc_controller::actor::ActorState::Blocked
                | agent_doc_controller::actor::ActorState::Closed
        );
        // `#fpeselectstashpane`: probe the BOUND pane, never scan for another
        // one. Every focus candidate needs current process-tree proof: a stale
        // actor row must not steer the client merely because its pane remains
        // alive and focusable.
        let still_owns_document =
            focusable && process_tree_exactly_owns_document(&tmux, &record.pane_id, &canonical);
        FocusActorCandidate {
            pane_id: record.pane_id.as_str(),
            focusable,
            still_owns_document,
        }
    });
    let decision = decide_focus_pane_candidate(
        actor,
        registry_entry.as_ref().and_then(|entry| {
            process_tree_exactly_owns_document(&tmux, &entry.pane, &canonical)
                .then_some(entry.pane.as_str())
        }),
        proven_live_owner.as_deref(),
    );
    let (mut pane_id, mut focused_reason, not_alive_reason) = match decision {
        FocusPaneCandidateDecision::Candidate {
            pane_id,
            focused_reason,
            not_alive_reason,
        } => (pane_id.to_string(), focused_reason, not_alive_reason),
        FocusPaneCandidateDecision::Reject { reason, pane_id } => {
            let pane_owner_document = pane_id.and_then(|pane| {
                active_pane_process_owner_document(&tmux, pane, &bootstrap.project_root)
            });
            if let Some(pane) = focus_reject_rescued_by_live_pane_owner(
                reason,
                pane_id,
                pane_owner_document.as_deref(),
                &document_id,
            ) {
                (
                    pane.to_string(),
                    "focused_live_process_owner",
                    "live_owner_pane_not_alive",
                )
            } else if rejected_focus_should_resume_latest(
                missing_pane_policy,
                reason,
                session_id.as_deref(),
            ) {
                (
                    pane_id.unwrap_or_default().to_string(),
                    "resuming_missing_actor_pane",
                    reason.as_str(),
                )
            } else {
                return Ok(tmux_focus_receipt(
                    false,
                    reason.as_str(),
                    Some(document_id),
                    pane_id.map(ToOwned::to_owned),
                    None,
                    None,
                    None,
                ));
            }
        }
    };
    if pane_id.is_empty() || !tmux.pane_alive(&pane_id) {
        if missing_pane_policy.provisions_missing()
            && let Some(session_id) = session_id.as_deref()
        {
            if focus_fence.is_some() {
                runtime
                    .context("async editor focus fence requires controller runtime")?
                    .async_editor_commands
                    .require_focus_fence_current(focus_fence)?;
            }
            let file_arg = canonical.to_string_lossy().to_string();
            let stale_pane = pane_id.clone();
            let last_known_window = actor_record
                .as_ref()
                .map(|record| record.window_id.as_str())
                .filter(|window| !window.is_empty())
                .or_else(|| {
                    registry_entry
                        .as_ref()
                        .map(|entry| entry.window.as_str())
                        .filter(|window| !window.is_empty())
                });
            pane_id = runtime_effects()?
                .route_auto_start(ControllerRouteAutoStartInvocation {
                    tmux: &tmux,
                    file: &canonical,
                    session_id,
                    file_arg: &file_arg,
                    window: None,
                    policy: ControllerRouteAutoStartPolicy::ProvisionOnly,
                    defer_focus_to_layout: missing_pane_policy
                        == MissingFocusPanePolicy::ProvisionForLayout,
                    missing_pane: missing_focus_pane_observation(
                        missing_pane_policy,
                        &stale_pane,
                        last_known_window,
                    ),
                    resume: Some(agent_doc_harness::ResumeRequest::Latest),
                })
                .with_context(|| {
                    format!(
                        "failed to resume killed selected-document session for {}",
                        canonical.display()
                    )
                })?;
            focused_reason = "resumed_missing_actor_pane";
            agent_doc_ops_log_io::log_op(
                &canonical,
                &format!(
                    "controller_focus_resumed_missing_actor document={} session={} stale_pane={} replacement_pane={}",
                    document_id, session_id, stale_pane, pane_id,
                ),
            );
        } else {
            return Ok(tmux_focus_receipt(
                false,
                not_alive_reason,
                Some(document_id),
                Some(pane_id),
                None,
                None,
                None,
            ));
        }
    }
    if pane_id.is_empty() || !tmux.pane_alive(&pane_id) {
        return Ok(tmux_focus_receipt(
            false,
            "resumed_pane_not_alive",
            Some(document_id),
            Some(pane_id),
            None,
            None,
            None,
        ));
    }
    if missing_pane_policy == MissingFocusPanePolicy::ProvisionForLayout {
        return Ok(tmux_focus_receipt(
            false,
            "layout_owner_provisioned",
            Some(document_id),
            Some(pane_id),
            None,
            None,
            None,
        ));
    }
    let session_name = tmux
        .pane_session(&pane_id)
        .ok()
        .or_else(|| configured_tmux_session_for_project(&bootstrap.project_root));
    let Some(session_name_value) = session_name.clone() else {
        return Ok(tmux_focus_receipt(
            false,
            "missing_tmux_session",
            Some(document_id),
            Some(pane_id),
            None,
            None,
            None,
        ));
    };
    let (window_id, window_name, _active_pane) =
        active_tmux_window_for_session(&tmux, &session_name_value);
    let agent_doc_window_id = if window_name.as_deref() == Some("agent-doc") {
        window_id.clone()
    } else {
        resolve_agent_doc_window_id_for_session(&tmux, &session_name_value)
    };
    let pane_window_id = tmux.pane_window(&pane_id).ok();
    match decide_focus_pane_placement(
        window_id.as_deref(),
        window_name.as_deref(),
        agent_doc_window_id.as_deref(),
        pane_window_id.as_deref(),
    ) {
        FocusPanePlacementDecision::PaneNotVisible
            if missing_pane_policy != MissingFocusPanePolicy::ResumeLatest =>
        {
            return Ok(tmux_focus_receipt(
                false,
                "actor_pane_not_visible",
                Some(document_id),
                Some(pane_id),
                Some(session_name_value),
                window_id,
                window_name,
            ));
        }
        FocusPanePlacementDecision::OutsideAgentDocWindow => {
            return Ok(tmux_focus_receipt(
                false,
                "outside_agent_doc_window",
                Some(document_id),
                Some(pane_id),
                Some(session_name_value),
                window_id,
                window_name,
            ));
        }
        FocusPanePlacementDecision::Ready | FocusPanePlacementDecision::PaneNotVisible => {}
    }
    let focus_effect = || {
        apply_focus_document_pane_effect(
            &pane_id,
            agent_doc_window_id.as_deref(),
            focus_fence.is_none() || desktop_editor_focus_state() != DesktopEditorFocusState::Other,
            missing_pane_policy == MissingFocusPanePolicy::ResumeLatest,
            |pane| tmux.pane_window(pane).ok(),
            |pane| runtime_effects()?.promote_pane_to_agent_doc_window(&tmux, pane),
            |pane| tmux.select_pane(pane),
        )
    };
    let focus_effect = if focus_fence.is_some() {
        runtime
            .context("async editor focus fence requires controller runtime")?
            .async_editor_commands
            .apply_focus_effect(focus_fence, focus_effect)?
    } else {
        focus_effect()?
    };
    match focus_effect {
        FocusDocumentPaneEffect::Focused => {}
        FocusDocumentPaneEffect::DesktopEditorInactive => {
            agent_doc_ops_log_io::log_op(
                &bootstrap.project_root,
                &format!(
                    "controller_focus_suppressed document={} pane={} reason=desktop_editor_inactive",
                    document_id, pane_id
                ),
            );
            return Ok(tmux_focus_receipt(
                false,
                "desktop_editor_inactive",
                Some(document_id),
                Some(pane_id),
                Some(session_name_value),
                window_id,
                window_name,
            ));
        }
        FocusDocumentPaneEffect::PaneNotVisible => {
            return Ok(tmux_focus_receipt(
                false,
                "actor_pane_not_visible",
                Some(document_id),
                Some(pane_id),
                Some(session_name_value),
                window_id,
                window_name,
            ));
        }
    }
    Ok(tmux_focus_receipt(
        true,
        focused_reason,
        Some(document_id),
        Some(pane_id),
        Some(session_name_value),
        window_id,
        window_name,
    ))
}

#[cfg(test)]
mod desktop_editor_focus_tests {
    use super::*;
    use std::cell::Cell;

    fn i3_tree(class: Option<&str>) -> serde_json::Value {
        let focused = match class {
            Some(class) => serde_json::json!({
                "focused": true,
                "window_properties": {"class": class},
                "nodes": [],
                "floating_nodes": []
            }),
            None => serde_json::json!({
                "focused": true,
                "nodes": [],
                "floating_nodes": []
            }),
        };
        serde_json::json!({
            "focused": false,
            "nodes": [{
                "focused": false,
                "nodes": [focused],
                "floating_nodes": []
            }],
            "floating_nodes": []
        })
    }

    #[test]
    fn i3_desktop_focus_distinguishes_editors_from_other_windows() {
        assert_eq!(
            desktop_editor_focus_state_from_i3_tree(&i3_tree(Some("jetbrains-idea"))),
            DesktopEditorFocusState::Editor
        );
        assert_eq!(
            desktop_editor_focus_state_from_i3_tree(&i3_tree(Some("Brave-browser"))),
            DesktopEditorFocusState::Other
        );
        assert_eq!(
            desktop_editor_focus_state_from_i3_tree(&i3_tree(None)),
            DesktopEditorFocusState::Unknown
        );
    }

    #[test]
    fn inactive_desktop_strips_only_automatic_layout_focus() {
        assert!(!automatic_editor_focus_allowed(
            DesktopEditorFocusState::Other
        ));
        assert!(automatic_editor_focus_allowed(
            DesktopEditorFocusState::Editor
        ));
        assert!(automatic_editor_focus_allowed(
            DesktopEditorFocusState::Unknown
        ));
        let mut automatic = ControllerTmuxLayoutSyncInvocation {
            columns: vec!["a.md,b.md".to_string()],
            window: None,
            focus: Some("a.md".to_string()),
            no_autostart: true,
            exact_visible: true,
            caller_kind: "automatic".to_string(),
            column_order: Default::default(),
            actor_bindings: Vec::new(),
            client_id: None,
        };
        assert!(suppress_inactive_automatic_layout_focus(
            &mut automatic,
            DesktopEditorFocusState::Other
        ));
        assert_eq!(automatic.focus, None);

        let mut manual = ControllerTmuxLayoutSyncInvocation {
            focus: Some("a.md".to_string()),
            caller_kind: "manual".to_string(),
            ..automatic
        };
        assert!(!suppress_inactive_automatic_layout_focus(
            &mut manual,
            DesktopEditorFocusState::Other
        ));
        assert_eq!(manual.focus.as_deref(), Some("a.md"));
    }

    #[test]
    fn observe_only_focus_cannot_add_a_third_pane() {
        for window in ["@stash", "@agent-doc"] {
            let selected = Cell::new(false);
            let outcome = apply_focus_document_pane_effect(
                "%64",
                Some("@agent-doc"),
                true,
                false,
                |_| Some(window.to_string()),
                |_| panic!("selection-only focus must never promote a pane"),
                |_| {
                    selected.set(true);
                    Ok(())
                },
            )
            .unwrap();
            assert_eq!(selected.get(), window == "@agent-doc");
            assert_eq!(
                outcome,
                if window == "@agent-doc" {
                    FocusDocumentPaneEffect::Focused
                } else {
                    FocusDocumentPaneEffect::PaneNotVisible
                }
            );
        }
    }

    #[test]
    fn focus_placement_classifies_stashed_selected_pane_before_active_window_guard() {
        assert_eq!(
            decide_focus_pane_placement(
                Some("@stash"),
                Some("stash"),
                Some("@agent-doc"),
                Some("@stash"),
            ),
            FocusPanePlacementDecision::PaneNotVisible,
        );
        assert_eq!(
            decide_focus_pane_placement(
                Some("@stash"),
                Some("stash"),
                Some("@agent-doc"),
                Some("@agent-doc"),
            ),
            FocusPanePlacementDecision::OutsideAgentDocWindow,
        );
        assert_eq!(
            decide_focus_pane_placement(
                Some("@agent-doc"),
                Some("agent-doc"),
                Some("@agent-doc"),
                Some("@agent-doc"),
            ),
            FocusPanePlacementDecision::Ready,
        );
    }

    #[test]
    fn no_promotion_disables_missing_actor_provisioning_even_with_legacy_resume_policy() {
        let payload: FocusDocumentPaneCommandPayload = serde_json::from_value(serde_json::json!({
            "document_path": "/tmp/session.md", "no_promotion": true,
            "missing_pane_policy": "resume_latest"
        }))
        .unwrap();
        assert_eq!(
            payload.effective_policy(),
            MissingFocusPanePolicy::ObserveOnly
        );
        assert!(!rejected_focus_should_resume_latest(
            payload.effective_policy(),
            FocusPaneRejectReason::MissingActorRecord,
            Some("session")
        ));
        let explicit = FocusDocumentPaneCommandPayload {
            no_promotion: false,
            ..payload
        };
        assert_eq!(
            explicit.effective_policy(),
            MissingFocusPanePolicy::ResumeLatest
        );
    }

    #[test]
    fn document_focus_promotes_stashed_pane_before_selecting_it() {
        let live_window = Cell::new("@stash");
        let promoted = Cell::new(false);
        let selected = Cell::new(false);

        let effect = apply_focus_document_pane_effect(
            "%64",
            Some("@agent-doc"),
            true,
            true,
            |_| Some(live_window.get().to_string()),
            |pane| {
                assert_eq!(pane, "%64");
                promoted.set(true);
                live_window.set("@agent-doc");
                Ok(true)
            },
            |pane| {
                assert_eq!(pane, "%64");
                assert!(promoted.get(), "promotion must precede selection");
                selected.set(true);
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(effect, FocusDocumentPaneEffect::Focused);
        assert!(selected.get());
    }

    #[test]
    fn document_focus_never_selects_when_promotion_does_not_make_pane_visible() {
        let selected = Cell::new(false);
        let effect = apply_focus_document_pane_effect(
            "%64",
            Some("@agent-doc"),
            true,
            true,
            |_| Some("@stash".to_string()),
            |_| Ok(true),
            |_| {
                selected.set(true);
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(effect, FocusDocumentPaneEffect::PaneNotVisible);
        assert!(!selected.get());
    }

    #[test]
    fn inactive_desktop_focus_does_not_move_or_select_a_pane() {
        let promoted = Cell::new(false);
        let selected = Cell::new(false);
        let effect = apply_focus_document_pane_effect(
            "%64",
            Some("@agent-doc"),
            false,
            true,
            |_| Some("@stash".to_string()),
            |_| {
                promoted.set(true);
                Ok(true)
            },
            |_| {
                selected.set(true);
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(effect, FocusDocumentPaneEffect::DesktopEditorInactive);
        assert!(!promoted.get());
        assert!(!selected.get());
    }
}

fn publish_pane_layout_desired(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<(
    agent_doc_editor_surface::NavigationLane,
    PaneLayoutDesired,
    ControllerTmuxLayoutSyncInvocation,
)> {
    let payload_json = request_string(&request.diagnostic_payload, "diagnostic_payload")?;
    let mut invocation =
        sync_tmux_layout_invocation_from_payload(Some((bootstrap, runtime)), &payload_json)?;
    let client_id = invocation.client_id.take();
    let lane = sync_tmux_layout_command_lane(
        runtime.editor_surface_graph.navigation_mode(),
        client_id.as_deref(),
    );
    let publication = pane_layout_command_publication_for_invocation(&invocation);
    if lane.is_shared() {
        let (desired, invocation) = publish_pane_layout_desired_invocation(
            bootstrap,
            runtime,
            invocation,
            None,
            publication,
            PaneLayoutPublisher::Command,
        )?;
        return Ok((lane, desired, invocation));
    }
    let (desired, invocation) = publish_pane_layout_desired_invocation_in_lane(
        bootstrap,
        runtime,
        &lane,
        invocation,
        None,
        publication,
        PaneLayoutPublisher::Command,
    )?;
    agent_doc_ops_log_io::log_op(
        &bootstrap.project_root,
        &format!(
            "sync_tmux_layout_lane_routed navigation_lane={} client_id={} generation={} caller_kind={}",
            lane.label(),
            client_id.as_deref().unwrap_or_default(),
            desired.generation,
            desired.invocation.caller_kind,
        ),
    );
    Ok((lane, desired, invocation))
}

/// The navigation lane an explicit `sync_tmux_layout` command publishes into
/// (`#ideriderindependentnav` P6): the requesting client's lane under
/// `navigation_mode` when the command names a client id, else the shared lane.
/// `shared` mode, an unscoped client, and a command without a client id are
/// all the shared lane, which is the pre-lane command path.
fn sync_tmux_layout_command_lane(
    navigation_mode: agent_doc_editor_surface::NavigationMode,
    client_id: Option<&str>,
) -> agent_doc_editor_surface::NavigationLane {
    client_id.map_or(
        agent_doc_editor_surface::NavigationLane::Shared,
        |client_id| {
            agent_doc_editor_surface::NavigationLane::for_client(navigation_mode, client_id)
        },
    )
}

/// GH #83: report which client the layout window renders for. Several attached
/// clients of different sizes under `window-size latest` render the computed layout
/// at whichever client was last active, dot-padding the rest, which looks exactly like
/// a missing or empty pane. Logged when the geometry changes, and on every pass while
/// the clients disagree, so a layout report can always be checked against it.
fn log_tmux_client_geometry(project_root: &Path, session: &str, window: &str) {
    static LAST: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);
    let tmux = agent_doc_tmux_io::configured_tmux();
    let Some(geometry) = agent_doc_tmux_io::client_geometry(&tmux, session, window) else {
        return;
    };
    let summary = geometry.summary();
    let changed = LAST
        .lock()
        .map(|mut last| {
            let changed = last.as_deref() != Some(summary.as_str());
            *last = Some(summary.clone());
            changed
        })
        .unwrap_or(true);
    if !changed && !geometry.clients_mismatched() {
        return;
    }
    agent_doc_ops_log_io::log_op(
        project_root,
        &format!(
            "tmux_client_geometry session={session} window={window} {summary}{}",
            geometry
                .mismatch_remedy()
                .map(|remedy| format!(
                    " warning=clients_of_different_sizes_attached remedy={remedy}"
                ))
                .unwrap_or_default(),
        ),
    );
}

fn publish_pane_layout_desired_invocation(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    invocation: ControllerTmuxLayoutSyncInvocation,
    source_plane_version: Option<u64>,
    publication: PaneLayoutPublication,
    claim: impl Into<PaneLayoutClaim>,
) -> Result<(PaneLayoutDesired, ControllerTmuxLayoutSyncInvocation)> {
    publish_pane_layout_desired_invocation_in_lane(
        bootstrap,
        runtime,
        &agent_doc_editor_surface::NavigationLane::Shared,
        invocation,
        source_plane_version,
        publication,
        claim,
    )
}

/// Publish a desired layout into one navigation lane's graph
/// (`#ideriderindependentnav` P2b).
///
/// The shared lane is the pre-lane publication path byte for byte, including
/// the durable `layout_state` column memory. An installation lane's desired
/// layout, retained basis, width memory, and supersession arbitration are its
/// own graph's; it never writes the shared lane's durable column memory, and
/// its effect worker routes the layout to the lane session.
fn publish_pane_layout_desired_invocation_in_lane(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
    mut invocation: ControllerTmuxLayoutSyncInvocation,
    source_plane_version: Option<u64>,
    publication: PaneLayoutPublication,
    claim: impl Into<PaneLayoutClaim>,
) -> Result<(PaneLayoutDesired, ControllerTmuxLayoutSyncInvocation)> {
    let claim = claim.into();
    let publisher = claim.publisher;
    let graph = runtime.pane_layout_graph_for_lane(lane);
    let store_lane_layout_state = |columns: &[String]| -> Result<()> {
        if lane.is_shared() {
            store_layout_state(&bootstrap.project_root, columns)?;
        }
        Ok(())
    };
    if bootstrap.handoff_state != ControllerHandoffState::Stable {
        anyhow::bail!(
            "pane layout observation refused: controller not authoritative (handoff_state={:?})",
            bootstrap.handoff_state
        );
    }
    let eligibility = runtime.main_layout_eligibility();
    invocation.columns =
        main_layout_eligible_columns(&bootstrap.project_root, &eligibility, &invocation.columns);
    // `#stalecontrollerhotupdate` (a): a desired layout names each document at
    // most once. An editor split showing the same file twice publishes
    // `[X, X]`, which tmux (one pane per document) can never satisfy.
    invocation.columns =
        collapse_duplicate_pane_layout_columns(&bootstrap.project_root, &invocation);
    invocation.focus = invocation.focus.filter(|document| {
        document_is_main_layout_eligible(&bootstrap.project_root, &eligibility, document)
    });
    let retained = graph.desired();
    let incoming_order = invocation.column_order;
    let mut desired_columns = layout_sync_state_expected_documents(
        &bootstrap.project_root,
        &ControllerTmuxLayoutSyncStateInvocation {
            columns: invocation.columns.clone(),
            window: invocation.window.clone(),
            focus: invocation.focus.clone(),
        },
    );
    // GH #343: anything short of a positive editor-authored vector has no structural authority.
    // Preserve the exact last frontend snapshot, or fail closed before publishing when none
    // exists. Such input may carry a focus intent only when that document is already present in
    // the retained vector. Positive tmux geometry is an effect receipt, not editor-layout
    // authority: equal widths still do not identify which editor document belongs in which slot.
    let incomplete_frontend_fallback = incoming_order != agent_doc_tmux::LayoutColumnOrder::Editor;
    if incomplete_frontend_fallback {
        let retained = retained.as_ref().context(format!(
            "sync_tmux_layout deferred: incomplete frontend layout has no authoritative snapshot; \
             reason=flat_evidence_has_no_column_geometry; frontend_publisher=unavailable; \
             frontend_readiness=blocked; frontend_readiness_reason={}; \
             remedy={}, then retry Run Agent Doc",
            agent_doc_editor_surface::FRONTEND_AUTHORITY_UNAVAILABLE_READINESS,
            agent_doc_editor_surface::FRONTEND_AUTHORITY_UNAVAILABLE_REMEDY,
        ))?;
        invocation.columns = retained.invocation.columns.clone();
        invocation.column_order = retained.invocation.column_order;
        desired_columns = retained.invocation.columns.clone();
    }
    anyhow::ensure!(
        !desired_columns.is_empty(),
        "sync_tmux_layout refused: desired pane layout is empty"
    );
    if let Some(focus) = invocation.focus.as_deref()
        && !pane_layout_foreground_focus_matches_columns(
            &bootstrap.project_root,
            &invocation,
            &desired_columns,
        )
    {
        if incomplete_frontend_fallback {
            anyhow::bail!(
                "sync_tmux_layout refused before layout publication: focused document `{focus}` is absent from the retained desired columns; \
                 reason=flat_evidence_has_no_column_geometry; frontend_publisher=unavailable; \
                 frontend_readiness=blocked; frontend_readiness_reason={}; \
                 remedy={}, then retry Run Agent Doc",
                agent_doc_editor_surface::FRONTEND_AUTHORITY_UNAVAILABLE_READINESS,
                agent_doc_editor_surface::FRONTEND_AUTHORITY_UNAVAILABLE_REMEDY,
            );
        }
        anyhow::bail!(
            "sync_tmux_layout refused before layout publication: focused document `{focus}` is absent from the desired columns"
        );
    }
    // GH #343: a positive frontend vector is already the structural authority.
    // Eligibility and duplicate validation above may reject invalid members,
    // but backend width memory must not fold, trim, or reorder the remainder.
    // Derived/retained publications remain width-bounded against realised tmux
    // state as before.
    let frontend_authored = incoming_order == agent_doc_tmux::LayoutColumnOrder::Editor
        && matches!(
            publisher,
            PaneLayoutPublisher::PluginPublication
                | PaneLayoutPublisher::EditorSurface
                | PaneLayoutPublisher::Command
        );
    let ordered_columns = if frontend_authored {
        desired_columns.clone()
    } else {
        bound_pane_layout_publication_width(
            &bootstrap.project_root,
            runtime,
            &graph.width_memory(),
            &claim,
            retained.as_ref(),
            desired_columns.clone(),
            invocation.focus.as_deref(),
        )
    };
    // The desired Lazily fact is durable before the effect graph sees it.
    // Tmux and crash-state sidecars are projections, never fallback inputs.
    store_lane_layout_state(&ordered_columns)?;
    invocation.columns = ordered_columns;

    let desired =
        graph.set_desired_attributed(invocation.clone(), source_plane_version, publication, claim);
    let supersessions = graph.drain_supersessions();
    let refused = supersessions.iter().any(|supersession| {
        supersession.loser == publisher
            && supersession.loser_generation.is_none()
            && supersession.loser_columns == invocation.columns
    });
    log_pane_layout_supersessions(&bootstrap.project_root, &supersessions);
    if refused {
        // `layoutpublisherarbiter`: the durable column memory was written
        // ahead of the graph; a refused publication must not leave its
        // columns there in place of the retained generation's.
        store_lane_layout_state(&desired.invocation.columns)?;
        publish_pane_layout_lane_status(runtime, lane);
        let applied_invocation = desired.invocation.clone();
        return Ok((desired, applied_invocation));
    }
    if desired.invocation.columns != invocation.columns {
        // GH #224: the graph may rebase a derived escalation after a newer
        // editor split wins the race into the publication critical section.
        // Keep the durable effect sink aligned with the graph-owned fact.
        store_lane_layout_state(&desired.invocation.columns)?;
    }
    log_pane_layout_desired_publication(
        &bootstrap.project_root,
        retained.as_ref().map(|retained| retained.generation),
        &desired,
        &desired_columns,
        false,
    );
    if retained.as_ref().map(|retained| retained.generation) != Some(desired.generation) {
        log_pane_layout_narrowed(&bootstrap.project_root, &desired);
    }
    publish_pane_layout_lane_status(runtime, lane);
    let applied_invocation = desired.invocation.clone();
    Ok((desired, applied_invocation))
}

/// `#stalecontrollerhotupdate` (a): apply
/// [`agent_doc_controller::pane_layout::collapse_duplicate_layout_documents`]
/// to one publication and log the collapse once per publication.
fn collapse_duplicate_pane_layout_columns(
    project_root: &Path,
    invocation: &ControllerTmuxLayoutSyncInvocation,
) -> Vec<String> {
    let (columns, dropped) = agent_doc_controller::pane_layout::collapse_duplicate_layout_documents(
        &invocation.columns,
        |file| canonical_layout_document_id(project_root, file),
    );
    if !dropped.is_empty() {
        agent_doc_ops_log_io::log_op(
            project_root,
            &format!(
                "pane_layout_publication_duplicate_columns_collapsed caller_kind={} incoming={:?} columns={:?} dropped={:?} (#stalecontrollerhotupdate)",
                invocation.caller_kind, invocation.columns, columns, dropped,
            ),
        );
    }
    columns
}

/// GH #136 follow-up (a): apply [`agent_doc_controller::pane_layout::bound_layout_width`]
/// to one publication and log what it decided. Pure but for the ops-log line;
/// every input is local to the controller (no editor message order, timing or
/// delivery participates).
fn bound_pane_layout_publication_width(
    project_root: &Path,
    runtime: &ControllerRuntime,
    memory: &PaneLayoutWidthMemory,
    claim: &PaneLayoutClaim,
    retained: Option<&PaneLayoutDesired>,
    columns: Vec<String>,
    focus: Option<&str>,
) -> Vec<String> {
    use agent_doc_controller::pane_layout::{
        LayoutWidthDecision, LayoutWidthExtent, bound_layout_width,
    };
    let eligibility = runtime.main_layout_eligibility();
    let columns = main_layout_eligible_columns(project_root, &eligibility, &columns);
    let retained_generation = retained.map(|desired| desired.generation);
    let retained_columns = retained
        .map(|desired| {
            main_layout_eligible_columns(project_root, &eligibility, &desired.invocation.columns)
                .len()
        })
        .unwrap_or_default();
    // Only the pass that realised the RETAINED generation speaks for it.
    let observed_panes = memory
        .observed_panes
        .filter(|_| Some(memory.observed_generation) == retained_generation);
    let gated_columns = if Some(memory.gated_generation) == retained_generation {
        layout_columns_holding_documents(project_root, &columns, &memory.gated_documents)
    } else {
        0
    };
    let extent = LayoutWidthExtent {
        observed_panes,
        gated_columns,
        retained_columns,
        asserted_columns: claim.asserted_column_count(),
    };
    let authority = claim.width_authority();
    let focus_id = focus
        .filter(|focus| document_is_main_layout_eligible(project_root, &eligibility, focus))
        .map(|focus| canonical_layout_document_id(project_root, focus));
    let holds_focus = |column: &str| {
        focus_id.as_ref().is_some_and(|focus_id| {
            column
                .split(',')
                .map(str::trim)
                .filter(|file| !file.is_empty())
                .any(|file| canonical_layout_document_id(project_root, file) == *focus_id)
        })
    };
    // The pure bound matches the focus column by exact text; resolve it to the
    // column's own spelling first so absolute and root-relative forms agree.
    let focus_column = columns.iter().find(|column| holds_focus(column)).cloned();
    let focus_token = focus_column.as_deref().and_then(|column| {
        column
            .split(',')
            .map(str::trim)
            .find(|file| {
                focus_id.as_ref().is_some_and(|focus_id| {
                    canonical_layout_document_id(project_root, file) == *focus_id
                })
            })
            .map(str::to_string)
    });
    let incoming = columns.len();
    let (bounded, decision) =
        bound_layout_width(&columns, focus_token.as_deref(), authority, extent);
    let observed = extent
        .observed_panes
        .map_or_else(|| "unknown".to_string(), |panes| panes.to_string());
    match decision {
        LayoutWidthDecision::Within | LayoutWidthDecision::DerivedWithinAccounted { .. } => {}
        LayoutWidthDecision::Widened { observed_bound } => agent_doc_ops_log_io::log_op(
            project_root,
            &format!(
                "pane_layout_publication_widened publisher={} authority={} columns={incoming} observed_panes={observed} observed_bound={observed_bound} retained_columns={retained_columns} (GH #136)",
                claim.publisher.label(),
                authority.label(),
            ),
        ),
        LayoutWidthDecision::Trimmed {
            derived_bound,
            dropped,
        } => agent_doc_ops_log_io::log_op(
            project_root,
            &format!(
                "pane_layout_publication_width_bounded publisher={} authority={} columns={incoming} published_columns={} observed_panes={observed} gated_columns={gated_columns} retained_columns={retained_columns} asserted_columns={} derived_bound={derived_bound} dropped={dropped:?} (GH #136)",
                claim.publisher.label(),
                authority.label(),
                bounded.len(),
                extent.asserted_columns,
            ),
        ),
    }
    bounded
}

/// GH #136 follow-up (a): how many of `columns` hold one of `documents`
/// (canonical identity).
fn layout_columns_holding_documents(
    project_root: &Path,
    columns: &[String],
    documents: &[String],
) -> usize {
    if documents.is_empty() {
        return 0;
    }
    let documents: Vec<String> = documents
        .iter()
        .map(|file| canonical_layout_document_id(project_root, file))
        .collect();
    columns
        .iter()
        .filter(|column| {
            column
                .split(',')
                .map(str::trim)
                .filter(|file| !file.is_empty())
                .any(|file| documents.contains(&canonical_layout_document_id(project_root, file)))
        })
        .count()
}

/// `layoutpublisherarbiter`: one `pane_layout_publication_superseded` line per
/// publication the arbiter displaced or refused. The route publisher and
/// `plugin_publication` used to overwrite each other with the loser unlogged.
fn log_pane_layout_supersessions(project_root: &Path, supersessions: &[PaneLayoutSupersession]) {
    for supersession in supersessions {
        agent_doc_ops_log_io::log_op(project_root, &supersession.log_line());
    }
}

/// GH #112 ask 2: one line per new desired generation naming the publisher
/// (`caller_kind`, plus `plane_version` for editor state-plane frames), the
/// columns exactly as received, and the columns as resolved with their order
/// source. Both downstream stages are order-preserving, so this line is where
/// any column order is decided. A coalesced republish of the same generation is
/// silent unless its order was rewritten.
fn log_pane_layout_desired_publication(
    project_root: &Path,
    previous_generation: Option<u64>,
    desired: &PaneLayoutDesired,
    incoming_columns: &[String],
    reordered: bool,
) {
    if previous_generation == Some(desired.generation) && !reordered {
        return;
    }
    agent_doc_ops_log_io::log_op(
        project_root,
        &format!(
            "pane_layout_desired_published generation={} caller_kind={} plane_version={} column_order={} reordered={} incoming={:?} columns={:?} focus={}",
            desired.generation,
            desired.invocation.caller_kind,
            desired
                .source_plane_version
                .map_or_else(|| "none".to_string(), |version| version.to_string()),
            desired.invocation.column_order,
            reordered,
            incoming_columns,
            desired.invocation.columns,
            desired.invocation.focus.as_deref().unwrap_or("none"),
        ),
    );
}

/// The publisher fields every `tmux_layout_effect_state` line carries (GH #111).
///
/// `publisher` names which plane produced the generation (`route`,
/// `plugin_publication`, `escalation`, `editor_surface`, `command`),
/// `plane_version` the editor state-plane frame it came from when there was
/// one, and `columns` / `retained_columns` / `observed_panes` the applied
/// column count against the retained layout and last tmux observation it
/// replaced.
fn tmux_layout_effect_state_provenance(desired: &PaneLayoutDesired) -> String {
    format!(
        "publisher={} plane_version={} columns={} retained_columns={} observed_panes={}",
        desired.provenance.publisher.label(),
        desired
            .source_plane_version
            .map_or_else(|| "none".to_string(), |version| version.to_string()),
        desired.invocation.columns.len(),
        desired.provenance.retained_columns,
        desired
            .provenance
            .observed_panes
            .map_or_else(|| "unknown".to_string(), |panes| panes.to_string()),
    )
}

/// GH #111: a distinct, greppable event for a generation that applies fewer
/// columns than the retained layout it replaced. Narrowing is legitimate after
/// a positive observation (a closed split), so this does not refuse; it makes
/// the event attributable instead of something reconstructed by position.
fn log_pane_layout_narrowed(project_root: &Path, desired: &PaneLayoutDesired) {
    if !desired.provenance.narrows(desired.invocation.columns.len()) {
        return;
    }
    agent_doc_ops_log_io::log_op(
        project_root,
        &format!(
            "tmux_layout_effect_state_narrowed generation={} {} caller_kind={} focus={} applied={:?}",
            desired.generation,
            tmux_layout_effect_state_provenance(desired),
            desired.invocation.caller_kind,
            desired.invocation.focus.as_deref().unwrap_or("none"),
            desired.invocation.columns,
        ),
    );
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn refresh_pane_layout_observation_before_await(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    desired: &PaneLayoutDesired,
) {
    let effect_file_panes = runtime.pane_layout_effect_file_panes(desired.generation);
    if effect_file_panes.is_empty() {
        return;
    }
    let actor_bindings = runtime.pane_layout_actor_bindings();
    let mut guarded = desired.invocation.clone();
    suppress_inactive_automatic_layout_focus(&mut guarded, desktop_editor_focus_state());
    let invocation = ControllerTmuxLayoutSyncStateInvocation {
        columns: guarded.columns,
        window: guarded.window,
        focus: guarded.focus,
    };
    let report = tmux_layout_sync_state_for_invocation_with_effect_assignment(
        bootstrap,
        runtime,
        &invocation,
        &effect_file_panes,
    )
    .unwrap_or_else(|error| {
        layout_sync_state_report(
            false,
            format!("tmux_observation_failed:{error:#}"),
            invocation.columns.clone(),
            Vec::new(),
            Vec::new(),
            LayoutSyncStateTarget {
                window_id: invocation.window.clone(),
                focus: invocation.focus.clone(),
                ..LayoutSyncStateTarget::default()
            },
        )
    });
    runtime.record_pane_layout_observation(PaneLayoutObservation {
        generation: desired.generation,
        actor_bindings,
        report,
    });
    publish_pane_layout_status(runtime);
}

pub(crate) fn handle_sync_tmux_layout(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    request: ControllerRequest,
) -> Result<ControllerTmuxLayoutSyncReceipt> {
    let (lane, desired, invocation) = publish_pane_layout_desired(bootstrap, runtime, request)?;
    // `#manualsynclayoutlease`: the explicit command is the authority that may
    // create a missing pane. Keep its generation current until its terminal
    // projection receipt is known; an identical passive editor snapshot must
    // not replace it with `no_autostart=true` between publication and effect.
    let _lease =
        pane_layout_invocation_awaits_effect(&invocation).then(|| PaneLayoutRouteLeaseGuard {
            runtime,
            lane: lane.clone(),
            project_root: bootstrap.project_root.clone(),
            generation: desired.generation,
            release_on_drop: true,
        });
    if !lane.is_shared() {
        return await_lane_sync_tmux_layout_effect(
            bootstrap,
            runtime,
            &lane,
            desired,
            invocation,
            MANUAL_PANE_LAYOUT_COMMAND_TIMEOUT,
        );
    }
    await_sync_tmux_layout_effect(
        bootstrap,
        runtime,
        desired,
        invocation,
        MANUAL_PANE_LAYOUT_COMMAND_TIMEOUT,
    )
}

/// [`await_sync_tmux_layout_effect`] for an installation navigation lane's
/// explicit `sync_tmux_layout` command (`#ideriderindependentnav` P6): the
/// receipt is the lane graph's effect state for the generation the command
/// published, applied by that lane's own effect worker into the lane session.
/// The shared lane's graph, durable column memory, and status are untouched.
fn await_lane_sync_tmux_layout_effect(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
    desired: PaneLayoutDesired,
    invocation: ControllerTmuxLayoutSyncInvocation,
    await_timeout: Duration,
) -> Result<ControllerTmuxLayoutSyncReceipt> {
    let graph = runtime.pane_layout_graph_for_lane(lane);
    #[cfg(any(test, feature = "test-support"))]
    {
        // The test runtime has no tmux effect worker, so the fake adapter is
        // the observation (as in `await_sync_tmux_layout_effect`).
        let _ = await_timeout;
        let mut invocation = invocation;
        invocation.actor_bindings = graph.actor_bindings();
        let mut receipt = runtime_effects()?.sync_tmux_layout(
            &bootstrap.project_root,
            invocation,
            &runtime.main_layout_eligibility(),
        )?;
        receipt.layout_generation = Some(desired.generation);
        receipt.layout_publisher = Some(desired.provenance.publisher.label().to_string());
        Ok(receipt)
    }
    #[cfg(not(any(test, feature = "test-support")))]
    {
        let _ = bootstrap;
        let routes_created_panes = invocation.routes_created_panes();
        if !pane_layout_invocation_awaits_effect(&invocation) {
            return Ok(ControllerTmuxLayoutSyncReceipt {
                gated_documents: Vec::new(),
                applied: false,
                reason: "target_published".to_string(),
                columns: invocation.columns,
                layout_generation: Some(desired.generation),
                layout_publisher: Some(desired.provenance.publisher.label().to_string()),
                window: invocation.window,
                focus: invocation.focus,
                no_autostart: invocation.no_autostart,
                exact_visible: invocation.exact_visible,
                routes_created_panes,
                file_panes: Vec::new(),
            });
        }
        let effect_state = graph.await_generation(desired.generation, await_timeout);
        let (applied, reason) = pane_layout_await_outcome(&effect_state, desired.generation);
        let current = tmux_layout_effect_state_desired(&effect_state);
        let receipt_generation = current
            .map(|current| current.generation)
            .unwrap_or(desired.generation);
        Ok(ControllerTmuxLayoutSyncReceipt {
            gated_documents: Vec::new(),
            applied,
            reason: reason.to_string(),
            columns: invocation.columns,
            layout_generation: current.map(|current| current.generation),
            layout_publisher: current
                .map(|current| current.provenance.publisher.label().to_string()),
            window: invocation.window,
            focus: invocation.focus,
            no_autostart: invocation.no_autostart,
            exact_visible: invocation.exact_visible,
            routes_created_panes,
            file_panes: graph.effect_file_panes(receipt_generation),
        })
    }
}

/// Publish one fresh editor-route layout intent and await its tmux effect receipt.
///
/// GH #110: `await_timeout` is the route's remaining `--wait-for-ready` budget,
/// not the fixed manual-sync await, so layout convergence and harness readiness
/// share one operator-supplied deadline.
fn handle_editor_route_layout<'a>(
    bootstrap: &ControllerBootstrap,
    runtime: &'a ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
    invocation: ControllerTmuxLayoutSyncInvocation,
    claim: PaneLayoutClaim,
    await_timeout: Duration,
) -> Result<(
    ControllerTmuxLayoutSyncReceipt,
    PaneLayoutRouteLeaseGuard<'a>,
    EditorRoutePublishedLayout,
)> {
    let (desired, invocation) = publish_pane_layout_desired_invocation_in_lane(
        bootstrap,
        runtime,
        lane,
        invocation,
        None,
        PaneLayoutPublication::FreshRouteIntent,
        claim,
    )?;
    let lease = PaneLayoutRouteLeaseGuard {
        runtime,
        lane: lane.clone(),
        project_root: bootstrap.project_root.clone(),
        generation: desired.generation,
        release_on_drop: true,
    };
    let published = EditorRoutePublishedLayout {
        lane: lane.clone(),
        generation: desired.generation,
        document: invocation.focus.clone().unwrap_or_default(),
        invocation: invocation.clone(),
    };
    let receipt = await_sync_tmux_layout_effect_in_lane(
        bootstrap,
        runtime,
        lane,
        desired,
        invocation,
        await_timeout,
    )?;
    Ok((receipt, lease, published))
}

/// What one editor-route publication put on the layout graph, kept so the GH
/// #110 gates can re-observe it without publishing again.
struct EditorRoutePublishedLayout {
    /// The navigation lane the route published into (P6).
    #[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
    lane: agent_doc_editor_surface::NavigationLane,
    #[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
    generation: u64,
    #[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
    document: String,
    invocation: ControllerTmuxLayoutSyncInvocation,
}

struct PaneLayoutRouteLeaseGuard<'a> {
    runtime: &'a ControllerRuntime,
    /// The lane whose graph holds the route lease (P6).
    lane: agent_doc_editor_surface::NavigationLane,
    project_root: PathBuf,
    generation: u64,
    release_on_drop: bool,
}

impl PaneLayoutRouteLeaseGuard<'_> {
    fn detach(&mut self) -> u64 {
        self.release_on_drop = false;
        self.generation
    }
}

impl Drop for PaneLayoutRouteLeaseGuard<'_> {
    fn drop(&mut self) {
        if !self.release_on_drop {
            return;
        }
        let graph = self.runtime.pane_layout_graph_for_lane(&self.lane);
        // The passive publication a route lease deferred lands here, outside
        // `publish_pane_layout_desired_invocation`, so it reports its own
        // narrowing (GH #111).
        if let Some(released) = graph.release_route_lease(self.generation) {
            log_pane_layout_narrowed(&self.project_root, &released);
        }
        // `layoutpublisherarbiter`: a deferred plugin publication that now
        // displaces the route is logged here too.
        log_pane_layout_supersessions(&self.project_root, &graph.drain_supersessions());
    }
}

fn await_sync_tmux_layout_effect(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    desired: PaneLayoutDesired,
    invocation: ControllerTmuxLayoutSyncInvocation,
    await_timeout: Duration,
) -> Result<ControllerTmuxLayoutSyncReceipt> {
    await_sync_tmux_layout_effect_in_lane(
        bootstrap,
        runtime,
        &agent_doc_editor_surface::NavigationLane::Shared,
        desired,
        invocation,
        await_timeout,
    )
}

/// [`await_sync_tmux_layout_effect`] on one navigation lane's graph
/// (`#ideriderindependentnav` P6). The shared lane is the pre-lane await byte
/// for byte; an installation lane awaits its own graph and leaves the
/// pre-await survey to its lane effect worker, which observes the lane session.
fn await_sync_tmux_layout_effect_in_lane(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    lane: &agent_doc_editor_surface::NavigationLane,
    desired: PaneLayoutDesired,
    invocation: ControllerTmuxLayoutSyncInvocation,
    await_timeout: Duration,
) -> Result<ControllerTmuxLayoutSyncReceipt> {
    #[cfg(any(test, feature = "test-support"))]
    {
        let _ = (&desired, await_timeout, lane);
        let mut invocation = invocation;
        invocation.actor_bindings = runtime.pane_layout_actor_bindings();
        return runtime_effects()?.sync_tmux_layout(
            &bootstrap.project_root,
            invocation,
            &runtime.main_layout_eligibility(),
        );
    }
    #[cfg(not(any(test, feature = "test-support")))]
    {
        if !pane_layout_invocation_awaits_effect(&invocation) {
            let routes_created_panes = invocation.routes_created_panes();
            return Ok(ControllerTmuxLayoutSyncReceipt {
                gated_documents: Vec::new(),
                applied: false,
                reason: "target_published".to_string(),
                columns: invocation.columns,
                layout_generation: Some(desired.generation),
                layout_publisher: Some(desired.provenance.publisher.label().to_string()),
                window: invocation.window,
                focus: invocation.focus,
                no_autostart: invocation.no_autostart,
                exact_visible: invocation.exact_visible,
                routes_created_panes,
                file_panes: Vec::new(),
            });
        }
        let graph = runtime.pane_layout_graph_for_lane(lane);
        // A repeated foreground command is also a physical observation edge.
        // Re-observe before awaiting so an identical desired Source cannot reuse
        // stale Converged state after pane focus or geometry drift.
        if lane.is_shared() {
            refresh_pane_layout_observation_before_await(bootstrap, runtime, &desired);
        }
        if invocation.caller_kind == "editor_route"
            && let Some(document) = invocation.focus.clone()
        {
            return Ok(editor_route_layout_receipt(
                &graph,
                desired.generation,
                invocation,
                &document,
                await_timeout,
            ));
        }
        let effect_state = graph.await_generation(desired.generation, await_timeout);
        let (applied, reason) = pane_layout_await_outcome(&effect_state, desired.generation);
        let receipt_generation = tmux_layout_effect_state_desired(&effect_state)
            .map(|current| current.generation)
            .unwrap_or(desired.generation);
        let routes_created_panes = invocation.routes_created_panes();
        Ok(ControllerTmuxLayoutSyncReceipt {
            gated_documents: Vec::new(),
            applied,
            reason: reason.to_string(),
            columns: invocation.columns,
            layout_generation: tmux_layout_effect_state_desired(&effect_state)
                .map(|current| current.generation),
            layout_publisher: tmux_layout_effect_state_desired(&effect_state)
                .map(|current| current.provenance.publisher.label().to_string()),
            window: invocation.window,
            focus: invocation.focus,
            no_autostart: invocation.no_autostart,
            exact_visible: invocation.exact_visible,
            routes_created_panes,
            file_panes: graph.effect_file_panes(receipt_generation),
        })
    }
}

/// Await semantic route readiness for `document` on the pane-layout graph and
/// fold the effect state into a receipt. Shared by the route's single publication
/// and its GH #110 re-observations, which must not publish again.
#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn editor_route_layout_receipt(
    graph: &ControllerPaneLayoutGraph,
    published_generation: u64,
    invocation: ControllerTmuxLayoutSyncInvocation,
    document: &str,
    await_timeout: Duration,
) -> ControllerTmuxLayoutSyncReceipt {
    let effect_state = graph.await_route_document(document, await_timeout);
    let (applied, reason) = pane_layout_route_await_outcome(&effect_state, document);
    // Preserve the target that won arbitration, even when it omits the
    // routed document. Falling back to the route's original columns hid the
    // superseding publisher and made a terminal foreground supersession look
    // like a retryable convergence race (GH #143).
    let accepted = tmux_layout_effect_state_desired(&effect_state);
    let receipt_invocation = accepted
        .map(|current| current.invocation.clone())
        .unwrap_or(invocation);
    let routes_created_panes = receipt_invocation.routes_created_panes();
    let receipt_generation = tmux_layout_effect_state_desired(&effect_state)
        .map(|current| current.generation)
        .unwrap_or(published_generation);
    ControllerTmuxLayoutSyncReceipt {
        gated_documents: Vec::new(),
        applied,
        reason: reason.to_string(),
        columns: receipt_invocation.columns,
        layout_generation: accepted.map(|current| current.generation),
        layout_publisher: accepted.map(|current| current.provenance.publisher.label().to_string()),
        window: receipt_invocation.window,
        focus: receipt_invocation.focus,
        no_autostart: receipt_invocation.no_autostart,
        exact_visible: receipt_invocation.exact_visible,
        routes_created_panes,
        file_panes: graph.effect_file_panes(receipt_generation),
    }
}

/// GH #110: re-observe an editor route's ALREADY-PUBLISHED layout, without
/// publishing it again (`the_editor_route_handler_publishes_layout_once`:
/// supersession is the layout graph's to resolve, never an RPC republish race).
///
/// If the current effect state still refuses the routed document, block until it
/// changes — a newer desired layout, a tmux observation, or an effect receipt
/// all notify the graph's waiters — or `timeout` passes; the comparison is
/// against the effect state just read, so a change that lands before the wait
/// starts is not missed. Then fold the current effect state into a fresh receipt
/// (which itself waits through a pending effect). There is no timer poll: if
/// nothing changes, the wait runs out the remaining `--wait-for-ready` budget.
fn reobserve_editor_route_layout(
    bootstrap: &ControllerBootstrap,
    runtime: &ControllerRuntime,
    published: &EditorRoutePublishedLayout,
    timeout: Duration,
) -> Result<ControllerTmuxLayoutSyncReceipt> {
    #[cfg(any(test, feature = "test-support"))]
    {
        // The test runtime has no tmux effect worker, so the fake adapter is
        // the observation (as in `await_sync_tmux_layout_effect`).
        let _ = timeout;
        let mut invocation = published.invocation.clone();
        invocation.actor_bindings = runtime.pane_layout_actor_bindings();
        runtime_effects()?.sync_tmux_layout(
            &bootstrap.project_root,
            invocation,
            &runtime.main_layout_eligibility(),
        )
    }
    #[cfg(not(any(test, feature = "test-support")))]
    {
        let _ = bootstrap;
        let deadline = Instant::now() + timeout;
        let graph = runtime.pane_layout_graph_for_lane(&published.lane);
        let current = graph.effect_state();
        if crate::project_controller::pane_layout_route_readiness(&current, &published.document)
            == PaneLayoutRouteReadiness::Refused
        {
            graph.await_tmux_effect_change(&current, timeout);
        }
        Ok(editor_route_layout_receipt(
            &graph,
            published.generation,
            published.invocation.clone(),
            &published.document,
            deadline.saturating_duration_since(Instant::now()),
        ))
    }
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn pane_layout_invocation_awaits_effect(invocation: &ControllerTmuxLayoutSyncInvocation) -> bool {
    invocation.caller_kind != "automatic" && !invocation.no_autostart
}

/// A foreground command cannot converge focus onto a document that its own
/// exact-visible layout omits. Passive observations may carry retained focus
/// from an inactive editor surface; their worker suppresses that focus later.
fn pane_layout_foreground_focus_matches_columns(
    project_root: &Path,
    invocation: &ControllerTmuxLayoutSyncInvocation,
    desired_columns: &[String],
) -> bool {
    !pane_layout_invocation_awaits_effect(invocation)
        || invocation.focus.as_deref().is_none_or(|focus| {
            let canonical_focus = canonical_layout_document_id(project_root, focus);
            desired_columns
                .iter()
                .any(|document| document == &canonical_focus)
        })
}

/// Preserve foreground/manual sync semantics across every ingress transport.
///
/// Editor state-plane updates are normally coalescible facts. The explicit
/// `Sync Tmux Pane` action is different: pressing it again is a fresh operator
/// intent even when the requested columns are byte-identical. Without a fresh
/// generation, a prior terminal/refused effect state permanently turns the
/// manual retry into a successful-looking no-op. Passive and automatic editor
/// observations remain coalesced so event storms do not manufacture effects.
fn pane_layout_publication_for_invocation(
    invocation: &ControllerTmuxLayoutSyncInvocation,
) -> PaneLayoutPublication {
    if pane_layout_invocation_awaits_effect(invocation) {
        PaneLayoutPublication::FreshIntent
    } else {
        PaneLayoutPublication::CoalesceIdentical
    }
}

/// Explicit command ingress additionally holds a generation lease until the
/// awaited projection is terminal. State-plane publications remain ordinary
/// fresh facts because they have no command lifetime in which to hold a lease.
fn pane_layout_command_publication_for_invocation(
    invocation: &ControllerTmuxLayoutSyncInvocation,
) -> PaneLayoutPublication {
    if pane_layout_invocation_awaits_effect(invocation) {
        PaneLayoutPublication::FreshCommandIntent
    } else {
        pane_layout_publication_for_invocation(invocation)
    }
}

/// A generation-specific layout command was replaced before it converged, or an
/// editor route's semantic wait observed a newer layout that no longer contains
/// the routed document.
pub(crate) const PANE_LAYOUT_SUPERSEDED_REASON: &str = "superseded_by_newer_layout_state";

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn pane_layout_route_await_outcome(
    effect_state: &TmuxLayoutEffectState,
    document: &str,
) -> (bool, &'static str) {
    match pane_layout_route_readiness(effect_state, document) {
        PaneLayoutRouteReadiness::Ready => (true, "observed_convergence"),
        PaneLayoutRouteReadiness::Wait => match effect_state {
            TmuxLayoutEffectState::NeedsEffect(_) => (false, "tmux_effect_not_started"),
            TmuxLayoutEffectState::Applying(_) => (false, "tmux_effect_in_flight"),
            TmuxLayoutEffectState::RetryPending(_) => (false, "tmux_effect_retry_pending"),
            _ => unreachable!("route readiness Wait requires a pending effect state"),
        },
        PaneLayoutRouteReadiness::Refused => match effect_state {
            TmuxLayoutEffectState::Absent => (false, "desired_layout_state_absent"),
            TmuxLayoutEffectState::Refused(_) => (false, "layout_effect_refused"),
            TmuxLayoutEffectState::OperatorOwned(_) => (false, "operator_owned_layout"),
            _ => (false, PANE_LAYOUT_SUPERSEDED_REASON),
        },
    }
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn pane_layout_await_outcome(
    effect_state: &TmuxLayoutEffectState,
    requested_generation: u64,
) -> (bool, &'static str) {
    let (current, applied, reason) = match effect_state {
        TmuxLayoutEffectState::Absent => return (false, "desired_layout_state_absent"),
        TmuxLayoutEffectState::Converged(current) => (current, true, "observed_convergence"),
        TmuxLayoutEffectState::Refused(current) => (current, false, "layout_effect_refused"),
        TmuxLayoutEffectState::OperatorOwned(current) => (current, false, "operator_owned_layout"),
        TmuxLayoutEffectState::NeedsEffect(current) => (current, false, "tmux_effect_not_started"),
        TmuxLayoutEffectState::Applying(current) => (current, false, "tmux_effect_in_flight"),
        TmuxLayoutEffectState::RetryPending(current) => {
            (current, false, "tmux_effect_retry_pending")
        }
    };
    if current.generation != requested_generation {
        (false, PANE_LAYOUT_SUPERSEDED_REASON)
    } else {
        (applied, reason)
    }
}

/// Automatic surface `Sync` intents are already the sparse structural edge:
/// first observation, changed columns, or controller-observed drift. They must
/// cross the tmux effect boundary instead of trusting a structural assignment
/// cached before this editor generation. Pure focus changes have their own
/// `SurfaceIntent::Focus` path and do not need this cache.
fn pane_layout_invocation_allows_structural_reuse(
    invocation: &ControllerTmuxLayoutSyncInvocation,
) -> bool {
    invocation.caller_kind != "automatic"
}

#[cfg(test)]
mod tmux_layout_effect_state_dispatch_tests {
    use super::*;

    fn invocation(caller_kind: &str, no_autostart: bool) -> ControllerTmuxLayoutSyncInvocation {
        ControllerTmuxLayoutSyncInvocation {
            columns: vec!["tasks/left.md".to_string(), "tasks/right.md".to_string()],
            window: None,
            focus: Some("tasks/right.md".to_string()),
            no_autostart,
            exact_visible: true,
            caller_kind: caller_kind.to_string(),
            column_order: Default::default(),
            actor_bindings: Vec::new(),
            client_id: None,
        }
    }

    #[test]
    fn automatic_and_passive_layout_updates_publish_without_waiting() {
        assert!(!pane_layout_invocation_awaits_effect(&invocation(
            "automatic",
            false,
        )));
        assert!(!pane_layout_invocation_awaits_effect(&invocation(
            "manual", true,
        )));
        assert!(pane_layout_invocation_awaits_effect(&invocation(
            "manual", false,
        )));
    }

    #[test]
    fn manual_layout_retry_is_fresh_while_automatic_and_passive_updates_coalesce() {
        assert_eq!(
            pane_layout_publication_for_invocation(&invocation("manual", false)),
            PaneLayoutPublication::FreshIntent,
        );
        assert_eq!(
            pane_layout_publication_for_invocation(&invocation("automatic", false)),
            PaneLayoutPublication::CoalesceIdentical,
        );
        assert_eq!(
            pane_layout_publication_for_invocation(&invocation("manual", true)),
            PaneLayoutPublication::CoalesceIdentical,
        );
        assert_eq!(
            pane_layout_command_publication_for_invocation(&invocation("manual", false)),
            PaneLayoutPublication::FreshCommandIntent,
        );
        assert_eq!(
            pane_layout_command_publication_for_invocation(&invocation("automatic", true)),
            PaneLayoutPublication::CoalesceIdentical,
        );
    }

    #[test]
    fn automatic_editor_surface_sync_allows_binary_owned_safe_autostart() {
        let columns = vec![SurfaceColumn::new(["/project/tasks/software/lazily.md"])];
        let invocation = automatic_editor_surface_sync_invocation(
            &columns,
            "/project/tasks/software/lazily.md",
            false,
            agent_doc_editor_surface::SurfaceColumnOrder::Editor,
        );

        assert!(!invocation.no_autostart);
        assert!(invocation.exact_visible);
        assert_eq!(invocation.caller_kind, "automatic");
        assert_eq!(
            invocation.columns,
            vec!["/project/tasks/software/lazily.md".to_string()]
        );
        assert_eq!(
            invocation.focus.as_deref(),
            Some("/project/tasks/software/lazily.md")
        );
    }

    #[test]
    fn passive_editor_surface_sync_preserves_the_active_tmux_pane() {
        let columns = vec![SurfaceColumn::new([
            "/project/tasks/left.md",
            "/project/tasks/right.md",
        ])];
        let invocation = automatic_editor_surface_sync_invocation(
            &columns,
            "/project/tasks/left.md",
            true,
            agent_doc_editor_surface::SurfaceColumnOrder::Editor,
        );

        assert_eq!(invocation.focus, None);
    }

    #[test]
    fn automatic_structural_edges_do_not_reuse_a_prior_editor_generation() {
        assert!(!pane_layout_invocation_allows_structural_reuse(
            &invocation("automatic", true)
        ));
        assert!(pane_layout_invocation_allows_structural_reuse(&invocation(
            "manual", false
        )));
    }

    #[test]
    fn an_observed_focus_pane_converges_even_when_the_focus_effect_was_superseded() {
        // `#tmuxautosyncwedge`: documents, panes and the focus pane all match,
        // and the focus receipt only says a newer revision arrived before this
        // pass could call `select-pane`. The live layout is already the desired
        // layout, so the generation converges instead of parking in
        // `retry_pending` forever while editor navigation keeps bumping the
        // input revision.
        assert!(tmux_layout_effect_state_converged(true, true, true, false));
        // Same observation, focus effect applied by this pass.
        assert!(tmux_layout_effect_state_converged(true, true, true, true));
    }

    #[test]
    fn an_unsynced_observation_never_converges_on_a_superseded_focus_receipt() {
        // A stashed / mismatched focus pane makes the report unsynced, and the
        // supersede reason must not launder that into convergence.
        assert!(!tmux_layout_effect_state_converged(
            false, true, true, false
        ));
        assert!(!tmux_layout_effect_state_converged(
            false, false, false, true
        ));
    }

    #[test]
    fn a_required_focus_the_observation_did_not_carry_still_falls_back_to_the_effect() {
        assert!(!tmux_layout_effect_state_converged(
            true, true, false, false
        ));
        assert!(tmux_layout_effect_state_converged(true, true, false, true));
        // Focus that was never required is settled by the structural report.
        assert!(tmux_layout_effect_state_converged(
            true, false, false, false
        ));
    }

    #[test]
    fn automatic_unmapped_focus_settles_until_the_next_editor_surface_edge() {
        let missing = PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: "focus_pane_not_found:/notes/design.md".to_string(),
        };
        assert!(!focus_required_for_pane_layout_generation(
            "automatic",
            &missing,
        ));
        assert!(focus_required_for_pane_layout_generation(
            "manual", &missing,
        ));

        let transient = PaneLayoutFocusEffectReceipt {
            required: true,
            applied: false,
            reason: "focus_pane_not_co_visible:/tasks/backend.md:%11".to_string(),
        };
        assert!(focus_required_for_pane_layout_generation(
            "automatic",
            &transient,
        ));
    }

    #[test]
    fn canonical_foreground_focus_must_belong_to_the_desired_layout() {
        let root = Path::new("/project");
        let desired = vec![
            "/project/tasks/bugs.md".to_string(),
            "/project/tasks/monster.md".to_string(),
        ];
        let mut request = invocation("manual", false);

        request.focus = Some("tasks/bugs.md".to_string());
        assert!(pane_layout_foreground_focus_matches_columns(
            root, &request, &desired,
        ));

        request.focus = Some("tasks/sdk-demo.md".to_string());
        assert!(!pane_layout_foreground_focus_matches_columns(
            root, &request, &desired,
        ));

        request.caller_kind = "automatic".to_string();
        request.no_autostart = true;
        assert!(pane_layout_foreground_focus_matches_columns(
            root, &request, &desired,
        ));
    }

    #[test]
    fn changed_left_document_focus_is_applied_after_layout_reconciliation() {
        let state =
            Mutex::new(agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default());
        assert!(state.lock().schedule(7));
        let file_panes = vec![
            ("/tasks/new-left.md".to_string(), "%76".to_string()),
            ("/tasks/right.md".to_string(), "%75".to_string()),
        ];
        let mut selected = None;

        let receipt = apply_pane_layout_focus_effect(
            &state,
            7,
            Some("/tasks/new-left.md"),
            false,
            &file_panes,
            PaneLayoutFocusCoVisibility {
                layout_window: Some("@894"),
                observe_pane_window: |_| {
                    Some(LivePaneWindow::from((
                        "@894".to_string(),
                        "agent-doc".to_string(),
                    )))
                },
            },
            |pane| {
                selected = Some(pane.to_string());
                Ok(())
            },
        );

        assert_eq!(selected.as_deref(), Some("%76"));
        assert!(receipt.required);
        assert!(receipt.applied);
    }

    /// `#panewindowdrift`: the operator-reported shape. The layout's file→pane
    /// record still names `%76`, but that pane was moved into the `stash` window
    /// after it was bound, so every record-vs-record check still agrees. Focus
    /// must be refused instead of mirrored onto a pane the operator cannot see,
    /// and the refusal must not count toward convergence.
    #[test]
    fn focus_is_refused_for_a_pane_stashed_out_of_the_layout_window() {
        let state =
            Mutex::new(agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default());
        assert!(state.lock().schedule(7));
        let file_panes = vec![
            ("/tasks/new-left.md".to_string(), "%76".to_string()),
            ("/tasks/right.md".to_string(), "%75".to_string()),
        ];
        let mut selected = None;

        let receipt = apply_pane_layout_focus_effect(
            &state,
            7,
            Some("/tasks/new-left.md"),
            false,
            &file_panes,
            PaneLayoutFocusCoVisibility {
                layout_window: Some("@894"),
                observe_pane_window: |pane| {
                    assert_eq!(pane, "%76");
                    Some(LivePaneWindow::from((
                        "@904".to_string(),
                        "agent-doc".to_string(),
                    )))
                },
            },
            |pane| {
                selected = Some(pane.to_string());
                Ok(())
            },
        );

        assert!(
            selected.is_none(),
            "a stashed pane must never reach tmux select-pane"
        );
        assert!(receipt.required);
        assert!(
            !receipt.applied,
            "a refused focus must not count as applied"
        );
        assert_eq!(
            receipt.reason,
            "focus_pane_not_co_visible:/tasks/new-left.md:%76:live_window=@904:layout_window=@894"
        );
    }

    /// `#stashfocusleg`: the stash leg is only as good as this mapping. An
    /// adapter that dropped the window name would silently disable the refusal
    /// while every test over the pure guard stayed green.
    #[test]
    fn the_pane_window_observation_preserves_the_window_name() {
        assert_eq!(
            observed_pane_window(Ok(("@904".to_string(), "stash".to_string()))),
            Some(("@904".to_string(), "stash".to_string())),
            "the window NAME must survive the observation adapter"
        );
        assert_eq!(
            observed_pane_window(Ok(("  @904  ".to_string(), "  stash-3  ".to_string()))),
            Some(("@904".to_string(), "stash-3".to_string()))
        );
        // "tmux could not say" — never a refusal for either leg.
        assert_eq!(
            observed_pane_window(Err(anyhow::anyhow!("no server"))),
            None
        );
        assert_eq!(
            observed_pane_window(Ok((String::new(), "stash".to_string()))),
            None
        );
        // A window with no name is readable but unnameable; the id still counts
        // for the drift leg.
        assert_eq!(
            observed_pane_window(Ok(("@904".to_string(), String::new()))),
            Some(("@904".to_string(), String::new()))
        );
    }

    /// `#stashfocusleg`: the operator-reported shape, and the one the drift leg
    /// could not see. `pane_layout_target_window_id` answered `None` — no
    /// `@`-prefixed invocation window and no resolvable `agent-doc` window for
    /// the project — so the whole co-visibility guard used to be skipped and
    /// `select-pane` ran on a pane parked in `stash`, yanking tmux away from the
    /// visible window. The stash leg needs no layout window to refuse.
    #[test]
    fn focus_is_refused_for_a_stashed_pane_even_with_no_layout_window() {
        for window_name in ["stash", "stash-1", "stash-42"] {
            let state = Mutex::new(
                agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default(),
            );
            assert!(state.lock().schedule(7));
            let file_panes = vec![("/tasks/sample-session.md".to_string(), "%21".to_string())];
            let mut selected = None;

            let receipt = apply_pane_layout_focus_effect(
                &state,
                7,
                Some("/tasks/sample-session.md"),
                false,
                &file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window: None,
                    observe_pane_window: |pane| {
                        assert_eq!(pane, "%21");
                        Some(LivePaneWindow::from((
                            "@904".to_string(),
                            window_name.to_string(),
                        )))
                    },
                },
                |pane| {
                    selected = Some(pane.to_string());
                    Ok(())
                },
            );

            assert!(
                selected.is_none(),
                "a stashed pane must never reach tmux select-pane ({window_name})"
            );
            assert!(receipt.required);
            assert!(
                !receipt.applied,
                "a refused focus must not count as applied"
            );
            assert_eq!(
                receipt.reason,
                format!(
                    "focus_pane_stashed:/tasks/sample-session.md:%21:live_window_name={window_name}"
                )
            );
        }
    }

    /// The stash leg must not swallow ordinary windows. `stashed` is not
    /// `stash`, and a pane in the layout window is focused normally even when
    /// the layout window is unknown.
    /// `layoutpublisherarbiter` (GH #120): a pane in a non-active window is
    /// never a focus target. With no resolvable layout window the stash-name
    /// leg alone let a pane in any other inactive window through, and
    /// `select_pane` runs `select-window`, switching the operator's client to
    /// it. An active window, or an unknown activity answer, is not refused.
    #[test]
    fn focus_is_refused_for_a_pane_in_an_inactive_window_with_no_layout_window() {
        for (active, refused) in [(Some(false), true), (Some(true), false), (None, false)] {
            let state = Mutex::new(
                agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default(),
            );
            assert!(state.lock().schedule(7));
            let file_panes = vec![("/tasks/sample-session.md".to_string(), "%21".to_string())];
            let mut selected = None;

            let receipt = apply_pane_layout_focus_effect(
                &state,
                7,
                Some("/tasks/sample-session.md"),
                false,
                &file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window: None,
                    observe_pane_window: |_| {
                        Some(LivePaneWindow {
                            id: "@904".to_string(),
                            name: "parked".to_string(),
                            active,
                        })
                    },
                },
                |pane| {
                    selected = Some(pane.to_string());
                    Ok(())
                },
            );

            if refused {
                assert!(
                    selected.is_none(),
                    "an inactive window's pane must never be selected"
                );
                assert!(receipt.required);
                assert!(!receipt.applied);
                assert_eq!(
                    receipt.reason,
                    "focus_pane_window_inactive:/tasks/sample-session.md:%21:live_window=@904:live_window_name=parked"
                );
            } else {
                assert_eq!(selected.as_deref(), Some("%21"), "active={active:?}");
                assert!(receipt.applied);
            }
        }
    }

    /// The production read carries activity, and a malformed answer is
    /// "unknown", never "inactive".
    #[test]
    fn live_pane_window_observation_parses_window_activity() {
        assert_eq!(
            observed_live_pane_window(Ok("@9\t0\tstash".to_string())),
            Some(LivePaneWindow {
                id: "@9".to_string(),
                name: "stash".to_string(),
                active: Some(false),
            })
        );
        assert_eq!(
            observed_live_pane_window(Ok("@3\t1\tagent doc".to_string())),
            Some(LivePaneWindow {
                id: "@3".to_string(),
                name: "agent doc".to_string(),
                active: Some(true),
            })
        );
        assert_eq!(
            observed_live_pane_window(Ok("@3".to_string())).map(|w| w.active),
            Some(None)
        );
        assert_eq!(
            observed_live_pane_window(Ok("\t1\tstash".to_string())),
            None
        );
        assert_eq!(
            observed_live_pane_window(Err(anyhow::anyhow!("no server"))),
            None
        );
    }

    #[test]
    fn focus_is_applied_for_a_non_stash_window_with_no_layout_window() {
        for window_name in ["agent-doc", "stashed", "claude", ""] {
            let state = Mutex::new(
                agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default(),
            );
            assert!(state.lock().schedule(7));
            let file_panes = vec![("/tasks/sample-session.md".to_string(), "%21".to_string())];
            let mut selected = None;

            let receipt = apply_pane_layout_focus_effect(
                &state,
                7,
                Some("/tasks/sample-session.md"),
                false,
                &file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window: None,
                    observe_pane_window: |_| {
                        Some(LivePaneWindow::from((
                            "@904".to_string(),
                            window_name.to_string(),
                        )))
                    },
                },
                |pane| {
                    selected = Some(pane.to_string());
                    Ok(())
                },
            );

            assert_eq!(
                selected.as_deref(),
                Some("%21"),
                "window {window_name:?} must not be treated as stash"
            );
            assert!(receipt.applied);
        }
    }

    /// Both legs read ONE observation, so they cannot disagree across a
    /// concurrent `move-window`: a stashed pane is refused as stashed even when
    /// its window id still matches the layout window.
    #[test]
    fn the_stash_leg_wins_over_a_matching_window_id() {
        let state =
            Mutex::new(agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default());
        assert!(state.lock().schedule(7));
        let file_panes = vec![("/tasks/left.md".to_string(), "%76".to_string())];
        let mut selected = None;

        let receipt = apply_pane_layout_focus_effect(
            &state,
            7,
            Some("/tasks/left.md"),
            false,
            &file_panes,
            PaneLayoutFocusCoVisibility {
                layout_window: Some("@894"),
                observe_pane_window: |_| {
                    Some(LivePaneWindow::from((
                        "@894".to_string(),
                        "stash".to_string(),
                    )))
                },
            },
            |pane| {
                selected = Some(pane.to_string());
                Ok(())
            },
        );

        assert!(selected.is_none());
        assert!(!receipt.applied);
        assert!(
            receipt.reason.starts_with("focus_pane_stashed:"),
            "{}",
            receipt.reason
        );
    }

    /// Strict tightening, mirroring the pure predicate: a window we cannot
    /// resolve on either side is never drift, so a transient tmux read or an
    /// unconfigured session cannot turn into a refused focus.
    #[test]
    fn unresolved_windows_never_refuse_focus() {
        let file_panes = vec![("/tasks/left.md".to_string(), "%76".to_string())];

        for (layout_window, live_window) in [
            (None, Some(("@904".to_string(), "agent-doc".to_string()))),
            (Some("@894"), None),
            (
                Some("  "),
                Some(("@904".to_string(), "agent-doc".to_string())),
            ),
            (Some("@894"), Some((String::new(), String::new()))),
        ] {
            let state = Mutex::new(
                agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default(),
            );
            assert!(state.lock().schedule(7));
            let mut selected = None;

            let receipt = apply_pane_layout_focus_effect(
                &state,
                7,
                Some("/tasks/left.md"),
                false,
                &file_panes,
                PaneLayoutFocusCoVisibility {
                    layout_window,
                    observe_pane_window: |_| live_window.clone().map(LivePaneWindow::from),
                },
                |pane| {
                    selected = Some(pane.to_string());
                    Ok(())
                },
            );

            assert_eq!(selected.as_deref(), Some("%76"));
            assert!(receipt.applied, "unknown window must not refuse focus");
        }
    }

    /// The layout target window is the accepted frontend snapshot's declared window, never
    /// an inferred active/first/majority window. An explicit window id is used
    /// verbatim; a window *name* falls through to the by-name lookup so the
    /// comparison stays id-to-id.
    #[test]
    fn layout_target_window_prefers_an_explicit_window_id() {
        let project_root = std::env::temp_dir().join("agent-doc-pane-layout-window-id-test");
        let tmux = agent_doc_tmux_io::configured_tmux();
        assert_eq!(
            pane_layout_target_window_id(&project_root, &tmux, Some("@894")),
            Some("@894".to_string())
        );
        assert_eq!(
            pane_layout_target_window_id(&project_root, &tmux, Some(" @894 ")),
            Some("@894".to_string())
        );
        // A name is not an id: it must not become the comparison reference.
        assert_ne!(
            pane_layout_target_window_id(&project_root, &tmux, Some("agent-doc")),
            Some("agent-doc".to_string())
        );
    }

    /// A pane assignment that names a pane outside the layout window is not a
    /// visible column, so it must not satisfy a layout slot or the focus target.
    #[test]
    fn stashed_assignment_does_not_satisfy_a_layout_slot_or_focus() {
        let project_root = Path::new("/project");
        let window_panes = ["%75".to_string()];
        let effect_file_panes = [
            ("/project/left.md".to_string(), "%76".to_string()),
            ("/project/right.md".to_string(), "%75".to_string()),
        ];
        let visible_effect_file_panes = effect_file_panes
            .iter()
            .filter(|(_, assigned_pane)| window_panes.iter().any(|pane| pane == assigned_pane))
            .cloned()
            .collect::<Vec<_>>();

        assert_eq!(
            layout_sync_state_expected_focus_pane(
                project_root,
                Some("/project/left.md"),
                &visible_effect_file_panes,
            ),
            None,
            "a stashed pane must not stand in as the focus target"
        );
        assert_eq!(
            layout_sync_state_expected_panes(
                project_root,
                &[
                    "/project/left.md".to_string(),
                    "/project/right.md".to_string()
                ],
                &visible_effect_file_panes,
            ),
            vec!["%75".to_string()],
        );
        let (synced, reason) = layout_sync_state_result(
            &[
                "/project/left.md".to_string(),
                "/project/right.md".to_string(),
            ],
            &[
                "/project/left.md".to_string(),
                "/project/right.md".to_string(),
            ],
            &["%75".to_string()],
            &window_panes,
            true,
            None,
            Some("%75"),
        );
        assert!(!synced);
        assert_eq!(reason, "focus_pane_not_found");
    }

    #[test]
    fn newer_layout_generation_cancels_stale_focus_before_select_pane() {
        let state =
            Mutex::new(agent_doc_controller::pane_layout::LatestTmuxEffectWorkerState::default());
        assert!(state.lock().schedule(7));
        assert!(!state.lock().schedule(8));
        let file_panes = vec![("/tasks/old-left.md".to_string(), "%72".to_string())];
        let mut selected = false;

        let receipt = apply_pane_layout_focus_effect(
            &state,
            7,
            Some("/tasks/old-left.md"),
            false,
            &file_panes,
            PaneLayoutFocusCoVisibility {
                layout_window: Some("@894"),
                observe_pane_window: |_| {
                    Some(LivePaneWindow::from((
                        "@894".to_string(),
                        "agent-doc".to_string(),
                    )))
                },
            },
            |_| {
                selected = true;
                Ok(())
            },
        );

        assert!(!selected, "a superseded focus effect must not reach tmux");
        assert!(receipt.required);
        assert!(!receipt.applied);
        assert_eq!(receipt.reason, "focus_superseded_by_newer_layout_state");
    }

    #[test]
    fn retry_pending_layout_attempt_remains_owned_for_retry() {
        let desired = PaneLayoutDesired {
            generation: 7,
            source_plane_version: None,
            invocation: invocation("automatic", false),
            provenance: PaneLayoutProvenance::default(),
        };

        assert_eq!(
            pane_layout_attempt_completion(
                Some(desired.generation),
                &TmuxLayoutEffectState::RetryPending(desired.clone()),
                desired.generation,
            ),
            PaneLayoutAttemptCompletion::RetryCurrent
        );
        assert_eq!(
            pane_layout_attempt_completion(
                Some(desired.generation),
                &TmuxLayoutEffectState::Refused(desired.clone()),
                desired.generation,
            ),
            PaneLayoutAttemptCompletion::Retire
        );
        assert_eq!(
            pane_layout_attempt_completion(
                Some(desired.generation),
                &TmuxLayoutEffectState::Converged(desired.clone()),
                desired.generation,
            ),
            PaneLayoutAttemptCompletion::Retire
        );
        assert_eq!(
            pane_layout_attempt_completion(
                Some(desired.generation),
                &TmuxLayoutEffectState::OperatorOwned(desired.clone()),
                desired.generation,
            ),
            PaneLayoutAttemptCompletion::Retire
        );
        assert_eq!(
            pane_layout_attempt_completion(
                Some(desired.generation + 1),
                &TmuxLayoutEffectState::RetryPending(desired.clone()),
                desired.generation,
            ),
            PaneLayoutAttemptCompletion::Superseded
        );
    }

    #[test]
    fn pane_layout_retry_backoff_is_bounded() {
        assert_eq!(
            tmux_layout_effect_state_retry_delay(1),
            Duration::from_millis(250)
        );
        assert_eq!(
            tmux_layout_effect_state_retry_delay(2),
            Duration::from_millis(500)
        );
        assert_eq!(
            tmux_layout_effect_state_retry_delay(5),
            Duration::from_secs(4)
        );
        assert_eq!(
            tmux_layout_effect_state_retry_delay(6),
            Duration::from_secs(5)
        );
        assert_eq!(
            tmux_layout_effect_state_retry_delay(u64::MAX),
            Duration::from_secs(5)
        );
    }
}

pub(crate) fn rejected_admin_receipt(
    bootstrap: &ControllerBootstrap,
    operation_kind: &str,
    document_id: Option<&str>,
    failed_stage: &str,
    diagnostic_payload: &str,
    observed_generation: Option<u64>,
    current_generation: Option<u64>,
) -> Result<ControllerAdminReceipt> {
    let mut receipt = insert_admin_operation_record(
        &bootstrap.project_root,
        operation_kind,
        document_id,
        "rejected",
        Some(diagnostic_payload),
    )?;
    receipt.failed_stage = Some(failed_stage.to_string());
    receipt.unblock_hint =
        Some("inspect the actor and retry with the current observed generation".to_string());
    receipt.observed_generation = observed_generation;
    receipt.current_generation = current_generation;
    Ok(receipt)
}

pub(crate) fn require_observed_generation(
    bootstrap: &ControllerBootstrap,
    operation_kind: &str,
    document_id: Option<&str>,
    record: Option<&agent_doc_controller::actor::ActorRecord>,
    observed_generation: Option<u64>,
    diagnostic_payload: &str,
) -> Result<Option<ControllerAdminReceipt>> {
    let Some(record) = record else {
        return Ok(None);
    };
    match observed_generation {
        None => rejected_admin_receipt(
            bootstrap,
            operation_kind,
            document_id,
            "missing_observed_generation",
            diagnostic_payload,
            None,
            Some(record.generation),
        )
        .map(Some),
        Some(observed) if observed != record.generation => rejected_admin_receipt(
            bootstrap,
            operation_kind,
            document_id,
            "stale_generation",
            diagnostic_payload,
            Some(observed),
            Some(record.generation),
        )
        .map(Some),
        Some(_) => Ok(None),
    }
}

pub(crate) fn handle_queue_control(
    bootstrap: &ControllerBootstrap,
    request: ControllerRequest,
) -> Result<ControllerAdminReceipt> {
    let action = request_string(&request.state, "queue control action")?;
    let control_state = match action.as_str() {
        "pause" | "paused" => "paused",
        "resume" | "resumed" => "resumed",
        "drain" | "draining" => "draining",
        other => anyhow::bail!("unknown queue control action: {other}"),
    };
    let operation_kind = format!("queue_{control_state}");
    let reason = request
        .reason
        .as_deref()
        .unwrap_or("operator queue control");
    let item_id = request.diagnostic_payload.as_deref();
    let diagnostic_payload = match item_id {
        Some(item_id) => format!("reason={reason} item_id={item_id}"),
        None => format!("reason={reason}"),
    };
    let (_target, document_id, record) = if request.file.is_some() {
        admin_target_record(bootstrap, &request)?
    } else {
        (bootstrap.project_root.display().to_string(), None, None)
    };
    if let Some(rejected) = require_observed_generation(
        bootstrap,
        &operation_kind,
        document_id.as_deref(),
        record.as_ref(),
        request.generation,
        &diagnostic_payload,
    )? {
        return Ok(rejected);
    }
    // `#netadv3` SIM-F2: a reordered older pause/resume/drain must not flip
    // queue control back over a newer one.
    let sequence_scope = document_id
        .clone()
        .unwrap_or_else(|| bootstrap.project_root.to_string_lossy().into_owned());
    let sequence_generation = record
        .as_ref()
        .map(|record| record.generation)
        .or(request.generation)
        .unwrap_or_default();
    if let Err(newest) = admit_level_update(
        agent_doc_controller::sequence::SequencedFamily::QueueControl,
        &sequence_scope,
        sequence_generation,
        request.sequence,
    ) {
        return rejected_admin_receipt(
            bootstrap,
            &operation_kind,
            document_id.as_deref(),
            "stale_sequence",
            &format!(
                "{diagnostic_payload} stamp={:?} newest={newest}",
                request.sequence
            ),
            request.generation,
            record.as_ref().map(|record| record.generation),
        );
    }
    let receipt = insert_admin_operation_record(
        &bootstrap.project_root,
        &operation_kind,
        document_id.as_deref(),
        "accepted",
        Some(&diagnostic_payload),
    )?;
    let conn = open_state_db(&bootstrap.project_root)?;
    let scope_kind = if document_id.is_some() {
        "document"
    } else {
        "project"
    };
    let project_scope = bootstrap.project_root.to_string_lossy();
    let scope_id = document_id.as_deref().unwrap_or(project_scope.as_ref());
    let control = state_store::upsert_queue_control_in_db(
        &conn,
        &state_store::QueueControlInsert {
            scope_kind,
            scope_id,
            state: control_state,
            reason: Some(reason),
            operation_receipt_id: Some(receipt.receipt_id),
        },
    )?;
    let mut receipt = receipt;
    receipt.diagnostic_payload = Some(format!(
        "{diagnostic_payload} scope_kind={} scope_id={} control_receipt_id={}",
        control.scope_kind, control.scope_id, control.receipt_id
    ));
    Ok(receipt)
}

pub(crate) fn handle_admin_control(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    request: ControllerRequest,
) -> Result<ControllerAdminReceipt> {
    let action = request_string(&request.state, "admin control action")?;
    let operation_kind = format!("admin_{action}");
    let reason = request
        .reason
        .as_deref()
        .unwrap_or("operator admin control");
    let diagnostic_payload = format!("reason={reason}");
    let (_target, document_id, record) = admin_target_record(bootstrap, &request)?;
    let Some(record) = record else {
        return rejected_admin_receipt(
            bootstrap,
            &operation_kind,
            document_id.as_deref(),
            "missing_actor",
            &diagnostic_payload,
            request.generation,
            None,
        );
    };
    if let Some(rejected) = require_observed_generation(
        bootstrap,
        &operation_kind,
        Some(&record.document_id),
        Some(&record),
        request.generation,
        &diagnostic_payload,
    )? {
        return Ok(rejected);
    }
    let receipt = insert_admin_operation_record(
        &bootstrap.project_root,
        &operation_kind,
        Some(&record.document_id),
        "accepted",
        Some(&diagnostic_payload),
    )?;
    let mut next = record.clone();
    match action.as_str() {
        "reap" => {
            next.state = agent_doc_controller::actor::ActorState::Closed;
            next.pane_id.clear();
            next.window_id.clear();
            next.last_transition = agent_doc_controller::actor::ActorLastTransition {
                caller: "admin".to_string(),
                reason: format!("manual_reap {reason} receipt_id={}", receipt.receipt_id),
                timestamp: timestamp_secs(),
                prior_generation: record.generation,
                new_generation: record.generation,
            };
        }
        "handoff" => {
            let to_pane = request_string(&request.pane_id, "to pane")?;
            next.generation = record.generation.saturating_add(1);
            next.pane_id = to_pane;
            next.state = agent_doc_controller::actor::ActorState::Ready;
            next.last_transition = agent_doc_controller::actor::ActorLastTransition {
                caller: "admin".to_string(),
                reason: format!("manual_handoff {reason} receipt_id={}", receipt.receipt_id),
                timestamp: timestamp_secs(),
                prior_generation: record.generation,
                new_generation: record.generation.saturating_add(1),
            };
        }
        other => anyhow::bail!("unknown admin control action: {other}"),
    }
    store_actor_record_for_runtime(
        &bootstrap.project_root,
        Some(record.generation),
        &next,
        runtime,
    )?;
    Ok(receipt)
}

pub(crate) fn handle_projection_repair(
    bootstrap: &ControllerBootstrap,
    request: ControllerRequest,
) -> Result<ControllerAdminReceipt> {
    let projection = request.state.as_deref().unwrap_or("all").trim().to_string();
    let reason = request
        .reason
        .as_deref()
        .unwrap_or("operator projection repair");
    let diagnostic_payload = format!("projection={projection} reason={reason}");
    let (_target, document_id, record) = if request.file.is_some() {
        admin_target_record(bootstrap, &request)?
    } else {
        (bootstrap.project_root.display().to_string(), None, None)
    };
    if let Some(rejected) = require_observed_generation(
        bootstrap,
        "projection_repair",
        document_id.as_deref(),
        record.as_ref(),
        request.generation,
        &diagnostic_payload,
    )? {
        return Ok(rejected);
    }
    let receipt = insert_admin_operation_record(
        &bootstrap.project_root,
        "projection_repair",
        document_id.as_deref(),
        "accepted",
        Some(&diagnostic_payload),
    )?;
    repair_projection_from_controller_state(
        &bootstrap.project_root,
        &projection,
        document_id.as_deref(),
    )?;
    Ok(receipt)
}

pub(crate) fn repair_projection_from_controller_state(
    project_root: &Path,
    projection: &str,
    _document_id: Option<&str>,
) -> Result<()> {
    match projection {
        "all" | "layout" => {
            load_layout_state(project_root)?;
        }
        other => anyhow::bail!("unknown projection repair target: {other}"),
    }
    Ok(())
}

pub(crate) fn handle_attach_pane(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    request: ControllerRequest,
) -> Result<agent_doc_controller::actor::ActorRecord> {
    let file = request_file(&request)?;
    let session_id = request_string(&request.session_id, "session_id")?;
    let pane_id = request_string(&request.pane_id, "pane_id")?;
    let window_id = request_string(&request.window_id, "window_id")?;
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &bootstrap.project_root,
        &file.to_string_lossy(),
    );
    let prior = actor_record_from_authority(bootstrap, runtime, &document_id)?;
    let prior_generation = prior.as_ref().map(|record| record.generation).unwrap_or(0);
    let generation = prior
        .as_ref()
        .filter(|record| record.pane_id == pane_id)
        .map(|record| record.generation)
        .unwrap_or_else(|| prior_generation.saturating_add(1).max(1));
    let harness = prior
        .as_ref()
        .map(|record| record.harness.clone())
        .filter(|harness| !harness.trim().is_empty())
        .unwrap_or_else(|| {
            agent_doc_session_actor_io::detect_document_harness_in(
                &bootstrap.project_root,
                &document_id,
            )
        });
    let record = agent_doc_controller::actor::ActorRecord {
        document_id: document_id.clone(),
        session_id: session_id.clone(),
        generation,
        pane_id: pane_id.clone(),
        window_id: window_id.clone(),
        harness,
        state: agent_doc_controller::actor::ActorState::Ready,
        last_transition: agent_doc_controller::actor::ActorLastTransition {
            caller: request.caller.as_deref().unwrap_or("session").to_string(),
            reason: request
                .reason
                .as_deref()
                .unwrap_or("manual_attach")
                .to_string(),
            timestamp: timestamp_secs(),
            prior_generation,
            new_generation: generation,
        },
    };
    let record = store_actor_record_for_runtime(
        &bootstrap.project_root,
        Some(prior_generation),
        &record,
        runtime,
    )?;
    agent_doc_ops_log_io::log_op(
        &file,
        &format!(
            "controller_attach_pane session={} pane={} generation={} state={}",
            session_id,
            pane_id,
            record.generation,
            record.state.as_str()
        ),
    );
    Ok(record)
}

pub(crate) fn handle_operator_command(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    request: ControllerRequest,
) -> Result<DispatchAuthorization> {
    let file = request_file(&request)?;
    let command_kind = request_string(&request.command_kind, "command_kind")?;
    // (`#clearunobservedrecycle`) An operator command is authorization to
    // mutate or contact the actor owned by this controller generation. A
    // retiring generation cannot issue that authorization: its supervisor and
    // pane projection may already be moving to the replacement. Returning the
    // standard retryable handoff refusal here lets the client reconnect after
    // promotion before it sends `/clear`, rather than accepting against stale
    // authority and later reporting `submission_unobserved` from a blank pane.
    // This guard precedes actor lookup and receipt insertion so a refused
    // generation leaves no durable acceptance behind.
    if bootstrap.handoff_state != ControllerHandoffState::Stable {
        anyhow::bail!(
            "operator command `{command_kind}` refused for {}: controller not authoritative (handoff_state={:?}); retry against the promoted generation",
            file.display(),
            bootstrap.handoff_state
        );
    }
    let diagnostic_payload = request
        .diagnostic_payload
        .as_deref()
        .unwrap_or_default()
        .to_string();
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &bootstrap.project_root,
        &file.to_string_lossy(),
    );
    let Some(record) = actor_record_from_authority(bootstrap, runtime, &document_id)? else {
        let receipt = insert_dispatch_attempt_record(
            &bootstrap.project_root,
            ControllerDispatchReceiptInsert {
                document_id: &document_id,
                generation: 0,
                command_kind: &command_kind,
                accepted_stage: None,
                failed_stage: Some("missing_actor"),
                diagnostic_payload: &diagnostic_payload,
                result_status: ControllerDispatchResultStatus::Rejected,
                proof_scope: ControllerDispatchProofScope::AcceptedOnly,
                dispatch_start_proven: false,
            },
        )?;
        anyhow::bail!(
            "operator command `{}` rejected for {}: stage=missing_actor receipt_id={}",
            command_kind,
            file.display(),
            receipt.receipt_id
        );
    };
    // A `Closed` or `Blocked` actor is a valid target for recovery commands.
    // `session_clear` / `session_interrupt_clear` reset a closed/blocked session,
    // and `session_restart` SUPERSEDES it — blue/green drain-and-supersede
    // (#supkill-bg): a restart must not fail closed against a dead/closed or
    // stuck/blocked generation. The whole point of restart is to replace the
    // superseded generation with the next one, so a `Closed` actor is exactly when
    // restart is meaningful (the operator's `session restart-supervisor` hit
    // `generation N is closed` here). A `Blocked` actor (starting-timeout) is the
    // same kind of stuck state: rejecting the recovery command on exactly the
    // state that needs recovery is self-defeating (#clear-blocked-actor). Only
    // non-recovery commands on a `Closed` or `Blocked` actor still reject.
    let is_recovery_command = matches!(
        command_kind.as_str(),
        "session_clear" | "session_interrupt_clear" | "session_restart"
    );
    let recovers_terminal_actor = is_recovery_command
        && matches!(
            record.state,
            agent_doc_controller::actor::ActorState::Closed
                | agent_doc_controller::actor::ActorState::Blocked
        );
    if !recovers_terminal_actor
        && matches!(
            record.state,
            agent_doc_controller::actor::ActorState::Blocked
                | agent_doc_controller::actor::ActorState::Closed
        )
    {
        let failed_stage = record.state.as_str();
        let receipt = insert_dispatch_attempt_record(
            &bootstrap.project_root,
            ControllerDispatchReceiptInsert {
                document_id: &document_id,
                generation: record.generation,
                command_kind: &command_kind,
                accepted_stage: None,
                failed_stage: Some(failed_stage),
                diagnostic_payload: &diagnostic_payload,
                result_status: ControllerDispatchResultStatus::Blocked,
                proof_scope: ControllerDispatchProofScope::AcceptedOnly,
                dispatch_start_proven: false,
            },
        )?;
        anyhow::bail!(
            "operator command `{}` rejected for {}: generation {} is {} receipt_id={}",
            command_kind,
            file.display(),
            record.generation,
            failed_stage,
            receipt.receipt_id
        );
    }
    let accepted_stage = format!("operator_{}", record.state.as_str());
    let receipt = insert_dispatch_attempt_record(
        &bootstrap.project_root,
        ControllerDispatchReceiptInsert {
            document_id: &document_id,
            generation: record.generation,
            command_kind: &command_kind,
            accepted_stage: Some(&accepted_stage),
            failed_stage: None,
            diagnostic_payload: &diagnostic_payload,
            result_status: ControllerDispatchResultStatus::Accepted,
            proof_scope: ControllerDispatchProofScope::AcceptedOnly,
            dispatch_start_proven: false,
        },
    )?;
    agent_doc_ops_log_io::log_op(
        &file,
        &format!(
            "controller_operator_command_accepted kind={} session={} pane={} generation={} stage={} receipt_id={} proof_scope={}",
            command_kind,
            record.session_id,
            record.pane_id,
            record.generation,
            accepted_stage,
            receipt.receipt_id,
            receipt.proof_scope.as_str()
        ),
    );
    // #supkill-bg blue/green redirect proof: a `session_restart` that authorizes
    // against a `Closed` or `Blocked` actor is the supersede signal — record the
    // prior (closed/blocked) generation and the next generation the restart drains
    // toward so racing dispatch / log forensics can see the "superseded -> retry
    // against N+1" redirect instead of the old `generation N is closed` hard
    // reject.
    if command_kind == "session_restart"
        && matches!(
            record.state,
            agent_doc_controller::actor::ActorState::Closed
                | agent_doc_controller::actor::ActorState::Blocked
        )
    {
        agent_doc_ops_log_io::log_op(
            &file,
            &format!(
                "supervisor_restart_supersede file={} action=supersede_{}_actor prior_generation={} next_generation={} receipt_id={} caller=operator",
                file.display(),
                record.state.as_str(),
                record.generation,
                record.generation.saturating_add(1),
                receipt.receipt_id,
            ),
        );
    }
    Ok(DispatchAuthorization {
        record,
        accepted_stage,
        receipt,
    })
}

#[cfg(not(any(test, feature = "test-support")))]
const SUPERVISOR_REPLACEMENT_WAIT_SECS_ENV: &str = "AGENT_DOC_SUPERVISOR_REPLACEMENT_WAIT_SECS";
#[cfg(not(any(test, feature = "test-support")))]
const DEFAULT_SUPERVISOR_REPLACEMENT_WAIT_SECS: u64 = 20;
#[cfg(not(any(test, feature = "test-support")))]
const SUPERVISOR_REPLACEMENT_POLL_INTERVAL: Duration = Duration::from_millis(250);

#[derive(Clone, Debug)]
struct SupervisorReplacementWork {
    project_root: PathBuf,
    file: PathBuf,
    session_id: String,
    pane_id: String,
    generation: u64,
    mode: String,
    force: bool,
    operator_receipt_id: u64,
}

#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SupervisorReplacementIpcStatus {
    Accepted,
    Dead,
    Failed,
    /// `#netadv5` R9: live socket, late effect receipt — maybe accepted.
    ResponseTimedOut,
}

/// `#netadv5` R9: classify a `restart` send error. A dead socket is positive
/// evidence; a response timeout on a live socket means the supervisor took the
/// command and may be executing it; anything else is a failure.
#[cfg_attr(any(test, feature = "test-support"), allow(dead_code))]
fn supervisor_replacement_ipc_error_status(
    socket_dead: bool,
    failure_kind: Option<agent_doc_supervisor_io::ipc::SupervisorCommandFailureKind>,
) -> SupervisorReplacementIpcStatus {
    if socket_dead {
        SupervisorReplacementIpcStatus::Dead
    } else if failure_kind
        == Some(agent_doc_supervisor_io::ipc::SupervisorCommandFailureKind::ResponseTimeout)
    {
        SupervisorReplacementIpcStatus::ResponseTimedOut
    } else {
        SupervisorReplacementIpcStatus::Failed
    }
}

/// `#restartlivepane`: refusing every live non-shell pane made "Restart Agent"
/// impossible on the one pane it is always aimed at — the document's own agent.
/// The operator explicitly asked to restart THIS document's harness, and
/// `--resume` (`#restartresume`) means relaunching costs the process, not the
/// conversation. So a pane running the document's own harness is restartable.
///
/// The guard that matters is kept, and narrowed rather than widened: a live pane
/// running anything ELSE is still untouchable. That covers a build, an editor, an
/// ssh session, or a harness bound to a different document — killing any of those
/// destroys unrelated work the operator never offered up.
///
/// Matching is deliberately EXACT against the resolved harness binary, not
/// `HarnessConfig::process_names` (which includes `node` and `agent-doc`): a
/// substring match there would make any Node process look like a restartable
/// agent. Related: `#bare-foreign-session-guard` — proving ownership, never
/// assuming it.
#[cfg(any(test, not(feature = "test-support")))]
fn supervisor_replacement_pane_start_decision(
    intent: SupervisorReplacementIntent,
    pane_alive: bool,
    current_command: Option<&str>,
    document_harness_binary: Option<&str>,
    process_tree_owns_document: bool,
) -> SupervisorReplacementPaneDecision {
    let current_command = current_command
        .map(str::trim)
        .filter(|command| !command.is_empty());
    let runs_own_harness = process_tree_owns_document
        || match (current_command, document_harness_binary) {
            (Some(command), Some(harness)) => {
                let harness = harness.trim();
                !harness.is_empty() && command.eq_ignore_ascii_case(harness)
            }
            _ => false,
        };
    decide_supervisor_replacement_pane(
        intent,
        SupervisorReplacementPaneFacts {
            pane_alive,
            current_command_is_shell: current_command
                .is_some_and(agent_doc_tmux::pane_current_command_is_bare_shell),
            runs_document_harness: runs_own_harness,
        },
    )
}

pub(crate) fn handle_supervisor_replacement(
    bootstrap: &ControllerBootstrap,
    runtime: Option<&ControllerRuntime>,
    request: ControllerRequest,
) -> Result<SupervisorReplacementReceipt> {
    let file = request_file(&request)?;
    let parsed = parse_supervisor_replacement_request(SupervisorReplacementRequestFields {
        state: request.state.as_deref(),
        reason: request.reason.as_deref(),
        diagnostic_payload: request.diagnostic_payload.as_deref(),
    })?;
    // `#agentrestartwire`: keep the operator's wire form (`agent:continue`)
    // verbatim. The supervisor's own `decode_restart_intent` is what stops a
    // Restart Agent from being downgraded to an in-place re-exec that preserves
    // the very harness child the operator asked to replace.
    let mode = parsed.wire_mode();
    let force = parsed.force;
    let authorization = handle_operator_command(
        bootstrap,
        runtime,
        ControllerRequest {
            command: "operator_command".to_string(),
            file: Some(file.clone()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: request.caller.clone(),
            reason: request.reason.clone(),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("session_restart".to_string()),
            diagnostic_payload: Some(format!(
                "session supervisor replacement background mode={mode} force={force}"
            )),
            sequence: None,
        },
    )?;
    let record = authorization.record.clone();
    let work = SupervisorReplacementWork {
        project_root: bootstrap.project_root.clone(),
        file: file.clone(),
        session_id: record.session_id.clone(),
        pane_id: record.pane_id.clone(),
        generation: record.generation,
        mode: mode.clone(),
        force,
        operator_receipt_id: authorization.receipt.receipt_id,
    };
    // `#replacementdrain`: count the worker so a self-handoff that promotes a
    // successor mid-replacement drains it instead of exiting under it.
    let in_flight = runtime.map(ControllerRuntime::begin_supervisor_replacement_worker);
    let background_started = spawn_supervisor_replacement_worker(work, in_flight)?;
    agent_doc_ops_log_io::log_op(
        &file,
        &format!(
            "controller_supervisor_replacement_accepted mode={} force={} session={} pane={} generation={} stage={} receipt_id={} background_started={}",
            mode,
            force,
            record.session_id,
            record.pane_id,
            record.generation,
            authorization.accepted_stage,
            authorization.receipt.receipt_id,
            background_started
        ),
    );
    Ok(SupervisorReplacementReceipt {
        record,
        accepted_stage: authorization.accepted_stage,
        operator_receipt: authorization.receipt,
        background_started,
        mode,
        force,
        session_id: authorization.record.session_id,
        pane_id: authorization.record.pane_id,
        generation: authorization.record.generation,
    })
}

#[cfg(any(test, feature = "test-support"))]
fn spawn_supervisor_replacement_worker(
    work: SupervisorReplacementWork,
    _in_flight: Option<crate::project_controller::SupervisorReplacementWorkerInFlight>,
) -> Result<bool> {
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_background_stub mode={} force={} session={} pane={} generation={} receipt_id={} project_root={}",
            work.mode,
            work.force,
            work.session_id,
            work.pane_id,
            work.generation,
            work.operator_receipt_id,
            work.project_root.display()
        ),
    );
    Ok(false)
}

#[cfg(not(any(test, feature = "test-support")))]
fn spawn_supervisor_replacement_worker(
    work: SupervisorReplacementWork,
    in_flight: Option<crate::project_controller::SupervisorReplacementWorkerInFlight>,
) -> Result<bool> {
    // `#replacementreceipt`: do not acknowledge a detached worker before its
    // first authoritative lifecycle decision. The worker may still own a slow
    // reexec/cold-start completion, but an immediate live-supervisor refusal
    // must reach the operator synchronously instead of being buried later as
    // `background_failed` after a false-success receipt.
    let (admission_sender, admission_receiver) = std::sync::mpsc::sync_channel(1);
    std::thread::Builder::new()
        .name("agent-doc-supervisor-replacement".to_string())
        .spawn(move || {
            // Released when this worker returns, whatever the outcome.
            let _in_flight = in_flight;
            if let Err(err) =
                drive_supervisor_replacement_background(work.clone(), admission_sender)
            {
                agent_doc_ops_log_io::log_op(
                    &work.file,
                    &format!(
                        "controller_supervisor_replacement_background_failed session={} pane={} generation={} receipt_id={} error={err:?}",
                        work.session_id, work.pane_id, work.generation, work.operator_receipt_id
                    ),
                );
            }
        })
        .context("failed to spawn supervisor replacement background worker")?;
    match admission_receiver.recv() {
        Ok(Ok(())) => Ok(true),
        Ok(Err(err)) => anyhow::bail!(err),
        Err(err) => {
            anyhow::bail!("supervisor replacement worker exited before lifecycle admission: {err}")
        }
    }
}

/// Finish a deferred replacement admission with the authoritative cold-start
/// result. A dead supervisor has accepted nothing, so its replacement receipt
/// cannot become successful until the controller has actually submitted the
/// successor start command.
#[cfg(any(test, not(feature = "test-support")))]
fn complete_deferred_supervisor_replacement_admission<T>(
    admission_sender: &std::sync::mpsc::SyncSender<Result<(), String>>,
    result: Result<T>,
) -> Result<T> {
    match result {
        Ok(value) => {
            let _ = admission_sender.send(Ok(()));
            Ok(value)
        }
        Err(err) => {
            let message = format!("{err:#}");
            let _ = admission_sender.send(Err(message));
            Err(err)
        }
    }
}

#[cfg(not(any(test, feature = "test-support")))]
fn drive_supervisor_replacement_background(
    work: SupervisorReplacementWork,
    admission_sender: std::sync::mpsc::SyncSender<Result<(), String>>,
) -> Result<()> {
    let initial_pid = agent_doc_supervisor_io::process::supervisor_pid_for_doc(&work.file);
    let initial_host_stale = host_supervisor_stale_warning_for_doc(&work.file).is_some();
    let socket = agent_doc_supervisor_io::ipc::socket_path(&work.project_root, &work.session_id);
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_background_started mode={} force={} session={} pane={} generation={} receipt_id={} initial_pid={} initial_host_stale={} socket={}",
            work.mode,
            work.force,
            work.session_id,
            work.pane_id,
            work.generation,
            work.operator_receipt_id,
            initial_pid
                .map(|pid| pid.to_string())
                .unwrap_or_else(|| "none".to_string()),
            initial_host_stale,
            socket.display()
        ),
    );

    let ipc_status = request_supervisor_replacement_ipc(&work, &socket);
    let ipc_outcome = match ipc_status {
        SupervisorReplacementIpcStatus::Accepted => SupervisorReplacementIpcOutcome::Accepted,
        SupervisorReplacementIpcStatus::Dead => SupervisorReplacementIpcOutcome::Dead,
        SupervisorReplacementIpcStatus::Failed => SupervisorReplacementIpcOutcome::Failed,
        SupervisorReplacementIpcStatus::ResponseTimedOut => {
            SupervisorReplacementIpcOutcome::ResponseTimedOut
        }
    };
    let defer_admission_until_cold_start = match decide_supervisor_replacement_escalation(
        SupervisorReplacementEscalationFacts {
            ipc_outcome,
            force: work.force,
            initial_host_stale,
        },
    ) {
        SupervisorReplacementEscalation::AwaitAcceptedInPlace => {
            // The live supervisor owns the accepted request. A stale binary
            // deliberately waits for the active turn to drain before execve;
            // the foreground proof timeout is observation only, never authority
            // to kill that supervisor or its live harness child.
            let _ = admission_sender.send(Ok(()));
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_background_completed stage=ipc_accepted_deferred mode={} session={} pane={} generation={} receipt_id={} initial_host_stale={} reason=live_supervisor_owns_drain",
                    work.mode,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id,
                    initial_host_stale
                ),
            );
            return Ok(());
        }
        SupervisorReplacementEscalation::WaitThenEscalate => {
            let _ = admission_sender.send(Ok(()));
            if wait_for_supervisor_replacement_completion(
                &work.file,
                initial_pid,
                initial_host_stale,
            ) {
                agent_doc_ops_log_io::log_op(
                    &work.file,
                    &format!(
                        "controller_supervisor_replacement_background_completed stage=ipc_reexec mode={} session={} pane={} generation={} receipt_id={} initial_host_stale={}",
                        work.mode,
                        work.session_id,
                        work.pane_id,
                        work.generation,
                        work.operator_receipt_id,
                        initial_host_stale
                    ),
                );
                return Ok(());
            }
            false
        }
        // No live supervisor accepted this request. Keep the foreground receipt
        // pending until the replacement has passed editor-authoritative
        // validation and its start command has actually been submitted.
        SupervisorReplacementEscalation::EscalateColdStart => true,
        SupervisorReplacementEscalation::FailClosed => {
            let message = format!(
                "live supervisor rejected the replacement request for {} and no force/stale-host evidence authorizes a destructive cold start",
                work.file.display()
            );
            let _ = admission_sender.send(Err(message.clone()));
            anyhow::bail!(message);
        }
    };

    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_background_escalating mode={} force={} session={} pane={} generation={} receipt_id={} ipc_status={ipc_status:?} initial_host_stale={}",
            work.mode,
            work.force,
            work.session_id,
            work.pane_id,
            work.generation,
            work.operator_receipt_id,
            initial_host_stale
        ),
    );
    // `#replacementintent`: record the CONTINUE intent before anything can
    // stop the supervisor. The kill below is honoured by the supervisor at its
    // own boundary, possibly after this worker (or its whole controller
    // process) is gone; without this marker that supervisor recorded its exit
    // as an operator stop and nothing ever restarted the document
    // (2026-10-20 `agent-doc-bugs.md`: the predecessor controller exited
    // mid-replacement and the pane was left at a bare shell).
    mark_replacement_cold_start_pending(
        &work,
        agent_doc_supervisor_io::selfkill::supervisor_pid_for_doc(&work.file),
        "pre_kill",
    );
    // `#replacementwithdraw`: a stale-binary continue replacement is satisfied
    // by the supervisor's own install re-exec (same pid, child preserved).
    // When that lands while the kill request is pending, withdraw the request
    // rather than kill a now-fresh supervisor and its live harness child
    // (2026-10-20: the re-exec landed 3 s after this escalation, and the
    // supervisor then honoured the stale request and killed its Claude child).
    let replacement_intent = SupervisorReplacementIntent::parse(&work.mode)?;
    let kill_outcome = agent_doc_supervisor_io::selfkill::drive_supervisor_kill_unless(
        &work.file,
        agent_doc_supervisor_io::selfkill::selfkill_grace(),
        false,
        || {
            agent_doc_controller::supervisor_replacement::replacement_goal_satisfied_by_refresh(
                replacement_intent,
                initial_host_stale,
                host_supervisor_stale_warning_for_doc(&work.file).is_some(),
            )
        },
    )?;
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_kill_outcome mode={} session={} pane={} generation={} receipt_id={} outcome={kill_outcome:?}",
            work.mode, work.session_id, work.pane_id, work.generation, work.operator_receipt_id
        ),
    );
    if let agent_doc_supervisor_io::selfkill::SupervisorKillOutcome::Withdrawn(pid) = kill_outcome {
        // The pre-kill replacement marker stays: it names this live pid, it is
        // consulted only once that pid is dead, and it expires with the
        // cold-start grace. Keeping it covers a supervisor that had already
        // committed to the self-kill when the request was withdrawn.
        if defer_admission_until_cold_start {
            let _ = admission_sender.send(Ok(()));
        }
        agent_doc_ops_log_io::log_op(
            &work.file,
            &format!(
                "controller_supervisor_replacement_background_completed stage=refreshed_in_place mode={} session={} pane={} generation={} receipt_id={} supervisor_pid={pid} (#replacementwithdraw)",
                work.mode, work.session_id, work.pane_id, work.generation, work.operator_receipt_id
            ),
        );
        return Ok(());
    }
    reap_dead_supervisor_socket(&work.file, &socket);
    // `#gh133sigterm` + `#runfrontendcrashed`: the kill above was controller
    // intent to CONTINUE this document, not operator intent to stop it — but
    // the cold start below is typed into the pane's shell and needs seconds to
    // register its lease. Clearing the marker outright let the crash watchdog
    // read this kill as a crash one tick later and issue a SECOND replacement
    // that force-killed the booting successor (bare shell). Hold the watchdog
    // off with a time-bounded cold-start marker instead; a failed cold start
    // clears it so the watchdog can recover immediately.
    let killed_pid = match kill_outcome {
        agent_doc_supervisor_io::selfkill::SupervisorKillOutcome::Graceful(pid)
        | agent_doc_supervisor_io::selfkill::SupervisorKillOutcome::Forced(pid) => Some(pid),
        _ => None,
    };
    mark_replacement_cold_start_pending(&work, killed_pid, "post_kill");
    let cold_start_result = cold_start_supervisor_replacement(&work);
    if cold_start_result.is_err() {
        clear_replacement_intentional_exit(&work);
    }
    let pane = if defer_admission_until_cold_start {
        complete_deferred_supervisor_replacement_admission(&admission_sender, cold_start_result)?
    } else {
        cold_start_result?
    };
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_background_completed stage=cold_start mode={} session={} pane={} generation={} receipt_id={} replacement_pane={}",
            work.mode,
            work.session_id,
            work.pane_id,
            work.generation,
            work.operator_receipt_id,
            pane
        ),
    );
    Ok(())
}

/// `#runfrontendcrashed`: replace the stopped supervisor's exit marker with a
/// time-bounded cold-start marker so the crash watchdog leaves the successor's
/// cold start alone. See
/// [`agent_doc_supervisor::intentional_exit::REPLACEMENT_COLD_START_SIGNAL`].
#[cfg_attr(all(feature = "test-support", not(test)), allow(dead_code))]
fn mark_replacement_cold_start_pending(
    work: &SupervisorReplacementWork,
    killed_pid: Option<u32>,
    stage: &str,
) {
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &work.project_root,
        &work.file.to_string_lossy(),
    );
    let outcome = agent_doc_supervisor_io::intentional_exit::mark_replacement_cold_start_pending(
        &work.project_root,
        &document_id,
        killed_pid,
        work.generation,
        &work.pane_id,
        &work.session_id,
    );
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_cold_start_marker stage={stage} session={} generation={} receipt_id={} outcome={}",
            work.session_id,
            work.generation,
            work.operator_receipt_id,
            match &outcome {
                Ok(Some(marker)) => format!(
                    "pending pid={} grace_ms={}",
                    marker.supervisor_pid,
                    agent_doc_supervisor::intentional_exit::REPLACEMENT_COLD_START_GRACE_MS
                ),
                Ok(None) => "cleared_no_pid".to_string(),
                Err(err) => format!("failed error={err}"),
            }
        ),
    );
}

/// `#gh133sigterm`: clear the intentional-exit marker left by the supervisor a
/// controller replacement just stopped. Best effort: a failure only means the
/// watchdog keeps honouring a pid that is already dead and replaced.
#[cfg_attr(all(feature = "test-support", not(test)), allow(dead_code))]
fn clear_replacement_intentional_exit(work: &SupervisorReplacementWork) {
    let document_id = agent_doc_session_actor_io::canonical_document_id_in(
        &work.project_root,
        &work.file.to_string_lossy(),
    );
    let outcome = agent_doc_supervisor_io::intentional_exit::clear_intentional_exit(
        &work.project_root,
        &document_id,
    );
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_intentional_exit_cleared session={} generation={} receipt_id={} outcome={}",
            work.session_id,
            work.generation,
            work.operator_receipt_id,
            match &outcome {
                Ok(true) => "cleared".to_string(),
                Ok(false) => "absent".to_string(),
                Err(err) => format!("failed error={err}"),
            }
        ),
    );
}

#[cfg(not(any(test, feature = "test-support")))]
fn request_supervisor_replacement_ipc(
    work: &SupervisorReplacementWork,
    socket: &Path,
) -> SupervisorReplacementIpcStatus {
    if matches!(
        agent_doc_supervisor_io::ipc::probe_socket(socket),
        agent_doc_supervisor_io::ipc::SocketLiveness::Dead
    ) {
        agent_doc_ops_log_io::log_op(
            &work.file,
            &format!(
                "controller_supervisor_replacement_ipc_dead session={} pane={} generation={} receipt_id={} socket={}",
                work.session_id,
                work.pane_id,
                work.generation,
                work.operator_receipt_id,
                socket.display()
            ),
        );
        return SupervisorReplacementIpcStatus::Dead;
    }
    match agent_doc_supervisor_io::ipc::send_command(
        socket,
        &agent_doc_supervisor::ipc_protocol::IpcMethod::Restart {
            mode: work.mode.clone(),
        },
    ) {
        Ok(response) if response.ok => {
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_ipc_accepted mode={} session={} pane={} generation={} receipt_id={} socket={}",
                    work.mode,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id,
                    socket.display()
                ),
            );
            SupervisorReplacementIpcStatus::Accepted
        }
        Ok(response) => {
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_ipc_failed mode={} session={} pane={} generation={} receipt_id={} error={}",
                    work.mode,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id,
                    response
                        .error
                        .unwrap_or_else(|| "supervisor restart request failed".to_string())
                ),
            );
            SupervisorReplacementIpcStatus::Failed
        }
        Err(err) => {
            let status = supervisor_replacement_ipc_error_status(
                matches!(
                    agent_doc_supervisor_io::ipc::probe_socket(socket),
                    agent_doc_supervisor_io::ipc::SocketLiveness::Dead
                ),
                agent_doc_supervisor_io::ipc::supervisor_command_failure_kind(&err),
            );
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_ipc_error mode={} session={} pane={} generation={} receipt_id={} status={status:?} error={err:?}",
                    work.mode,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id
                ),
            );
            status
        }
    }
}

#[cfg(not(any(test, feature = "test-support")))]
fn wait_for_supervisor_replacement_completion(
    file: &Path,
    initial_pid: Option<u32>,
    initial_host_stale: bool,
) -> bool {
    let deadline = Instant::now() + supervisor_replacement_wait_timeout();
    while Instant::now() < deadline {
        let current_pid = agent_doc_supervisor_io::process::supervisor_pid_for_doc(file);
        if let (Some(initial), Some(current)) = (initial_pid, current_pid)
            && initial != current
        {
            return true;
        }
        if initial_pid.is_some() && current_pid.is_none() {
            return true;
        }
        if initial_host_stale && host_supervisor_stale_warning_for_doc(file).is_none() {
            return true;
        }
        std::thread::sleep(SUPERVISOR_REPLACEMENT_POLL_INTERVAL);
    }
    false
}

#[cfg(not(any(test, feature = "test-support")))]
fn supervisor_replacement_wait_timeout() -> Duration {
    let secs = std::env::var(SUPERVISOR_REPLACEMENT_WAIT_SECS_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(DEFAULT_SUPERVISOR_REPLACEMENT_WAIT_SECS);
    Duration::from_secs(secs)
}

#[cfg(not(any(test, feature = "test-support")))]
fn reap_dead_supervisor_socket(file: &Path, socket: &Path) {
    if !matches!(
        agent_doc_supervisor_io::ipc::probe_socket(socket),
        agent_doc_supervisor_io::ipc::SocketLiveness::Dead
    ) || !socket.exists()
    {
        return;
    }
    match std::fs::remove_file(socket) {
        Ok(()) => agent_doc_ops_log_io::log_op(
            file,
            &format!(
                "controller_supervisor_replacement_reaped_stale_socket socket={}",
                socket.display()
            ),
        ),
        Err(err) => agent_doc_ops_log_io::log_op(
            file,
            &format!(
                "controller_supervisor_replacement_reap_stale_socket_failed socket={} error={err}",
                socket.display()
            ),
        ),
    }
}

/// Quit a live harness pane back to its shell so a supervisor can relaunch it.
///
/// Returns `false` if the pane never becomes a bare shell, so the caller can fail
/// closed instead of typing a shell command into a live agent.
#[cfg(not(any(test, feature = "test-support")))]
fn quit_live_harness_pane_to_shell(
    tmux: &tmux_router::Tmux,
    pane_id: &str,
    harness_binary: &str,
) -> bool {
    // `#restartbusyquit`: a mid-turn harness ignores `C-d`, so interrupt first.
    // Detected from the live capture rather than assumed, because interrupting an
    // IDLE composer is not always harmless (Codex `C-g`, stray `C-c`).
    let busy = agent_doc_tmux_io::capture_pane_with_ansi(tmux, pane_id)
        .or_else(|_| agent_doc_tmux_io::capture_pane(tmux, pane_id))
        .ok()
        .is_some_and(|captured| {
            agent_doc_harness::HarnessConfig::from_agent_name(harness_binary)
                .dispatch_blocker_reason(&captured)
                .is_some()
        });
    let plan = agent_doc_harness::operator_quit_key_plan_for_state(harness_binary, busy);
    for (index, key) in plan.iter().enumerate() {
        if index > 0 {
            std::thread::sleep(std::time::Duration::from_millis(150));
        }
        if tmux.send_keys_raw(pane_id, key).is_err() {
            return false;
        }
    }
    // Harness shutdown is not instant (flushing state, writing the session log),
    // so poll rather than sleeping one guessed interval.
    for _ in 0..40 {
        std::thread::sleep(std::time::Duration::from_millis(250));
        if !tmux.pane_alive(pane_id) {
            // The pane closed outright; the caller's cold-start path handles this.
            return false;
        }
        if agent_doc_tmux_io::target_current_command(tmux, pane_id)
            .as_deref()
            .map(str::trim)
            .is_some_and(agent_doc_tmux::pane_current_command_is_bare_shell)
        {
            return true;
        }
    }
    false
}

#[cfg(not(any(test, feature = "test-support")))]
fn cold_start_supervisor_replacement(work: &SupervisorReplacementWork) -> Result<String> {
    let tmux = agent_doc_tmux_io::configured_tmux();
    let intent = SupervisorReplacementIntent::parse(&work.mode)?;
    let mode = intent.mode;
    // The editor/controller model is the document authority. Cold recovery must
    // not select a harness or conversation from a stale disk replica.
    let current_document = match current_text_via_controller_model_read_for_doc(
        &work.file,
        "controller_supervisor_replacement_current_document",
    )
    .with_context(|| {
        format!(
            "failed to resolve editor-authoritative document state for supervisor replacement of {}",
            work.file.display()
        )
    })? {
        Some(agent_doc_crdt_relay_io::CurrentText::Current { text, .. }) => text,
        Some(agent_doc_crdt_relay_io::CurrentText::Detached) => {
            std::fs::read_to_string(&work.file).with_context(|| {
                format!(
                    "failed to read detached document state for supervisor replacement of {}",
                    work.file.display()
                )
            })?
        }
        Some(agent_doc_crdt_relay_io::CurrentText::EditorAttachedMissingReplica) => {
            anyhow::bail!(
                "editor authority for {} has no registered replica; refusing supervisor replacement",
                work.file.display()
            )
        }
        Some(agent_doc_crdt_relay_io::CurrentText::EditorSyncPending) => {
            anyhow::bail!(
                "editor authority for {} is still converging; refusing supervisor replacement",
                work.file.display()
            )
        }
        None => anyhow::bail!(
            "controller model is unavailable for {}; refusing supervisor replacement",
            work.file.display()
        ),
    };
    let (current_frontmatter, _) = agent_doc_frontmatter::frontmatter::parse(&current_document)?;
    let document_harness = agent_doc_harness::document_harness_from_content(&current_document)
        .map(|name| agent_doc_harness::HarnessConfig::from_agent_name(&name).binary)
        .unwrap_or_else(|| agent_doc_harness::HarnessConfig::claude().binary);
    // Continue mode means this document's exact conversation for the selected
    // harness, never another harness's id, a global latest selector, or a silent
    // fresh fallback.
    let resume = match mode {
        SupervisorReplacementMode::Fresh => None,
        SupervisorReplacementMode::Continue => current_frontmatter
            .resume_for_harness(&document_harness)
            .map(|id| agent_doc_harness::ResumeRequest::Id(id.to_string())),
    };
    if !work.pane_id.trim().is_empty() {
        let pane_alive = tmux.pane_alive(&work.pane_id);
        let current_command = if pane_alive {
            agent_doc_tmux_io::target_current_command(&tmux, &work.pane_id)
        } else {
            None
        };
        let initial_pane_decision = supervisor_replacement_pane_start_decision(
            intent,
            pane_alive,
            current_command.as_deref(),
            Some(document_harness.as_str()),
            process_tree_exactly_owns_document(&tmux, &work.pane_id, &work.file),
        );
        if initial_pane_decision == SupervisorReplacementPaneDecision::PreserveLiveHarness {
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_live_harness_preserved mode={} session={} pane={} generation={} receipt_id={} harness={} action=fail_closed_without_new_session",
                    work.mode,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id,
                    document_harness,
                ),
            );
            anyhow::bail!(
                "supervisor recovery for {} found its live {document_harness} session in pane {}; continue mode preserved and reattached that session instead of terminating it or starting another conversation. Retry supervisor replacement after the harness returns to a shell.",
                work.file.display(),
                work.pane_id
            );
        }
        if initial_pane_decision == SupervisorReplacementPaneDecision::RestartLiveHarness {
            // Quit the document's own harness so the pane falls back to its
            // shell, then take the normal preserve-existing start path below.
            // Bounded and fail-closed: if the pane does not become a shell we
            // refuse exactly as before rather than typing into a live agent.
            agent_doc_ops_log_io::log_op(
                &work.file,
                &format!(
                    "controller_supervisor_replacement_quitting_live_harness harness={} session={} pane={} generation={} receipt_id={}",
                    document_harness,
                    work.session_id,
                    work.pane_id,
                    work.generation,
                    work.operator_receipt_id,
                ),
            );
            if !quit_live_harness_pane_to_shell(&tmux, &work.pane_id, &document_harness) {
                agent_doc_ops_log_io::log_op(
                    &work.file,
                    &format!(
                        "controller_supervisor_replacement_preserve_pane_blocked mode={} session={} pane={} generation={} receipt_id={} reason=live_harness_quit_timeout harness={} (a mid-turn harness that ignores the quit keys reports here; see #restartbusyquit)",
                        work.mode,
                        work.session_id,
                        work.pane_id,
                        work.generation,
                        work.operator_receipt_id,
                        document_harness,
                    ),
                );
                anyhow::bail!(
                    "the {document_harness} session in pane {} did not exit to a shell, so the replacement supervisor was not started; quit it manually and retry",
                    work.pane_id
                );
            }
        }
        match supervisor_replacement_pane_start_decision(
            intent,
            pane_alive,
            // Re-read: the quit above may have turned this into a bare shell.
            agent_doc_tmux_io::target_current_command(&tmux, &work.pane_id).as_deref(),
            Some(document_harness.as_str()),
            process_tree_exactly_owns_document(&tmux, &work.pane_id, &work.file),
        ) {
            SupervisorReplacementPaneDecision::PreserveExistingShell => {
                if mode == SupervisorReplacementMode::Continue && resume.is_none() {
                    anyhow::bail!(
                        "cannot cold-start supervisor recovery for {} in continue mode: the editor-authoritative document records no exact `resume:` conversation id; the existing pane was preserved and no fresh session was started",
                        work.file.display()
                    );
                }
                let agent_doc_bin = agent_doc_supervisor_process::agent_doc_start_bin();
                let start_cmd =
                    agent_doc_supervisor_process::start_command::route_owned_start_command_with_options(
                        &agent_doc_bin,
                        &work.file,
                        &agent_doc_supervisor_process::start_command::RouteOwnedStartOptions {
                            reap_policy:
                                agent_doc_supervisor::route_owned::RouteOwnedReapPolicy::Auto,
                            start_purpose:
                                agent_doc_supervisor::route_owned::RouteOwnedStartPurpose::Dispatch,
                            resume: resume.clone(),
                        },
                    );
                agent_doc_ops_log_io::log_op(
                    &work.file,
                    &format!(
                        "controller_supervisor_replacement_preserve_pane mode={} resume={} session={} pane={}",
                        work.mode,
                        if resume.is_some() {
                            "continue"
                        } else {
                            "fresh"
                        },
                        work.session_id,
                        work.pane_id,
                    ),
                );
                agent_doc_tmux_io::input_diag::log_text_submit(
                    agent_doc_tmux_io::input_diag::InputDiagSink::new(
                        Some(&work.file),
                        agent_doc_ops_log_io::log_op,
                    ),
                    "controller.supervisor_replacement.cold_start_preserve_pane",
                    &format!("pane:{}", work.pane_id),
                    &start_cmd,
                    None,
                    "route_owned_start_enter",
                    "Enter",
                );
                agent_doc_tmux_io::send_submitted_text_logged(
                    &tmux,
                    &work.pane_id,
                    &start_cmd,
                    agent_doc_tmux_io::input_diag::InputDiagSink::new(
                        None,
                        agent_doc_ops_log_io::log_op,
                    ),
                    "sessions.send_submitted_text",
                )
                .with_context(|| {
                    format!(
                        "failed to submit replacement supervisor start command into pane {}",
                        work.pane_id
                    )
                })?;
                return Ok(work.pane_id.clone());
            }
            SupervisorReplacementPaneDecision::BlockLiveNonShell => {
                let current_command = current_command
                    .as_deref()
                    .map(str::trim)
                    .filter(|command| !command.is_empty())
                    .unwrap_or("unknown");
                agent_doc_ops_log_io::log_op(
                    &work.file,
                    &format!(
                        "controller_supervisor_replacement_preserve_pane_blocked mode={} session={} pane={} generation={} receipt_id={} reason=live_non_shell_pane current_command={}",
                        work.mode,
                        work.session_id,
                        work.pane_id,
                        work.generation,
                        work.operator_receipt_id,
                        current_command
                    ),
                );
                // Do NOT advertise `--force` here: this decision takes no force
                // flag (`--force` only affects the earlier IPC-escalation choice),
                // so suggesting it sends the operator in a circle. `#restartlivepane`
                // already auto-restarts a pane running the document's OWN harness;
                // reaching this arm means the pane is running something else, and
                // the honest advice is to free it or point the document elsewhere.
                anyhow::bail!(
                    "refusing to start a replacement supervisor in pane {}: it is running `{current_command}`, which is not {}'s harness. Quit that program (or claim the document to another pane with `agent-doc claim {}`) and retry.",
                    work.pane_id,
                    work.file.display(),
                    work.file.display()
                );
            }
            SupervisorReplacementPaneDecision::RestartLiveHarness => {
                // The quit above reported the pane back at a shell, so re-reading
                // it must not still show the harness. If it does, something else
                // reclaimed the pane between the two reads — fail closed rather
                // than quitting twice or typing into whatever is now running.
                anyhow::bail!(
                    "pane {} is still running {document_harness} after it reported exiting; refusing to start a replacement supervisor into it",
                    work.pane_id
                );
            }
            SupervisorReplacementPaneDecision::PreserveLiveHarness => {
                anyhow::bail!(
                    "supervisor recovery for {} still observes its live {document_harness} session in pane {}; preserving it without starting another conversation",
                    work.file.display(),
                    work.pane_id
                );
            }
            SupervisorReplacementPaneDecision::AutoStartNew => {}
        }
    }
    if mode == SupervisorReplacementMode::Continue && resume.is_none() {
        anyhow::bail!(
            "cannot cold-start supervisor recovery for {} in continue mode: the editor-authoritative document records no exact `resume:` conversation id; no fresh session was started",
            work.file.display()
        );
    }
    let file_str = work.file.to_string_lossy().to_string();
    // `#restartresume`: `restart-supervisor` defaults to continue-mode (`--fresh`
    // is the opt-out), but when there is no live supervisor to restart we escalate
    // to a COLD START — and a cold start with no resume intent silently downgrades
    // that promise to a brand-new conversation. That is the worst possible moment
    // to discard context: the supervisor is already dead, so the operator is
    // recovering, not starting over. Carry the mode into the cold start.
    agent_doc_ops_log_io::log_op(
        &work.file,
        &format!(
            "controller_supervisor_replacement_cold_start mode={} resume={} session={} pane={}",
            work.mode,
            if resume.is_some() {
                "continue"
            } else {
                "fresh"
            },
            work.session_id,
            work.pane_id,
        ),
    );
    runtime_effects()?
        .route_auto_start(ControllerRouteAutoStartInvocation {
            tmux: &tmux,
            file: &work.file,
            session_id: &work.session_id,
            file_arg: &file_str,
            window: None,
            policy: ControllerRouteAutoStartPolicy::WaitForReady,
            defer_focus_to_layout: false,
            missing_pane: None,
            resume,
        })
        .with_context(|| {
            format!(
                "failed to cold-start replacement supervisor for {}",
                work.file.display()
            )
        })
}

pub(crate) fn handle_admin_operation(
    bootstrap: &ControllerBootstrap,
    request: ControllerRequest,
) -> Result<ControllerAdminReceipt> {
    let operation_kind = request_string(&request.command_kind, "command_kind")?;
    let status = request.state.as_deref().unwrap_or("accepted");
    let document_id = request.file.as_ref().map(|file| {
        agent_doc_session_actor_io::canonical_document_id_in(
            &bootstrap.project_root,
            &file.to_string_lossy(),
        )
    });
    insert_admin_operation_record(
        &bootstrap.project_root,
        &operation_kind,
        document_id.as_deref(),
        status,
        request.diagnostic_payload.as_deref(),
    )
}

pub fn run_status(root: Option<&Path>, ensure: bool) -> Result<()> {
    let project_root = agent_doc_project_root_io::project_root_from_arg(root)?;
    if ensure {
        ensure_controller_running(&project_root, LaunchMode::Lazy)?;
    }
    println!("{}", serde_json::to_string_pretty(&status(&project_root)?)?);
    Ok(())
}

pub fn run_serve(
    root: Option<&Path>,
    launch_mode: &str,
    listen_socket: Option<&Path>,
    controller_generation: Option<u64>,
    previous_controller_pid: Option<u32>,
    handoff_state: &str,
) -> Result<()> {
    let project_root = agent_doc_project_root_io::project_root_from_arg(root)?;
    // `#statedbfdclobber`: close only descriptors `main` proved it inherited.
    // Listing the live fd table here closed this process's own debug-log
    // descriptor, and SQLite's next open reused the number under the appender.
    let inherited = crate::inherited_fds::close_process_entry_fds();
    if inherited.snapshot_missing {
        agent_doc_ops_log_io::log_op(
            &project_root,
            "controller_serve_inherited_fds_snapshot_missing closed=0",
        );
    } else if inherited.closed > 0 || inherited.skipped_not_inherited > 0 {
        agent_doc_ops_log_io::log_op(
            &project_root,
            &format!(
                "controller_serve_inherited_fds_closed count={} skipped_not_inherited={}",
                inherited.closed, inherited.skipped_not_inherited
            ),
        );
    }
    serve_with_options(
        &project_root,
        LaunchMode::parse(launch_mode)?,
        listen_socket.map(Path::to_path_buf),
        controller_generation,
        previous_controller_pid,
        status::parse_handoff_state(handoff_state)?,
        None,
    )
}

pub fn run_launch_detached(
    root: Option<&Path>,
    launch_mode: &str,
    listen_socket: Option<&Path>,
    controller_generation: Option<u64>,
    previous_controller_pid: Option<u32>,
    handoff_state: &str,
) -> Result<()> {
    let project_root = agent_doc_project_root_io::project_root_from_arg(root)?;
    let launch = launch_detached_at(
        &project_root,
        LaunchMode::parse(launch_mode)?,
        listen_socket,
        controller_generation,
        previous_controller_pid,
        status::parse_handoff_state(handoff_state)?,
    )?;
    println!("controller_pid={}", launch.pid);
    Ok(())
}

pub fn run_shutdown(root: Option<&Path>) -> Result<()> {
    let project_root = agent_doc_project_root_io::project_root_from_arg(root)?;
    println!(
        "{}",
        request_with_reason(&project_root, "shutdown", "operator_shutdown")?
    );
    Ok(())
}

/// Outcome of a controller restart (`#cpcrestart`).
#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize)]
pub struct ControllerRestartOutcome {
    /// Controller PIDs verified same-project and reaped (SIGTERM → SIGKILL).
    pub reaped_pids: Vec<u32>,
    /// Whether a bounded graceful `shutdown` RPC was accepted before the reap.
    pub graceful: bool,
    /// Whether the caller forced the signal reap without the graceful RPC.
    pub force: bool,
}

/// `#cpcrestart` — restart/recycle the current project controller out-of-band.
///
/// The CP is the live state authority; a restart is only for cold-start recovery
/// (recycle onto a new binary, or recover from a bug that wedged it). Because a
/// spin-wedged controller stops servicing RPCs (`shutdown` times out), the reap
/// signals the controller PID(s) directly (SIGTERM → 750ms → SIGKILL, via
/// [`reap_verified_controller_pid`], which is guarded by
/// [`is_same_project_controller_pid`] so it never touches this process or another
/// project's controller). Route-owned documents are observed through their
/// keyed controller projection first; no CRDT sidecar is written. With
/// `--launch-mode lazy` the next request relaunches a fresh controller, so no
/// explicit relaunch is issued here.
///
/// `force == false` first attempts a bounded graceful `shutdown` RPC (clean exit
/// when the controller is healthy); `force == true` skips straight to the signal
/// reap — the correct path for a spin-wedged / RPC-unreachable controller.
pub fn force_restart_controller(
    project_root: &Path,
    force: bool,
) -> Result<ControllerRestartOutcome> {
    // Best-effort observation for diagnostics. Never block restart on an
    // unavailable reactive projection.
    if let Err(err) =
        checkpoint_route_owned_documents_for_project(project_root, "controller_restart_request")
    {
        eprintln!("[controller] restart: projection observation warning: {err:#}");
    }

    let mut graceful = false;
    if !force {
        // A healthy controller exits cleanly here; a wedged one times out and we
        // fall through to the signal reap below (bounded inside `request`).
        graceful = request_with_reason(project_root, "shutdown", "controller_restart").is_ok();
    }

    let self_pid = std::process::id();
    let mut reaped = Vec::new();
    // Kill-everything: a restart leaves no process serving this root, fork
    // images included (#controllerforkimage).
    for pid in crate::process::project_controller_pids_including_fork_images(project_root) {
        if pid == self_pid {
            continue;
        }
        reap_verified_controller_pid(project_root, pid, 0);
        if !process_is_alive(pid) {
            reaped.push(pid);
        }
    }
    reaped.sort_unstable();
    reaped.dedup();

    agent_doc_ops_log_io::log_op(
        project_root,
        &format!(
            "controller_restart_requested project_root={} force={} graceful={} reaped={:?} (#cpcrestart)",
            project_root.display(),
            force,
            graceful,
            reaped,
        ),
    );

    Ok(ControllerRestartOutcome {
        reaped_pids: reaped,
        graceful,
        force,
    })
}

pub fn run_restart(root: Option<&Path>, force: bool) -> Result<()> {
    let project_root = agent_doc_project_root_io::project_root_from_arg(root)?;
    let outcome = force_restart_controller(&project_root, force)?;
    println!("{}", serde_json::to_string_pretty(&outcome)?);
    if outcome.reaped_pids.is_empty() && !outcome.graceful {
        println!(
            "[controller] no live project controller to restart; a lazy launcher starts a fresh one on the next request"
        );
    } else {
        println!(
            "[controller] restarted: reaped {} controller pid(s); a fresh controller launches on the next request",
            outcome.reaped_pids.len()
        );
    }
    Ok(())
}

