    fn intentional_exit_fixture() -> (tempfile::TempDir, PathBuf, String) {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("doc.md");
        std::fs::write(&file, "# doc\n").unwrap();
        let document_id = agent_doc_session_actor_io::canonical_document_id_in(
            dir.path(),
            &file.to_string_lossy(),
        );
        (dir, file, document_id)
    }

    fn sigterm_identity(
        root: &Path,
        document_id: &str,
        pid: u32,
    ) -> agent_doc_supervisor_io::intentional_exit::IntentionalExitIdentity {
        agent_doc_supervisor_io::intentional_exit::IntentionalExitIdentity {
            project_root: root.to_path_buf(),
            document_id: document_id.to_string(),
            supervisor_pid: pid,
            generation: 5,
            pane_id: "%3".to_string(),
            session_id: "session".to_string(),
        }
    }

    /// `#gh133sigterm`: a supervisor whose SIGTERM handler recorded a marker for
    /// exactly this dead pid + generation is NOT respawned by the watchdog,
    /// while a crash (no marker) still is.
    #[test]
    fn supervisor_watchdog_honours_deliberate_sigterm_but_restarts_a_crash() {
        let (dir, _file, document_id) = intentional_exit_fixture();
        let conn = state_store::open_state_db(dir.path()).unwrap();

        let crash = supervisor_watchdog_intentional_exit_decision(&conn, &document_id, 4242, 5);
        assert!(
            crash.allows_restart(),
            "crash without a marker must respawn"
        );

        agent_doc_supervisor_io::intentional_exit::record_intentional_exit(
            &sigterm_identity(dir.path(), &document_id, 4242),
            "SIGTERM",
        )
        .unwrap();
        let deliberate =
            supervisor_watchdog_intentional_exit_decision(&conn, &document_id, 4242, 5);
        assert_eq!(
            deliberate,
            agent_doc_supervisor::intentional_exit::IntentionalExitDecision::Intentional
        );
        assert!(
            !deliberate.allows_restart(),
            "deliberate SIGTERM must not respawn"
        );

        // The marker is pid-scoped: a later generation's crash still respawns.
        let later = supervisor_watchdog_intentional_exit_decision(&conn, &document_id, 5151, 6);
        assert!(later.allows_restart());
    }

    /// `#gh133sigterm`: the controller replacement path SIGTERMs the old
    /// supervisor and then cold-starts the new one. It clears the marker its own
    /// kill produced, so replacement is never mistaken for operator intent.
    #[test]
    fn controller_replacement_clears_intentional_exit_before_cold_start() {
        let (dir, file, document_id) = intentional_exit_fixture();
        agent_doc_supervisor_io::intentional_exit::record_intentional_exit(
            &sigterm_identity(dir.path(), &document_id, 4242),
            "SIGTERM",
        )
        .unwrap();
        let work = SupervisorReplacementWork {
            project_root: dir.path().to_path_buf(),
            file,
            session_id: "session".to_string(),
            pane_id: "%3".to_string(),
            generation: 5,
            mode: "continue".to_string(),
            force: true,
            operator_receipt_id: 1,
        };
        clear_replacement_intentional_exit(&work);
        let conn = state_store::open_state_db(dir.path()).unwrap();
        assert!(
            supervisor_watchdog_intentional_exit_decision(&conn, &document_id, 4242, 5)
                .allows_restart(),
            "a controller replacement is not operator intent"
        );
    }

    /// `#runfrontendcrashed` regression (2026-10-10, haiven-dev frontend.md):
    /// replacement receipt 3275 force-killed stale supervisor 1989646 and typed
    /// the cold start into pane %166; one second later the watchdog saw the
    /// lease still naming 1989646 with its marker CLEARED, called it a crash,
    /// and its own replacement (receipt 3277) force-killed the booting
    /// successor 3708335, leaving a bare shell. The replacement path must keep
    /// the watchdog off the replaced pid while the cold start is in flight, and
    /// a failed cold start must still be recoverable.
    #[test]
    fn controller_replacement_cold_start_keeps_watchdog_off_the_replaced_pid() {
        let (dir, file, document_id) = intentional_exit_fixture();
        agent_doc_supervisor_io::intentional_exit::record_intentional_exit(
            &sigterm_identity(dir.path(), &document_id, 4242),
            "SIGTERM",
        )
        .unwrap();
        let work = SupervisorReplacementWork {
            project_root: dir.path().to_path_buf(),
            file,
            session_id: "session".to_string(),
            pane_id: "%3".to_string(),
            generation: 5,
            mode: "continue".to_string(),
            force: true,
            operator_receipt_id: 1,
        };
        mark_replacement_cold_start_pending(&work, Some(4242), "post_kill");
        let conn = state_store::open_state_db(dir.path()).unwrap();
        let marker = agent_doc_supervisor_io::intentional_exit::load_intentional_exit_from_db(
            &conn,
            &document_id,
        )
        .unwrap()
        .expect("cold-start marker recorded");
        let tick = supervisor_watchdog_intentional_exit_decision_at(
            &conn,
            &document_id,
            4242,
            5,
            marker.recorded_at_ms + 1_000,
        );
        assert_eq!(
            tick,
            agent_doc_supervisor::intentional_exit::IntentionalExitDecision::ReplacementColdStartPending
        );
        assert!(
            !tick.allows_restart(),
            "the watchdog must not replace (and kill) a successor that is still booting"
        );
        let expired = supervisor_watchdog_intentional_exit_decision_at(
            &conn,
            &document_id,
            4242,
            5,
            marker.recorded_at_ms
                + agent_doc_supervisor::intentional_exit::REPLACEMENT_COLD_START_GRACE_MS,
        );
        assert!(
            expired.allows_restart(),
            "a cold start that never registered is recovered after the grace"
        );

        // A cold start that failed synchronously clears the marker: immediate recovery.
        clear_replacement_intentional_exit(&work);
        assert!(
            supervisor_watchdog_intentional_exit_decision(&conn, &document_id, 4242, 5)
                .allows_restart()
        );
    }

    /// `#replacementintent` regression (2026-10-20 `agent-doc-bugs.md`, pane %2):
    /// replacement receipt 2172 escalated against stale supervisor 2909057 and
    /// requested its self-kill; controller 1504840 then self-recycled
    /// (`live_plugin_update`) and its worker thread died before
    /// `controller_supervisor_replacement_kill_outcome`. The supervisor honoured
    /// the kill (`supervisor_intentional_exit signal=self_kill_request`), so the
    /// watchdog read an operator stop, no cold start ever ran, and the operator
    /// found a bare shell. The marker written BEFORE the kill must survive the
    /// supervisor's own record and leave the death recoverable even though no
    /// post-kill step ever runs.
    #[test]
    fn replacement_whose_controller_dies_after_the_kill_request_stays_recoverable() {
        let (dir, file, document_id) = intentional_exit_fixture();
        let work = SupervisorReplacementWork {
            project_root: dir.path().to_path_buf(),
            file,
            session_id: "session".to_string(),
            pane_id: "%3".to_string(),
            generation: 5,
            mode: "continue".to_string(),
            force: true,
            operator_receipt_id: 2172,
        };
        // The worker marks the supervisor it is about to stop...
        mark_replacement_cold_start_pending(&work, Some(4242), "pre_kill");
        let conn = state_store::open_state_db(dir.path()).unwrap();
        let pre_kill = agent_doc_supervisor_io::intentional_exit::load_intentional_exit_from_db(
            &conn,
            &document_id,
        )
        .unwrap()
        .expect("pre-kill marker recorded");
        // ...its process exits, and the supervisor then honours the self-kill.
        let recorded = agent_doc_supervisor_io::intentional_exit::record_intentional_exit_at(
            &sigterm_identity(dir.path(), &document_id, 4242),
            "self_kill_request",
            pre_kill.recorded_at_ms + 9_000,
        )
        .unwrap();
        assert_eq!(
            recorded,
            agent_doc_supervisor::intentional_exit::IntentionalExitRecordDecision::PreserveReplacementIntent
        );
        let tick = supervisor_watchdog_intentional_exit_decision_at(
            &conn,
            &document_id,
            4242,
            5,
            pre_kill.recorded_at_ms + 10_000,
        );
        assert_ne!(
            tick,
            agent_doc_supervisor::intentional_exit::IntentionalExitDecision::Intentional,
            "a replacement's own kill must never read as an operator stop"
        );
        let expired = supervisor_watchdog_intentional_exit_decision_at(
            &conn,
            &document_id,
            4242,
            5,
            pre_kill.recorded_at_ms
                + agent_doc_supervisor::intentional_exit::REPLACEMENT_COLD_START_GRACE_MS,
        );
        assert!(
            expired.allows_restart(),
            "an orphaned replacement is recovered as a crash once its grace ends"
        );
    }

