    /// A project root long enough that `<root>/.agent-doc/controller.sock`
    /// overflows `sun_path`.
    fn over_sun_path_root() -> PathBuf {
        PathBuf::from(format!(
            "/{}",
            "d".repeat(agent_doc_controller::paths::SUN_PATH_MAX)
        ))
    }

    /// `#ctrlsockpathtoolong`: the wait loop used to poll a path that can never
    /// bind until its whole budget elapsed — which is how a fresh EMPTY document
    /// burned a full 90s preflight admission budget. The budget is the thing
    /// under test: this must fail in a small fraction of the timeout it is given.
    #[test]
    fn waiting_on_an_over_sun_path_socket_fails_before_the_timeout() {
        let sock = socket_path(&over_sun_path_root());
        let timeout = Duration::from_secs(30);

        let start = Instant::now();
        let err = wait_for_controller_path_with_timeout(&sock, timeout)
            .expect_err("a socket path over sun_path can never be connected");
        let elapsed = start.elapsed();

        assert!(
            elapsed < timeout / 2,
            "expected an immediate refusal, waited {elapsed:?} of a {timeout:?} budget"
        );
        let message = format!("{err:#}");
        assert!(message.contains("sun_path"), "{message}");
        assert!(
            !message.contains("timed out"),
            "the refusal must name the real cause, not a timeout: {message}"
        );
    }

    #[test]
    fn handoff_wait_fails_as_soon_as_the_replacement_exit_is_observed() {
        let dir = tempfile::tempdir().unwrap();
        let sock = dir.path().join(".agent-doc/controller-handoff.sock");
        std::fs::create_dir_all(sock.parent().unwrap()).unwrap();
        let status = Command::new("false").status().unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(Ok(status)).unwrap();
        let launch = DetachedControllerLaunch {
            pid: 424_242,
            exit: Some(rx),
        };

        let started = Instant::now();
        let err = wait_for_controller_path_with_launch(
            &sock,
            Duration::from_secs(30),
            &launch,
            "replacement",
        )
        .expect_err("an exited replacement can never report ready");

        assert!(started.elapsed() < Duration::from_secs(30) / 2);
        let message = format!("{err:#}");
        assert!(message.contains("pid 424242 exited"), "{message}");
        assert!(message.contains("exit status"), "{message}");
        assert!(message.contains("controller-stderr.log"), "{message}");
    }

    /// Launch exit masked as a timeout (the load flake of
    /// `run_queue_maintenance_strikes_free_text_head_tracked_by_backlog_item`,
    /// 2026-10-15): a cold-launched controller exited at startup on a corrupt
    /// `state.db`, and the client polled the bare socket path for the whole
    /// launch budget, then reported "timed out waiting for project controller".
    /// The launched child's exit must end the wait with its stderr.
    #[test]
    fn launch_wait_reports_the_launched_controllers_exit_and_stderr_tail() {
        let dir = tempfile::tempdir().unwrap();
        let sock = socket_path(dir.path());
        let logs = sock.parent().unwrap().join("logs");
        std::fs::create_dir_all(&logs).unwrap();
        std::fs::write(
            logs.join("controller-stderr.log"),
            "Error: authoritative state db is unavailable; refusing automatic replacement\n\n    0: state db is corrupt\n",
        )
        .unwrap();
        let status = Command::new("false").status().unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(Ok(status)).unwrap();
        let launch = DetachedControllerLaunch {
            pid: 424_243,
            exit: Some(rx),
        };

        let budget = Duration::from_secs(30);
        let started = Instant::now();
        let err = wait_for_controller_path_with_launch(&sock, budget, &launch, "launched")
            .expect_err("an exited launch can never report ready");

        assert!(started.elapsed() < budget / 2, "the exit must end the wait");
        let message = format!("{err:#}");
        assert!(
            message.contains("launched controller pid 424243 exited"),
            "{message}"
        );
        assert!(!message.contains("timed out"), "{message}");
        assert!(message.contains("state db is corrupt"), "{message}");
    }

    /// A launch that lost the race exits once a peer owns the socket; the
    /// wait adopts that peer instead of reporting the exit.
    #[test]
    fn launch_wait_adopts_a_peer_published_after_the_child_exited() {
        let dir = tempfile::tempdir().unwrap();
        let sock = socket_path(dir.path());
        std::fs::create_dir_all(sock.parent().unwrap()).unwrap();
        let name = sock.clone().to_fs_name::<GenericFilePath>().unwrap();
        let _listener = ListenerOptions::new().name(name).create_sync().unwrap();
        let status = Command::new("true").status().unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(Ok(status)).unwrap();
        let launch = DetachedControllerLaunch {
            pid: 424_244,
            exit: Some(rx),
        };

        wait_for_controller_path_with_launch(&sock, Duration::from_secs(30), &launch, "launched")
            .expect("the published peer is adopted");
    }

    /// A single connect must name the cause too: a bare OS error here is what
    /// made callers treat a permanent condition as "not started yet".
    #[test]
    fn connecting_to_an_over_sun_path_socket_names_the_limit() {
        let err = connect_path(&socket_path(&over_sun_path_root()))
            .expect_err("a socket path over sun_path can never be connected");

        let message = format!("{err:#}");
        assert!(message.contains("sun_path"), "{message}");
        assert!(
            message.contains("retrying cannot help"),
            "the refusal must say the condition is permanent: {message}"
        );
    }

    /// The guard must not fire on ordinary roots — a false positive here would
    /// refuse every controller connect in the product.
    #[test]
    fn an_ordinary_project_root_still_connects_normally() {
        let tmp = tempfile::TempDir::new().unwrap();
        let sock = socket_path(tmp.path());

        let err = connect_path(&sock).expect_err("nothing is listening in a fresh temp dir");

        let message = format!("{err:#}");
        assert!(
            !message.contains("sun_path"),
            "an ordinary root must fail as an ordinary connect failure: {message}"
        );
    }

