    /// `#focusstashescalate`: only a refusal that means "the pane exists, it is
    /// just not in the `agent-doc` window" is repairable by republishing a
    /// layout. Escalating a missing actor/session/pane would ask the layout
    /// owner to conjure something it cannot.
    #[test]
    fn only_placement_focus_refusals_escalate_to_the_structural_layout_owner() {
        for reason in ["actor_pane_not_visible", "outside_agent_doc_window"] {
            assert!(
                focus_refusal_requires_structural_layout(reason),
                "{reason} is a placement refusal the layout owner repairs"
            );
        }
        for reason in [
            "missing_actor_record",
            "missing_tmux_session",
            "resumed_pane_not_alive",
            "desktop_editor_inactive",
            "layout_owner_provisioned",
            "focused",
        ] {
            assert!(
                !focus_refusal_requires_structural_layout(reason),
                "{reason} must not republish a layout"
            );
        }
    }

    /// `#surfacefocussilent`: the ingress receipt (`#surfaceobservesilent`)
    /// proved the selection arrived and was accepted, but the *consequence* was
    /// silent — a refused focus and an applied focus left byte-identical
    /// ops.log. Assert the focus lane now names its own verdict, for an applied
    /// selection, a refusal, and an error alike.
    #[test]
    fn editor_surface_focus_outcome_always_leaves_an_ops_log_receipt() {
        let dir = tempfile::tempdir().unwrap();
        // ops.log is anchored to a real project root; without it `log_op` is a
        // no-op and the assertion below would pass for the wrong reason.
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let mut receipt = SurfaceObservationReceipt {
            intent: SurfaceIntent::Focus {
                document: "/project/payments-ledger.md".to_string(),
            },
            idle: false,
            outcome: None,
            error: None,
            terminal_decision: Default::default(),
            deferred_to: None,
            rejected: None,
            reregister_above_generation: None,
        };

        record_editor_surface_focus_outcome(
            dir.path(),
            &mut receipt,
            Ok(tmux_focus_receipt(
                false,
                "actor_pane_not_visible",
                Some("payments-ledger".to_string()),
                Some("%188".to_string()),
                Some("agent-doc".to_string()),
                Some("@5".to_string()),
                Some("stash".to_string()),
            )),
        )
        .unwrap();
        record_editor_surface_focus_outcome(
            dir.path(),
            &mut receipt,
            Err(anyhow::anyhow!("tmux socket closed")),
        )
        .unwrap();

        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        let receipts = ops_log
            .lines()
            .filter(|line| line.contains("controller_editor_surface_focus_outcome"))
            .collect::<Vec<_>>();
        assert_eq!(
            receipts.len(),
            2,
            "every focus consequence must leave one receipt: {ops_log}"
        );
        assert!(
            receipts[0].contains("focused=false")
                && receipts[0].contains("reason=actor_pane_not_visible")
                && receipts[0].contains("pane=%188"),
            "a refusal must name its reason and pane: {receipts:?}"
        );
        assert!(
            receipts[1].contains("reason=focus_error")
                && receipts[1].contains("tmux socket closed"),
            "an error must be distinguishable from a refusal: {receipts:?}"
        );
    }

    /// `#focusstashescalate`: the escalation is the whole fix, so it must leave
    /// proof that it ran — and with no editor columns AND no retained
    /// structural layout to fall back on there is nothing to republish, which
    /// `publish_pane_layout_desired_invocation` rejects anyway.
    #[test]
    fn focus_escalation_records_its_handoff_and_skips_when_no_layout_is_known() {
        let dir = tempfile::tempdir().unwrap();
        let bootstrap = ControllerBootstrap {
            project_root: dir.path().to_path_buf(),
            socket_path: socket_path(dir.path()),
            launch_mode: LaunchMode::Lazy,
            bootstrap_epoch: 0,
            pid: std::process::id(),
            controller_binary: Some(current_binary_identity().unwrap()),
            controller_generation: 1,
            handoff_state: ControllerHandoffState::Stable,
            handoff_started_at: None,
            previous_controller_pid: None,
        };
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let path = |name: &str| {
            let path = dir.path().join(name);
            std::fs::write(&path, "---\nagent_doc_session: s\n---\n# s\n").unwrap();
            path.canonicalize().unwrap().display().to_string()
        };
        let ledger = path("payments-ledger.md");
        let infra = path("infra.md");

        let deferred = escalate_focus_to_structural_layout_disposition(
            &bootstrap,
            runtime.as_ref(),
            &ledger,
            &[],
            agent_doc_editor_surface::SurfaceColumnOrder::Editor,
            "actor_pane_not_visible",
        );
        assert_eq!(
            deferred,
            FocusEscalationDisposition::Deferred("no_frontend_layout_snapshot")
        );
        assert!(!deferred.effect_failed());
        assert_eq!(
            deferred.receipt_reason().as_deref(),
            Some("focus_deferred:no_frontend_layout_snapshot")
        );
        let mut deferred_focus = Ok(tmux_focus_receipt(
            false,
            "actor_pane_not_visible",
            Some(ledger.clone()),
            Some("%60".to_string()),
            Some("project".to_string()),
            Some("@1".to_string()),
            Some("stash".to_string()),
        ));
        assert!(!deferred.apply_to(&mut deferred_focus));
        assert_eq!(
            deferred_focus.unwrap().reason,
            "focus_deferred:no_frontend_layout_snapshot"
        );

        let published = escalate_focus_to_structural_layout_disposition(
            &bootstrap,
            runtime.as_ref(),
            &ledger,
            &[
                SurfaceColumn {
                    files: vec![ledger.clone()],
                },
                SurfaceColumn {
                    files: vec![infra],
                },
            ],
            agent_doc_editor_surface::SurfaceColumnOrder::Editor,
            "actor_pane_not_visible",
        );
        assert_eq!(published, FocusEscalationDisposition::Published);
        assert!(!published.effect_failed());
        assert_eq!(
            published.receipt_reason().as_deref(),
            Some("focus_escalated_to_structural_layout")
        );

        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops_log.contains(&format!(
                "controller_editor_surface_focus_escalation_skipped \
                 document={ledger} reason=actor_pane_not_visible \
                 cause=no_frontend_layout_snapshot"
            )),
            "an empty editor layout must be refused, not republished: {ops_log}"
        );
        assert!(
            ops_log.contains(&format!(
                "controller_editor_surface_focus_escalated document={ledger} \
                 reason=actor_pane_not_visible columns=2"
            )),
            "the handoff to the structural layout owner must be provable: {ops_log}"
        );
    }

    /// `#idleclearrestart`: recording a deferred operator clear publishes the
    /// document-scoped wake a Ready, quiescent supervisor idle watch parks on;
    /// each re-arm publishes again with the new clear epoch.
    #[test]
    fn deferred_operator_clear_publishes_one_wake_per_deferral() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let file = dir.path().join("doc.md");
        std::fs::write(&file, "---\nagent_doc_session: s\n---\n# s\n").unwrap();
        let file = file.canonicalize().unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&file);
        let channel = operator_clear_wake_channel(&document_hash);
        let defer = || {
            handle_queue_context_clear_deferred(
                &bootstrap,
                runtime.as_ref(),
                ControllerRequest {
                    command: "queue_context_clear_deferred".to_string(),
                    file: Some(file.clone()),
                    session_id: None,
                    pane_id: Some("%1".to_string()),
                    window_id: None,
                    generation: None,
                    state: None,
                    caller: Some("test".to_string()),
                    reason: Some("operator_live_turn_deferred_clear".to_string()),
                    supervisor_pid: None,
                    supervisor_socket: None,
                    command_kind: Some("claude-code".to_string()),
                    diagnostic_payload: Some(
                        serde_json::to_string(&QueueContextClearPayload {
                            command: "/clear".to_string(),
                            head_sha256: None,
                            head_bytes: None,
                            retired_reason: None,
                        })
                        .unwrap(),
                    ),
                    sequence: None,
                },
            )
            .unwrap()
        };
        let wake_epoch = |frames: &[ControllerStatePlaneFrame]| {
            frames.iter().rev().find_map(|frame| {
                let message =
                    serde_json::from_str::<lazily::IpcMessage>(&frame.message_json).ok()?;
                let payload =
                    state_plane_snapshot_payload(&message, &channel, OPERATOR_CLEAR_WAKE_TYPE_TAG)
                        .ok()?;
                serde_json::from_slice::<OperatorClearWakeProjection>(&payload)
                    .ok()
                    .filter(|wake| wake.document_hash == document_hash)
                    .map(|wake| wake.clear_epoch)
            })
        };

        let first = defer();
        let cold = runtime.subscribe_state_plane(&channel, None, 0, Duration::ZERO);
        assert_eq!(wake_epoch(&cold.frames), Some(first.clear_epoch));

        let quiet = runtime.subscribe_state_plane(
            &channel,
            Some(cold.controller_generation),
            cold.latest_version,
            Duration::ZERO,
        );
        assert!(quiet.frames.is_empty(), "no deferral, no wake");

        let rearmed = defer();
        assert!(rearmed.clear_epoch > first.clear_epoch);
        let warm = runtime.subscribe_state_plane(
            &channel,
            Some(cold.controller_generation),
            cold.latest_version,
            Duration::ZERO,
        );
        assert_eq!(wake_epoch(&warm.frames), Some(rearmed.clear_epoch));
    }

    #[test]
    fn gh166_fresh_controller_focus_only_switch_defers_without_frontend_layout() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let path = |name: &str| {
            let path = dir.path().join(name);
            std::fs::write(&path, "---\nagent_doc_session: s\n---\n# s\n").unwrap();
            path.canonicalize().unwrap().display().to_string()
        };
        let first = path("first.md");
        let second = path("second.md");
        let stashed = path("stashed.md");
        assert!(
            runtime.pane_layout_desired().is_none(),
            "the promoted controller must start without retained desired layout"
        );

        TEST_LIVE_LAYOUT_DOCUMENTS
            .with(|documents| *documents.borrow_mut() = Some(vec![first.clone(), second.clone()]));
        let escalated = escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &stashed,
            &[],
            "actor_pane_not_visible",
        );
        TEST_LIVE_LAYOUT_DOCUMENTS.with(|documents| *documents.borrow_mut() = None);

        assert!(
            !escalated,
            "tmux observation is a receipt, not editor authority"
        );
        assert!(runtime.pane_layout_desired().is_none());
        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops_log.contains("controller_editor_surface_focus_escalation_skipped"),
            "focus must defer until a frontend layout snapshot arrives: {ops_log}"
        );
    }

    /// `#focusstashedactor`: the regression `#focusstashescalate` shipped with.
    ///
    /// A plain tab switch publishes `buildFocusProjection`, which carries
    /// `columns: []` by design, and that `focus_only` shape is the *only* one
    /// that derives `SurfaceIntent::Focus` for a selection. Reading the
    /// observation's own columns therefore skipped the escalation every time it
    /// mattered — 47 `cause=no_editor_columns` lines and zero escalations on
    /// agent-loop, with the pane still stashed. The retained structural layout
    /// is the fallback when it already covers the document (GH #106: it is
    /// republished unchanged, never grown).
    #[test]
    fn a_focus_only_switch_escalates_from_the_retained_structural_layout() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        // The layout owner resolves desired columns against real documents, so
        // the escalation only retains anything if these exist.
        let path = |name: &str| {
            let path = dir.path().join(name);
            std::fs::write(&path, "---\nagent_doc_session: s\n---\n# s\n").unwrap();
            path.canonicalize().unwrap().display().to_string()
        };
        let ledger = path("payments-ledger.md");
        let infra = path("infra.md");

        // A layout-changing switch converges a structural layout first; that is
        // the state a later focus-only switch escalates against.
        escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &ledger,
            &[
                SurfaceColumn {
                    files: vec![ledger.clone()],
                },
                SurfaceColumn {
                    files: vec![infra.clone()],
                },
            ],
            "actor_pane_not_visible",
        );
        assert!(
            runtime.pane_layout_desired().is_some(),
            "the editor-surface escalation must retain a structural layout"
        );

        // The tab switch itself: focus-only, so no columns at all.
        escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &infra,
            &[],
            "actor_pane_not_visible",
        );
        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            !ops_log.contains("controller_editor_surface_focus_escalation_skipped"),
            "a focus-only switch must not be refused for carrying no columns: {ops_log}"
        );
        assert!(
            !ops_log.contains("controller_editor_surface_focus_escalation_failed"),
            "the republished layout must be one the layout owner accepts: {ops_log}"
        );
        assert!(
            ops_log.contains(&format!(
                "controller_editor_surface_focus_escalated document={infra} \
                 reason=actor_pane_not_visible columns=2 source=cached_frontend_layout"
            )),
            "the retained layout must be republished as-is when it covers the document: {ops_log}"
        );

        let desired = runtime.pane_layout_desired().unwrap();
        assert_eq!(
            desired.invocation.focus.as_deref(),
            Some(infra.as_str()),
            "the escalation's whole point is moving the focus onto the switched-to document"
        );
        assert!(
            desired.invocation.columns.contains(&infra),
            "the focused document must be visible in the layout it is focused in: {desired:?}"
        );
    }

    /// A synthetic legacy unknown-order publication used to exercise generic
    /// controller provenance rules. Flat Remote Dev backend evidence no longer creates columns.
    fn plugin_unknown_order_publication(
        columns: &[&str],
        focus: &str,
    ) -> ControllerTmuxLayoutSyncInvocation {
        ControllerTmuxLayoutSyncInvocation {
            columns: columns.iter().map(|column| column.to_string()).collect(),
            window: None,
            focus: Some(focus.to_string()),
            no_autostart: false,
            exact_visible: true,
            caller_kind: "automatic".to_string(),
            column_order: agent_doc_tmux::LayoutColumnOrder::Unknown,
            actor_bindings: Vec::new(),
            client_id: None,
        }
    }

    fn manual_unknown_order_publication(
        columns: &[&str],
        focus: &str,
    ) -> ControllerTmuxLayoutSyncInvocation {
        let mut invocation = plugin_unknown_order_publication(columns, focus);
        invocation.caller_kind = "manual".to_string();
        invocation
    }

    fn session_document(dir: &tempfile::TempDir, name: &str) -> String {
        let path = dir.path().join(name);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, "---\nagent_doc_session: s\n---\n# s\n").unwrap();
        path.canonicalize().unwrap().display().to_string()
    }

    /// GH #112/#332: consecutive converged two-column projections for the same two
    /// documents alternated their column order, placing the focused document
    /// first, because the publisher's order was focus-first and nothing
    /// upstream of the order-preserving stages questioned it. An `unknown`
    /// order must preserve the last positive editor vector, so focus toggles
    /// move focus only. Cold unknown input is covered by
    /// `manual_unknown_order_preserves_structure_until_frontend_snapshot`.
    #[test]
    fn unknown_order_publications_keep_the_retained_column_order_across_focus_toggles() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let ad = session_document(&dir, "tasks/agent-doc/agent-doc.ad.md");
        let mr = session_document(&dir, "tasks/pmt2/mr/1102.md");

        let mut initial = plugin_unknown_order_publication(&[&ad, &mr], &ad);
        initial.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            initial,
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();

        for focus in [&ad, &mr, &ad, &mr] {
            let other = if focus == &ad { &mr } else { &ad };
            let (desired, _) = publish_pane_layout_desired_invocation(
                &bootstrap,
                runtime.as_ref(),
                plugin_unknown_order_publication(&[focus, other], focus),
                None,
                PaneLayoutPublication::FreshIntent,
                PaneLayoutPublisher::PluginPublication,
            )
            .unwrap();
            assert_eq!(
                desired.invocation.columns,
                vec![ad.clone(), mr.clone()],
                "focus on {focus} must not reorder the retained columns"
            );
            assert_eq!(desired.invocation.focus.as_deref(), Some(focus.as_str()));
        }
        assert_eq!(
            runtime
                .pane_layout_desired()
                .unwrap()
                .invocation
                .column_order,
            agent_doc_tmux::LayoutColumnOrder::Editor
        );
        assert_eq!(
            pane_layout_order_authority(runtime.as_ref()),
            vec![ad.clone(), mr.clone()],
        );
        assert_eq!(
            load_layout_state(&bootstrap.project_root).unwrap_or_default(),
            vec![ad.clone(), mr.clone()],
            "the durable column memory must hold the resolved order, not the incoming one"
        );

        let mut measured = plugin_unknown_order_publication(&[&mr, &ad], &mr);
        measured.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        let (measured, _) = publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            measured,
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();
        assert_eq!(
            measured.invocation.column_order,
            agent_doc_tmux::LayoutColumnOrder::Editor
        );
        assert_eq!(pane_layout_order_authority(runtime.as_ref()), vec![mr, ad]);
    }

    /// GH #343: connected frontend columns are the effect target. A manual Sync Tmux Layout uses
    /// that authoritative snapshot to recover from conflicting retained backend state without
    /// reordering or reconstructing the vector.
    #[test]
    fn manual_sync_frontend_snapshot_replaces_stale_backend_target_unchanged() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let a = session_document(&dir, "a.md");
        let b = session_document(&dir, "b.md");
        let c = session_document(&dir, "c.md");

        let mut stale = plugin_unknown_order_publication(&[&a, &b], &a);
        stale.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            stale,
            Some(1),
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();

        // Wider and deliberately reversed relative to the stale backend target:
        // neither retained order nor width memory may fold this positive vector.
        let mut frontend = plugin_unknown_order_publication(&[&c, &b, &a], &c);
        frontend.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        frontend.caller_kind = "manual".to_string();
        let (desired, published) = publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            frontend,
            Some(2),
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::Command,
        )
        .unwrap();
        assert_eq!(published.columns, vec![c.clone(), b.clone(), a.clone()]);
        assert_eq!(
            desired.invocation.columns,
            vec![c.clone(), b.clone(), a.clone()]
        );
        assert_eq!(
            desired.invocation.column_order,
            agent_doc_tmux::LayoutColumnOrder::Editor
        );
        assert_eq!(pane_layout_order_authority(runtime.as_ref()), vec![c, b, a]);
    }

    /// GH #343: a manual click with unknown order is not structural evidence. It preserves the
    /// retained vector; recovery requires the connected frontend's positive column snapshot.
    #[test]
    fn manual_unknown_order_preserves_structure_until_frontend_snapshot() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let a = session_document(&dir, "a.md");
        let b = session_document(&dir, "b.md");

        let cold_error = publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            plugin_unknown_order_publication(&[&b, &a], &b),
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap_err();
        assert!(
            cold_error
                .to_string()
                .contains("incomplete frontend layout"),
            "cold unknown structure must defer, got {cold_error:#}",
        );

        let mut measured = plugin_unknown_order_publication(&[&b, &a], &b);
        measured.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            measured,
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();
        assert_eq!(
            pane_layout_order_authority(runtime.as_ref()),
            vec![b.clone(), a.clone()],
        );

        let (manual, _) = publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            manual_unknown_order_publication(&[&a, &b], &a),
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::Command,
        )
        .unwrap();
        assert_eq!(manual.invocation.columns, vec![b.clone(), a.clone()]);
        assert_eq!(
            manual.invocation.column_order,
            agent_doc_tmux::LayoutColumnOrder::Editor,
        );
        assert_eq!(
            pane_layout_order_authority(runtime.as_ref()),
            vec![b.clone(), a.clone()],
        );

        let (automatic, _) = publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            plugin_unknown_order_publication(&[&a, &b], &a),
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();
        assert_eq!(
            automatic.invocation.columns,
            vec![b.clone(), a.clone()],
            "manual unknown input must not become a new structural basis",
        );
    }

    /// GH #112: a focus escalation that republishes a `retained`-order layout
    /// keeps that label, so the unchanged layout coalesces rather than minting
    /// a new generation per tab switch.
    #[test]
    fn a_retained_layout_escalation_coalesces_but_outside_window_mints_an_effect() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let ad = session_document(&dir, "ad.md");
        let mr = session_document(&dir, "mr.md");
        let mut authoritative = plugin_unknown_order_publication(&[&ad, &mr], &ad);
        authoritative.column_order = agent_doc_tmux::LayoutColumnOrder::Editor;
        publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            authoritative,
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();
        publish_pane_layout_desired_invocation(
            &bootstrap,
            runtime.as_ref(),
            plugin_unknown_order_publication(&[&mr, &ad], &mr),
            None,
            PaneLayoutPublication::FreshIntent,
            PaneLayoutPublisher::PluginPublication,
        )
        .unwrap();
        escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &ad,
            &[],
            "actor_pane_not_visible",
        );
        let first = runtime.pane_layout_desired().unwrap();
        assert_eq!(first.invocation.columns, vec![ad.clone(), mr.clone()]);
        assert_eq!(
            first.invocation.column_order,
            agent_doc_tmux::LayoutColumnOrder::Editor
        );
        escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &ad,
            &[],
            "actor_pane_not_visible",
        );
        assert_eq!(
            runtime.pane_layout_desired().unwrap().generation,
            first.generation,
            "an identical retained escalation must coalesce"
        );
        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops_log.contains("controller_editor_surface_focus_escalation_coalesced document=")
                && ops_log.contains("reason=actor_pane_not_visible"),
            "coalescing must be observable: {ops_log}"
        );

        escalate_focus_to_structural_layout(
            &bootstrap,
            runtime.as_ref(),
            &ad,
            &[],
            "outside_agent_doc_window",
        );
        assert!(
            runtime.pane_layout_desired().unwrap().generation > first.generation,
            "an identical outside-window escalation must mint a generation so the effect selects the agent-doc window"
        );
    }

