    fn sync_tmux_layout_command_request(
        columns: &[String],
        client_id: Option<&str>,
    ) -> ControllerRequest {
        let mut invocation = super::super::tests::pane_layout_desired_for_test(1).invocation;
        invocation.columns = columns.to_vec();
        invocation.focus = columns.first().cloned();
        invocation.caller_kind = "manual".to_string();
        invocation.no_autostart = false;
        invocation.client_id = client_id.map(str::to_string);
        serde_json::from_value(serde_json::json!({
            "command": "sync_tmux_layout",
            "diagnostic_payload": serde_json::to_string(&invocation).unwrap(),
        }))
        .unwrap()
    }

    /// `#ideriderindependentnav` P6: the lane an explicit `sync_tmux_layout`
    /// command publishes into. Only an installation-scoped client id under
    /// `per_installation` leaves the shared lane.
    #[test]
    fn sync_tmux_layout_command_lane_follows_the_client_id_only_per_installation() {
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        const IDEA: &str = "jetbrains@IU.0a1b2c3d-pid:41";
        for mode in [NavigationMode::Shared, NavigationMode::PerInstallation] {
            assert_eq!(
                sync_tmux_layout_command_lane(mode, None),
                NavigationLane::Shared
            );
            assert_eq!(
                sync_tmux_layout_command_lane(mode, Some("vscode-pid:9")),
                NavigationLane::Shared
            );
        }
        assert_eq!(
            sync_tmux_layout_command_lane(NavigationMode::Shared, Some(IDEA)),
            NavigationLane::Shared
        );
        assert_eq!(
            sync_tmux_layout_command_lane(NavigationMode::PerInstallation, Some(IDEA)),
            NavigationLane::Installation("IU.0a1b2c3d".to_string())
        );
    }

    /// `#ideriderindependentnav` P6: an explicit `sync_tmux_layout` command
    /// naming its client publishes into that client's navigation lane, as the
    /// `Command` publisher, and never touches the shared lane's graph or its
    /// durable column memory. A command without a client id, or from an
    /// unscoped client, is the shared lane. The client id is consumed by the
    /// routing and never retained in a lane's invocation.
    #[test]
    fn sync_tmux_layout_command_publishes_into_the_requesting_clients_lane() {
        use agent_doc_editor_surface::NavigationLane;
        let (dir, bootstrap, runtime) = per_installation_lane_fixture();
        let idea_doc = lane_test_document(&dir, "idea");
        let rider_doc = lane_test_document(&dir, "rider");
        let shared_doc = lane_test_document(&dir, "shared");
        let vscode_doc = lane_test_document(&dir, "vscode");
        let idea = NavigationLane::Installation("IU.0a1b2c3d".to_string());
        let rider = NavigationLane::Installation("RD.9f8e7d6c".to_string());
        let desired = |lane: &NavigationLane| runtime.pane_layout_graph_for_lane(lane).desired();

        let receipt = handle_sync_tmux_layout(
            &bootstrap,
            runtime.as_ref(),
            sync_tmux_layout_command_request(
                std::slice::from_ref(&idea_doc),
                Some("jetbrains@IU.0a1b2c3d-pid:41"),
            ),
        )
        .unwrap();
        assert!(receipt.applied);
        let idea_desired = desired(&idea).expect("the idea lane received the command");
        assert_eq!(receipt.layout_generation, Some(idea_desired.generation));
        assert_eq!(receipt.layout_publisher.as_deref(), Some("command"));
        assert_eq!(idea_desired.invocation.columns, vec![idea_doc.clone()]);
        assert_eq!(
            idea_desired.provenance.publisher,
            PaneLayoutPublisher::Command
        );
        assert_eq!(idea_desired.invocation.client_id, None);
        assert!(desired(&NavigationLane::Shared).is_none());
        assert!(
            load_layout_state(dir.path()).unwrap_or_default().is_empty(),
            "an installation lane never writes the shared durable column memory"
        );

        handle_sync_tmux_layout(
            &bootstrap,
            runtime.as_ref(),
            sync_tmux_layout_command_request(
                std::slice::from_ref(&rider_doc),
                Some("jetbrains@RD.9f8e7d6c-pid:42"),
            ),
        )
        .unwrap();
        assert_eq!(
            desired(&rider).unwrap().invocation.columns,
            vec![rider_doc.clone()]
        );
        assert_eq!(
            desired(&idea).unwrap().generation,
            idea_desired.generation,
            "another lane's command never re-projects this lane"
        );

        handle_sync_tmux_layout(
            &bootstrap,
            runtime.as_ref(),
            sync_tmux_layout_command_request(std::slice::from_ref(&shared_doc), None),
        )
        .unwrap();
        let shared = desired(&NavigationLane::Shared).unwrap();
        assert_eq!(shared.invocation.columns, vec![shared_doc.clone()]);
        assert_eq!(
            load_layout_state(dir.path()).unwrap(),
            vec![shared_doc.clone()]
        );

        handle_sync_tmux_layout(
            &bootstrap,
            runtime.as_ref(),
            sync_tmux_layout_command_request(
                std::slice::from_ref(&vscode_doc),
                Some("vscode-pid:9"),
            ),
        )
        .unwrap();
        let shared = desired(&NavigationLane::Shared).unwrap();
        assert_eq!(shared.invocation.columns, vec![vscode_doc]);
        assert_eq!(shared.invocation.client_id, None);
        assert_eq!(desired(&idea).unwrap().generation, idea_desired.generation);
        assert_eq!(
            runtime.pane_layout_lane_ids(),
            vec![NavigationLane::Shared, idea.clone(), rider.clone()]
        );
        let ops =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops.contains(
                "sync_tmux_layout_lane_routed navigation_lane=IU.0a1b2c3d client_id=jetbrains@IU.0a1b2c3d-pid:41"
            ),
            "{ops}"
        );
        assert_eq!(
            ops.matches("sync_tmux_layout_lane_routed").count(),
            2,
            "only the two installation-lane commands are lane-routed: {ops}"
        );
    }

    /// `#ideriderindependentnav` P6: in `shared` mode a command's client id
    /// changes nothing. Every command reaches the shared lane, no installation
    /// lane is created, and a command without a client id serializes exactly
    /// as before (no `client_id` key on the wire).
    #[test]
    fn shared_mode_sync_tmux_layout_command_is_the_pre_lane_path_for_every_client() {
        use agent_doc_editor_surface::NavigationLane;
        let dir = tempfile::TempDir::new().unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = test_controller_runtime(&bootstrap);
        let alpha = lane_test_document(&dir, "alpha");
        let beta = lane_test_document(&dir, "beta");

        let unnamed = sync_tmux_layout_command_request(std::slice::from_ref(&alpha), None);
        assert!(
            !unnamed
                .diagnostic_payload
                .as_deref()
                .unwrap()
                .contains("client_id"),
            "an invocation without a client id keeps the pre-lane wire shape"
        );
        handle_sync_tmux_layout(&bootstrap, runtime.as_ref(), unnamed).unwrap();
        let first = runtime.pane_layout_desired().unwrap();
        handle_sync_tmux_layout(
            &bootstrap,
            runtime.as_ref(),
            sync_tmux_layout_command_request(
                std::slice::from_ref(&beta),
                Some("jetbrains@IU.0a1b2c3d-pid:41"),
            ),
        )
        .unwrap();
        let second = runtime.pane_layout_desired().unwrap();
        assert!(second.generation > first.generation);
        assert_eq!(second.invocation.columns, vec![beta.clone()]);
        assert_eq!(second.invocation.client_id, None);
        assert_eq!(runtime.pane_layout_lane_ids(), vec![NavigationLane::Shared]);
        assert_eq!(load_layout_state(dir.path()).unwrap(), vec![beta]);
        let ops =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(!ops.contains("sync_tmux_layout_lane_routed"), "{ops}");
    }

    /// `#ideriderindependentnav` P6: a supervisor settle re-applies each
    /// navigation lane's own retained layout, but only in the lanes whose last
    /// pass gated the settled document, each into its own lane. An installation
    /// lane's retained explicit claim is republished passively (so a pane that
    /// moved away is never taken back) with its autostart setting unchanged.
    /// `shared` mode's republish (caller kind kept) is
    /// `gh136d_recycle_settle_republishes_a_gated_layout_exactly_once`.
    #[test]
    fn recycle_settle_republishes_each_navigation_lanes_own_retained_layout() {
        use agent_doc_editor_surface::{LaneClaim, NavigationLane};
        let (dir, bootstrap, runtime) = per_installation_lane_fixture();
        let idea_doc = lane_test_document(&dir, "idea");
        let rider_doc = lane_test_document(&dir, "rider");
        let shared_doc = lane_test_document(&dir, "shared");
        let idea = NavigationLane::Installation("IU.0a1b2c3d".to_string());
        let rider = NavigationLane::Installation("RD.9f8e7d6c".to_string());
        for (lane, columns) in [
            (&idea, vec![idea_doc.clone(), rider_doc.clone()]),
            (&rider, vec![rider_doc.clone()]),
            (&NavigationLane::Shared, vec![shared_doc.clone()]),
        ] {
            let mut invocation = super::super::tests::pane_layout_desired_for_test(1).invocation;
            invocation.focus = columns.first().cloned();
            invocation.columns = columns;
            invocation.caller_kind = "manual".to_string();
            invocation.no_autostart = false;
            let (published, _) = publish_pane_layout_desired_invocation_in_lane(
                &bootstrap,
                &runtime,
                lane,
                invocation,
                None,
                PaneLayoutPublication::FreshIntent,
                PaneLayoutPublisher::Command,
            )
            .unwrap();
            runtime.pane_layout_graph_for_lane(lane).record_gated(
                published.generation,
                published.invocation.columns[..1].to_vec(),
            );
        }
        let desired =
            |lane: &NavigationLane| runtime.pane_layout_graph_for_lane(lane).desired().unwrap();
        let before = [&NavigationLane::Shared, &idea, &rider].map(desired);

        // A document no lane gated republishes nothing anywhere.
        let ungated = lane_test_document(&dir, "ungated");
        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&ungated));
        for (lane, retained) in [&NavigationLane::Shared, &idea, &rider].iter().zip(&before) {
            assert_eq!(desired(lane).generation, retained.generation);
        }

        // IDEA gated its own document: only IDEA's lane republishes.
        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&idea_doc));
        let idea_republished = desired(&idea);
        assert!(idea_republished.generation > before[1].generation);
        assert_eq!(
            idea_republished.provenance.publisher,
            PaneLayoutPublisher::RecycleSettled
        );
        assert_eq!(
            idea_republished.invocation.columns,
            before[1].invocation.columns
        );
        assert_eq!(
            idea_republished.invocation.focus,
            before[1].invocation.focus
        );
        assert_eq!(
            idea_republished.invocation.caller_kind,
            agent_doc_editor_surface::RECYCLE_SETTLED_CALLER_KIND
        );
        assert_eq!(
            LaneClaim::for_caller_kind(&idea_republished.invocation.caller_kind),
            LaneClaim::Passive,
            "a background republish can never hand a pane over from another lane"
        );
        assert!(!idea_republished.invocation.no_autostart);
        assert_eq!(desired(&rider).generation, before[2].generation);
        assert_eq!(
            desired(&NavigationLane::Shared).generation,
            before[0].generation
        );

        // A retried settle is a no-op in every lane.
        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&idea_doc));
        assert_eq!(desired(&idea).generation, idea_republished.generation);

        // Rider's settle republishes Rider's lane only, though IDEA's layout
        // also lists the document (IDEA's last pass did not gate it).
        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&rider_doc));
        assert!(desired(&rider).generation > before[2].generation);
        assert_eq!(desired(&rider).invocation.columns, vec![rider_doc.clone()]);
        assert_eq!(desired(&idea).generation, idea_republished.generation);

        // Lane membership applies to the shared lane too under
        // `per_installation`, so its republish is passive as well.
        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&shared_doc));
        let shared = desired(&NavigationLane::Shared);
        assert!(shared.generation > before[0].generation);
        assert_eq!(
            shared.invocation.caller_kind,
            agent_doc_editor_surface::RECYCLE_SETTLED_CALLER_KIND
        );
        assert_eq!(shared.invocation.columns, vec![shared_doc.clone()]);
        assert_eq!(load_layout_state(dir.path()).unwrap(), vec![shared_doc]);

        let ops =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert_eq!(
            ops.matches("pane_layout_recycle_settled_republished")
                .count(),
            3,
            "{ops}"
        );
        assert!(ops.contains("navigation_lane=IU.0a1b2c3d"), "{ops}");
        assert!(ops.contains("navigation_lane=RD.9f8e7d6c"), "{ops}");
    }

    /// `#ideriderindependentnav` P6: only a retained explicit claim is
    /// rewritten for an installation lane's recycle republish; a passive kind
    /// and every other field are kept.
    #[test]
    fn recycle_settled_lane_invocation_only_demotes_an_explicit_claim() {
        let mut manual = super::super::tests::pane_layout_desired_for_test(1).invocation;
        manual.caller_kind = "manual".to_string();
        manual.no_autostart = false;
        let republished = recycle_settled_lane_invocation(manual.clone());
        assert_eq!(
            republished.caller_kind,
            agent_doc_editor_surface::RECYCLE_SETTLED_CALLER_KIND
        );
        assert_eq!(
            ControllerTmuxLayoutSyncInvocation {
                caller_kind: manual.caller_kind.clone(),
                ..republished
            },
            manual
        );
        for passive in ["automatic", "editor_route", "projection", "lane_handoff"] {
            let mut invocation = manual.clone();
            invocation.caller_kind = passive.to_string();
            assert_eq!(
                recycle_settled_lane_invocation(invocation.clone()),
                invocation
            );
        }
    }

    /// `#ideriderindependentnav` P3: the IDE terminal's lane session for a
    /// client. `shared` mode, an unscoped client, and a missing pin keep the
    /// shared attach target (`None`) and never touch tmux.
    #[test]
    fn navigation_lane_session_for_client_is_none_on_the_shared_lane() {
        let root = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(root.path().join(".agent-doc")).unwrap();
        // A tmux binding that would fail loudly if it were ever invoked.
        let tmux = tmux_router::Tmux::default_server()
            .with_server_socket(Some("agent-doc-test-never-started".to_string()));
        for (config, client) in [
            ("tmux_session = \"proj\"\n", "jetbrains@IU.0a1b2c3d-pid:41"),
            (
                "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
                "vscode-pid:7",
            ),
            (
                "editor_navigation = \"per_installation\"\n",
                "jetbrains@IU.0a1b2c3d-pid:41",
            ),
        ] {
            std::fs::write(root.path().join(".agent-doc/config.toml"), config).unwrap();
            assert_eq!(
                navigation_lane_session_for_client(&tmux, root.path(), client).unwrap(),
                None,
                "{config:?} {client}"
            );
        }
    }

    /// `#ideriderindependentnav` P3: an installation-scoped client's lane
    /// session is provisioned for the IDE terminal exactly as the controller's
    /// first driving layout provisions it, reused afterwards, and a foreign
    /// same-named session is an error. Isolated tmux server only.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_for_client_provisions_the_clients_lane() {
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane-client");
        let root = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(root.path().join(".agent-doc")).unwrap();
        std::fs::write(
            root.path().join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        tmux.new_session("proj", root.path()).unwrap();
        let first =
            navigation_lane_session_for_client(&tmux, root.path(), "jetbrains@IU.0a1b2c3d-pid:41")
                .unwrap()
                .unwrap();
        assert_eq!(
            first,
            NavigationLaneSession {
                installation: "IU.0a1b2c3d".to_string(),
                session: "proj-IU-0a1b2c3d".to_string(),
                provisioned: true,
            }
        );
        let mut windows = tmux.list_window_names("proj-IU-0a1b2c3d");
        windows.sort();
        assert_eq!(windows, vec!["agent-doc", "stash"]);
        // The focus client of the same installation shares the lane.
        let again = navigation_lane_session_for_client(
            &tmux,
            root.path(),
            "jetbrains-focus@IU.0a1b2c3d-pid:41",
        )
        .unwrap()
        .unwrap();
        assert!(!again.provisioned);
        assert_eq!(again.session, first.session);

        tmux.new_session("proj-RD-9f8e7d6c", root.path()).unwrap();
        let foreign =
            navigation_lane_session_for_client(&tmux, root.path(), "jetbrains@RD.9f8e7d6c-pid:42")
                .unwrap_err();
        assert!(
            format!("{foreign:#}").contains("navigation_lane_session_not_owned:proj-RD-9f8e7d6c"),
            "{foreign:#}"
        );
    }

    /// `#ideriderindependentnav` P4: an explicit handoff moves a pane between
    /// lane sessions agent-doc owns, into the requesting lane's `stash`
    /// window, leaving an empty shell in place when it was the last pane of
    /// the old lane's `agent-doc` window. It is idempotent, refuses a pane that
    /// moved since the claim was routed, and never touches a session that only
    /// carries a lane's name (`#bare-foreign-session-guard`). Isolated tmux
    /// server only.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_handoff_moves_panes_only_between_owned_lanes() {
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane-handoff");
        let root = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(root.path().join(".agent-doc")).unwrap();
        std::fs::write(
            root.path().join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        let shared_pane = tmux.new_session("proj", root.path()).unwrap();
        let route = |installation: &str| {
            pane_layout_lane_route(
                root.path(),
                NavigationMode::PerInstallation,
                &NavigationLane::Installation(installation.to_string()),
                &tmux,
            )
            .unwrap()
        };
        let idea = route("IU.0a1b2c3d");
        let rider = route("RD.9f8e7d6c");
        let (idea_session, rider_session) = (
            idea.sessions.clone().unwrap().1,
            rider.sessions.clone().unwrap().1,
        );
        let rider_window = rider.window.clone().unwrap();
        let window_name = |pane: &str| {
            tmux.raw_cmd(&["display-message", "-p", "-t", pane, "#{window_name}"])
                .unwrap()
                .trim()
                .to_string()
        };
        let hand_over = |pane: &str, from: &str, to: &str| {
            hand_over_navigation_lane_pane(
                &tmux,
                root.path(),
                "proj",
                to,
                &NavigationLaneHandoff {
                    document: "/doc.md".to_string(),
                    pane: pane.to_string(),
                    from_session: from.to_string(),
                },
            )
        };

        // The only pane of Rider's agent-doc window moves to IDEA's stash and
        // leaves an empty shell, so Rider's lane keeps its window.
        let rider_pane = tmux.list_window_panes(&rider_window).unwrap()[0].clone();
        let outcome = hand_over(&rider_pane, &rider_session, &idea_session).unwrap();
        let NavigationLaneHandoffOutcome::Moved {
            placeholder: Some(placeholder),
        } = outcome
        else {
            panic!("expected a placeholder: {outcome:?}");
        };
        assert_eq!(tmux.pane_session(&rider_pane).unwrap(), idea_session);
        assert_eq!(window_name(&rider_pane), "stash");
        assert_eq!(
            tmux.list_window_panes(&rider_window).unwrap(),
            vec![placeholder.clone()],
            "Rider's agent-doc window survives with an empty shell"
        );
        assert_eq!(tmux.pane_session(&placeholder).unwrap(), rider_session);
        // A retried claim is a no-op.
        assert_eq!(
            hand_over(&rider_pane, &rider_session, &idea_session),
            Ok(NavigationLaneHandoffOutcome::AlreadyInLane)
        );
        // A pane that left the claimed session since the claim was routed.
        assert_eq!(
            hand_over(&rider_pane, &rider_session, "proj"),
            Err(format!(
                "navigation_lane_handoff_pane_moved:{rider_pane}:{idea_session}"
            ))
        );

        // The shared session is a lane too: a pane that is not alone in its
        // window moves without a placeholder.
        let shared_doc_pane = tmux.split_window(&shared_pane, root.path(), "-d").unwrap();
        assert_eq!(
            hand_over(&shared_doc_pane, "proj", &rider_session),
            Ok(NavigationLaneHandoffOutcome::Moved { placeholder: None })
        );
        assert_eq!(tmux.pane_session(&shared_doc_pane).unwrap(), rider_session);
        assert!(tmux.pane_alive(&shared_pane));

        // A session that only carries a lane's name was not created by
        // agent-doc: never a source, never a target, and never reshaped.
        let foreign_pane = tmux.new_session("proj-ZZ-00000000", root.path()).unwrap();
        assert_eq!(
            hand_over(&foreign_pane, "proj-ZZ-00000000", &idea_session),
            Err("navigation_lane_handoff_source_not_owned:proj-ZZ-00000000".to_string())
        );
        assert_eq!(
            hand_over(&shared_pane, "proj", "proj-ZZ-00000000"),
            Err("navigation_lane_handoff_target_not_owned:proj-ZZ-00000000".to_string())
        );
        assert_eq!(
            tmux.pane_session(&foreign_pane).unwrap(),
            "proj-ZZ-00000000"
        );
        assert_eq!(tmux.list_window_names("proj-ZZ-00000000").len(), 1);
        assert_eq!(tmux.pane_session(&shared_pane).unwrap(), "proj");
    }

    /// `#ideriderindependentnav` P6: a recycle settle republishes IDEA's and
    /// Rider's retained layouts into their own lanes against a real (isolated)
    /// tmux server. Both retained layouts are explicit claims on a contended
    /// document whose pane Rider's lane holds: republished verbatim, IDEA's
    /// would hand the pane over; republished as `recycle_settled` it routes
    /// with no handoff, IDEA drops the document and targets its own window,
    /// Rider keeps it, and no pane changes session, is duplicated, or is lost.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_recycle_republish_keeps_every_pane_in_its_lane() {
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane-recycle");
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        std::fs::write(
            dir.path().join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        let root = dir.path().canonicalize().unwrap();
        let shared_pane = tmux.new_session("proj", &root).unwrap();
        let idea = NavigationLane::Installation("IU.0a1b2c3d".to_string());
        let rider = NavigationLane::Installation("RD.9f8e7d6c".to_string());
        let route = |lane: &NavigationLane| {
            pane_layout_lane_route(&root, NavigationMode::PerInstallation, lane, &tmux).unwrap()
        };
        let (idea_route, rider_route) = (route(&idea), route(&rider));
        let idea_window = idea_route.window.clone().unwrap();
        let rider_window = rider_route.window.clone().unwrap();
        let idea_pane = tmux.list_window_panes(&idea_window).unwrap()[0].clone();
        let rider_pane = tmux.list_window_panes(&rider_window).unwrap()[0].clone();
        let contended_pane = tmux.split_window(&rider_pane, &root, "-d").unwrap();
        let idea_doc = lane_test_document(&dir, "idea");
        let rider_doc = lane_test_document(&dir, "rider");
        let contended_doc = lane_test_document(&dir, "contended");
        let binding = |document: &str, pane: &str| ControllerTmuxActorBinding {
            document_path: document.to_string(),
            session_id: String::new(),
            pane_id: pane.to_string(),
            generation: 1,
        };
        let bindings = vec![
            binding(&idea_doc, &idea_pane),
            binding(&rider_doc, &rider_pane),
            binding(&contended_doc, &contended_pane),
        ];
        let panes = [&shared_pane, &idea_pane, &rider_pane, &contended_pane];
        let placement = || {
            panes
                .iter()
                .map(|pane| tmux.pane_session(pane).unwrap())
                .collect::<Vec<_>>()
        };
        let before = placement();
        assert_eq!(
            before,
            vec![
                "proj",
                "proj-IU-0a1b2c3d",
                "proj-RD-9f8e7d6c",
                "proj-RD-9f8e7d6c"
            ]
        );

        let bootstrap = test_bootstrap(&dir);
        let runtime = test_controller_runtime(&bootstrap);
        let mut retained = BTreeMap::new();
        for (lane, columns) in [
            (&idea, vec![idea_doc.clone(), contended_doc.clone()]),
            (&rider, vec![rider_doc.clone(), contended_doc.clone()]),
        ] {
            let mut invocation = super::super::tests::pane_layout_desired_for_test(1).invocation;
            invocation.focus = columns.first().cloned();
            invocation.columns = columns;
            invocation.caller_kind = "manual".to_string();
            invocation.no_autostart = false;
            let (published, _) = publish_pane_layout_desired_invocation_in_lane(
                &bootstrap,
                &runtime,
                lane,
                invocation,
                None,
                PaneLayoutPublication::FreshIntent,
                PaneLayoutPublisher::Command,
            )
            .unwrap();
            runtime
                .pane_layout_graph_for_lane(lane)
                .record_gated(published.generation, vec![contended_doc.clone()]);
            retained.insert(lane.clone(), published);
        }
        let route_lane = |route: &PaneLayoutLaneRoute, desired| {
            route_pane_layout_desired_to_lane(&root, route, desired, &bindings, |pane| {
                tmux.pane_session(pane).ok()
            })
        };
        // The retained explicit claim, republished verbatim, would take the pane.
        assert_eq!(
            route_lane(&idea_route, retained[&idea].clone())
                .handoffs
                .iter()
                .map(|handoff| handoff.pane.clone())
                .collect::<Vec<_>>(),
            vec![contended_pane.clone()]
        );

        republish_pane_layout_after_recycle(&bootstrap, &runtime, Path::new(&contended_doc));
        let idea_routed = route_lane(
            &idea_route,
            runtime.pane_layout_graph_for_lane(&idea).desired().unwrap(),
        );
        let rider_routed = route_lane(
            &rider_route,
            runtime
                .pane_layout_graph_for_lane(&rider)
                .desired()
                .unwrap(),
        );
        for (lane, routed) in [(&idea, &idea_routed), (&rider, &rider_routed)] {
            assert!(routed.desired.generation > retained[lane].generation);
            assert_eq!(
                routed.desired.provenance.publisher,
                PaneLayoutPublisher::RecycleSettled
            );
            assert!(routed.handoffs.is_empty(), "{}: {routed:?}", lane.label());
        }
        assert_eq!(
            idea_routed.desired.invocation.columns,
            vec![idea_doc.clone()]
        );
        assert_eq!(
            idea_routed.dropped,
            vec![(contended_doc.clone(), "proj-RD-9f8e7d6c".to_string())]
        );
        assert_eq!(idea_routed.desired.invocation.window, Some(idea_window));
        assert_eq!(
            rider_routed.desired.invocation.columns,
            vec![rider_doc, contended_doc]
        );
        assert!(rider_routed.dropped.is_empty());
        assert_eq!(rider_routed.desired.invocation.window, Some(rider_window));
        assert!(
            runtime
                .pane_layout_graph_for_lane(&NavigationLane::Shared)
                .desired()
                .is_none(),
            "the shared lane held no retained layout and is not republished"
        );
        assert_eq!(placement(), before, "no pane changed session");
        let all_panes = tmux
            .raw_cmd(&["list-panes", "-a", "-F", "#{pane_id}"])
            .unwrap();
        for pane in panes {
            assert_eq!(
                all_panes.lines().filter(|line| line.trim() == pane).count(),
                1,
                "{pane} exists exactly once"
            );
        }
    }

    /// `#ideriderindependentnav` P2b: an installation lane's session is created
    /// on first use with `agent-doc` + `stash` windows and a lane mark, reused
    /// on later passes, and a same-named session agent-doc did not create is
    /// refused rather than adopted. Isolated tmux server only.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_is_provisioned_once_and_never_adopted() {
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane");
        let root = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(root.path().join(".agent-doc")).unwrap();
        std::fs::write(
            root.path().join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        // The operator's shared session, which the lane must never touch.
        tmux.new_session("proj", root.path()).unwrap();
        let shared_windows = tmux.list_window_names("proj");

        let idea = NavigationLane::Installation("IU.0a1b2c3d".to_string());
        let route =
            pane_layout_lane_route(root.path(), NavigationMode::PerInstallation, &idea, &tmux)
                .unwrap();
        assert!(route.provisioned);
        assert_eq!(
            route.sessions,
            Some(("proj".to_string(), "proj-IU-0a1b2c3d".to_string()))
        );
        assert!(tmux.session_alive("proj-IU-0a1b2c3d"));
        let mut windows = tmux.list_window_names("proj-IU-0a1b2c3d");
        windows.sort();
        assert_eq!(windows, vec!["agent-doc", "stash"]);
        assert_eq!(
            route.window,
            resolve_agent_doc_window_id_for_session(&tmux, "proj-IU-0a1b2c3d")
        );
        assert_eq!(
            tmux.list_window_names("proj"),
            shared_windows,
            "provisioning a lane never changes the shared session"
        );

        // Second pass reuses the marked session.
        let again =
            pane_layout_lane_route(root.path(), NavigationMode::PerInstallation, &idea, &tmux)
                .unwrap();
        assert!(!again.provisioned);
        assert_eq!(again.window, route.window);

        // A session with Rider's lane name that agent-doc did not create.
        tmux.new_session("proj-RD-9f8e7d6c", root.path()).unwrap();
        let rider = NavigationLane::Installation("RD.9f8e7d6c".to_string());
        assert_eq!(
            pane_layout_lane_route(root.path(), NavigationMode::PerInstallation, &rider, &tmux),
            Err("navigation_lane_session_not_owned:proj-RD-9f8e7d6c".to_string())
        );
        assert_eq!(
            tmux.list_window_names("proj-RD-9f8e7d6c").len(),
            1,
            "a foreign session is never adopted or reshaped"
        );
    }

    /// `#lanegcflake`: the lane GC's busy rule. An agent-doc placeholder in a
    /// lane no client ever attached to is idle whatever its starting shell is
    /// running (`tmux` before exec, rc children); every other pane is busy
    /// unless it is a bare shell.
    #[test]
    fn navigation_lane_pane_busy_ignores_untouched_placeholder_startup() {
        for command in ["tmux", "grep", "mkdir", "zsh", "-zsh", "bash", "vim", ""] {
            assert!(
                !navigation_lane_pane_busy(true, command),
                "untouched placeholder running {command:?} is idle"
            );
        }
        for command in ["tmux", "grep", "vim", "claude", "sleep"] {
            assert!(
                navigation_lane_pane_busy(false, command),
                "{command:?} in an operator-reachable pane is busy"
            );
        }
        for shell in ["zsh", "-zsh", "bash", "sh", "fish"] {
            assert!(!navigation_lane_pane_busy(false, shell), "{shell} is idle");
        }
    }

    /// `#lanegcflake`: the panes agent-doc creates for a lane carry the
    /// placeholder mark, so a lane whose shells are still starting is closed
    /// deterministically; the mark stops applying once a client has attached,
    /// and a pane agent-doc did not create is never covered by it. The
    /// "startup" is made deterministic by respawning the placeholder into a
    /// long-running command. Isolated tmux server only.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_placeholders_are_idle_until_a_client_attaches() {
        use agent_doc_editor_surface::{LaneReconcileAction, LaneRetainReason};
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane-placeholder");
        let root = tempfile::TempDir::new().unwrap();
        let root = root.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join(".agent-doc")).unwrap();
        std::fs::write(
            root.join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        tmux.new_session("proj", &root).unwrap();
        let lane = |client: &str| {
            navigation_lane_session_for_client(&tmux, &root, client)
                .unwrap()
                .unwrap()
                .session
        };
        let lane_panes = |session: &str| -> Vec<(String, String)> {
            tmux.raw_cmd(&[
                "list-panes",
                "-s",
                "-t",
                &format!("={session}:"),
                "-F",
                &format!("#{{pane_id}}\t#{{{NAVIGATION_LANE_PLACEHOLDER_PANE_OPTION}}}"),
            ])
            .unwrap()
            .lines()
            .map(|line| {
                let (pane, mark) = line.split_once('\t').unwrap_or((line, ""));
                (pane.to_string(), mark.to_string())
            })
            .collect()
        };
        // Stand-in for a shell still running its rc files: a non-shell
        // foreground command that stays put for the whole test.
        let respawn_busy = |pane: &str| {
            tmux.raw_cmd(&["respawn-pane", "-k", "-t", pane, "sleep 600"])
                .unwrap();
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            while tmux
                .raw_cmd(&[
                    "display-message",
                    "-p",
                    "-t",
                    pane,
                    "#{pane_current_command}",
                ])
                .unwrap()
                != "sleep"
            {
                assert!(
                    std::time::Instant::now() < deadline,
                    "{pane} never ran sleep"
                );
                std::thread::yield_now();
            }
        };
        let attached = |session: &str| {
            tmux.raw_cmd(&[
                "display-message",
                "-p",
                "-t",
                &format!("={session}:"),
                "#{session_attached}",
            ])
            .unwrap()
        };
        let root_mark = root.to_string_lossy().to_string();

        // Fresh lane, never attached: both agent-doc shells are marked, and it
        // closes even though its placeholder reads as a running program.
        let idea = lane("jetbrains@IU.0a1b2c3d-pid:41");
        let idea_panes = lane_panes(&idea);
        assert_eq!(idea_panes.len(), 2, "{idea_panes:?}");
        assert!(
            idea_panes.iter().all(|(_, mark)| *mark == root_mark),
            "{idea_panes:?}"
        );
        respawn_busy(&idea_panes[0].0);

        // A lane holding a pane agent-doc did not create: the mark never
        // covers it, attached or not.
        let clion = lane("jetbrains@CL.11223344-pid:43");
        let operator_pane = tmux.new_window(&clion, &root).unwrap();
        respawn_busy(&operator_pane);

        // A lane a client attached to (and left): its placeholder's foreground
        // command decides again.
        let rider = lane("jetbrains@RD.9f8e7d6c-pid:42");
        let rider_placeholder = lane_panes(&rider)[0].0.clone();
        respawn_busy(&rider_placeholder);
        let mut client = std::process::Command::new("tmux")
            .arg("-S")
            .arg(tmux.socket_path())
            .args(["-C", "attach-session", "-t", &format!("={rider}")])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while attached(&rider) != "1" {
            assert!(
                std::time::Instant::now() < deadline,
                "client never attached"
            );
            std::thread::yield_now();
        }
        let _ = client.kill();
        let _ = client.wait();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while attached(&rider) != "0" {
            assert!(
                std::time::Instant::now() < deadline,
                "client never detached"
            );
            std::thread::yield_now();
        }

        let report = reconcile_navigation_lane_sessions(&tmux, &root, &BTreeSet::new(), false);
        assert!(report.failures.is_empty(), "{:?}", report.failures);
        let mut actions = report.actions.clone();
        actions.sort_by_key(|action| format!("{action:?}"));
        let mut expected = vec![
            LaneReconcileAction::Close {
                session: idea.clone(),
            },
            LaneReconcileAction::Retain {
                session: clion.clone(),
                reason: LaneRetainReason::BusyUnownedPane,
            },
            LaneReconcileAction::Retain {
                session: rider.clone(),
                reason: LaneRetainReason::BusyUnownedPane,
            },
        ];
        expected.sort_by_key(|action| format!("{action:?}"));
        assert_eq!(actions, expected);
        assert_eq!(report.closed, vec![idea.clone()]);
        assert!(!tmux.session_alive(&idea));
        assert!(tmux.session_alive(&clion));
        assert!(tmux.session_alive(&rider));
        assert!(tmux.pane_alive(&operator_pane));
        assert!(tmux.pane_alive(&rider_placeholder));
    }

    /// `#ridernavp6gc`: a recording runner for the controller's lane
    /// reconcile trigger.
    fn recording_lane_reconcile_runner() -> (
        NavigationLaneReconcileRunner,
        Arc<Mutex<Vec<agent_doc_editor_surface::LaneReconcileTrigger>>>,
    ) {
        let runs = Arc::new(Mutex::new(Vec::new()));
        let recorded = Arc::clone(&runs);
        let runner: NavigationLaneReconcileRunner = Arc::new(move |_, trigger| {
            recorded.lock().push(trigger.clone());
            NavigationLaneReconcileReport::default()
        });
        (runner, runs)
    }

    fn lane_surface_observation(client_id: &str, sequence: u64) -> EditorSurfaceObservation {
        EditorSurfaceObservation {
            client_id: client_id.to_string(),
            surface_id: "project".to_string(),
            generation: 100,
            sequence,
            surface: agent_doc_editor_surface::EditorSurface {
                column_order: Default::default(),
                focused: "/project/a.md".to_string(),
                open: vec!["/project/a.md".to_string()],
                visible: vec!["/project/a.md".to_string()],
                columns: Vec::new(),
                force_reconcile: false,
                focus_only: true,
                preserve_focus: false,
            },
        }
    }

    #[test]
    fn navigation_lane_reconcile_fires_when_an_installation_retires() {
        use agent_doc_editor_surface::{LaneLiveness, NavigationMode};
        let scope = agent_doc_state_scope::ProcessScope::new();
        let root = Path::new("/project");
        let reconcile =
            NavigationLaneReconcileGraph::new_in(&scope, root, NavigationMode::PerInstallation);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(|_, _| Ok("ok".to_string())))
            .with_navigation_mode(NavigationMode::PerInstallation)
            .with_lane_reconcile(Arc::clone(&reconcile));
        let (runner, runs) = recording_lane_reconcile_runner();
        reconcile.install_worker(runner);
        let idea = "jetbrains@IU.0a1b2c3d-pid:41";
        let idea_focus = "jetbrains-focus@IU.0a1b2c3d-pid:41";
        let rider = "jetbrains@RD.9f8e7d6c-pid:42";
        let mut sequence = 0;
        for client in [idea, idea_focus, rider, "vscode-pid:9"] {
            sequence += 1;
            assert!(
                graph
                    .observe(
                        &scope,
                        root,
                        lane_surface_observation(client, sequence),
                        None
                    )
                    .0
            );
        }
        // Startup and joins request nothing under `per_installation`.
        assert_eq!(reconcile.trigger(), None);
        assert!(runs.lock().is_empty());

        // IDEA retires one family but its focus surface is still live: no
        // installation is gone.
        assert_eq!(graph.forget_client_family(root, idea, 100), 1);
        assert_eq!(reconcile.trigger(), None);

        // Rider quits: the controller runs the reconcile on its own.
        assert_eq!(graph.forget_client_family(root, rider, 100), 1);
        let receipt = reconcile
            .wait_for_receipt(1, Duration::from_secs(10))
            .expect("the retirement runs the reconcile");
        assert_eq!(receipt.sequence, 1);
        assert_eq!(receipt.trigger.mode, NavigationMode::PerInstallation);
        assert_eq!(
            receipt.trigger.retired,
            BTreeSet::from(["RD.9f8e7d6c".to_string()])
        );
        assert_eq!(
            receipt.trigger.liveness(),
            LaneLiveness::RetiredOnly(BTreeSet::from(["RD.9f8e7d6c".to_string()]))
        );
        // IDEA's remaining surface goes too: one more run, both retired.
        assert_eq!(graph.forget_client_family(root, idea_focus, 100), 1);
        let receipt = reconcile
            .wait_for_receipt(2, Duration::from_secs(10))
            .expect("the second retirement runs the reconcile again");
        assert_eq!(
            receipt.trigger.retired,
            BTreeSet::from(["IU.0a1b2c3d".to_string(), "RD.9f8e7d6c".to_string()])
        );
        assert_eq!(runs.lock().len(), 2);
        // A surface of another project root publishes nothing here.
        assert!(
            graph
                .observe(
                    &scope,
                    Path::new("/other"),
                    lane_surface_observation("jetbrains@CL.11223344-pid:43", 99),
                    None
                )
                .0
        );
        assert_eq!(reconcile.trigger().unwrap().retired.len(), 2);
    }

    #[test]
    fn navigation_lane_reconcile_runs_at_start_under_shared_mode() {
        use agent_doc_editor_surface::{LaneLiveness, NavigationMode};
        let scope = agent_doc_state_scope::ProcessScope::new();
        let root = Path::new("/project");
        let reconcile = NavigationLaneReconcileGraph::new_in(&scope, root, NavigationMode::Shared);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(|_, _| Ok("ok".to_string())))
            .with_lane_reconcile(Arc::clone(&reconcile));
        // The request exists before the worker starts; starting the worker
        // is the edge that delivers it (the disable migration).
        assert!(reconcile.trigger().is_some());
        let (runner, runs) = recording_lane_reconcile_runner();
        reconcile.install_worker(runner);
        let receipt = reconcile
            .wait_for_receipt(1, Duration::from_secs(10))
            .expect("a controller started under shared reconciles at once");
        assert_eq!(receipt.trigger.mode, NavigationMode::Shared);
        assert_eq!(
            receipt.trigger.liveness(),
            LaneLiveness::Live(BTreeSet::new())
        );
        // A join changes nothing; a retirement runs it again.
        assert!(
            graph
                .observe(
                    &scope,
                    root,
                    lane_surface_observation("jetbrains@IU.0a1b2c3d-pid:41", 1),
                    None
                )
                .0
        );
        assert_eq!(runs.lock().len(), 1);
        assert_eq!(
            graph.forget_client_family(root, "jetbrains@IU.0a1b2c3d-pid:41", 100),
            1
        );
        let receipt = reconcile
            .wait_for_receipt(2, Duration::from_secs(10))
            .expect("a retirement re-runs it");
        assert_eq!(receipt.sequence, 2);
        assert_eq!(
            receipt.trigger.liveness(),
            LaneLiveness::Live(BTreeSet::new())
        );
    }

    #[test]
    fn controller_runtime_wires_the_navigation_lane_reconcile_to_its_surface_graph() {
        let dir = tempfile::TempDir::new().unwrap();
        let runtime = ControllerRuntime::new(test_bootstrap(&dir)).unwrap();
        assert_eq!(runtime.navigation_lane_reconcile.project_root(), dir.path());
        assert_eq!(
            runtime.navigation_lane_reconcile.mode(),
            runtime.editor_surface_graph.navigation_mode()
        );
        assert!(Arc::ptr_eq(
            runtime
                .editor_surface_graph
                .lane_reconcile
                .as_ref()
                .expect("the surface graph publishes liveness"),
            &runtime.navigation_lane_reconcile
        ));
    }

    /// `#ridernavp6gc` end to end on an isolated tmux server: the controller's
    /// own trigger closes the empty lane of an IDE that quit (keeping a live
    /// IDE's lane, a lane whose installation it never saw, and a foreign
    /// lane-named session), and a controller started under `shared` folds a
    /// lane's document pane back and closes the lanes, without `agent-doc gc`.
    #[test]
    #[ignore = "live tmux integration test; run `make tmux-ci`"]
    fn navigation_lane_session_reconcile_is_driven_by_installation_liveness() {
        use agent_doc_editor_surface::NavigationMode;
        let tmux = agent_doc_tmux_io::isolated_test_tmux("navlane-p6gc");
        let root = tempfile::TempDir::new().unwrap();
        let root = root.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join(".agent-doc")).unwrap();
        std::fs::create_dir_all(root.join("tasks")).unwrap();
        std::fs::write(
            root.join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"per_installation\"\n",
        )
        .unwrap();
        let shared_pane = tmux.new_session("proj", &root).unwrap();
        tmux.raw_cmd(&["rename-window", "-t", &shared_pane, "agent-doc"])
            .unwrap();
        let foreign = tmux.new_session("proj-XX-55667788", &root).unwrap();
        const IDEA: &str = "jetbrains@IU.0a1b2c3d-pid:41";
        const RIDER: &str = "jetbrains@RD.9f8e7d6c-pid:42";
        const CLION: &str = "jetbrains@CL.11223344-pid:43";
        let lane = |client: &str| {
            navigation_lane_session_for_client(&tmux, &root, client)
                .unwrap()
                .unwrap()
                .session
        };
        let (idea, rider, clion) = (lane(IDEA), lane(RIDER), lane(CLION));
        let server: &tmux_router::Tmux = &tmux;
        let server = server.clone();
        let runner = || -> NavigationLaneReconcileRunner {
            let server = server.clone();
            Arc::new(move |project_root, trigger| {
                reconcile_navigation_lane_sessions_in_mode(
                    &server,
                    project_root,
                    trigger.mode,
                    &trigger.liveness(),
                    false,
                )
            })
        };

        // A per_installation controller sees IDEA and Rider; CLion quit
        // before this controller started.
        let scope = agent_doc_state_scope::ProcessScope::new();
        let reconcile =
            NavigationLaneReconcileGraph::new_in(&scope, &root, NavigationMode::PerInstallation);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(|_, _| Ok("ok".to_string())))
            .with_navigation_mode(NavigationMode::PerInstallation)
            .with_lane_reconcile(Arc::clone(&reconcile));
        reconcile.install_worker(runner());
        for (sequence, client) in [IDEA, RIDER].into_iter().enumerate() {
            assert!(
                graph
                    .observe(
                        &scope,
                        &root,
                        lane_surface_observation(client, sequence as u64 + 1),
                        None
                    )
                    .0
            );
        }
        assert_eq!(reconcile.receipt(), None, "joining reconciles nothing");

        // Rider quits: its empty lane closes; nothing else is touched.
        assert_eq!(graph.forget_client_family(&root, RIDER, 100), 1);
        let receipt = reconcile
            .wait_for_receipt(1, Duration::from_secs(30))
            .expect("Rider's retirement runs the reconcile");
        assert!(receipt.failures.is_empty(), "{:?}", receipt.failures);
        assert_eq!(receipt.closed, vec![rider.clone()]);
        assert!(!tmux.session_alive(&rider));
        assert!(tmux.session_alive(&idea), "a live IDE's lane is kept");
        assert!(
            tmux.session_alive(&clion),
            "a lane whose installation this controller never saw is left to gc"
        );
        assert!(tmux.session_alive("proj-XX-55667788"));
        assert!(tmux.pane_alive(&foreign));
        drop(graph);
        drop(reconcile);
        drop(scope);

        // IDEA placed two documents in its lane; then the project switches to
        // `shared` and the controller restarts under it.
        let register = |name: &str| {
            let pane = tmux.new_window(&idea, &root).unwrap();
            let file = root.join(format!("tasks/{name}.md"));
            std::fs::write(&file, format!("# {name}\n")).unwrap();
            let pid: u32 = tmux
                .raw_cmd(&["display-message", "-p", "-t", &pane, "#{pane_pid}"])
                .unwrap()
                .trim()
                .parse()
                .unwrap();
            let window = tmux.pane_window(&pane).unwrap();
            agent_doc_session_registry_io::registration::register_full_with_cwd_in(
                &root,
                name,
                &pane,
                &file.to_string_lossy(),
                pid,
                &window,
                &root.to_string_lossy(),
            )
            .unwrap();
            pane
        };
        let laid_out = register("idea-laid-out");
        let idea_doc = register("idea-doc");
        std::fs::write(
            root.join(".agent-doc/config.toml"),
            "tmux_session = \"proj\"\neditor_navigation = \"shared\"\n",
        )
        .unwrap();
        // A shared sync holds the sync lock while it adopts the pane its
        // layout shows (`#ridernavp6switchback`): the controller's start
        // reconcile waits for it and then finds that pane already home.
        let sync_lock = lock_navigation_lane_reconcile(&root).unwrap();
        let scope = agent_doc_state_scope::ProcessScope::new();
        let reconcile = NavigationLaneReconcileGraph::new_in(&scope, &root, NavigationMode::Shared);
        reconcile.install_worker(runner());
        assert_eq!(
            reconcile.wait_for_receipt(1, Duration::from_millis(500)),
            None,
            "the reconcile waits for the sync holding the lock"
        );
        tmux.stash_pane(&laid_out, "proj").unwrap();
        drop(sync_lock);
        let receipt = reconcile
            .wait_for_receipt(1, Duration::from_secs(30))
            .expect("a controller started under shared runs the disable migration");
        assert!(receipt.failures.is_empty(), "{:?}", receipt.failures);
        assert_eq!(
            receipt.folded,
            vec![(idea.clone(), idea_doc.clone())],
            "only the pane the sync did not adopt is folded; none twice"
        );
        let mut closed = receipt.closed.clone();
        closed.sort();
        let mut expected = vec![idea.clone(), clion.clone()];
        expected.sort();
        assert_eq!(closed, expected);
        assert_eq!(tmux.pane_session(&idea_doc).unwrap(), "proj");
        assert_eq!(tmux.pane_session(&laid_out).unwrap(), "proj");
        assert!(tmux.session_alive("proj-XX-55667788"));
        assert!(tmux.pane_alive(&foreign));
    }

    #[test]
    fn per_installation_lanes_key_layout_ownership_by_installation() {
        // `#ideriderindependentnav`: with the installation in the
        // layout-ownership key, IDEA and Rider no longer compete for one owner.
        // Each installation's lane has exactly one installation, so each drives
        // its own lane and neither is ever deferred to the other; the shared
        // lane keeps the `#idefocusowner` rule for unscoped clients.
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        let scope = agent_doc_state_scope::ProcessScope::new();
        let effects = Arc::new(Mutex::new(Vec::<SurfaceIntent>::new()));
        let recorded = Arc::clone(&effects);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(move |_, intent| {
            recorded.lock().push(intent.clone());
            Ok("recorded".to_string())
        }))
        .with_navigation_mode(NavigationMode::PerInstallation);
        assert_eq!(graph.navigation_mode(), NavigationMode::PerInstallation);
        let root = Path::new("/project");
        let idea = "jetbrains@IU.0a1b2c3d-pid:41";
        let idea_focus = "jetbrains-focus@IU.0a1b2c3d-pid:41";
        let rider = "jetbrains@RD.9f8e7d6c-pid:42";
        let rider_focus = "jetbrains-focus@RD.9f8e7d6c-pid:42";
        let idea_lane = NavigationLane::Installation("IU.0a1b2c3d".to_string());
        let rider_lane = NavigationLane::Installation("RD.9f8e7d6c".to_string());
        let sequence = std::cell::Cell::new(0_u64);
        let layout = |files: &[&str]| {
            let files = files
                .iter()
                .map(|file| (*file).to_string())
                .collect::<Vec<_>>();
            agent_doc_editor_surface::EditorSurface {
                column_order: Default::default(),
                focused: files[0].clone(),
                open: files.clone(),
                visible: files.clone(),
                columns: files
                    .iter()
                    .map(|file| SurfaceColumn {
                        files: vec![file.clone()],
                    })
                    .collect(),
                force_reconcile: false,
                focus_only: false,
                preserve_focus: true,
            }
        };
        let focus = |document: &str| agent_doc_editor_surface::EditorSurface {
            column_order: Default::default(),
            focused: document.to_string(),
            visible: vec![document.to_string()],
            open: vec![document.to_string()],
            columns: Vec::new(),
            force_reconcile: true,
            focus_only: true,
            preserve_focus: false,
        };
        let observe = |client_id: &str, surface| {
            sequence.set(sequence.get() + 1);
            let (accepted, receipt) = graph.observe(
                &scope,
                root,
                EditorSurfaceObservation {
                    client_id: client_id.to_string(),
                    surface_id: "project".to_string(),
                    generation: 100,
                    sequence: sequence.get(),
                    surface,
                },
                None,
            );
            assert!(accepted);
            receipt
        };
        let owner_epoch = |lane: &NavigationLane| {
            graph
                .focus_owners
                .lock()
                .get(&agent_doc_editor_surface::LayoutOwnerKey::new(
                    root,
                    lane.clone(),
                ))
                .and_then(|owner| owner.owner())
                .map(|owner| owner.epoch)
        };

        observe(idea_focus, focus("/project/a.md"));
        observe(rider_focus, focus("/project/c.md"));
        assert_eq!(
            graph.focus_owner_in(root, &idea_lane).as_deref(),
            Some("IU.0a1b2c3d")
        );
        assert_eq!(
            graph.focus_owner_in(root, &rider_lane).as_deref(),
            Some("RD.9f8e7d6c")
        );
        assert_eq!(
            graph.focus_owner(root),
            None,
            "scoped installations never claim the shared lane"
        );

        // Rider gained focus last, yet IDEA's changed layout still drives its
        // own lane: no deferral exists between lanes.
        for (client, files) in [
            (idea, &["/project/a.md", "/project/b.md"][..]),
            (rider, &["/project/c.md"][..]),
            (idea, &["/project/b.md"][..]),
        ] {
            let receipt = observe(client, layout(files));
            assert_eq!(receipt.deferred_to, None, "{client}");
            assert!(
                matches!(receipt.intent, SurfaceIntent::Sync { .. }),
                "{client}: {:?}",
                receipt.intent
            );
        }

        // An unscoped editor stays on the shared lane and drives it.
        let receipt = observe("vscode-pid:9", layout(&["/project/d.md"]));
        assert_eq!(receipt.deferred_to, None);
        assert!(matches!(receipt.intent, SurfaceIntent::Sync { .. }));

        // Retiring IDEA clears only IDEA's lane; Rider keeps its epoch (no
        // fallback re-stamp, because Rider never lost its own lane).
        let rider_epoch = owner_epoch(&rider_lane);
        assert!(rider_epoch.is_some());
        assert_eq!(graph.forget_client_family(root, idea, 100), 1);
        assert_eq!(graph.forget_client_family(root, idea_focus, 100), 1);
        assert_eq!(graph.focus_owner_in(root, &idea_lane), None);
        assert_eq!(
            graph.focus_owner_in(root, &rider_lane).as_deref(),
            Some("RD.9f8e7d6c")
        );
        assert_eq!(owner_epoch(&rider_lane), rider_epoch);
        assert_eq!(observe(rider, layout(&["/project/c.md"])).deferred_to, None);
        assert!(!effects.lock().is_empty());
    }

    #[test]
    fn shared_navigation_mode_is_the_default_and_keeps_one_owner_per_root() {
        use agent_doc_editor_surface::{NavigationLane, NavigationMode};
        let scope = agent_doc_state_scope::ProcessScope::new();
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(|_, _| Ok("ok".to_string())));
        assert_eq!(graph.navigation_mode(), NavigationMode::Shared);
        let root = Path::new("/project");
        for (sequence, client) in [
            "jetbrains-focus@IU.0a1b2c3d-pid:41",
            "jetbrains-focus@RD.9f8e7d6c-pid:42",
        ]
        .into_iter()
        .enumerate()
        {
            graph.observe(
                &scope,
                root,
                EditorSurfaceObservation {
                    client_id: client.to_string(),
                    surface_id: "project".to_string(),
                    generation: 1,
                    sequence: sequence as u64 + 1,
                    surface: agent_doc_editor_surface::EditorSurface {
                        column_order: Default::default(),
                        focused: "/project/a.md".to_string(),
                        visible: vec!["/project/a.md".to_string()],
                        open: vec!["/project/a.md".to_string()],
                        columns: Vec::new(),
                        force_reconcile: true,
                        focus_only: true,
                        preserve_focus: false,
                    },
                },
                None,
            );
        }
        assert_eq!(graph.focus_owners.lock().len(), 1, "one key per root");
        assert_eq!(graph.focus_owner(root).as_deref(), Some("RD.9f8e7d6c"));
        assert_eq!(
            graph.focus_owner_in(
                root,
                &NavigationLane::Installation("IU.0a1b2c3d".to_string())
            ),
            None
        );
    }

    #[test]
    fn passive_editor_observation_does_not_bootstrap_or_touch_state_db() {
        let dir = tempfile::tempdir().unwrap();
        let db = state_db_path(dir.path());
        std::fs::create_dir_all(db.parent().unwrap()).unwrap();
        std::fs::write(&db, b"sentinel-not-a-sqlite-database").unwrap();
        let before = std::fs::read(&db).unwrap();
        let before_entries = std::fs::read_dir(db.parent().unwrap())
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect::<BTreeSet<_>>();
        let observation = EditorSurfaceObservation {
            client_id: "idea:passive".to_string(),
            surface_id: "project".to_string(),
            generation: 1,
            sequence: 1,
            surface: test_editor_surface("/project/passive.md"),
        };

        let error = observe_editor_surface_existing(dir.path(), &observation).unwrap_err();

        assert!(
            format!("{error:#}").contains("failed to connect to project controller"),
            "passive ingress should fail at the absent socket: {error:#}"
        );
        assert_eq!(std::fs::read(&db).unwrap(), before);
        let after_entries = std::fs::read_dir(db.parent().unwrap())
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            after_entries, before_entries,
            "passive editor ingress must not create bootstrap, WAL, or SHM files"
        );
    }

    /// `#surfaceobservesilent`: the observe handler used to log NOTHING on ingress,
    /// so a published selection the surface graph rejected was indistinguishable in
    /// ops.log from a selection that never published at all. That is precisely the
    /// evidence a "tmux focus did not auto-sync" report needs, and its absence is
    /// what stalled #tmuxfocussyncverify. Assert the ingress receipt exists for BOTH
    /// outcomes, and that the logged `accepted=` matches the graph's own verdict
    /// rather than a constant.
    /// The churn half of `#surfaceobservesilent`. Logging every ingress literally
    /// produced a steady 30 lines/min per attached editor at an unchanging
    /// generation — ~43k lines/day, the bulk of an 11.5MB ops.log — which buried
    /// the rare events the log exists for. Folding must be aggressive on a
    /// steady state and instant on any change.
    #[test]
    fn a_steady_surface_heartbeat_folds_while_every_change_logs_immediately() {
        let logged = |key: &str| fold_repeated_surface_observation(key).is_some();

        // First observation of a state always logs.
        assert!(logged("idea|7|true|idle"));
        // Then 1, 2, 4, 8, ... — never every repeat.
        let steady = (0..64).filter(|_| logged("idea|7|true|idle")).count();
        assert!(
            steady <= 8,
            "a 64-observation steady state must fold to a handful of lines, got {steady}"
        );
        assert!(
            steady >= 4,
            "folding must still sample the run so a stuck heartbeat stays visible, got {steady}"
        );

        // Every component of the key is a change that must log at once: a new
        // generation, a flipped verdict, and a non-idle intent are exactly the
        // three things a "focus did not auto-sync" report needs to see.
        assert!(logged("idea|8|true|idle"), "a new generation must log");
        assert!(logged("idea|8|false|idle"), "a rejected verdict must log");
        assert!(logged("idea|8|false|focus"), "a non-idle intent must log");
        assert!(logged("vscode|8|false|focus"), "a new client must log");
    }

    /// `#surfaceretireformal` runtime monitor, end to end through the ingress:
    /// every retired rejection returns the re-registration directive, the K-th
    /// consecutive one leaves exactly one `controller_editor_surface_muted_live_endpoint`
    /// record, and acting on the directive ends the streak.
    #[test]
    fn editor_surface_observe_reports_a_muted_live_endpoint_once_per_streak() {
        let dir = tempfile::tempdir().unwrap();
        let bootstrap = ControllerBootstrap {
            project_root: dir.path().to_path_buf(),
            socket_path: socket_path(dir.path()),
            launch_mode: LaunchMode::Lazy,
            bootstrap_epoch: 0,
            pid: std::process::id(),
            controller_binary: Some(current_binary_identity().unwrap()),
            controller_generation: 1,
            handoff_state: ControllerHandoffState::Stable,
            handoff_started_at: None,
            previous_controller_pid: None,
        };
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let request = |command: &str, generation: u64, payload: Option<String>| ControllerRequest {
            command: command.to_string(),
            file: None,
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: Some(generation),
            state: None,
            caller: Some("idea:muted".to_string()),
            reason: Some("editor_surface_client_retired".to_string()),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: payload,
            sequence: None,
        };
        let observe = |generation: u64, sequence: u64| {
            let mut surface = test_editor_surface("/project/observed.md");
            surface.force_reconcile = false;
            surface.focus_only = true;
            let observation = EditorSurfaceObservation {
                client_id: "idea:muted".to_string(),
                surface_id: "frame-1".to_string(),
                generation,
                sequence,
                surface,
            };
            handle_editor_surface_observe(
                &bootstrap,
                runtime.as_ref(),
                request(
                    "editor_surface_observe",
                    generation,
                    Some(serde_json::to_string(&observation).unwrap()),
                ),
            )
            .unwrap()
        };
        let muted_records = || {
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log"))
                .unwrap_or_default()
                .lines()
                .filter(|line| line.contains("controller_editor_surface_muted_live_endpoint"))
                .map(str::to_string)
                .collect::<Vec<_>>()
        };

        assert_eq!(observe(4, 1).rejected, None);
        handle_editor_surface_forget(
            &bootstrap,
            runtime.as_ref(),
            request(
                "editor_surface_forget",
                4,
                Some(r#"{"surface_id":"frame-1"}"#.to_string()),
            ),
        )
        .unwrap();
        let mut sequence = 1;
        for n in 1..=RETIRED_ENDPOINT_MUTE_THRESHOLD + 2 {
            sequence += 1;
            let receipt = observe(4, sequence);
            assert_eq!(
                receipt.rejected,
                Some(SurfaceObservationRejection::RetiredEndpoint)
            );
            assert_eq!(
                receipt.reregister_above_generation,
                Some(4),
                "every retired rejection carries the directive (rejection {n})"
            );
            let expected = usize::from(n >= RETIRED_ENDPOINT_MUTE_THRESHOLD);
            assert_eq!(muted_records().len(), expected, "after rejection {n}");
        }
        let records = muted_records();
        assert!(
            records[0].contains("client=idea:muted surface=frame-1 generation=4")
                && records[0].contains(&format!(
                    "consecutive={RETIRED_ENDPOINT_MUTE_THRESHOLD} threshold={RETIRED_ENDPOINT_MUTE_THRESHOLD}"
                ))
                && records[0].contains("recovery=reregister_directive reregister_above_generation=4"),
            "{records:?}"
        );

        sequence += 1;
        let next = agent_doc_editor_surface::reregistration_generation(4, 4);
        assert_eq!(
            observe(next, sequence).rejected,
            None,
            "the directive re-registers"
        );
        assert_eq!(
            muted_records().len(),
            1,
            "an accepted re-registration raises nothing"
        );
        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops_log.contains(
                "controller_editor_surface_observed client=idea:muted surface=frame-1 generation=4"
            ),
            "the ingress receipt names the surface endpoint: {ops_log}"
        );
    }

    #[test]
    fn editor_surface_observe_logs_an_ingress_receipt_for_accepted_and_rejected_facts() {
        let dir = tempfile::tempdir().unwrap();
        let bootstrap = ControllerBootstrap {
            project_root: dir.path().to_path_buf(),
            socket_path: socket_path(dir.path()),
            launch_mode: LaunchMode::Lazy,
            bootstrap_epoch: 0,
            pid: std::process::id(),
            controller_binary: Some(current_binary_identity().unwrap()),
            controller_generation: 1,
            handoff_state: ControllerHandoffState::Stable,
            handoff_started_at: None,
            previous_controller_pid: None,
        };
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();

        let observe = |client_id: &str, generation: u64, sequence: u64| {
            let observation = EditorSurfaceObservation {
                client_id: client_id.to_string(),
                surface_id: "project".to_string(),
                generation,
                sequence,
                surface: test_editor_surface("/project/observed.md"),
            };
            let payload = serde_json::to_string(&observation).unwrap();
            handle_editor_surface_observe(
                &bootstrap,
                runtime.as_ref(),
                ControllerRequest {
                    command: "editor_surface_observe".to_string(),
                    file: Some(PathBuf::from(&observation.surface.focused)),
                    session_id: None,
                    pane_id: None,
                    window_id: None,
                    generation: Some(generation),
                    state: None,
                    caller: Some(observation.client_id.clone()),
                    reason: Some("editor_surface_observation".to_string()),
                    supervisor_pid: None,
                    supervisor_socket: None,
                    command_kind: None,
                    diagnostic_payload: Some(payload),
                    sequence: None,
                },
            )
        };

        observe("idea:ingress", 2, 2).unwrap();
        // A retired generation must be fenced, which is the deterministic way to
        // drive the graph's reject branch without guessing at dedup semantics.
        handle_editor_surface_forget(
            &bootstrap,
            runtime.as_ref(),
            ControllerRequest {
                command: "editor_surface_forget".to_string(),
                file: None,
                session_id: None,
                pane_id: None,
                window_id: None,
                generation: Some(2),
                state: None,
                caller: Some("idea:ingress".to_string()),
                reason: Some("editor_surface_client_retired".to_string()),
                supervisor_pid: None,
                supervisor_socket: None,
                command_kind: None,
                diagnostic_payload: None,
                sequence: None,
            },
        )
        .unwrap();
        observe("idea:ingress", 2, 3).unwrap();

        let ops_log =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        let receipts = ops_log
            .lines()
            .filter(|line| line.contains("controller_editor_surface_observed"))
            .collect::<Vec<_>>();
        assert_eq!(
            receipts.len(),
            2,
            "every observation must leave one ingress receipt, accepted or not: {ops_log}"
        );
        assert!(
            receipts
                .iter()
                .all(|line| line.contains("client=idea:ingress") && line.contains("sequence=")),
            "the receipt must identify the publishing client and sequence: {receipts:?}"
        );
        assert!(
            receipts
                .iter()
                .all(|line| { line.contains("layout=observed") && line.contains("pane_action=") }),
            "the same line must join layout authority to its pane action: {receipts:?}"
        );
        let accepted_values = receipts
            .iter()
            .filter_map(|line| {
                line.split_whitespace()
                    .find_map(|field| field.strip_prefix("accepted="))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            accepted_values,
            vec!["true", "false"],
            "the receipt must report the graph's real verdict, not a constant: {receipts:?}"
        );
        assert!(
            ops_log.contains("controller_editor_surface_forgotten client=idea:ingress"),
            "a retirement must leave its own receipt, since a stray forget is what \
             makes every later observation reject: {ops_log}"
        );
        // `#tmuxautosyncretired`: the rejected receipt names WHY, so an editor that
        // keeps publishing into its own retired endpoint is distinguishable from a
        // benign duplicate without correlating the forget line by hand.
        assert!(
            receipts[1].contains(" rejected=retired_endpoint"),
            "a fact fenced by a retired endpoint must say so: {receipts:?}"
        );
        assert!(
            !receipts[0].contains(" rejected="),
            "an accepted fact carries no rejection reason: {receipts:?}"
        );
    }

    #[test]
    fn surface_observation_rejection_classifies_each_fence() {
        use SurfaceObservationRejection as R;
        // (retired, current_generation, current_sequence, generation, sequence)
        assert_eq!(R::classify(true, 7, 3, 7, 4), Some(R::RetiredEndpoint));
        assert_eq!(
            R::classify(true, 7, 3, 7, u64::MAX),
            Some(R::RetiredEndpoint)
        );
        assert_eq!(R::classify(true, 7, 3, 6, 9), Some(R::RetiredEndpoint));
        assert_eq!(
            R::classify(true, 7, 3, 8, 1),
            None,
            "a newer generation rejoins"
        );
        assert_eq!(R::classify(false, 7, 3, 6, 9), Some(R::StaleGeneration));
        assert_eq!(R::classify(false, 7, 3, 7, 3), Some(R::StaleSequence));
        assert_eq!(R::classify(false, 7, 3, 7, 2), Some(R::StaleSequence));
        assert_eq!(R::classify(false, 7, 3, 7, 4), None);
        assert_eq!(R::classify(false, 7, 3, 8, 1), None);
    }

    /// `#tmuxautosyncretired`: retiring a still-live frame endpoint at the
    /// editor's live connection generation mutes every later tab switch from
    /// that frame. The controller fence is deliberate (a retired generation
    /// cannot regain effect authority), so the editor must never retire an
    /// endpoint it is about to publish again; this pins the consequence.
    #[test]
    fn controller_editor_surface_graph_mutes_a_live_endpoint_retired_at_its_generation() {
        let scope = agent_doc_state_scope::ProcessScope::new();
        let effects = Arc::new(Mutex::new(Vec::<SurfaceIntent>::new()));
        let recorded = Arc::clone(&effects);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(move |_, intent| {
            recorded.lock().push(intent.clone());
            Ok("recorded".to_string())
        }));
        let root = Path::new("/project");
        let observation =
            |generation: u64, sequence: u64, focused: &str| EditorSurfaceObservation {
                client_id: "jetbrains@IU.abc-pid:7".to_string(),
                surface_id: "frame-1".to_string(),
                generation,
                sequence,
                surface: test_editor_surface(focused),
            };

        let (accepted, _) = graph.observe(&scope, root, observation(5, 27, "/project/a.md"), None);
        assert!(accepted);
        let effects_before = effects.lock().len();

        let (forgotten, _) = graph.forget_surface(root, "jetbrains@IU.abc-pid:7", "frame-1", 5);
        assert!(forgotten);

        let (rejection, receipt) =
            graph.observe_classified(&scope, root, observation(5, 28, "/project/b.md"), None);
        assert_eq!(
            rejection,
            Some(SurfaceObservationRejection::RetiredEndpoint)
        );
        assert!(receipt.idle);
        assert_eq!(
            effects.lock().len(),
            effects_before,
            "the next tab switch from the retired frame drives no tmux effect"
        );

        let (rejoined, _) =
            graph.observe_classified(&scope, root, observation(6, 1, "/project/b.md"), None);
        assert_eq!(rejoined, None, "only a newer connection generation rejoins");
        assert!(effects.lock().len() > effects_before);
    }

    fn surface_retire_graph() -> (
        agent_doc_state_scope::ProcessScope,
        ControllerEditorSurfaceGraph,
        Arc<Mutex<Vec<SurfaceIntent>>>,
    ) {
        let scope = agent_doc_state_scope::ProcessScope::new();
        let effects = Arc::new(Mutex::new(Vec::<SurfaceIntent>::new()));
        let recorded = Arc::clone(&effects);
        let graph = ControllerEditorSurfaceGraph::new(Arc::new(move |_, intent| {
            recorded.lock().push(intent.clone());
            Ok("recorded".to_string())
        }));
        (scope, graph, effects)
    }

    fn surface_retire_observation(
        generation: u64,
        sequence: u64,
        focused: &str,
    ) -> EditorSurfaceObservation {
        EditorSurfaceObservation {
            client_id: "jetbrains@IU.abc-pid:7".to_string(),
            surface_id: "frame-1".to_string(),
            generation,
            sequence,
            surface: test_editor_surface(focused),
        }
    }

    /// `#surfaceretireformal` (`EditorReregister`): the retired receipt is the
    /// re-registration directive, and acting on it ends the mute in one round
    /// trip without lifting the fence for the retired generation.
    #[test]
    fn retired_endpoint_receipt_directs_a_reregistration_that_ends_the_mute() {
        let (scope, graph, effects) = surface_retire_graph();
        let root = Path::new("/project");
        let (accepted, _) = graph.observe(
            &scope,
            root,
            surface_retire_observation(5, 27, "/project/a.md"),
            None,
        );
        assert!(accepted);
        assert!(
            graph
                .forget_surface(root, "jetbrains@IU.abc-pid:7", "frame-1", 5)
                .0
        );

        let (rejection, receipt) = graph.observe_classified(
            &scope,
            root,
            surface_retire_observation(5, 28, "/project/b.md"),
            None,
        );
        assert_eq!(
            rejection,
            Some(SurfaceObservationRejection::RetiredEndpoint)
        );
        assert_eq!(
            receipt.rejected, rejection,
            "the receipt carries the typed fence"
        );
        assert_eq!(receipt.reregister_above_generation, Some(5));
        let wire = serde_json::to_value(&receipt).unwrap();
        assert_eq!(wire["rejected"], "retired_endpoint");
        assert_eq!(wire["reregister_above_generation"], 5);

        let effects_before = effects.lock().len();
        let next = agent_doc_editor_surface::reregistration_generation(5, 5);
        let (rejection, receipt) = graph.observe_classified(
            &scope,
            root,
            surface_retire_observation(next, 29, "/project/b.md"),
            None,
        );
        assert_eq!(rejection, None, "the re-registered endpoint is accepted");
        assert_eq!(receipt.rejected, None);
        assert_eq!(receipt.reregister_above_generation, None);
        assert!(
            effects.lock().len() > effects_before,
            "and drives tmux again"
        );

        let (stale, receipt) = graph.observe_classified(
            &scope,
            root,
            surface_retire_observation(5, 30, "/project/a.md"),
            None,
        );
        assert_eq!(
            stale,
            Some(SurfaceObservationRejection::StaleGeneration),
            "the retired generation stays fenced after the re-registration"
        );
        assert_eq!(
            receipt.reregister_above_generation, None,
            "only a retired endpoint carries the directive"
        );
    }

    /// `#surfaceretireformal` (`RetireRaisesFence`): a forget at a generation
    /// NEWER than the root retires it and raises its fence, so a re-registering
    /// observation the forget overtook cannot resurrect the frame
    /// (`PassiveTmuxSyncRetireNetExactForgetWedge`). A forget OLDER than the
    /// root never retires a re-registration.
    #[test]
    fn forget_raises_the_fence_to_its_generation_and_never_retires_a_newer_one() {
        let (scope, graph, _effects) = surface_retire_graph();
        let root = Path::new("/project");
        let client = "jetbrains@IU.abc-pid:7";
        assert!(
            graph
                .observe(
                    &scope,
                    root,
                    surface_retire_observation(5, 1, "/project/a.md"),
                    None
                )
                .0
        );

        assert!(
            graph.forget_surface(root, client, "frame-1", 6).0,
            "a newer forget retires an older registration"
        );
        let (rejection, receipt) = graph.observe_classified(
            &scope,
            root,
            surface_retire_observation(6, 2, "/project/b.md"),
            None,
        );
        assert_eq!(
            rejection,
            Some(SurfaceObservationRejection::RetiredEndpoint),
            "the forget's own generation is fenced: the overtaken observation is not resurrected"
        );
        assert_eq!(receipt.reregister_above_generation, Some(6));
        assert!(
            !graph.forget_surface(root, client, "frame-1", 6).0,
            "an equal forget of a retired endpoint changes nothing"
        );
        assert!(
            graph.forget_surface(root, client, "frame-1", 8).0,
            "a newer forget of a retired endpoint raises its fence"
        );
        assert_eq!(
            graph
                .observe_classified(
                    &scope,
                    root,
                    surface_retire_observation(8, 3, "/project/b.md"),
                    None
                )
                .0,
            Some(SurfaceObservationRejection::RetiredEndpoint)
        );
        assert_eq!(
            graph
                .observe_classified(
                    &scope,
                    root,
                    surface_retire_observation(9, 4, "/project/b.md"),
                    None
                )
                .0,
            None,
            "above the fence re-registers"
        );

        assert!(
            !graph.forget_surface(root, client, "frame-1", 8).0,
            "a delayed older forget never retires the re-registration"
        );
        assert!(
            !graph.forget(root, client, 8),
            "nor does a delayed older client-wide forget"
        );
        assert_eq!(
            graph.forget_client_family(root, client, 8),
            0,
            "nor a delayed older family forget"
        );
        assert_eq!(
            graph
                .observe_classified(
                    &scope,
                    root,
                    surface_retire_observation(9, 5, "/project/a.md"),
                    None
                )
                .0,
            None
        );

        assert!(
            graph.forget(root, client, 10),
            "a client-wide forget raises too"
        );
        assert_eq!(
            graph
                .observe_classified(
                    &scope,
                    root,
                    surface_retire_observation(10, 6, "/project/a.md"),
                    None
                )
                .0,
            Some(SurfaceObservationRejection::RetiredEndpoint)
        );
        assert_eq!(
            graph.forget_client_family(root, client, 11),
            0,
            "a family forget of an already-retired root only raises its fence"
        );
        assert_eq!(
            graph
                .observe_classified(
                    &scope,
                    root,
                    surface_retire_observation(11, 7, "/project/a.md"),
                    None
                )
                .0,
            Some(SurfaceObservationRejection::RetiredEndpoint)
        );
    }

    /// `#surfaceretireformal` runtime monitor: K consecutive retired rejections
    /// of one endpoint raise one alert per streak; an accepted re-registration
    /// ends the streak.
    #[test]
    fn retired_endpoint_monitor_alerts_once_per_streak_of_k_rejections() {
        let (scope, graph, _effects) = surface_retire_graph();
        let root = Path::new("/project");
        let observe = |generation: u64, sequence: u64| {
            graph.observe_monitored(
                &scope,
                root,
                surface_retire_observation(generation, sequence, "/project/a.md"),
                None,
            )
        };
        assert_eq!(observe(5, 1).2, None);
        assert!(
            graph
                .forget_surface(root, "jetbrains@IU.abc-pid:7", "frame-1", 5)
                .0
        );
        let mut sequence = 1;
        let mut alerts = Vec::new();
        for _ in 0..(2 * RETIRED_ENDPOINT_MUTE_THRESHOLD) {
            sequence += 1;
            let (rejection, _, alert) = observe(5, sequence);
            assert_eq!(
                rejection,
                Some(SurfaceObservationRejection::RetiredEndpoint)
            );
            alerts.push(alert.map(|alert| alert.consecutive));
        }
        let expected = (1..=2 * RETIRED_ENDPOINT_MUTE_THRESHOLD)
            .map(|n| (n == RETIRED_ENDPOINT_MUTE_THRESHOLD).then_some(n))
            .collect::<Vec<_>>();
        assert_eq!(alerts, expected, "exactly one alert, on the K-th rejection");

        sequence += 1;
        assert_eq!(observe(6, sequence).0, None, "re-registered");
        assert!(
            graph
                .forget_surface(root, "jetbrains@IU.abc-pid:7", "frame-1", 6)
                .0
        );
        for n in 1..=RETIRED_ENDPOINT_MUTE_THRESHOLD {
            sequence += 1;
            let alert = observe(6, sequence).2;
            assert_eq!(
                alert.is_some(),
                n == RETIRED_ENDPOINT_MUTE_THRESHOLD,
                "a new streak after a re-registration alerts again at K"
            );
        }
    }

