    #[test]
    fn controller_model_pressure_logs_once_per_continuous_episode() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("doc.md");
        std::fs::write(&doc, "# doc\n").unwrap();

        record_controller_model_pressure(dir.path(), &doc, "first", "controller busy");
        let conn = agent_doc_sqlite::state_store::open_state_db(dir.path()).unwrap();
        agent_doc_sqlite::state_store::upsert_project_runtime_state_in_db(
            &conn,
            CONTROLLER_MODEL_PRESSURE_STATE_KEY,
            &(controller_model_pressure_now_secs()
                + CONTROLLER_MODEL_PRESSURE_COOLDOWN.as_secs() / 2)
                .to_string(),
            controller_model_pressure_now_secs() * 1000,
        )
        .unwrap();

        // An active-but-near-expiry marker refreshes the cooldown, but remains
        // part of the same pressure episode and must not add another log line.
        record_controller_model_pressure(dir.path(), &doc, "refresh", "still busy");
        let ops = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert_eq!(ops.matches("controller_model_pressure_recorded").count(), 1);

        agent_doc_sqlite::state_store::upsert_project_runtime_state_in_db(
            &conn,
            CONTROLLER_MODEL_PRESSURE_STATE_KEY,
            "0",
            controller_model_pressure_now_secs() * 1000,
        )
        .unwrap();
        record_controller_model_pressure(dir.path(), &doc, "next", "busy again");
        let ops = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert_eq!(ops.matches("controller_model_pressure_recorded").count(), 2);
    }

    #[test]
    fn controller_model_pressure_lock_contention_is_bounded_and_nonfatal() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("doc.md");
        std::fs::write(&doc, "# doc\n").unwrap();
        let mut blocker = agent_doc_sqlite::state_store::open_state_db(dir.path()).unwrap();
        let tx = blocker
            .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
            .unwrap();
        agent_doc_sqlite::state_store::upsert_project_runtime_state_in_db(
            &tx,
            "blocking_writer",
            "held",
            1,
        )
        .unwrap();

        let started = std::time::Instant::now();
        record_controller_model_pressure(dir.path(), &doc, "locked_test", "controller busy");
        assert!(
            started.elapsed() < std::time::Duration::from_secs(15),
            "an advisory pressure marker must not inherit the 30s state-db timeout",
        );
        drop(tx);

        let ops = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops.contains("controller_model_pressure_persist_deferred")
                && ops.contains("stage=upsert"),
            "lock contention should be diagnostic-only and recorded off stderr:\n{ops}",
        );
    }

    #[test]
    fn realtime_steering_event_carries_the_full_crdt_aggregate() {
        let document = |tail: &str| {
            format!(
                "---\nagent_doc_format: template\n---\n\n## Exchange\n\n<!-- agent:exchange patch=append -->\n<!-- agent:boundary:base -->\n{tail}<!-- /agent:exchange -->\n"
            )
        };
        let baseline = document("");
        let current = document("❯ First live edit\n\n❯ Second live edit\n");
        let event = realtime_steering_event_for_text("doc", "cycle", &baseline, &current);

        let agent_doc_state_backbone::StateFact::RealtimeSteeringObserved {
            cycle_id,
            steering,
            content_hash,
            ..
        } = &event.fact
        else {
            panic!("expected realtime steering fact");
        };
        assert_eq!(cycle_id, "cycle");
        assert_eq!(steering.count, 2);
        assert_eq!(steering.elements.len(), 2);
        assert_eq!(
            steering.observed_content_hash.as_deref(),
            Some(content_hash.as_str())
        );
        assert!(
            steering
                .elements
                .values()
                .any(|element| element.verbatim.contains("First live edit"))
        );
        assert!(
            steering
                .elements
                .values()
                .any(|element| element.verbatim.contains("Second live edit"))
        );
        assert!(steering.verbatim.as_deref().is_some_and(
            |body| body.contains("First live edit") && body.contains("Second live edit")
        ));
        assert_eq!(content_hash, &agent_doc_hash::content_hash(&current));
        assert!(event.event_id.ends_with(content_hash));
    }

    #[test]
    fn realtime_queue_revision_reaches_cycle_projection_and_retracts() {
        let baseline = "<!-- agent:queue -->\n- do [#task] old option\n<!-- /agent:queue -->\n";
        let current = baseline.replace("old option", "new option");
        for (text, expected_count) in [(current.as_str(), 1), (baseline, 0)] {
            let event = realtime_steering_event_for_text("doc", "cycle", baseline, text);
            let agent_doc_state_backbone::StateFact::RealtimeSteeringObserved {
                cycle_id,
                steering,
                content_hash,
                ..
            } = event.fact
            else {
                panic!("expected steering fact")
            };
            assert_eq!(cycle_id, "cycle");
            assert_eq!(steering.count, expected_count);
            assert_eq!(
                steering.observed_content_hash.as_deref(),
                Some(content_hash.as_str())
            );
            if expected_count > 0 {
                assert_eq!(
                    steering.elements.values().next().unwrap().verbatim,
                    "do [#task] new option"
                );
            }
        }
    }

