    /// GH #128: the start-of-recycle row must not claim a `new_version` — the
    /// old code took it from the RUNNING image and logged `0.35.448 ->
    /// 0.35.448` while launching 0.35.449. It must also record the attempt so
    /// a client cannot launch a second handoff for the same pid + generation.
    #[test]
    fn gh128_self_recycle_start_records_attempt_without_claiming_a_new_version() {
        let dir = async_handoff_test_project();
        let mut bootstrap = test_bootstrap(&dir);
        bootstrap.controller_binary = Some(gh128_identity("0.35.448", 100));
        bootstrap.controller_generation = 35;
        let runtime = test_controller_runtime(&bootstrap);

        controller_self_recycle(runtime.as_ref(), "stale_binary");

        let log = gh128_ops_log(&dir);
        assert!(
            log.contains(
                "controller_self_recycle_started pid=456 generation=35 reason=stale_binary old_version=0.35.448"
            ),
            "{log}"
        );
        assert!(!log.contains("controller_self_recycled"), "{log}");
        assert!(!log.contains("new_version="), "{log}");
        let attempt = read_stale_restart_attempt(dir.path()).expect("attempt recorded");
        assert_eq!(attempt.pid, Some(456));
        assert_eq!(attempt.generation, 35);
        assert_eq!(attempt.requester, "self_recycle");
    }

    /// GH #128 ask 1: `new_version` is the version the replacement reports for
    /// itself. A stale-binary replacement on the predecessor's exact image is a
    /// failed recycle; an explicit same-image refresh is completed successfully.
    #[test]
    fn gh128_self_recycle_outcome_reports_the_replacement_image() {
        let dir = async_handoff_test_project();
        let recorded = gh128_identity("0.35.448", 100);
        let mut replacement =
            active_controller_status_with_handoff_state(ControllerHandoffState::Preparing);
        replacement.pid = Some(777);
        replacement.controller_generation = Some(36);
        replacement.controller_binary = Some(gh128_identity("0.35.449", 200));
        log_self_recycle_outcome(
            dir.path(),
            1223695,
            35,
            "stale_binary",
            Some(&recorded),
            &replacement,
        );
        replacement.controller_binary = Some(recorded.clone());
        log_self_recycle_outcome(
            dir.path(),
            1223695,
            35,
            "stale_binary",
            Some(&recorded),
            &replacement,
        );
        log_self_recycle_outcome(
            dir.path(),
            1223695,
            35,
            "operator_request",
            Some(&recorded),
            &replacement,
        );

        let log = gh128_ops_log(&dir);
        assert!(
            log.contains(
                "controller_self_recycled pid=1223695 generation=35 reason=stale_binary old_version=0.35.448 new_version=0.35.449 new_pid=777 new_generation=36"
            ),
            "{log}"
        );
        assert!(
            log.contains(
                "controller_self_recycle_failed cause=same_image pid=1223695 generation=35 reason=stale_binary old_version=0.35.448 new_version=0.35.448"
            ),
            "{log}"
        );
        assert!(
            log.contains(
                "controller_self_recycled pid=1223695 generation=35 reason=operator_request old_version=0.35.448 new_version=0.35.448"
            ),
            "{log}"
        );
    }

    /// GH #128 ask 2: a restart for a pid + generation that already has a
    /// recent attempt is suppressed — no second `restart_requested` row and no
    /// replacement launch; the caller connects to the live controller instead.
    #[test]
    fn gh128_repeat_stale_restart_for_same_pid_and_generation_is_suppressed() {
        let dir = async_handoff_test_project();
        let mut stale = active_controller_status_with_handoff_state(ControllerHandoffState::Stable);
        stale.project_root = dir.path().to_path_buf();
        stale.pid = Some(1223695);
        stale.controller_generation = Some(35);
        record_stale_restart_attempt(dir.path(), Some(1223695), 35, "self_recycle");

        // No controller is listening in the fixture, so the fallback connect
        // fails — what matters is that no replacement was launched.
        let result =
            request_stable_stale_controller_restart(dir.path(), LaunchMode::Lazy, stale, None);
        assert!(result.is_err());

        let log = gh128_ops_log(&dir);
        assert!(
            log.contains(
                "controller_active_stale_binary_restart_suppressed pid=1223695 generation=35 reason=recent_attempt attempt_by=self_recycle"
            ),
            "{log}"
        );
        assert!(
            !log.contains("controller_active_stale_binary_restart_requested"),
            "{log}"
        );
        assert!(
            !dir.path()
                .join(".agent-doc")
                .read_dir()
                .unwrap()
                .flatten()
                .any(|entry| entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with("controller-handoff-")),
            "a suppressed restart must not launch a replacement"
        );
    }

    /// `#drainingpredecessor`: 2026-10-10 `tools.md` — a client-driven
    /// stale-binary restart promoted a successor and SIGTERMed the predecessor
    /// in the same second, killing the Run Agent Doc route it was finishing;
    /// the editor replayed the whole route (58s). A stale controller that
    /// accepts `recycle_force` now hands itself off (and drains); the client
    /// leases it against duplicate reaping, never prepares a handoff itself,
    /// and adopts the successor.
    #[test]
    fn stale_restart_delegates_to_draining_self_recycle_instead_of_reaping() {
        let dir = async_handoff_test_project();
        let sock = socket_path(dir.path());
        let name = sock.clone().to_fs_name::<GenericFilePath>().unwrap();
        let listener = ListenerOptions::new().name(name).create_sync().unwrap();
        let mut successor =
            active_controller_status_with_handoff_state(ControllerHandoffState::Stable);
        successor.project_root = dir.path().to_path_buf();
        successor.pid = Some(2854081);
        successor.controller_generation = Some(2242);
        successor.controller_binary = current_binary_identity().ok();
        let successor_json = serde_json::to_string(&successor).unwrap();
        let server = std::thread::spawn(move || {
            let mut commands = Vec::new();
            // recycle_force, one adopting status poll, then the client's
            // connect. Incidental reads (ops-log document projection) are
            // answered as unsupported and not recorded.
            while commands.last().map(String::as_str) != Some("<connect>") {
                assert!(
                    commands.len() < 8,
                    "unexpected request sequence {commands:?}"
                );
                let stream = listener.accept().unwrap();
                let (reader_half, mut writer_half) = stream.split();
                let mut line = String::new();
                BufReader::new(reader_half).read_line(&mut line).unwrap();
                if line.trim().is_empty() {
                    commands.push("<connect>".to_string());
                    continue;
                }
                let request: serde_json::Value = serde_json::from_str(&line).unwrap();
                let command = request["command"].as_str().unwrap().to_string();
                let response = match command.as_str() {
                    "recycle_force" => {
                        assert_eq!(request["reason"], "stale_binary_client");
                        r#"{"ok":true}"#.to_string()
                    }
                    "status" => successor_json.clone(),
                    _ => {
                        let _ = writeln!(writer_half, r#"{{"ok":false,"error":"unsupported"}}"#);
                        continue;
                    }
                };
                writeln!(writer_half, "{response}").unwrap();
                writer_half.flush().unwrap();
                commands.push(command);
            }
            commands
        });
        let mut stale = active_controller_status_with_handoff_state(ControllerHandoffState::Stable);
        stale.project_root = dir.path().to_path_buf();
        stale.pid = Some(3726008);
        stale.controller_generation = Some(2241);

        let stream =
            request_stable_stale_controller_restart(dir.path(), LaunchMode::Lazy, stale, None)
                .expect("the delegated self-recycle's successor is adopted");
        drop(stream);
        let commands = server.join().unwrap();

        assert_eq!(commands, vec!["recycle_force", "status", "<connect>"]);
        let lease = read_predecessor_drain_lease(dir.path()).expect("drain lease recorded");
        assert_eq!((lease.pid, lease.generation), (3726008, 2241));
        assert!(
            agent_doc_controller::recycle::predecessor_drain_lease_protects(
                Some(&lease),
                3726008,
                timestamp_secs()
            ),
            "the draining predecessor must be protected from duplicate reaping"
        );
        let log = gh128_ops_log(&dir);
        assert!(
            log.contains(
                "controller_active_stale_binary_restart_delegated pid=3726008 generation=2241 via=self_recycle"
            ),
            "{log}"
        );
        assert!(
            log.contains("new_pid=2854081 new_generation=2242")
                && log.contains("via=self_recycle_delegated"),
            "{log}"
        );
        assert!(
            !log.contains("controller_reap_signal")
                && !log.contains("controller_detached_child_launched"),
            "the client must neither launch a replacement nor signal the predecessor: {log}"
        );
    }

    /// `#drainingpredecessor`: a stale controller that refuses the delegation
    /// (no controller answers here) falls back to the direct handoff without
    /// leaving a lease that would shield an undrained predecessor from reaping.
    #[test]
    fn stale_restart_delegation_refusal_leaves_no_drain_lease() {
        let dir = async_handoff_test_project();
        let mut stale = active_controller_status_with_handoff_state(ControllerHandoffState::Stable);
        stale.project_root = dir.path().to_path_buf();
        stale.pid = Some(3726008);
        stale.controller_generation = Some(2241);
        let mut claim = None;
        assert!(matches!(
            delegate_stale_restart_to_self_recycle(dir.path(), &stale, &mut claim),
            DelegatedStaleRestart::NotDelegated
        ));
        assert!(read_predecessor_drain_lease(dir.path()).is_none());
        assert!(
            gh128_ops_log(&dir).contains(
                "controller_active_stale_binary_restart_delegation_refused pid=3726008 generation=2241 fallback=direct_handoff"
            ),
            "{}",
            gh128_ops_log(&dir)
        );
    }

    /// `#drainingpredecessor`: duplicate reaping skips exactly the leased,
    /// still-draining predecessor until its deadline; everything else (and the
    /// predecessor after the deadline) stays reapable.
    #[test]
    fn duplicate_reap_skips_leased_draining_predecessor_until_deadline() {
        let dir = async_handoff_test_project();
        record_predecessor_drain_lease(dir.path(), 3726008, 2241, Duration::from_secs(60));
        let now = timestamp_secs();
        assert_eq!(
            reap_candidates_excluding_draining_predecessor(dir.path(), vec![3726008, 1685180], now),
            vec![1685180]
        );
        assert!(gh128_ops_log(&dir).contains(
            "controller_duplicate_reap_protected_draining_predecessor pid=3726008 generation=2241"
        ));
        assert_eq!(
            reap_candidates_excluding_draining_predecessor(
                dir.path(),
                vec![3726008, 1685180],
                now + 61
            ),
            vec![3726008, 1685180]
        );
    }

    /// GH #128 ask 3: a routine stale-binary recycle that declined a target
    /// which was not newer must not re-arm on that same on-disk identity every
    /// debounce; a different identity (a further install) re-arms it.
    #[test]
    fn gh128_declined_target_identity_does_not_rearm_stale_detection() {
        let dir = async_handoff_test_project();
        let mut bootstrap = test_bootstrap(&dir);
        let mut launched = current_binary_identity().unwrap();
        launched.modified_secs = launched.modified_secs.saturating_sub(1);
        bootstrap.controller_binary = Some(launched);
        let runtime = test_controller_runtime(&bootstrap);
        assert!(controller_wants_recycle(runtime.as_ref()));

        runtime.decline_recycle_target(current_binary_identity().ok());
        assert!(!controller_wants_recycle(runtime.as_ref()));

        runtime.decline_recycle_target(Some(gh128_identity("0.35.449", 1)));
        assert!(controller_wants_recycle(runtime.as_ref()));
    }

    /// GH #128: the target version is read FROM the target binary.
    #[test]
    fn gh128_target_binary_identity_reads_version_from_the_binary_on_disk() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::TempDir::new().unwrap();
        let fresh = dir.path().join("agent-doc");
        std::fs::write(&fresh, "#!/bin/sh\necho 'agent-doc 0.35.449'\n").unwrap();
        std::fs::set_permissions(&fresh, std::fs::Permissions::from_mode(0o755)).unwrap();
        let identity = binary_identity_at(&fresh).unwrap();
        assert_eq!(identity.version, "0.35.449");
        assert_eq!(identity.path, fresh);

        let wedged = dir.path().join("agent-doc-wedged");
        std::fs::write(&wedged, "#!/bin/sh\nsleep 5\n").unwrap();
        std::fs::set_permissions(&wedged, std::fs::Permissions::from_mode(0o755)).unwrap();
        assert_eq!(
            probe_agent_doc_binary_version(&wedged, Duration::from_millis(100)),
            None
        );
        assert!(
            probe_agent_doc_binary_version(&dir.path().join("missing"), Duration::from_secs(1))
                .is_none()
        );
    }

    fn command_submit_request_for_test(
        file: Option<PathBuf>,
        name: &str,
        payload_type: &str,
        payload: serde_json::Value,
        command_id: &str,
    ) -> ControllerRequest {
        let payload_bytes = payload.to_string().into_bytes();
        let submit = lazily::CommandSubmit {
            command_id: command_id.to_string(),
            causation_id: command_id.to_string(),
            source: "test-plugin".to_string(),
            target: "project-controller".to_string(),
            namespace: "agent-doc".to_string(),
            name: name.to_string(),
            authority_generation: 0,
            idempotency_key: format!("test:{name}"),
            deadline_ms: 5_000,
            policy: lazily::CommandPolicy {
                dedupe: lazily::DedupePolicy::SameIdempotencyKey,
                supersede: true,
                cancel_on_preempt: true,
            },
            payload_type: payload_type.to_string(),
            payload_hash: "sha256:test".to_string(),
            payload: lazily::IpcValue::Inline(payload_bytes),
            required_features: vec!["causal-receipts".to_string(), "command-events".to_string()],
        };
        let message = lazily::CommandMessage::CommandSubmit(Box::new(submit));
        ControllerRequest {
            command: "editor_command_submit".to_string(),
            file,
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: Some(serde_json::to_string(&message).unwrap()),
            sequence: None,
        }
    }

