    /// `#routelayoutsupersede`: a passive surface generation may replace an
    /// editor route generation while keeping the routed document. The route now
    /// awaits that semantic condition in the layout graph instead of publishing
    /// another competing generation from the RPC handler.
    #[test]
    fn an_editor_route_accepts_newer_semantically_covering_layout_state() {
        let document = "/project/tasks/api.md";
        let desired = |generation, columns: Vec<String>| PaneLayoutDesired {
            generation,
            source_plane_version: None,
            invocation: ControllerTmuxLayoutSyncInvocation {
                columns,
                window: Some("agent-doc".to_string()),
                focus: Some(document.to_string()),
                no_autostart: false,
                exact_visible: true,
                caller_kind: "automatic".to_string(),
                column_order: Default::default(),
                actor_bindings: Vec::new(),
                client_id: None,
            },
            provenance: PaneLayoutProvenance::default(),
        };

        assert_eq!(
            pane_layout_route_await_outcome(
                &TmuxLayoutEffectState::Applying(desired(2, vec![document.to_string()])),
                document,
            ),
            (false, "tmux_effect_in_flight")
        );
        assert_eq!(
            pane_layout_route_await_outcome(
                &TmuxLayoutEffectState::Converged(desired(3, vec![document.to_string()])),
                document,
            ),
            (true, "observed_convergence")
        );
        assert_eq!(
            pane_layout_route_await_outcome(
                &TmuxLayoutEffectState::Converged(desired(
                    4,
                    vec!["/project/tasks/other.md".to_string()],
                )),
                document,
            ),
            (false, PANE_LAYOUT_SUPERSEDED_REASON)
        );
        assert_eq!(
            pane_layout_route_await_outcome(
                &TmuxLayoutEffectState::OperatorOwned(desired(5, vec![document.to_string()])),
                document,
            ),
            (false, "operator_owned_layout")
        );
    }

    #[test]
    fn the_editor_route_handler_publishes_layout_once() {
        let source = include_str!("rpc.rs");
        let route = &source[source
            .find("fn handle_editor_route_rpc_with_layout_delegate(")
            .expect("editor route handler")..];
        let route = &route[..route
            .find("controller_editor_route_layout_converged")
            .expect("layout convergence log")];
        assert_eq!(
            route.matches("route_editor_layout_with_owner(").count(),
            1,
            "the route resolves the main-window owner once (`#crossrootcolumnflip`)"
        );
        let publish = &source[source
            .find("fn publish_editor_route_layout_locally<")
            .expect("local route layout publication")..];
        let publish = &publish[..publish
            .find("Ok((layout_receipt, layout_observations, route_layout_lease))")
            .expect("local publication tail")];
        assert_eq!(
            publish.matches("handle_editor_route_layout(").count(),
            1,
            "semantic supersession belongs to the layout graph, not an RPC republish loop"
        );
    }

    #[test]
    fn controller_request_primes_turn_attribution_before_domain_dispatch() {
        let source = include_str!("rpc.rs");
        let handler = &source[source
            .find("pub(crate) fn handle_request_locked(")
            .expect("controller request handler")..];
        let handler = &handler[..handler
            .find("\nfn serve_document_turn_authority_stream(")
            .expect("next top-level helper")];
        let snapshot = handler
            .find("let bootstrap_snapshot = runtime.bootstrap_snapshot()?")
            .expect("bootstrap snapshot admission");
        let prime = handler
            .find("agent_doc_ops_log_io::prime_turn_attribution(&canonical)")
            .expect("turn attribution prime");
        let dispatch = handler
            .find("match request.command.as_str()")
            .expect("domain command dispatch");

        assert!(
            snapshot < prime && prime < dispatch,
            "turn attribution must resolve at request admission, before any command can acquire a relay or state lock"
        );
    }

