    /// `#handoffrouteforward`: an editor await that reaches the successor before
    /// the predecessor's forward lands is held while that predecessor lives, and
    /// fails explicitly (naming the re-run) once it does not.
    #[test]
    fn an_await_on_the_successor_adopts_a_command_its_predecessor_forwards() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let publisher = {
            let runtime = Arc::clone(&runtime);
            std::thread::spawn(move || {
                std::thread::sleep(Duration::from_millis(50));
                runtime.async_editor_commands.publish(
                    "cmd-forwarded-later",
                    AsyncEditorCommandPhase::Terminal,
                    serde_json::json!({ "command_id": "cmd-forwarded-later", "exit_code": 0 }),
                );
            })
        };
        let adopted = runtime
            .async_editor_commands
            .await_terminal_adopting("cmd-forwarded-later", Duration::from_secs(5), || Some(456))
            .unwrap();
        publisher.join().unwrap();
        assert_eq!(adopted["exit_code"], 0);

        let started = Instant::now();
        let err = runtime
            .async_editor_commands
            .await_terminal_adopting("cmd-never-forwarded", Duration::from_secs(60), || None)
            .unwrap_err();
        assert!(
            started.elapsed() < Duration::from_secs(30),
            "no predecessor: fail at once"
        );
        let message = format!("{err:#}");
        assert!(message.contains("unknown or expired async editor command"));
        assert!(message.contains("re-run the command"), "{message}");
    }

    /// Injected drain clock: `sleep` advances `now`, so a drain bound is pinned
    /// by poll count rather than by wall-clock time.
    struct FakeDrainClock(std::cell::Cell<Instant>);

    impl FakeDrainClock {
        fn new() -> Self {
            Self(std::cell::Cell::new(Instant::now()))
        }
        fn now(&self) -> Instant {
            self.0.get()
        }
        fn sleep(&self, delay: Duration) {
            self.0.set(self.0.get() + delay);
        }
    }

    /// `#handoffrouteforward`: the predecessor's exit waits for its admitted
    /// async workers (which hold no client connection) and tells them the
    /// successor exists — bounded, so a stuck worker cannot pin the process.
    #[test]
    fn the_predecessor_drain_waits_for_admitted_async_workers() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let clients = AtomicUsize::new(0);
        let mut worker = Some(ControllerAsyncEditorCommandGraph::begin_worker(&runtime));
        let clock = FakeDrainClock::new();
        let mut sleeps = 0usize;
        let exit = drain_predecessor_after_promotion(
            &runtime,
            &clients,
            Duration::from_secs(30),
            || clock.now(),
            |delay| {
                clock.sleep(delay);
                sleeps += 1;
                if sleeps == 3 {
                    worker.take();
                }
            },
        );
        assert_eq!(exit, PredecessorDrainExit::default());
        assert_eq!(sleeps, 3, "exit waited for the in-flight worker");
        assert!(runtime.async_editor_commands.successor_promoted());

        let _stuck = ControllerAsyncEditorCommandGraph::begin_worker(&runtime);
        let clock = FakeDrainClock::new();
        let exit = drain_predecessor_after_promotion(
            &runtime,
            &clients,
            Duration::from_millis(200),
            || clock.now(),
            |delay| clock.sleep(delay),
        );
        assert_eq!(
            exit.abandoned_workers, 1,
            "bounded: a stuck worker is reported, not waited forever"
        );
    }

    /// `#replacementdrain` regression (2026-10-20 `agent-doc-bugs.md`): a
    /// supervisor replacement admitted by controller 1504840 had already asked
    /// the stale supervisor to stop when that controller self-recycled. Its
    /// receipt had been returned, so it held no client connection, and the
    /// drain counted only async editor workers (`workers=0`): the predecessor
    /// exited under the replacement and the cold start never ran. A
    /// replacement worker now holds the drain open exactly like an admitted
    /// async worker, and remains bounded by the same budget.
    #[test]
    fn the_predecessor_drain_waits_for_an_in_flight_supervisor_replacement() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let clients = AtomicUsize::new(0);
        let mut replacement = Some(runtime.begin_supervisor_replacement_worker());
        assert_eq!(runtime.supervisor_replacement_worker_count(), 1);
        let clock = FakeDrainClock::new();
        let mut sleeps = 0usize;
        let exit = drain_predecessor_after_promotion(
            &runtime,
            &clients,
            Duration::from_secs(30),
            || clock.now(),
            |delay| {
                clock.sleep(delay);
                sleeps += 1;
                if sleeps == 4 {
                    replacement.take();
                }
            },
        );
        assert_eq!(exit, PredecessorDrainExit::default());
        assert_eq!(sleeps, 4, "exit waited for the replacement to finish");
        assert_eq!(runtime.supervisor_replacement_worker_count(), 0);

        let _stuck = runtime.begin_supervisor_replacement_worker();
        let clock = FakeDrainClock::new();
        let exit = drain_predecessor_after_promotion(
            &runtime,
            &clients,
            Duration::from_millis(200),
            || clock.now(),
            |delay| clock.sleep(delay),
        );
        assert_eq!(
            exit.abandoned_workers, 1,
            "bounded: a stuck replacement is reported, not waited forever"
        );
    }

    /// `#drainingpredecessor` (GH #261): the editor kept 38 connections open to
    /// a promoted predecessor, and the drain waited for them without a bound.
    /// It now retires the predecessor's authority at once and gives open
    /// client connections the lease-length budget, then exits regardless.
    #[test]
    fn an_open_client_connection_cannot_hold_the_predecessor_drain_past_its_budget() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let clients = AtomicUsize::new(38);
        let clock = FakeDrainClock::new();
        let budget = ASYNC_EDITOR_PREDECESSOR_DRAIN_BUDGET;
        let expected_sleeps = budget.as_millis().div_ceil(CONNECT_POLL.as_millis());
        let mut sleeps = 0u128;
        let exit = drain_predecessor_after_promotion(
            &runtime,
            &clients,
            budget,
            || clock.now(),
            |delay| {
                clock.sleep(delay);
                sleeps += 1;
                assert!(
                    sleeps <= expected_sleeps,
                    "an open client connection held the drain past its budget"
                );
            },
        );
        assert_eq!(
            exit,
            PredecessorDrainExit {
                abandoned_clients: 38,
                abandoned_workers: 0,
            }
        );
        assert_eq!(
            sleeps, expected_sleeps,
            "the drain ends exactly at its budget"
        );
        assert!(runtime.successor_promoted());
        assert!(runtime.state_plane_graph.subscribers_retired());
        assert!(
            agent_doc_crdt_relay_io::relay_authority_retired_for_file(
                &dir.path().join("tasks/one.md")
            ),
            "the predecessor's frozen relay hubs no longer answer as authority"
        );
    }

    /// `#drainingpredecessor` (GH #261): the editor's document-turn authority
    /// stream used to end only at `should_stop`, which a draining predecessor
    /// set only after that same stream closed. Promotion must release it, so the
    /// editor reconnects to the successor and the drain can finish.
    #[test]
    fn a_promoted_predecessor_releases_the_editors_authority_streams() {
        // Hang ceiling only: the interleaving is forced by the parked count.
        const HANG_CEILING: Duration = Duration::from_secs(30);
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let file = dir.path().join("tasks/one.md");
        let channel = document_turn_authority_channel(&agent_doc_hash::document_id_for_path(&file));
        let (request, _) = document_turn_authority_stream_request(&file, &channel, None).unwrap();
        let dependency = runtime.state_plane_graph.channel_dependency(&channel);
        let stream_runtime = Arc::clone(&runtime);
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let stream = std::thread::spawn(move || {
            let should_stop = AtomicBool::new(false);
            let mut written = Vec::new();
            let result = serve_document_turn_authority_stream(
                &stream_runtime,
                request,
                &should_stop,
                &mut written,
            );
            let _ = done_tx.send(());
            (result, written)
        });
        let parked_by = Instant::now() + HANG_CEILING;
        while dependency.parked_subscribers.load(Ordering::SeqCst) == 0 {
            assert!(!stream.is_finished(), "the stream ended before parking");
            assert!(Instant::now() < parked_by, "the stream never parked");
            std::thread::yield_now();
        }

        runtime.retire_after_successor_promotion();

        done_rx
            .recv_timeout(HANG_CEILING)
            .expect("a promoted predecessor must end the authority stream");
        let (result, written) = stream.join().unwrap();
        result.unwrap();
        let frames = String::from_utf8(written).unwrap();
        // The stream's own subscription publishes the initial projection
        // asynchronously, so it may land before or after the stream first
        // parks: an optional genuine projection frame, then at most one
        // terminal wake. No frame may follow a timed-out (retirement) frame —
        // that would be the stream spinning after promotion.
        let parsed: Vec<serde_json::Value> = frames
            .lines()
            .map(|line| serde_json::from_str(line).unwrap())
            .collect();
        assert!(
            parsed.len() <= 2,
            "a projection and one wake at most: {frames}"
        );
        for (index, frame) in parsed.iter().enumerate() {
            let last = index + 1 == parsed.len();
            if frame["data"]["timed_out"] == serde_json::Value::Bool(true) {
                assert!(last, "a frame followed the retirement wake: {frames}");
            } else {
                assert!(
                    !frame["data"]["projection"].is_null(),
                    "a non-wake frame must carry a published projection: {frames}"
                );
            }
        }
        // A later subscriber returns immediately instead of parking. Its cursor
        // is ahead of every frame in this generation, so only retirement can
        // return it before the ceiling, whether or not the asynchronous initial
        // projection has landed yet.
        let generation = parsed
            .last()
            .and_then(|frame| frame["data"]["controller_generation"].as_u64())
            .expect("the parked stream wrote at least one frame");
        let started = Instant::now();
        let late =
            runtime.subscribe_state_plane(&channel, Some(generation), u64::MAX, HANG_CEILING);
        assert!(late.timed_out);
        assert!(started.elapsed() < HANG_CEILING);
    }

    /// `#dogfood-authority-channel-retry-loop`: an editor computes the
    /// canonical-path channel while a file exists. If the file is deleted
    /// before reconnect, `document_id_for_path` deliberately falls back to the
    /// display path. The server must derive its own channel from the file
    /// authority instead of rejecting a deterministic stale client key.
    #[test]
    fn a_deleted_document_cannot_wedge_authority_reconnect_on_its_old_channel() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let file = dir.path().join("tasks/one.md");
        let client_channel =
            document_turn_authority_channel(&agent_doc_hash::document_id_for_path(&file));
        let (request, _) =
            document_turn_authority_stream_request(&file, &client_channel, None).unwrap();
        std::fs::remove_file(&file).unwrap();
        let server_channel =
            document_turn_authority_channel(&agent_doc_hash::document_id_for_path(&file));
        assert_ne!(
            client_channel, server_channel,
            "deletion must reproduce the stale client-channel mismatch"
        );

        let should_stop = AtomicBool::new(true);
        let mut written = Vec::new();
        serve_document_turn_authority_stream(&runtime, request, &should_stop, &mut written)
            .expect("the server-derived channel must tolerate a file deleted after subscription");
        assert!(written.is_empty());
    }

    /// `#drainingpredecessor` (GH #261): a promoted predecessor ran the
    /// supervisor watchdog and orphan drain every interval for its whole drain,
    /// re-dispatching an orphan queue head every 90s from a frozen replica.
    #[test]
    fn a_promoted_predecessor_runs_no_watchdog_or_orphan_drain() {
        let dir = async_handoff_test_project();
        let runtime = test_controller_runtime(&test_bootstrap(&dir));
        let interval = Duration::from_secs(90);
        let start = Instant::now();
        let mut last_run = None;
        let mut ran = 0usize;
        assert!(run_controller_background_ticks(
            &runtime,
            &mut last_run,
            interval,
            start,
            |_| ran += 1
        ));
        assert!(!run_controller_background_ticks(
            &runtime,
            &mut last_run,
            interval,
            start + Duration::from_secs(1),
            |_| ran += 1
        ));
        assert!(run_controller_background_ticks(
            &runtime,
            &mut last_run,
            interval,
            start + interval,
            |_| ran += 1
        ));

        runtime.retire_after_successor_promotion();

        for tick in 2..10u32 {
            assert!(!run_controller_background_ticks(
                &runtime,
                &mut last_run,
                interval,
                start + interval * tick,
                |_| ran += 1
            ));
        }
        assert_eq!(ran, 2, "no background tick after promotion");
    }

    /// GH #122 invariant 3: the settle budget covers a handoff whose successor
    /// times out and is retried — the measured 141s window (three aborted
    /// attempts + the promoting one) — and is still bounded.
    #[test]
    fn the_handoff_settle_budget_covers_an_aborted_and_retried_handoff() {
        let measured_window = Duration::from_secs(141);
        assert!(
            CONTROLLER_HANDOFF_SETTLE_BUDGET > measured_window,
            "budget {:?} is shorter than the measured {:?} handoff",
            CONTROLLER_HANDOFF_SETTLE_BUDGET,
            measured_window
        );
        assert!(CONTROLLER_HANDOFF_SETTLE_BUDGET >= HANDOFF_CONNECT_WAIT * 4);
        assert!(CONTROLLER_HANDOFF_SETTLE_BUDGET <= Duration::from_secs(600));
        assert_eq!(
            AsyncEditorHandoffSettle::production().budget,
            CONTROLLER_HANDOFF_SETTLE_BUDGET
        );
    }

