    #[test]
    fn focus_document_pane_missing_policy_is_a_closed_wire_enum() {
        let legacy: FocusDocumentPaneCommandPayload =
            serde_json::from_value(serde_json::json!({ "document_path": "/tmp/legacy.md" }))
                .unwrap();
        assert_eq!(
            legacy.missing_pane_policy,
            MissingFocusPanePolicy::ObserveOnly
        );

        let resume: FocusDocumentPaneCommandPayload = serde_json::from_value(serde_json::json!({
            "document_path": "/tmp/resume.md",
            "missing_pane_policy": "resume_latest"
        }))
        .unwrap();
        assert_eq!(
            resume.missing_pane_policy,
            MissingFocusPanePolicy::ResumeLatest
        );
        let layout: FocusDocumentPaneCommandPayload = serde_json::from_value(serde_json::json!({
            "document_path": "/tmp/layout.md",
            "no_promotion": false,
            "missing_pane_policy": "provision_for_layout"
        }))
        .unwrap();
        assert_eq!(
            layout.effective_policy(),
            MissingFocusPanePolicy::ProvisionForLayout
        );
        assert!(rejected_focus_should_resume_latest(
            layout.effective_policy(),
            FocusPaneRejectReason::ActorNotFocusable,
            Some("closed-session")
        ));
        let focus_only = FocusDocumentPaneCommandPayload {
            no_promotion: true,
            ..layout
        };
        assert_eq!(
            focus_only.effective_policy(),
            MissingFocusPanePolicy::ObserveOnly
        );
        assert!(!rejected_focus_should_resume_latest(
            focus_only.effective_policy(),
            FocusPaneRejectReason::ActorNotFocusable,
            Some("closed-session")
        ));
        assert!(
            serde_json::from_value::<FocusDocumentPaneCommandPayload>(serde_json::json!({
                "document_path": "/tmp/invalid.md",
                "missing_pane_policy": "resume_if_missing"
            }))
            .is_err()
        );
    }

    #[test]
    fn newer_async_focus_admission_fences_the_older_effect() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = test_controller_runtime(&bootstrap);
        let payload = |document: &str| {
            serde_json::json!({
                "project_root": dir.path().display().to_string(),
                "document_path": dir.path().join(document).display().to_string(),
                "active_window_guard": true,
                "missing_pane_policy": "observe_only"
            })
        };
        let first_request = command_submit_request_for_test(
            None,
            "focus_document_pane",
            "agent-doc.focus_document_pane.v1",
            payload("one.md"),
            "cmd-focus-one",
        );
        let second_request = command_submit_request_for_test(
            None,
            "focus_document_pane",
            "agent-doc.focus_document_pane.v1",
            payload("two.md"),
            "cmd-focus-two",
        );
        let (first_submit, first_payload) =
            parse_editor_command_submit_request(&first_request).unwrap();
        let (second_submit, second_payload) =
            parse_editor_command_submit_request(&second_request).unwrap();

        let first = admit_async_editor_focus_fence(
            &bootstrap,
            &runtime.async_editor_commands,
            AsyncEditorCommandKind::FocusDocumentPane,
            &first_submit,
            &first_payload,
        )
        .unwrap();
        assert!(
            runtime
                .async_editor_commands
                .require_focus_fence_current(first.as_ref())
                .is_ok()
        );
        let second = admit_async_editor_focus_fence(
            &bootstrap,
            &runtime.async_editor_commands,
            AsyncEditorCommandKind::FocusDocumentPane,
            &second_submit,
            &second_payload,
        )
        .unwrap();
        let first_err = runtime
            .async_editor_commands
            .require_focus_fence_current(first.as_ref())
            .unwrap_err();
        assert!(format!("{first_err:#}").contains("superseded_focus_intent"));
        assert!(
            runtime
                .async_editor_commands
                .require_focus_fence_current(second.as_ref())
                .is_ok()
        );

        // Completion of the older worker must not clear the newer fence.
        runtime
            .async_editor_commands
            .release_focus_fence(first.as_ref());
        assert!(
            runtime
                .async_editor_commands
                .require_focus_fence_current(second.as_ref())
                .is_ok()
        );
        runtime
            .async_editor_commands
            .release_focus_fence(second.as_ref());
    }

    #[test]
    fn expired_async_focus_is_refused_at_the_effect_boundary() {
        let scope = agent_doc_state_scope::ProcessScope::new();
        let graph = ControllerAsyncEditorCommandGraph::new_in(&scope);
        let fence = AsyncEditorFocusFence {
            project_root: PathBuf::from("/tmp/focus-expiry"),
            command_id: "cmd-expired".to_string(),
            expires_at: Some(std::time::Instant::now()),
        };
        graph.publish_focus_fence(fence.clone());
        assert_eq!(
            graph.focus_fence_decision(&fence),
            AsyncEditorFocusFenceDecision::Expired
        );
    }

