    /// Bound actor whose live process tree was NOT proven to still own the
    /// document — the shape every pre-`#fpeselectstashpane` test described.
    fn unproven_actor(pane_id: &str, focusable: bool) -> FocusActorCandidate<'_> {
        FocusActorCandidate {
            pane_id,
            focusable,
            still_owns_document: false,
        }
    }

    #[test]
    fn focus_candidate_uses_exact_live_owner_when_actor_projection_is_closed() {
        assert_eq!(
            decide_focus_pane_candidate(Some(unproven_actor("%stale", false)), None, Some("%live")),
            FocusPaneCandidateDecision::Candidate {
                pane_id: "%live",
                focused_reason: "focused_live_process_owner",
                not_alive_reason: "live_owner_pane_not_alive",
            },
        );
    }

    #[test]
    fn focus_candidate_uses_exact_live_owner_when_actor_and_registry_are_missing() {
        assert_eq!(
            decide_focus_pane_candidate(None, None, Some("%busy-live")),
            FocusPaneCandidateDecision::Candidate {
                pane_id: "%busy-live",
                focused_reason: "focused_live_process_owner",
                not_alive_reason: "live_owner_pane_not_alive",
            },
        );
    }

    /// `#fpeselectstashpane`: the operator-reported shape. `fpe.md`'s actor
    /// record AND durable registry both name the correct visible pane, while
    /// the session log's `latest_start_pane` still names a superseded pane
    /// whose stale owner process is alive in the `stash` window. The bound pane
    /// wins; a historical start record never outranks the live binding.
    #[test]
    fn focus_candidate_keeps_the_bound_actor_pane_over_a_differing_session_log_owner() {
        assert_eq!(
            decide_focus_pane_candidate(
                Some(FocusActorCandidate {
                    pane_id: "%5",
                    focusable: true,
                    still_owns_document: true,
                }),
                Some("%5"),
                Some("%28"),
            ),
            FocusPaneCandidateDecision::Candidate {
                pane_id: "%5",
                focused_reason: "focused_agent_doc_actor",
                not_alive_reason: "actor_pane_not_alive",
            },
            "a selection effect must use the bound pane, never a live-resolved one",
        );
    }

    /// The guard only ever *demotes* the binding. A bound pane that no longer
    /// runs this document's owner still yields to the proven live owner, so the
    /// reroute / fresh-restart repair path is unchanged.
    #[test]
    fn focus_candidate_reconciles_stale_active_actor_to_new_live_owner() {
        assert_eq!(
            decide_focus_pane_candidate(
                Some(unproven_actor("%old", true)),
                Some("%old"),
                Some("%new"),
            ),
            FocusPaneCandidateDecision::Candidate {
                pane_id: "%new",
                focused_reason: "focused_live_process_owner",
                not_alive_reason: "live_owner_pane_not_alive",
            },
        );
    }

    #[test]
    fn focus_candidate_refuses_unproven_active_actor_instead_of_focusing_wrong_pane() {
        assert_eq!(
            decide_focus_pane_candidate(Some(unproven_actor("%wrong", true)), None, None),
            FocusPaneCandidateDecision::Reject {
                reason: FocusPaneRejectReason::ActorOwnershipUnproven,
                pane_id: Some("%wrong"),
            },
            "a durable actor row without matching live process ownership must never move tmux focus",
        );
    }

    /// A non-focusable actor is never rescued by the bound-pane preference:
    /// `still_owns_document` is gated on `focusable` at the call site, and the
    /// decision re-checks it, so a `Blocked`/`Closed` projection keeps going
    /// through the live-owner / rescue path it always did.
    #[test]
    fn focus_candidate_bound_pane_preference_does_not_revive_a_closed_actor() {
        assert_eq!(
            decide_focus_pane_candidate(
                Some(FocusActorCandidate {
                    pane_id: "%closed",
                    focusable: false,
                    still_owns_document: true,
                }),
                Some("%stale"),
                Some("%live"),
            ),
            FocusPaneCandidateDecision::Candidate {
                pane_id: "%live",
                focused_reason: "focused_live_process_owner",
                not_alive_reason: "live_owner_pane_not_alive",
            },
        );
    }

    #[test]
    fn focus_candidate_still_refuses_closed_actor_without_exact_live_proof() {
        assert_eq!(
            decide_focus_pane_candidate(
                Some(unproven_actor("%closed", false)),
                Some("%stale"),
                None,
            ),
            FocusPaneCandidateDecision::Reject {
                reason: FocusPaneRejectReason::ActorNotFocusable,
                pane_id: Some("%closed"),
            },
        );
    }

    #[test]
    fn actor_not_focusable_reject_is_rescued_when_live_pane_still_owns_the_document() {
        // A Blocked/Closed durable actor whose pane's live process tree still
        // owns the same document is a valid non-mutating focus target — the
        // finished/blocked session's pane is still open and showing that doc.
        assert_eq!(
            focus_reject_rescued_by_live_pane_owner(
                FocusPaneRejectReason::ActorNotFocusable,
                Some("%59"),
                Some("doc-bugs2"),
                "doc-bugs2",
            ),
            Some("%59"),
        );
    }

    #[test]
    fn actor_not_focusable_reject_stands_when_live_pane_owns_a_different_document() {
        // A pane reused by a different document must NOT be focus-stolen.
        assert_eq!(
            focus_reject_rescued_by_live_pane_owner(
                FocusPaneRejectReason::ActorNotFocusable,
                Some("%59"),
                Some("doc-other"),
                "doc-bugs2",
            ),
            None,
        );
        // No live owner proof at all (bare shell / dead) also stands.
        assert_eq!(
            focus_reject_rescued_by_live_pane_owner(
                FocusPaneRejectReason::ActorNotFocusable,
                Some("%59"),
                None,
                "doc-bugs2"
            ),
            None,
        );
        // Only `actor_not_focusable` is rescuable; other rejects are untouched.
        assert_eq!(
            focus_reject_rescued_by_live_pane_owner(
                FocusPaneRejectReason::MissingActorRecord,
                Some("%59"),
                Some("doc-bugs2"),
                "doc-bugs2",
            ),
            None,
        );
    }

    #[test]
    fn resume_latest_policy_crosses_closed_actor_reject_when_session_is_known() {
        assert!(rejected_focus_should_resume_latest(
            MissingFocusPanePolicy::ResumeLatest,
            FocusPaneRejectReason::ActorNotFocusable,
            Some("session"),
        ));
        assert!(rejected_focus_should_resume_latest(
            MissingFocusPanePolicy::ResumeLatest,
            FocusPaneRejectReason::ActorOwnershipUnproven,
            Some("session"),
        ));
        assert!(rejected_focus_should_resume_latest(
            MissingFocusPanePolicy::ResumeLatest,
            FocusPaneRejectReason::MissingActorRecord,
            Some("session"),
        ));
        assert!(!rejected_focus_should_resume_latest(
            MissingFocusPanePolicy::ObserveOnly,
            FocusPaneRejectReason::ActorNotFocusable,
            Some("session"),
        ));
        assert!(!rejected_focus_should_resume_latest(
            MissingFocusPanePolicy::ResumeLatest,
            FocusPaneRejectReason::ActorNotFocusable,
            None,
        ));
    }

    /// Deterministic controller world for the cross-root Sync Tmux Layout
    /// regression. The outer document already owns one physical pane. The
    /// nested document still has a Ready actor row, but that row points at a
    /// pane whose process ownership is unproven and which is no longer in the
    /// window. The model drives the same candidate and recovery predicates as
    /// `handle_focus_document_pane_with_policy`, while making pane creation and
    /// focus attempts explicit effects that the test can assert.
    #[derive(Clone)]
    struct CrossRootSyncLayoutSimWorld {
        documents: [&'static str; 2],
        nested_actor_state: agent_doc_controller::actor::ActorState,
        nested_actor_pane: &'static str,
        panes: Vec<(&'static str, &'static str)>,
        provisioned: Vec<(&'static str, &'static str)>,
        focused: Vec<&'static str>,
    }

    impl CrossRootSyncLayoutSimWorld {
        const OUTER_DOCUMENT: &'static str = "/work/agent-loop/tasks/agent-doc/agent-doc-bugs.md";
        const NESTED_DOCUMENT: &'static str = "/work/agent-loop/src/haiven-dev/tasks/contracts.md";
        const STALE_NESTED_PANE: &'static str = "%dead-or-unproven";
        const REPLACEMENT_NESTED_PANE: &'static str = "%replacement";

        fn new() -> Self {
            Self {
                documents: [Self::OUTER_DOCUMENT, Self::NESTED_DOCUMENT],
                nested_actor_state: agent_doc_controller::actor::ActorState::Ready,
                nested_actor_pane: Self::STALE_NESTED_PANE,
                panes: vec![(Self::OUTER_DOCUMENT, "%outer")],
                provisioned: Vec::new(),
                focused: Vec::new(),
            }
        }

        fn sync(&mut self, policy: MissingFocusPanePolicy) {
            let decision = decide_focus_pane_candidate(
                Some(FocusActorCandidate {
                    pane_id: self.nested_actor_pane,
                    focusable: !matches!(
                        self.nested_actor_state,
                        agent_doc_controller::actor::ActorState::Blocked
                            | agent_doc_controller::actor::ActorState::Closed
                    ),
                    // The actor row says Ready/focusable, but current process
                    // ownership does not prove that this pane owns the doc.
                    still_owns_document: false,
                }),
                None,
                None,
            );

            match decision {
                FocusPaneCandidateDecision::Candidate { pane_id, .. } => {
                    self.focused.push(pane_id);
                }
                FocusPaneCandidateDecision::Reject { reason, .. }
                    if rejected_focus_should_resume_latest(policy, reason, Some("contracts")) =>
                {
                    self.nested_actor_pane = Self::REPLACEMENT_NESTED_PANE;
                    self.panes
                        .push((Self::NESTED_DOCUMENT, Self::REPLACEMENT_NESTED_PANE));
                    self.provisioned
                        .push((Self::NESTED_DOCUMENT, Self::REPLACEMENT_NESTED_PANE));
                }
                FocusPaneCandidateDecision::Reject { .. } => {}
            }
        }

        fn converged(&self) -> bool {
            self.panes.len() == self.documents.len()
                && self
                    .documents
                    .iter()
                    .all(|document| self.panes.iter().any(|(bound, _)| bound == document))
        }
    }

    /// `#sync-cross-root-stale-binding`: Sync Tmux Layout is structural and
    /// must replace a stale Ready actor binding for the nested document. The
    /// passive observe-only path remains effect-free and must never select or
    /// reuse the pane whose document ownership was not proven.
    #[test]
    fn cross_root_sync_layout_replaces_unproven_binding_only_when_provisioning() {
        let initial = CrossRootSyncLayoutSimWorld::new();
        assert_eq!(
            initial.nested_actor_state,
            agent_doc_controller::actor::ActorState::Ready
        );

        let mut observe_only = initial.clone();
        observe_only.sync(MissingFocusPanePolicy::ObserveOnly);
        assert_eq!(observe_only.panes.len(), 1, "observe-only preserves layout");
        assert!(observe_only.provisioned.is_empty());
        assert!(
            observe_only.focused.is_empty(),
            "observe-only must never focus or reuse an ownership-unproven pane"
        );
        assert_eq!(
            observe_only.nested_actor_pane,
            CrossRootSyncLayoutSimWorld::STALE_NESTED_PANE
        );
        assert!(!observe_only.converged());

        let mut provision = initial;
        provision.sync(MissingFocusPanePolicy::ProvisionForLayout);
        assert_eq!(
            provision.provisioned,
            vec![(
                CrossRootSyncLayoutSimWorld::NESTED_DOCUMENT,
                CrossRootSyncLayoutSimWorld::REPLACEMENT_NESTED_PANE,
            )]
        );
        assert_eq!(
            provision.nested_actor_pane,
            CrossRootSyncLayoutSimWorld::REPLACEMENT_NESTED_PANE,
            "the stale cross-root actor binding is replaced"
        );
        assert_eq!(provision.panes.len(), 2);
        assert!(
            provision.converged(),
            "the exact two-document layout converges"
        );
        assert!(
            provision.focused.is_empty(),
            "layout provisioning defers focus to the structural layout effect"
        );
        assert!(
            provision
                .panes
                .iter()
                .all(|(_, pane)| *pane != CrossRootSyncLayoutSimWorld::STALE_NESTED_PANE)
        );
    }

