    #[test]
    fn actor_record_for_active_pane_finds_live_match_and_skips_terminal_states() {
        use agent_doc_controller::actor::{ActorLastTransition, ActorRecord, ActorState};
        use std::collections::BTreeMap;

        fn transition() -> ActorLastTransition {
            ActorLastTransition {
                caller: "test".to_string(),
                reason: "test".to_string(),
                timestamp: 0,
                prior_generation: 0,
                new_generation: 1,
            }
        }
        fn record(document_id: &str, pane_id: &str, state: ActorState) -> ActorRecord {
            ActorRecord {
                document_id: document_id.to_string(),
                session_id: "s".to_string(),
                generation: 1,
                pane_id: pane_id.to_string(),
                window_id: "@1".to_string(),
                harness: "claude".to_string(),
                state,
                last_transition: transition(),
            }
        }

        let mut store: BTreeMap<String, ActorRecord> = BTreeMap::new();
        store.insert(
            "a".to_string(),
            record("tasks/a.md", "%11", ActorState::Ready),
        );
        store.insert(
            "b".to_string(),
            record("tasks/b.md", "%22", ActorState::Blocked),
        );
        store.insert(
            "c".to_string(),
            record("tasks/c.md", "%33", ActorState::Closed),
        );

        // Live match is returned.
        let hit = actor_record_for_active_pane(&store, "%11").unwrap();
        assert_eq!(hit.document_id, "tasks/a.md");

        // Terminal-state panes never own the active focus.
        assert!(actor_record_for_active_pane(&store, "%22").is_none());
        assert!(actor_record_for_active_pane(&store, "%33").is_none());

        // Unknown pane resolves to None so the caller falls back to the
        // process-owner (/proc) probe.
        assert!(actor_record_for_active_pane(&store, "%99").is_none());
    }

    #[test]
    fn structurally_assigned_outgoing_actor_is_not_operator_owned() {
        use agent_doc_controller::actor::{ActorLastTransition, ActorRecord, ActorState};

        let project_root = Path::new("/project");
        let outgoing = "/project/tasks/outgoing.md".to_string();
        let actor = ActorRecord {
            document_id: outgoing.clone(),
            session_id: "outgoing-session".to_string(),
            generation: 7,
            pane_id: "%2".to_string(),
            window_id: "@1".to_string(),
            harness: "codex".to_string(),
            state: ActorState::Busy,
            last_transition: ActorLastTransition {
                caller: "test".to_string(),
                reason: "turn_in_progress".to_string(),
                timestamp: 0,
                prior_generation: 6,
                new_generation: 7,
            },
        };
        let actor_store = BTreeMap::from([(outgoing.clone(), actor)]);
        let physical_panes = vec!["%1".to_string(), "%2".to_string()];
        let expected_documents = vec!["/project/tasks/current.md".to_string()];

        let scope = agent_doc_state_scope::ProcessScope::new();
        let actors = ControllerActorGraph::new_in(&scope, actor_store.clone());
        let graph = ControllerPaneLayoutGraph::new_in(&scope, actors.live_bindings_handle());
        let mut invocation = ControllerTmuxLayoutSyncInvocation {
            columns: vec![outgoing.clone()],
            window: None,
            focus: None,
            no_autostart: false,
            exact_visible: true,
            caller_kind: "automatic".into(),
            column_order: Default::default(),
            actor_bindings: Vec::new(),
            client_id: None,
        };
        let old = graph.set_desired(invocation.clone(), None);
        graph.record_structural_assignment(
            &old,
            graph.actor_bindings(),
            None,
            vec![(outgoing.clone(), "%2".into())],
        );
        invocation.columns = expected_documents.clone();
        graph.set_desired(invocation, None);
        // This is the worker's actual evidence path, including a nonempty actor
        // session and a changed desired layout. Neither may drop ownership.
        assert!(
            layout_sync_state_operator_owned_documents(
                project_root,
                &expected_documents,
                &physical_panes,
                &actor_store,
                &graph.ctx.get(&graph.owned_assignments),
                &[],
            )
            .is_empty()
        );

        assert_eq!(
            layout_sync_state_operator_owned_documents(
                project_root,
                &expected_documents,
                &physical_panes,
                &actor_store,
                &[],
                &[],
            ),
            vec![outgoing.clone()],
            "without a controller receipt the unexpected live actor remains operator-owned",
        );
        assert!(
            layout_sync_state_operator_owned_documents(
                project_root,
                &expected_documents,
                &physical_panes,
                &actor_store,
                &[(outgoing, "%2".to_string())],
                &[],
            )
            .is_empty(),
            "a superseded structural effect remains controller-owned and must be reconciled by the newest exact-visible generation",
        );
    }

