    #[test]
    fn controller_local_state_event_reaches_live_graph_without_project_reload() {
        // A dedicated worker owns the same thread-local ingress context as a
        // production request; no socket or ledger replay may supply the result.
        std::thread::spawn(|| {
            let dir = tempfile::TempDir::new().unwrap();
            let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();
            install_controller_request_thread_context(&runtime);
            let document_hash = "local-compact-document".to_string();
            // The compact mutation is retained until the editor's save receipt.
            // Keep that frontier pending so the continuation cannot settle yet.
            append_apply_state_event(
                &runtime.bootstrap_snapshot().unwrap(),
                &runtime,
                agent_doc_state_backbone::StateEvent::new(
                    "local-compact-write",
                    agent_doc_state_backbone::StateFact::DocumentWriteDeferred {
                        document_hash: document_hash.clone(),
                        intent_id: "compact-write".to_string(),
                        expected_hash: agent_doc_hash::content_hash("base"),
                        expected_content: Some("base".to_string()),
                        target_hash: agent_doc_hash::content_hash("live"),
                        target_content: "live".to_string(),
                        source: agent_doc_state_backbone::DocumentWriteSource::PendingWrite,
                        reason: agent_doc_state_backbone::DocumentWriteDeferredReason::EditorProjectionPending,
                    },
                ),
            ).unwrap();
            let event = agent_doc_state_backbone::StateEvent::new(
                "local-compact-continuation",
                agent_doc_state_backbone::StateFact::DocumentCompactProjectionRetained {
                    document_hash: document_hash.clone(),
                    continuation_id: "compact-local".to_string(),
                    retained_at_ms: 100,
                    file: dir.path().join("session.md").to_string_lossy().into_owned(),
                    live_content: "live".to_string(),
                    committed_content: "committed".to_string(),
                    target_component: Some("exchange".to_string()),
                    commit: true,
                },
            );

            assert!(publish_state_event(dir.path(), &event).unwrap());
            let projected = runtime.document_state_projection(&document_hash).unwrap();
            assert!(
                projected
                    .is_some_and(|document| document.document.pending_compact_projection.is_some()),
                "a local compact continuation must enter the live graph before its RPC returns"
            );
            assert!(!publish_state_event(dir.path(), &event).unwrap());
        })
        .join()
        .unwrap();
    }

    #[test]
    fn controller_request_does_not_claim_another_projects_local_runtime() {
        // A spanning editor surface can reconcile a nested project while the
        // outer project's controller request is active on this thread. The
        // nested publication must use that project's controller IPC path.
        std::thread::spawn(|| {
            let outer = tempfile::TempDir::new().unwrap();
            let nested = tempfile::TempDir::new().unwrap();
            let runtime = ControllerRuntime::new_arc(test_bootstrap(&outer)).unwrap();
            install_controller_request_thread_context(&runtime);

            assert!(agent_doc_state_wire::in_controller_request());
            assert!(
                local_controller_runtime_for_project(outer.path())
                    .unwrap()
                    .is_some()
            );
            assert!(
                local_controller_runtime_for_project(nested.path())
                    .unwrap()
                    .is_none(),
                "a controller request is process-local, not authority for every project root"
            );
        })
        .join()
        .unwrap();
    }

    #[test]
    fn duplicate_state_event_ingress_does_not_republish_captured_finalize_wake() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/session.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "# Session\n").unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let event = agent_doc_state_backbone::StateEvent::new(
            "deduplicated-captured-finalize-wake",
            agent_doc_state_backbone::StateFact::ResponseCaptured {
                document_hash,
                cycle_id: "cycle-1".to_string(),
                capture_id: "capture-1".to_string(),
                response_sha256: "response-1".to_string(),
                response_body: Some("response body".to_string()),
                intent_body: None,
                mutation_plan_json: None,
                file_hash: None,
                snapshot_hash: None,
                baseline_content: None,
            },
        );
        let request = || ControllerRequest {
            command: "state_event_append".to_string(),
            file: Some(doc.clone()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: Some("test_state_source".to_string()),
            reason: Some("prove_duplicate_ingress_is_quiet".to_string()),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: Some(serde_json::to_string(&event).unwrap()),
            sequence: None,
        };

        assert!(handle_state_event_append(&bootstrap, &runtime, request()).unwrap());
        let first = runtime.subscribe_state_plane(
            CAPTURED_FINALIZE_WAKE_STATE_CHANNEL,
            None,
            0,
            Duration::ZERO,
        );
        assert_eq!(first.frames.len(), 1, "the inserted event publishes once");

        assert!(
            !handle_state_event_append(&bootstrap, &runtime, request()).unwrap(),
            "the durable ledger rejects the duplicate identity"
        );
        let replay = runtime.subscribe_state_plane(
            CAPTURED_FINALIZE_WAKE_STATE_CHANNEL,
            Some(first.controller_generation),
            first.latest_version,
            Duration::ZERO,
        );
        assert!(replay.timed_out);
        assert!(
            replay.frames.is_empty(),
            "a deduplicated event must not manufacture another reactive wake"
        );
    }

    #[test]
    fn command_plane_submit_dispatch_reaches_closeout_authority_and_returns_receipt() {
        // `#lzdurablesink` live transport (server half): a `command_plane_submit`
        // controller request carries a `CommandSubmit` envelope, the dispatch
        // routes it by `(namespace, name)` to `service_closeout_advance`, the
        // authority decides from the live Lazily projection, sinks the fact, and
        // the terminal `CausalReceipt` (applied) comes back in the response
        // envelope — never a transport ACK. This is the in-process proof that
        // `service_closeout_advance` is now reachable from a client request.
        use super::command_plane::{
            CloseoutAdvancePayload, CloseoutPhaseEvent, build_closeout_advance_submit,
        };

        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/dispatch.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();

        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();

        let submit = build_closeout_advance_submit(
            "cmd-dispatch-1",
            "cycle_state",
            "doc:cycle:write_applied:body",
            1,
            CloseoutAdvancePayload {
                document_path: doc.to_string_lossy().to_string(),
                event: CloseoutPhaseEvent::WriteApplied,
                event_label: None,
                reason: None,
                snapshot_content: None,
                file_content: Some("body".to_string()),
                response_sha256: None,
                cycle_id_hint: None,
                terminal_turn_fence: None,
            },
        )
        .unwrap();

        // Frame the submit exactly as the live `ControllerCommandTransport` does:
        // serialized into the request's `diagnostic_payload`.
        let request =
            ControllerRequest::command_plane_submit(serde_json::to_string(&submit).unwrap());
        let line = serde_json::to_string(&request).unwrap();
        let mut should_stop = false;
        let response = handle_request_locked(&line, &runtime, &mut should_stop).unwrap();

        let envelope: serde_json::Value = serde_json::from_str(&response).unwrap();
        assert_eq!(envelope["ok"], true, "envelope should be ok: {envelope}");
        let receipt: lazily::CausalReceipt =
            serde_json::from_value(envelope["data"].clone()).unwrap();
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Applied);
        assert_eq!(receipt.causation_id, submit.command_id);

        // The durable sink fired through the dispatched authority path: the live
        // projection now observes WriteApplied.
        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let phase = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .and_then(|d| d.closeout.phase);
        assert_eq!(phase, Some(agent_doc_turn::CyclePhase::WriteApplied));
    }

    #[test]
    fn editor_op_capture_update_serializes_complete_lazily_epoch() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/op-capture.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();

        for (nonce, ops_json) in [
            ("one", r#"[{"insert":"a"}]"#),
            ("two", r#"[{"insert":"b"}]"#),
        ] {
            let request: ControllerRequest = serde_json::from_value(serde_json::json!({
                "command": "editor_op_capture_update",
                "file": doc,
                "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                    "action": "append",
                    "base_hash": "base-a",
                    "ops_json": ops_json,
                    "updated_ms": 10,
                    "event_nonce": nonce,
                })).unwrap(),
            }))
            .unwrap();
            assert!(handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap());
        }

        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let projected = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap();
        let capture = projected
            .document
            .editor_op_capture
            .expect("active capture");
        assert_eq!(capture.epoch, 1);
        assert_eq!(
            serde_json::from_str::<Vec<serde_json::Value>>(&capture.ops_json)
                .unwrap()
                .len(),
            2,
            "same-base callbacks must serialize into one complete checkpoint"
        );

        let ops_before_touch = capture.ops_json.clone();
        let request: ControllerRequest = serde_json::from_value(serde_json::json!({
            "command": "editor_op_capture_update",
            "file": doc,
            "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                "action": "touch",
                "updated_ms": 15_000,
                "event_nonce": "raced-drain",
            })).unwrap(),
        }))
        .unwrap();
        assert!(handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap());
        let projected = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap();
        let capture = projected
            .document
            .editor_op_capture
            .as_ref()
            .expect("activity refresh preserves active capture");
        assert_eq!(
            capture.epoch, 1,
            "activity refresh must not rotate the epoch"
        );
        assert_eq!(
            capture.ops_json, ops_before_touch,
            "activity refresh must not duplicate ops"
        );
        assert_eq!(capture.updated_ms, 15_000);
        assert_eq!(
            compact_document_admission(Some(&projected), 20_000),
            CompactDocumentAdmission::DeferActiveTyping {
                retry_after_ms: 5_000,
            },
            "a raced editor drain must keep Compact Exchange behind the quiet window",
        );

        let request: ControllerRequest = serde_json::from_value(serde_json::json!({
            "command": "editor_op_capture_update",
            "file": doc,
            "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                "action": "clear",
                "event_nonce": "clear",
            })).unwrap(),
        }))
        .unwrap();
        assert!(handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap());
        let projected = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap();
        assert!(projected.document.editor_op_capture.is_none());
        assert_eq!(projected.document.editor_op_capture_generation, 2);
    }

    /// `#keylogrebase` on the live controller: an attested burst opens its
    /// epoch at the text it was typed into, chains on the attested tip across a
    /// change of the stamped merge baseline, and re-bases after a projection
    /// fence instead of inheriting the lagging baseline's hash.
    #[test]
    fn editor_op_capture_update_bases_attested_bursts_on_their_pre_text() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/op-lineage.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let send = |payload: serde_json::Value| {
            let request: ControllerRequest = serde_json::from_value(serde_json::json!({
                "command": "editor_op_capture_update",
                "file": doc,
                "diagnostic_payload": serde_json::to_string(&payload).unwrap(),
            }))
            .unwrap();
            handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap();
        };
        let append = |nonce: &str, stamped: &str, pre: &str, post: &str| {
            serde_json::json!({
                "action": "append",
                "base_hash": stamped,
                "ops_json": r#"[{"kind":"insert","offset":0,"text":"x"}]"#,
                "updated_ms": 10,
                "event_nonce": nonce,
                "lineage": {"pre_hash": pre, "post_hash": post},
            })
        };
        let active = || {
            runtime
                .document_state_projection(&document_hash)
                .unwrap()
                .and_then(|document| document.document.editor_op_capture)
        };

        // Compaction fenced the epoch; the editor stamps the stale baseline.
        send(serde_json::json!({"action": "clear", "event_nonce": "fence"}));
        send(append("one", "pre-compaction", "compacted", "t1"));
        let capture = active().expect("attested burst opens an epoch");
        assert_eq!(capture.base_hash, "compacted");
        assert_eq!(capture.tip_hash, "t1");
        let opened = capture.epoch;

        // The commit advanced the baseline: the stamp changes, the chain holds.
        send(append("two", "compacted", "t1", "t2"));
        let capture = active().unwrap();
        assert_eq!(capture.epoch, opened);
        assert_eq!(capture.base_hash, "compacted");
        assert_eq!(capture.tip_hash, "t2");
        assert_eq!(
            serde_json::from_str::<Vec<serde_json::Value>>(&capture.ops_json)
                .unwrap()
                .len(),
            2
        );

        // An activity refresh keeps the tip.
        send(serde_json::json!({"action": "touch", "updated_ms": 20, "event_nonce": "touch"}));
        assert_eq!(active().unwrap().tip_hash, "t2");

        // A burst that does not start at the tip re-bases on its own pre-text.
        send(append("three", "compacted", "elsewhere", "t3"));
        let capture = active().unwrap();
        assert!(capture.epoch > opened);
        assert_eq!(capture.base_hash, "elsewhere");
        assert_eq!(capture.tip_hash, "t3");
    }

    /// `#editoropscheckpointfail`: during a typing burst the state-ingress lock
    /// can be held by a durable reload far past the editor's 250ms response
    /// budget. Every editor append queued behind it times out client-side and
    /// is re-sent with its original nonce — while the stalled original is still
    /// applied late. Each burst must land exactly once regardless.
    #[test]
    fn editor_op_capture_append_resend_after_ingress_stall_applies_each_burst_once() {
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/op-capture.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let append = |nonce: String| -> ControllerRequest {
            serde_json::from_value(serde_json::json!({
                "command": "editor_op_capture_update",
                "file": doc,
                "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                    "action": "append",
                    "base_hash": "base-a",
                    "ops_json": serde_json::json!([{ "insert": nonce }]).to_string(),
                    "updated_ms": 10,
                    "event_nonce": nonce,
                }))
                .unwrap(),
            }))
            .unwrap()
        };

        const BURSTS: usize = 8;
        let stalled = std::sync::Arc::new(std::sync::Barrier::new(2));
        let stall = {
            let runtime = runtime.clone();
            let root = bootstrap.project_root.clone();
            let stalled = stalled.clone();
            std::thread::spawn(move || {
                let _ingress =
                    runtime.lock_state_event_ingress(&root, "refresh_memory", "durable_reload");
                stalled.wait();
                std::thread::sleep(Duration::from_millis(300));
            })
        };
        stalled.wait();
        // Originals and their re-sends race each other into the stalled
        // controller, exactly as a timed-out editor and its drainer do.
        let senders: Vec<_> = (0..BURSTS)
            .flat_map(|index| [index, index])
            .map(|index| {
                let (bootstrap, runtime) = (bootstrap.clone(), runtime.clone());
                let request = append(format!("burst-{index}"));
                std::thread::spawn(move || {
                    handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap()
                })
            })
            .collect();
        let inserted = senders
            .into_iter()
            .map(|sender| sender.join().unwrap())
            .filter(|inserted| *inserted)
            .count();
        stall.join().unwrap();
        assert_eq!(
            inserted, BURSTS,
            "exactly one of each original/re-send pair appends"
        );

        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let capture = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap()
            .document
            .editor_op_capture
            .expect("active capture");
        let mut ops: Vec<String> =
            serde_json::from_str::<Vec<serde_json::Value>>(&capture.ops_json)
                .unwrap()
                .into_iter()
                .map(|op| op["insert"].as_str().unwrap().to_string())
                .collect();
        ops.sort();
        let mut expected: Vec<String> = (0..BURSTS).map(|index| format!("burst-{index}")).collect();
        expected.sort();
        assert_eq!(ops, expected, "no burst lost and none duplicated");

        // A late re-send after the epoch closed must not resurrect the burst.
        // Within one epoch the durable event id already deduplicates; across an
        // epoch boundary only the applied-nonce ledger does, so this is the
        // discriminating case.
        let request: ControllerRequest = serde_json::from_value(serde_json::json!({
            "command": "editor_op_capture_update",
            "file": doc,
            "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                "action": "clear",
                "event_nonce": "clear",
            })).unwrap(),
        }))
        .unwrap();
        assert!(handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap());
        assert!(
            !handle_editor_op_capture_update(&bootstrap, &runtime, append("burst-0".into()))
                .unwrap(),
            "a re-send of an applied burst is acknowledged without appending"
        );
        let projected = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap();
        assert!(projected.document.editor_op_capture.is_none());
    }

    /// `#refreshmemlockstall`: a `refresh_memory` durable reload must never run
    /// its full ledger replay under `state_event_ingress`. It used to: when an
    /// append raced the unlocked load (the common case during a typing burst)
    /// the whole load was redone under the lock, a 1-4s replay on a real
    /// ledger, and every editor-op append queued behind it blew its 250ms
    /// budget (sdk.md, 2026-10-11). The hook below runs inside every full
    /// durable load and issues a real editor-op append from another thread;
    /// each must complete while that load is still in progress. The race the
    /// first append creates is then repaired from the delta alone, and the
    /// raced append survives the swap.
    #[test]
    fn editor_op_append_is_not_blocked_by_a_durable_reload_in_progress() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/reload-race.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let bootstrap = test_bootstrap(&dir);
        let runtime = ControllerRuntime::new_arc(bootstrap.clone()).unwrap();
        let append = {
            let doc = doc.clone();
            move |nonce: String| -> ControllerRequest {
                serde_json::from_value(serde_json::json!({
                    "command": "editor_op_capture_update",
                    "file": doc,
                    "diagnostic_payload": serde_json::to_string(&serde_json::json!({
                        "action": "append",
                        "base_hash": "base-a",
                        "ops_json": serde_json::json!([{ "insert": nonce }]).to_string(),
                        "updated_ms": 10,
                        "event_nonce": nonce,
                    }))
                    .unwrap(),
                }))
                .unwrap()
            }
        };
        // A non-empty ledger, so the snapshot and the delta are distinguishable.
        for index in 0..4 {
            assert!(
                handle_editor_op_capture_update(
                    &bootstrap,
                    &runtime,
                    append(format!("seed-{index}"))
                )
                .unwrap()
            );
        }

        let full_loads = std::sync::Arc::new(AtomicUsize::new(0));
        let blocked = std::sync::Arc::new(AtomicUsize::new(0));
        let stragglers = std::sync::Arc::new(parking_lot::Mutex::new(Vec::new()));
        {
            let (bootstrap, runtime, append) = (bootstrap.clone(), runtime.clone(), append.clone());
            let (full_loads, blocked, stragglers) =
                (full_loads.clone(), blocked.clone(), stragglers.clone());
            super::super::set_full_durable_load_test_hook(Some(Box::new(move || {
                let load = full_loads.fetch_add(1, Ordering::SeqCst);
                let (done_tx, done_rx) = std::sync::mpsc::channel();
                let (bootstrap, runtime) = (bootstrap.clone(), runtime.clone());
                let request = append(format!("during-load-{load}"));
                let sender = std::thread::spawn(move || {
                    let inserted =
                        handle_editor_op_capture_update(&bootstrap, &runtime, request).unwrap();
                    let _ = done_tx.send(inserted);
                });
                // The reload waits for the append, so an append that queues
                // behind a reload holding ingress can never finish: the bound
                // only turns that deadlock into a failure, it is not the sync.
                // `#remainingwallclock`: a 30s hang ceiling, not a 10s budget.
                match done_rx.recv_timeout(Duration::from_secs(30)) {
                    Ok(inserted) => {
                        assert!(inserted);
                        sender.join().unwrap();
                    }
                    Err(_) => {
                        blocked.fetch_add(1, Ordering::SeqCst);
                        stragglers.lock().push(sender);
                    }
                }
            })));
        }
        let refreshed = runtime.refresh_memory();
        super::super::set_full_durable_load_test_hook(None);
        for sender in stragglers.lock().drain(..) {
            sender.join().unwrap();
        }
        refreshed.unwrap();

        assert_eq!(
            blocked.load(Ordering::SeqCst),
            0,
            "an editor-op append issued during a durable load waited on the reload's ingress lock"
        );
        assert_eq!(
            full_loads.load(Ordering::SeqCst),
            1,
            "the race is repaired from the delta, never by a second full load"
        );
        let ops =
            std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap_or_default();
        assert!(
            ops.contains("controller_refresh_memory_caught_up_after_concurrent_apply rows=1 "),
            "only the raced append is folded under the lock:\n{ops}"
        );

        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let capture = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap()
            .document
            .editor_op_capture
            .expect("active capture");
        let mut ops: Vec<String> =
            serde_json::from_str::<Vec<serde_json::Value>>(&capture.ops_json)
                .unwrap()
                .into_iter()
                .map(|op| op["insert"].as_str().unwrap().to_string())
                .collect();
        ops.sort();
        assert_eq!(
            ops,
            ["during-load-0", "seed-0", "seed-1", "seed-2", "seed-3"],
            "the append that raced the reload survives the swap"
        );
    }

    #[test]
    fn command_plane_submit_unknown_name_fails_closed_as_rejected_receipt() {
        // Every command resolves to a terminal receipt: an unknown command name
        // fails closed as a `rejected` receipt (with the command id) so the client
        // resolves instead of hanging on a non-terminal ACK.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();

        let mut submit = super::command_plane::build_supervisor_recycle_submit(
            "cmd-unknown-1",
            "cycle_state",
            "root:unknown",
            "x",
            1,
        )
        .unwrap();
        // Same namespace, but a name no service is wired to yet.
        submit.name = "nonexistent_op".to_string();
        let request =
            ControllerRequest::command_plane_submit(serde_json::to_string(&submit).unwrap());
        let line = serde_json::to_string(&request).unwrap();
        let mut should_stop = false;
        let response = handle_request_locked(&line, &runtime, &mut should_stop).unwrap();

        let envelope: serde_json::Value = serde_json::from_str(&response).unwrap();
        assert_eq!(envelope["ok"], true, "envelope should be ok: {envelope}");
        let receipt: lazily::CausalReceipt =
            serde_json::from_value(envelope["data"].clone()).unwrap();
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Rejected);
        assert_eq!(receipt.causation_id, submit.command_id);
        assert!(
            receipt
                .reason
                .as_deref()
                .unwrap()
                .contains("nonexistent_op")
        );
    }

    #[test]
    fn command_plane_submit_foreign_namespace_refused() {
        // The controller is the `agent-doc` namespace authority; a foreign
        // namespace is refused at the envelope boundary (envelope error), not
        // routed to a domain service.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();

        let mut submit = super::command_plane::build_supervisor_recycle_submit(
            "cmd-foreign-1",
            "cycle_state",
            "root:foreign",
            "x",
            1,
        )
        .unwrap();
        submit.namespace = "not-agent-doc".to_string();
        let request =
            ControllerRequest::command_plane_submit(serde_json::to_string(&submit).unwrap());
        let line = serde_json::to_string(&request).unwrap();
        let mut should_stop = false;
        let response = handle_request_locked(&line, &runtime, &mut should_stop).unwrap();

        let envelope: serde_json::Value = serde_json::from_str(&response).unwrap();
        assert_eq!(
            envelope["ok"], false,
            "foreign namespace must be refused: {envelope}"
        );
        assert!(
            envelope["error"]
                .as_str()
                .unwrap()
                .contains("foreign namespace")
        );
    }

    #[test]
    fn closeout_advance_authority_decides_from_live_projection_and_sinks_fact() {
        // `#lzdurablesink`: the authority services a closeout_advance CommandSubmit
        // from its live Lazily projection — no state.db replay — advances the pure
        // phase machine, emits the fact(s) as the durable sink, and returns a
        // terminal CausalReceipt (applied). With no prior state the machine
        // synthesizes a PreflightStarted cycle and advances it to WriteApplied.
        use super::command_plane::{
            CloseoutAdvancePayload, CloseoutPhaseEvent, build_closeout_advance_submit,
        };

        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/authority.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();

        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();
        let bootstrap = runtime.bootstrap_snapshot().unwrap();

        let submit = build_closeout_advance_submit(
            "cmd-authority-1",
            "cycle_state",
            "doc:cycle:write_applied:body",
            1,
            CloseoutAdvancePayload {
                document_path: doc.to_string_lossy().to_string(),
                event: CloseoutPhaseEvent::WriteApplied,
                event_label: None,
                reason: None,
                snapshot_content: None,
                file_content: Some("body".to_string()),
                response_sha256: None,
                cycle_id_hint: None,
                terminal_turn_fence: None,
            },
        )
        .unwrap();

        let receipt = service_closeout_advance(&bootstrap, &runtime, &submit);
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Applied);

        // The durable sink fired: the live projection now observes WriteApplied.
        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let phase = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .and_then(|d| d.closeout.phase);
        assert_eq!(phase, Some(agent_doc_turn::CyclePhase::WriteApplied));
    }

    #[test]
    fn closeout_advance_authority_routes_committed_and_abandoned() {
        // All four transitions route through the authority on the command plane.
        // Seed WriteApplied, then advance Committed(CommitSuccess); also verify
        // Abandoned on a fresh open cycle reaches the Abandoned phase. Each step
        // returns an applied CausalReceipt and the live projection advances.
        use super::command_plane::{
            CloseoutAdvancePayload, CloseoutPhaseEvent, CommitObservation,
            build_closeout_advance_submit,
        };

        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/routed.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();
        let bootstrap = runtime.bootstrap_snapshot().unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&doc);
        let mk = |command_id: &str, event: CloseoutPhaseEvent, reason: Option<&str>| {
            build_closeout_advance_submit(
                command_id,
                "cycle_state",
                format!("doc:cycle:{command_id}"),
                1,
                CloseoutAdvancePayload {
                    document_path: doc.to_string_lossy().to_string(),
                    event,
                    event_label: None,
                    reason: reason.map(str::to_string),
                    snapshot_content: None,
                    file_content: Some("body".to_string()),
                    response_sha256: None,
                    cycle_id_hint: None,
                    terminal_turn_fence: None,
                },
            )
            .unwrap()
        };

        // PreflightStarted → WriteApplied → Committed.
        let receipt = service_closeout_advance(
            &bootstrap,
            &runtime,
            &mk("wa", CloseoutPhaseEvent::WriteApplied, None),
        );
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Applied);
        let receipt = service_closeout_advance(
            &bootstrap,
            &runtime,
            &mk(
                "cm",
                CloseoutPhaseEvent::Committed(CommitObservation::CommitSuccess),
                None,
            ),
        );
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Applied);
        let phase = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .and_then(|d| d.closeout.phase);
        assert_eq!(phase, Some(agent_doc_turn::CyclePhase::Committed));

        // A fresh document with an open cycle can be abandoned through the authority.
        let dir2 = tempfile::TempDir::new().unwrap();
        let doc2 = dir2.path().join("tasks/abandon.md");
        std::fs::create_dir_all(doc2.parent().unwrap()).unwrap();
        std::fs::write(&doc2, "body").unwrap();
        let runtime2 = ControllerRuntime::new_arc(test_bootstrap(&dir2)).unwrap();
        let bootstrap2 = runtime2.bootstrap_snapshot().unwrap();
        let submit = build_closeout_advance_submit(
            "ab",
            "cycle_state",
            "doc:cycle:ab",
            1,
            CloseoutAdvancePayload {
                document_path: doc2.to_string_lossy().to_string(),
                event: CloseoutPhaseEvent::Abandoned,
                event_label: None,
                reason: Some("stalled_preflight".to_string()),
                snapshot_content: None,
                file_content: None,
                response_sha256: None,
                cycle_id_hint: None,
                terminal_turn_fence: None,
            },
        )
        .unwrap();
        let receipt = service_closeout_advance(&bootstrap2, &runtime2, &submit);
        assert_eq!(receipt.outcome, lazily::ReceiptOutcome::Applied);
        let phase2 = runtime2
            .document_state_projection(&agent_doc_hash::document_id_for_path(&doc2))
            .unwrap()
            .and_then(|d| d.closeout.phase);
        assert_eq!(phase2, Some(agent_doc_turn::CyclePhase::Abandoned));
    }

    #[test]
    fn closeout_advance_terminal_fence_preserves_cycle_after_turn_activation() {
        use super::command_plane::{
            CloseoutAdvancePayload, CloseoutPhaseEvent, CommitObservation,
            build_closeout_advance_submit,
        };

        let dir = tempfile::TempDir::new().unwrap();
        let doc = dir.path().join("tasks/fenced.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body").unwrap();
        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();
        let bootstrap = runtime.bootstrap_snapshot().unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&doc);

        let open = build_closeout_advance_submit(
            "fenced-open",
            "cycle_state",
            "doc:cycle:fenced-open",
            1,
            CloseoutAdvancePayload {
                document_path: doc.to_string_lossy().to_string(),
                event: CloseoutPhaseEvent::WriteApplied,
                event_label: None,
                reason: None,
                snapshot_content: None,
                file_content: Some("body".to_string()),
                response_sha256: None,
                cycle_id_hint: None,
                terminal_turn_fence: None,
            },
        )
        .unwrap();
        assert_eq!(
            service_closeout_advance(&bootstrap, &runtime, &open).outcome,
            lazily::ReceiptOutcome::Applied,
        );
        let projected = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .unwrap();
        let cycle_id = agent_doc_cycle_state_io::reconstruct_cycle_state(&projected)
            .unwrap()
            .unwrap()
            .cycle_id;

        agent_doc_session_actor_io::record_session_start_direct(
            &doc,
            "session-fenced",
            "%91",
            "@9",
            1,
        )
        .unwrap();
        let conn = agent_doc_sqlite::state_store::open_state_db(dir.path()).unwrap();
        agent_doc_sqlite::state_store::upsert_coordination_lease_in_db(
            &conn,
            &agent_doc_sqlite::state_store::CoordinationLeaseRecord {
                scope_kind: "turn_active".to_string(),
                scope_id: "%91".to_string(),
                holder: "%91".to_string(),
                holder_pid: Some(std::process::id()),
                heartbeat_secs: timestamp_secs(),
            },
        )
        .unwrap();
        let terminal = build_closeout_advance_submit(
            "fenced-terminal",
            "cycle_state",
            "doc:cycle:fenced-terminal",
            1,
            CloseoutAdvancePayload {
                document_path: doc.to_string_lossy().to_string(),
                event: CloseoutPhaseEvent::Committed(CommitObservation::CommitSuccess),
                event_label: None,
                reason: None,
                snapshot_content: None,
                file_content: Some("body".to_string()),
                response_sha256: None,
                cycle_id_hint: Some(cycle_id),
                terminal_turn_fence: Some(
                    agent_doc_cycle_state_io::command_plane::TerminalTurnFence {
                        session_id: Some("session-fenced".to_string()),
                        pane_id: Some("%91".to_string()),
                        generation: Some(1),
                    },
                ),
            },
        )
        .unwrap();

        assert_eq!(
            service_closeout_advance(&bootstrap, &runtime, &terminal).outcome,
            lazily::ReceiptOutcome::Applied,
            "a lost terminal CAS is an applied no-op on the command plane",
        );
        let phase = runtime
            .document_state_projection(&document_hash)
            .unwrap()
            .and_then(|document| document.closeout.phase);
        assert_eq!(phase, Some(agent_doc_turn::CyclePhase::WriteApplied));
    }

