    #[test]
    fn mark_write_applied_routes_through_command_plane_when_controller_live() {
        // `#lzdurablesink` / `#lazily-hot-path`: with a live controller, the
        // `mark_write_applied` chokepoint submits a `closeout_advance` command
        // over the command plane instead of the local load→decide→save→append
        // path. The controller authority decides from the live projection, sinks
        // the fact, and returns a terminal applied receipt; the client reads back
        // the advanced cycle state. End-to-end proof through the real controller
        // socket (not `handle_request_locked` in-process).
        let dir = tempfile::TempDir::new().unwrap();
        let project_root = dir.path().to_path_buf();
        std::fs::create_dir_all(project_root.join("tasks")).unwrap();
        let doc = project_root.join("tasks/live.md");
        std::fs::write(&doc, "body\n").unwrap();

        let server_root = project_root.clone();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let handle = std::thread::spawn(move || {
            serve_announcing_ready(&server_root, LaunchMode::Lazy, ready_tx).unwrap()
        });
        wait_for_test_controller(&project_root, &ready_rx);

        let state = agent_doc_cycle_state_io::mark_write_applied(
            &doc,
            "write_applied",
            None,
            Some("body\n"),
        )
        .expect("mark_write_applied through the command plane");
        assert_eq!(state.phase, agent_doc_turn::CyclePhase::WriteApplied);

        // The durable sink fired through the controller authority: a fresh
        // client read reconstructs WriteApplied from the sunk facts.
        let readback = agent_doc_cycle_state_io::load(&doc)
            .expect("read back cycle state")
            .expect("a cycle state exists");
        assert_eq!(readback.phase, agent_doc_turn::CyclePhase::WriteApplied);

        let shutdown = request_with_reason(&project_root, "shutdown", "test_shutdown").unwrap();
        assert!(shutdown.contains("\"ok\":true"), "{shutdown}");
        handle.join().unwrap();
    }

    #[test]
    fn mark_committed_and_abandoned_route_through_command_plane_when_controller_live() {
        // The remaining closeout transitions route through the command plane:
        // write_applied → committed (the caller's free-text label canonicalizes
        // to the typed CommitObservation on the wire), and abandoned (the
        // descriptive reason rides the `reason` field; the authority stamps it
        // back as last_event).
        let dir = tempfile::TempDir::new().unwrap();
        let project_root = dir.path().to_path_buf();
        std::fs::create_dir_all(project_root.join("tasks")).unwrap();
        let doc = project_root.join("tasks/live.md");
        std::fs::write(&doc, "body\n").unwrap();

        let server_root = project_root.clone();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let handle = std::thread::spawn(move || {
            serve_announcing_ready(&server_root, LaunchMode::Lazy, ready_tx).unwrap()
        });
        wait_for_test_controller(&project_root, &ready_rx);

        agent_doc_cycle_state_io::mark_write_applied(&doc, "write_applied", None, Some("body\n"))
            .expect("write_applied through the command plane");
        let committed =
            agent_doc_cycle_state_io::mark_committed(&doc, "commit_success", None, Some("body\n"))
                .expect("mark_committed through the command plane");
        assert_eq!(committed.phase, agent_doc_turn::CyclePhase::Committed);
        // The command plane carries the typed CommitObservation, so the canonical
        // label is stamped back as last_event.
        assert_eq!(committed.last_event, "commit_success");

        // `mark_committed` routes through the command plane (the caller's label
        // rides the event_label payload field). A re-commit on an already-
        // committed cycle refreshes and keeps the stable label, so "repair_applied"
        // folds onto the existing "commit_success".
        let refreshed =
            agent_doc_cycle_state_io::mark_committed(&doc, "repair_applied", None, Some("body\n"))
                .expect("mark_committed (re-commit) through the command plane");
        assert_eq!(refreshed.phase, agent_doc_turn::CyclePhase::Committed);
        assert_eq!(
            refreshed.last_event, "commit_success",
            "re-commit refreshes onto the existing stable commit label"
        );

        // Abandon on a fresh open cycle: the descriptive reason round-trips as last_event.
        let doc2 = project_root.join("tasks/abandon.md");
        std::fs::write(&doc2, "body\n").unwrap();
        let abandoned = agent_doc_cycle_state_io::mark_abandoned(
            &doc2,
            "stalled_preflight",
            None,
            Some("body\n"),
        )
        .expect("mark_abandoned through the command plane");
        assert_eq!(abandoned.phase, agent_doc_turn::CyclePhase::Abandoned);
        assert_eq!(abandoned.last_event, "stalled_preflight");

        let shutdown = request_with_reason(&project_root, "shutdown", "test_shutdown").unwrap();
        assert!(shutdown.contains("\"ok\":true"), "{shutdown}");
        handle.join().unwrap();
    }

    #[test]
    fn closeout_owner_claim_and_release_route_through_command_plane_dispatch() {
        // `#lzdurablesink` todo (3): the command-plane dispatch routes
        // closeout_owner_claim / closeout_owner_release and returns the typed CAS
        // result (Acquired / HeldByOther), not a coarse receipt — the authority
        // result for a coordination op is preserved. The live-socket transport is
        // already proven by the mark_write_applied integration test, so this
        // exercises the dispatch + service in-process (mirroring the CAS test).
        use super::command_plane::{
            CloseoutOwnerClaimPayload, CloseoutOwnerReleasePayload,
            build_closeout_owner_claim_submit, build_closeout_owner_release_submit,
        };
        use agent_doc_state_backbone::{CloseoutOwnerClaimOutcome, CloseoutOwnerClaimRequest};

        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/owner-cp.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(&doc, "body\n").unwrap();
        let cycle = agent_doc_cycle_state_io::start_preflight(&doc, Some("body\n"), Some("body\n"))
            .unwrap();

        let runtime = ControllerRuntime::new_arc(test_bootstrap(&dir)).unwrap();
        let bootstrap = runtime.bootstrap_snapshot().unwrap();

        let claim_submit = |owner_id: &str| {
            build_closeout_owner_claim_submit(
                format!("closeout-owner-claim:{owner_id}"),
                format!("closeout-owner-claim:{owner_id}"),
                0,
                CloseoutOwnerClaimPayload {
                    document_path: doc.to_string_lossy().to_string(),
                    request: CloseoutOwnerClaimRequest {
                        expected_cycle_id: Some(cycle.cycle_id.clone()),
                        owner_id: owner_id.to_string(),
                        owner_pid: std::process::id(),
                        role: "test_closeout".to_string(),
                        now_secs: 10,
                        lease_secs: 30,
                        allow_dead_owner_takeover: true,
                    },
                },
            )
            .unwrap()
        };

        let first = serde_json::from_value::<CloseoutOwnerClaimOutcome>(
            dispatch_command_plane_submit(&bootstrap, runtime.as_ref(), &claim_submit("owner-1"))
                .unwrap(),
        )
        .unwrap();
        assert!(matches!(
            first,
            CloseoutOwnerClaimOutcome::Acquired(ref p) if p.owner_id == "owner-1"
        ));
        let second = serde_json::from_value::<CloseoutOwnerClaimOutcome>(
            dispatch_command_plane_submit(&bootstrap, runtime.as_ref(), &claim_submit("owner-2"))
                .unwrap(),
        )
        .unwrap();
        assert!(matches!(
            second,
            CloseoutOwnerClaimOutcome::HeldByOther(ref p) if p.owner_id == "owner-1"
        ));

        // Release owner-1 over the command plane, then owner-2 can claim.
        let release = build_closeout_owner_release_submit(
            "closeout-owner-release",
            "closeout-owner-release",
            0,
            CloseoutOwnerReleasePayload {
                document_path: doc.to_string_lossy().to_string(),
                cycle_id: cycle.cycle_id.clone(),
                owner_id: "owner-1".to_string(),
                reason: "finished".to_string(),
                released_secs: 11,
            },
        )
        .unwrap();
        // The owner process may span an install: its CLI is then older than the
        // promoted controller. The exact capability release must still cross
        // the stale-binary gate, or its five-minute lease wedges repair and the
        // Stop hook even though the foreground closeout already finished.
        let request = ControllerRequest::command_plane_submit(
            serde_json::to_string(&release).expect("encode release submit"),
        );
        let mut request_value = serde_json::to_value(request).unwrap();
        request_value.as_object_mut().unwrap().insert(
            "binary_version".to_string(),
            serde_json::Value::String("0.0.0-older-owner".to_string()),
        );
        let mut should_stop = false;
        let response = handle_request_locked(
            &serde_json::to_string(&request_value).unwrap(),
            &runtime,
            &mut should_stop,
        )
        .unwrap();
        let released: ControllerEnvelope<bool> = serde_json::from_str(&response).unwrap();
        assert!(released.ok, "stale owner release was refused: {response}");
        assert_eq!(released.data, Some(true));
        let reclaimed = serde_json::from_value::<CloseoutOwnerClaimOutcome>(
            dispatch_command_plane_submit(&bootstrap, runtime.as_ref(), &claim_submit("owner-2"))
                .unwrap(),
        )
        .unwrap();
        assert!(matches!(
            reclaimed,
            CloseoutOwnerClaimOutcome::Acquired(ref p) if p.owner_id == "owner-2"
        ));
    }

    #[test]
    fn detached_controller_exits_when_temp_project_root_is_removed() {
        let dir = tempfile::TempDir::new().unwrap();
        let project_root = dir.path().to_path_buf();
        let server_root = project_root.clone();
        let (tx, rx) = std::sync::mpsc::channel();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let handle = std::thread::spawn(move || {
            let result = serve_announcing_ready(&server_root, LaunchMode::Lazy, ready_tx)
                .map_err(|err| err.to_string());
            let _ = tx.send(result);
        });
        wait_for_test_controller(&project_root, &ready_rx);

        remove_root_despite_concurrent_writers(dir);
        // Recreate the same path before the next idle tick. A path-existence check
        // cannot distinguish this new directory from the controller's original
        // project root; the retained incarnation must.
        std::fs::create_dir_all(&project_root).unwrap();

        let result = rx
            // Loaded CI runners can delay the detached controller's reaper
            // beyond two seconds even though its normal polling cadence is
            // much shorter. Keep the assertion bounded without turning
            // scheduler contention into a release-gating failure.
            // `#remainingwallclock`: a hang ceiling, not a reaper budget.
            .recv_timeout(Duration::from_secs(60))
            .expect("controller should exit after its temp project root is removed");
        assert_eq!(result, Ok(()));
        handle.join().unwrap();
        std::fs::remove_dir_all(&project_root).unwrap();
    }

    /// Remove a served test root and prove it is gone (`#detachedexitci`).
    ///
    /// `TempDir`'s drop ignores removal errors. A controller thread that writes
    /// into the root while `remove_dir_all` walks it (an exit-watcher reap, an
    /// idle-tick state.db open) makes the final `rmdir` fail with `ENOTEMPTY`,
    /// and the root silently survives with its original inode. Retry until the
    /// path is gone so the test's precondition actually holds; each attempt
    /// removes what the last writer added.
    fn remove_root_despite_concurrent_writers(dir: tempfile::TempDir) {
        let root = dir.path().to_path_buf();
        let mut last = match dir.close() {
            Ok(()) => return,
            Err(err) => err,
        };
        for _ in 0..100 {
            match std::fs::remove_dir_all(&root) {
                Ok(()) => return,
                Err(err) if err.kind() == ErrorKind::NotFound => return,
                Err(err) => last = err,
            }
        }
        panic!("test root {} could not be removed: {last}", root.display());
    }

    /// Serve `project_root` in-process and return the serve result channel once
    /// the listener is ready.
    fn serve_test_root_in_process(
        project_root: &Path,
    ) -> (
        std::sync::mpsc::Receiver<std::result::Result<(), String>>,
        std::thread::JoinHandle<()>,
    ) {
        let server_root = project_root.to_path_buf();
        let (tx, rx) = std::sync::mpsc::channel();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let handle = std::thread::spawn(move || {
            let result = serve_announcing_ready(&server_root, LaunchMode::Lazy, ready_tx)
                .map_err(|err| err.to_string());
            let _ = tx.send(result);
        });
        wait_for_test_controller(project_root, &ready_rx);
        (rx, handle)
    }

    /// A root whose name does not start with `.tmp`, so the 60s detached-temp
    /// idle exit cannot end the controller and mask the exit under test.
    fn non_temp_shaped_root() -> tempfile::TempDir {
        tempfile::Builder::new()
            .prefix("detachedexitci-")
            .tempdir()
            .unwrap()
    }

    #[cfg(unix)]
    fn inode(path: &Path) -> u64 {
        use std::os::unix::fs::MetadataExt;
        std::fs::symlink_metadata(path).unwrap().ino()
    }

    /// `#detachedexitci`: CI run 38837770714. The test's `TempDir` removal raced
    /// a controller-side writer: `remove_dir_all` unlinked the socket and the
    /// ledger, the writer recreated `.agent-doc/state.db`, and the final `rmdir`
    /// failed. The root and `.agent-doc` kept their original inodes, so the
    /// root-incarnation check passed and the controller served a gutted root
    /// with no socket until the 60s temp-root idle exit, which lost the race
    /// against the test's 60s ceiling. This replays that end state directly.
    #[cfg(unix)]
    #[test]
    fn controller_exits_when_its_public_socket_is_unlinked_under_a_surviving_root() {
        let dir = non_temp_shaped_root();
        let project_root = dir.path().to_path_buf();
        let (rx, handle) = serve_test_root_in_process(&project_root);
        let state_dir = project_root.join(".agent-doc");
        let (root_inode, state_dir_inode) = (inode(&project_root), inode(&state_dir));

        // What `remove_dir_all` finished before its `rmdir` failed: every file
        // directly under `.agent-doc` is gone, the directories remain.
        for entry in std::fs::read_dir(&state_dir).unwrap().flatten() {
            if !entry.file_type().unwrap().is_dir() {
                std::fs::remove_file(entry.path()).unwrap();
            }
        }
        // The concurrent writer: an exit-watcher reap recreates the ledger.
        agent_doc_sqlite::reliable_sync_inbox::record_local_liveness(
            &agent_doc_sqlite::state_store::state_db_path(&project_root),
            "controller-alive:4100001",
            1,
            "[]",
        )
        .unwrap();
        assert_eq!(
            (inode(&project_root), inode(&state_dir)),
            (root_inode, state_dir_inode),
            "precondition: the root keeps its incarnation, so only the socket check can see this"
        );

        let result = rx
            // `#remainingwallclock`: a hang ceiling, not a reaper budget. The
            // exit happens on the next idle tick.
            .recv_timeout(Duration::from_secs(60))
            .expect("a controller whose public socket was unlinked must exit");
        assert_eq!(result, Ok(()));
        handle.join().unwrap();
    }

    /// `#detachedexitci`: a controller whose public pathname another listener
    /// now owns is unreachable and must exit, and it must not unlink that
    /// listener's socket on the way out.
    #[cfg(unix)]
    #[test]
    fn controller_exits_without_unlinking_a_public_socket_another_listener_now_owns() {
        let dir = non_temp_shaped_root();
        let project_root = dir.path().to_path_buf();
        let (rx, handle) = serve_test_root_in_process(&project_root);
        let public_sock = socket_path(&project_root);

        std::fs::remove_file(&public_sock).unwrap();
        let foreign = std::os::unix::net::UnixListener::bind(&public_sock).unwrap();
        let foreign_inode = inode(&public_sock);

        let result = rx
            // `#remainingwallclock`: a hang ceiling, not a reaper budget.
            .recv_timeout(Duration::from_secs(60))
            .expect("a controller whose public pathname was rebound must exit");
        assert_eq!(result, Ok(()));
        handle.join().unwrap();
        assert_eq!(
            std::fs::symlink_metadata(&public_sock)
                .ok()
                .map(|_| inode(&public_sock)),
            Some(foreign_inode),
            "the exiting controller unlinked the socket another listener owns"
        );
        drop(foreign);
    }

    #[cfg(unix)]
    #[test]
    fn controller_socket_incarnation_tracks_the_bound_listener_file() {
        let dir = tempfile::tempdir().unwrap();
        let sock = dir.path().join("controller.sock");
        let listener = std::os::unix::net::UnixListener::bind(&sock).unwrap();
        let incarnation = ControllerSocketIncarnation::capture(&sock);
        assert!(incarnation.identity.is_some());
        assert!(incarnation.still_published_at(&sock));

        // A promotion `rename` keeps the identity.
        let promoted = dir.path().join("promoted.sock");
        std::fs::rename(&sock, &promoted).unwrap();
        assert!(incarnation.still_published_at(&promoted));
        assert!(!incarnation.still_published_at(&sock), "unlinked pathname");

        // The original listener stays open, as a serving controller's does: a
        // bound socket pins its inode, so the rebound file cannot reuse it.
        std::fs::remove_file(&promoted).unwrap();
        let _rebound = std::os::unix::net::UnixListener::bind(&promoted).unwrap();
        assert!(
            !incarnation.still_published_at(&promoted),
            "another listener bound at the same pathname"
        );
        drop(listener);
    }

    #[test]
    fn public_socket_loss_is_judged_only_for_a_stable_controller_outside_a_handoff() {
        let lost = ControllerSocketIncarnation {
            identity: Some((u64::MAX, u64::MAX)),
        };
        let gone = Path::new("/nonexistent-detachedexitci/controller.sock");
        assert!(controller_public_socket_lost(
            &lost, gone, false, false, false
        ));
        assert!(
            !controller_public_socket_lost(&lost, gone, true, false, false),
            "a replacement on its temp socket belongs to the stranded-replacement watchdog"
        );
        assert!(
            !controller_public_socket_lost(&lost, gone, false, true, false),
            "an outgoing self-handoff replaces the public pathname on purpose"
        );
        assert!(
            !controller_public_socket_lost(&lost, gone, false, false, true),
            "a promoted predecessor drains; its successor owns the pathname"
        );
        let untracked = ControllerSocketIncarnation { identity: None };
        assert!(
            !controller_public_socket_lost(&untracked, gone, false, false, false),
            "a platform without filesystem sockets never judges loss"
        );
    }

