    #[test]
    fn connect_or_launch_adopts_controller_published_during_launch_claim_contention() {
        // #suprecyclelock / #1j8q: a self-recycled supervisor can re-run `start`
        // while another project-root launcher still owns the bootstrap endpoint.
        // If that holder publishes a healthy controller before the waiter gives
        // up, the waiter must connect to it instead of surfacing os-error-11.
        let dir = tempfile::TempDir::new().unwrap();
        let project_root = dir.path().to_path_buf();
        let held_claim = LaunchClaim::acquire(&project_root).unwrap();

        // `#ctrliotestflake`: this used to race wall-clock. The waiter was given a
        // fixed 150ms lock wait and the publish was timed with a bare 25ms sleep,
        // so the adoption marker only appeared when the controller happened to be
        // published inside that window — too early and the caller's PRE-lock
        // status check adopts with no marker, too late (a loaded machine) and the
        // waiter fails outright. Order the phases explicitly instead: the caller
        // blocks on a lock wait long enough that it never expires, the publish
        // happens only after the caller signals it is about to contend, and
        // releasing `held_claim` is what lets the waiter through. It then adopts
        // via the `phase=acquired` marker path rather than the timeout one, with
        // no timing budget to blow.
        let (entering_tx, entering_rx) = std::sync::mpsc::channel::<()>();
        let caller_root = project_root.clone();
        let caller = std::thread::spawn(move || {
            let stream = connect_or_launch_with_claim_wait_and_before_claim(
                &caller_root,
                LaunchMode::Lazy,
                Duration::from_secs(30),
                || entering_tx.send(()).unwrap(),
            )?;
            drop(stream);
            Ok::<(), anyhow::Error>(())
        });

        // The caller is about to take the pre-lock status check (which must find
        // no controller) and then block on the held lock.
        entering_rx.recv().unwrap();
        let server_root = project_root.clone();
        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
        let server = std::thread::spawn(move || {
            let started = Instant::now();
            loop {
                // Each attempt gets its own sender; a failed attempt drops it
                // unsent and the retry announces through the next clone.
                match serve_announcing_ready(&server_root, LaunchMode::Lazy, ready_tx.clone()) {
                    Ok(()) => return Ok::<(), anyhow::Error>(()),
                    Err(err)
                        if err.to_string().contains("database is locked")
                            && started.elapsed() < Duration::from_secs(30) =>
                    {
                        std::thread::sleep(Duration::from_millis(25));
                    }
                    Err(err) => return Err(err),
                }
            }
        });
        wait_for_test_controller(&project_root, &ready_rx);

        // Only now may the contended waiter proceed: it waited, so it must adopt
        // the controller published while it was blocked.
        drop(held_claim);
        let result = caller.join().unwrap();
        assert!(
            result.is_ok(),
            "contended waiter should adopt the published controller, not fail: {:?}",
            result.err().map(|err| err.to_string())
        );

        let ops_log = std::fs::read_to_string(project_root.join(".agent-doc/logs/ops.log"))
            .unwrap_or_default();
        assert!(
            ops_log.contains("controller_launch_claim_waiter_adopted_published_controller"),
            "contended adoption proof marker missing:\n{ops_log}"
        );
        assert!(
            !ops_log.contains("controller launch already in progress"),
            "the historical launch-contention error must not be logged:\n{ops_log}"
        );

        let shutdown = request_with_reason(&project_root, "shutdown", "test_shutdown").unwrap();
        assert!(shutdown.contains("\"ok\":true"), "{shutdown}");
        server.join().unwrap().unwrap();
    }

    /// GH #146: publishing the command-plane socket and serving a complete
    /// status receipt are separate launch phases. Claim contention must adopt
    /// the socket in that interval so the caller's real RPC can report the
    /// document-level blocker instead of a bootstrap-lock error.
    #[test]
    fn connect_or_launch_adopts_published_socket_before_status_is_ready() {
        let dir = tempfile::TempDir::new().unwrap();
        let project_root = dir.path().to_path_buf();
        let held_claim = LaunchClaim::acquire(&project_root).unwrap();
        let mut server = None;
        let mut release_server = None;

        let stream = connect_or_launch_with_claim_wait_and_before_claim(
            &project_root,
            LaunchMode::Lazy,
            Duration::ZERO,
            || {
                let sock = socket_path(&project_root);
                std::fs::create_dir_all(sock.parent().unwrap()).unwrap();
                let name = sock.to_fs_name::<GenericFilePath>().unwrap();
                let listener = ListenerOptions::new().name(name).create_sync().unwrap();
                let (release_tx, release_rx) = std::sync::mpsc::channel::<()>();
                release_server = Some(release_tx);
                server = Some(std::thread::spawn(move || {
                    // The status probe reaches the newly-published socket, but
                    // the controller is still hydrating and closes without a
                    // receipt. The following raw connect is the adoption.
                    {
                        let status_stream = listener.accept().unwrap();
                        let (reader_half, _writer_half) = status_stream.split();
                        let mut request = String::new();
                        BufReader::new(reader_half).read_line(&mut request).unwrap();
                        assert!(request.contains("status"), "{request}");
                    }
                    let _adopted_stream = listener.accept().unwrap();
                    release_rx.recv().unwrap();
                }));
            },
        )
        .expect("the published socket should be adopted while status hydrates");

        drop(stream);
        release_server.unwrap().send(()).unwrap();
        server.unwrap().join().unwrap();
        drop(held_claim);

        let ops_log = std::fs::read_to_string(project_root.join(".agent-doc/logs/ops.log"))
            .unwrap_or_default();
        assert!(
            ops_log.contains(
                "controller_launch_claim_waiter_adopted_published_socket phase=timeout status=not_ready"
            ),
            "published-socket adoption proof marker missing:\n{ops_log}",
        );
        assert!(
            !ops_log.contains("controller launch already in progress"),
            "the launch race must not shadow the caller's real RPC:\n{ops_log}",
        );
    }

    #[test]
    fn controller_session_operator_status_reports_history_and_command_stages() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/operator.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-operator\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        let bootstrap = test_bootstrap(&dir);
        let mut should_stop = false;
        agent_doc_session_actor_io::record_session_start_direct(
            &doc,
            "session-operator",
            "%41",
            "@1",
            1,
        )
        .unwrap();
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-operator",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Ready,
            "supervisor",
            "prompt_ready",
        )
        .unwrap();

        let operator_command = ControllerRequest {
            command: "operator_command".to_string(),
            file: Some(doc.clone()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("session_clear".to_string()),
            diagnostic_payload: Some("test operator command".to_string()),
            sequence: None,
        };
        let response = handle_request(
            &(serde_json::to_string(&operator_command).unwrap() + "\n"),
            &bootstrap,
            &mut should_stop,
        )
        .unwrap();
        let envelope: ControllerEnvelope<DispatchAuthorization> =
            serde_json::from_str(&response).unwrap();
        assert!(envelope.ok);
        let authorization = envelope.data.unwrap();
        assert_eq!(authorization.accepted_stage, "operator_ready");
        assert!(authorization.receipt.receipt_id > 0);
        assert_eq!(
            authorization.receipt.status,
            ControllerDispatchResultStatus::Accepted
        );
        assert_eq!(
            authorization.receipt.proof_scope,
            ControllerDispatchProofScope::AcceptedOnly
        );

        let status = ControllerRequest {
            command: "session_status".to_string(),
            file: Some(doc.clone()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: None,
            sequence: None,
        };
        let response = handle_request(
            &(serde_json::to_string(&status).unwrap() + "\n"),
            &bootstrap,
            &mut should_stop,
        )
        .unwrap();
        let envelope: ControllerEnvelope<SessionOperatorStatus> =
            serde_json::from_str(&response).unwrap();
        assert!(envelope.ok);
        let status = envelope.data.unwrap();
        assert_eq!(
            status.record.unwrap().state,
            agent_doc_controller::actor::ActorState::Ready
        );
        assert_eq!(status.transitions.len(), 2);
        let attempt = status.dispatch_attempts.last().unwrap();
        assert_eq!(attempt.receipt_id, authorization.receipt.receipt_id);
        assert_eq!(attempt.accepted_stage.as_deref(), Some("operator_ready"));
        assert_eq!(attempt.result_status.as_deref(), Some("accepted"));
        assert_eq!(attempt.proof_scope.as_deref(), Some("accepted_only"));
        assert!(!attempt.dispatch_start_proven);
    }

    #[test]
    fn clear_authorization_waits_out_a_non_authoritative_controller_generation() {
        // `#clearunobservedrecycle`: Clear used to accept against a retiring
        // controller and immediately inject through a supervisor whose actor pane
        // was still being recycled. The pane never rendered `/clear`, leaving the
        // submit verifier with `submission_unobserved`. The operator-command
        // acceptance must instead be the retryable barrier: only the promoted
        // controller may issue the one durable acceptance receipt.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/clear-during-recycle.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-clear-recycle\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        let bootstrap = test_bootstrap(&dir);
        agent_doc_session_actor_io::record_session_start_direct(
            &doc,
            "session-clear-recycle",
            "%42",
            "@1",
            1,
        )
        .unwrap();
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-clear-recycle",
            "%42",
            Some(1),
            agent_doc_controller::actor::ActorState::Ready,
            "supervisor",
            "prompt_ready",
        )
        .unwrap();

        let operator_command = ControllerRequest {
            command: "operator_command".to_string(),
            file: Some(doc.clone()),
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("session_clear".to_string()),
            diagnostic_payload: Some("clear during controller recycle".to_string()),
            sequence: None,
        };
        let mut attempts = 0usize;
        let authorization = retry_controller_handoff_refusal(
            &doc,
            "operator_command",
            Duration::from_secs(1),
            Duration::ZERO,
            |_| {},
            || {
                attempts += 1;
                let mut generation = bootstrap.clone();
                generation.handoff_state = if attempts < 3 {
                    ControllerHandoffState::Preparing
                } else {
                    ControllerHandoffState::Stable
                };
                handle_operator_command(&generation, None, operator_command.clone())
            },
        )
        .unwrap();

        assert_eq!(attempts, 3, "clear must wait for controller promotion");
        assert_eq!(authorization.accepted_stage, "operator_ready");
        let status = session_operator_status(dir.path(), &doc).unwrap();
        assert_eq!(
            status.dispatch_attempts.len(),
            1,
            "retiring generations must not write false acceptance receipts"
        );
        assert_eq!(
            status.dispatch_attempts[0].receipt_id,
            authorization.receipt.receipt_id
        );
    }

