    #[test]
    fn dead_supervisor_cold_start_failure_reaches_admission_caller() {
        let (admission_sender, admission_receiver) = std::sync::mpsc::sync_channel(1);
        let result = complete_deferred_supervisor_replacement_admission::<()>(
            &admission_sender,
            Err(anyhow::anyhow!("Unterminated frontmatter block")),
        );

        assert!(result.is_err());
        let admission = admission_receiver.recv().unwrap();
        assert_eq!(
            admission.unwrap_err(),
            "Unterminated frontmatter block",
            "a failed dead-supervisor cold start must not publish false acceptance"
        );
    }

    #[test]
    fn dead_supervisor_cold_start_success_completes_admission() {
        let (admission_sender, admission_receiver) = std::sync::mpsc::sync_channel(1);
        let pane = complete_deferred_supervisor_replacement_admission(
            &admission_sender,
            Ok("%19".to_string()),
        )
        .unwrap();

        assert_eq!(pane, "%19");
        assert_eq!(admission_receiver.recv().unwrap(), Ok(()));
    }

    /// A plain controller recycle: no operator "Restart Agent" intent attached.
    const fn recycle_intent(mode: SupervisorReplacementMode) -> SupervisorReplacementIntent {
        SupervisorReplacementIntent {
            mode,
            restart_agent: false,
        }
    }

    #[test]
    fn supervisor_replacement_preserves_only_bare_shell_panes() {
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                false,
                None,
                Some("claude"),
                false,
            ),
            SupervisorReplacementPaneDecision::AutoStartNew
        );
        for shell in ["sh", "bash", "zsh", "-zsh", "fish"] {
            assert_eq!(
                supervisor_replacement_pane_start_decision(
                    recycle_intent(SupervisorReplacementMode::Continue),
                    true,
                    Some(shell),
                    Some("claude"),
                    false,
                ),
                SupervisorReplacementPaneDecision::PreserveExistingShell,
                "{shell} should be safe for shell-command cold start"
            );
        }
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                true,
                None,
                Some("claude"),
                false,
            ),
            SupervisorReplacementPaneDecision::BlockLiveNonShell,
            "unknown command on a live pane is not safe for prompt injection"
        );
    }

    /// Continue-mode replaces the supervisor, not the conversation. Fresh-mode
    /// is the explicit operator authorization to quit and relaunch the harness.
    #[test]
    fn supervisor_replacement_preserves_or_restarts_own_harness_by_mode() {
        for harness in ["claude", "codex", "opencode"] {
            assert_eq!(
                supervisor_replacement_pane_start_decision(
                    recycle_intent(SupervisorReplacementMode::Continue),
                    true,
                    Some(harness),
                    Some(harness),
                    false,
                ),
                SupervisorReplacementPaneDecision::PreserveLiveHarness,
                "{harness} continue-mode recovery must preserve the live child"
            );
            assert_eq!(
                supervisor_replacement_pane_start_decision(
                    recycle_intent(SupervisorReplacementMode::Fresh),
                    true,
                    Some(harness),
                    Some(harness),
                    false,
                ),
                SupervisorReplacementPaneDecision::RestartLiveHarness,
                "{harness} fresh-mode recovery may restart the live child"
            );
        }
    }

    /// The guard that matters is NARROWED, not removed. A live pane running
    /// anything other than this document's own harness stays untouchable —
    /// killing a build, an editor, an ssh session, or a harness bound to a
    /// DIFFERENT document destroys work the operator never offered up.
    #[test]
    fn supervisor_replacement_still_refuses_panes_that_are_not_our_harness() {
        for foreign in [
            "vim",
            "nvim",
            "ssh",
            "cargo",
            "make",
            "node",
            "agent-doc",
            "",
        ] {
            assert_eq!(
                supervisor_replacement_pane_start_decision(
                    recycle_intent(SupervisorReplacementMode::Continue),
                    true,
                    Some(foreign),
                    Some("claude"),
                    false,
                ),
                SupervisorReplacementPaneDecision::BlockLiveNonShell,
                "{foreign:?} must not be quit or receive route-owned start text"
            );
        }
        // A codex pane must not be quit just because a claude document asked.
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                true,
                Some("codex"),
                Some("claude"),
                false,
            ),
            SupervisorReplacementPaneDecision::BlockLiveNonShell,
            "a pane running a DIFFERENT harness is someone else's session"
        );
        // `node` is in claude's `process_names`; matching on that list instead of
        // the exact binary would make any Node process look restartable.
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                true,
                Some("node"),
                Some("claude"),
                false,
            ),
            SupervisorReplacementPaneDecision::BlockLiveNonShell,
            "process_names substring matching must not be used here"
        );
        // Unknown document harness proves nothing, so it cannot authorise a quit.
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                true,
                Some("claude"),
                None,
                false,
            ),
            SupervisorReplacementPaneDecision::BlockLiveNonShell,
            "an unresolved document harness must not authorise quitting a live pane"
        );
    }

    /// `#agentrestartwire`: the editor's "Restart Agent" action exists to
    /// re-resolve frontmatter and replace the harness child. Preserving that
    /// child on the cold-start path would discard the operator's request — and
    /// when the request came from an `agent:` switch, keep the OLD harness
    /// running for the rest of the session.
    #[test]
    fn restart_agent_intent_restarts_the_live_harness_in_continue_mode() {
        let restart_agent = SupervisorReplacementIntent {
            mode: SupervisorReplacementMode::Continue,
            restart_agent: true,
        };
        for harness in ["claude", "codex", "opencode"] {
            assert_eq!(
                supervisor_replacement_pane_start_decision(
                    restart_agent,
                    true,
                    Some(harness),
                    Some(harness),
                    false,
                ),
                SupervisorReplacementPaneDecision::RestartLiveHarness,
                "{harness} Restart Agent must replace the live child, not preserve it"
            );
        }
        // The foreign-pane guard is unchanged: Restart Agent authorises replacing
        // THIS document's harness, never someone else's live pane.
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                restart_agent,
                true,
                Some("vim"),
                Some("claude"),
                false,
            ),
            SupervisorReplacementPaneDecision::BlockLiveNonShell,
        );
    }

    #[test]
    fn supervisor_replacement_preserves_owned_codex_node_wrapper() {
        assert_eq!(
            supervisor_replacement_pane_start_decision(
                recycle_intent(SupervisorReplacementMode::Continue),
                true,
                Some("node"),
                Some("codex"),
                true,
            ),
            SupervisorReplacementPaneDecision::PreserveLiveHarness,
            "exact process-tree document ownership must preserve Codex even when tmux reports node",
        );
    }

    #[test]
    fn host_supervisor_is_stale_compares_running_inode_against_installed_inode() {
        use agent_doc_supervisor::config::host_supervisor_is_stale;

        // #fccsupwarn2 — staleness is identity (inode), NOT process start time. A
        // supervisor that hot-reloaded onto the fresh binary via in-place `execve`
        // preserves its process start time but remaps the inode, so it must read FRESH.
        let installed_inode = 4242u64;

        // Supervisor maps a DIFFERENT inode (original launch never re-exec'd; the old,
        // now-unlinked binary) → STALE.
        assert!(host_supervisor_is_stale(
            Some(installed_inode + 1),
            installed_inode
        ));

        // Supervisor maps the SAME inode as the install (fresh launch OR in-place
        // execve hot-reload) → FRESH. This is the case the start-time heuristic got
        // wrong: a re-exec'd supervisor that runs current code.
        assert!(!host_supervisor_is_stale(
            Some(installed_inode),
            installed_inode
        ));

        // Running inode unknown (non-Linux / unreadable `/proc/<pid>/exe`) → fail-open,
        // NOT stale, so a read error can never spam the warning.
        assert!(!host_supervisor_is_stale(None, installed_inode));
    }

    #[test]
    fn queue_boundary_self_recycle_makes_stale_content_ours_refusal_ineligible() {
        use agent_doc_supervisor::config::host_supervisor_is_stale;
        use agent_doc_supervisor::lifecycle::{
            SupervisorRecycleAction, SupervisorRecycleCheckpoint, supervisor_recycle_action,
        };

        let installed_inode = 4242u64;
        assert!(
            host_supervisor_is_stale(Some(installed_inode + 1), installed_inode),
            "an old mapped inode is the prerequisite for stale content_ours refusal"
        );

        assert_eq!(
            supervisor_recycle_action(
                /* stale */ true,
                /* auto_recycle */ true,
                /* checkpoint */ SupervisorRecycleCheckpoint::TurnBoundary,
                /* head_pending */ true,
                /* explicit_admin */ false,
                /* write_wedged */ false,
                /* editor_delivery_stale */ false,
                /* reexec_failed */ false,
                /* cycle_open */ false,
            ),
            SupervisorRecycleAction::RecycleImmediate,
            "a stale supervisor with a pending queue head must self-recycle before the next item"
        );

        assert!(
            !host_supervisor_is_stale(Some(installed_inode), installed_inode),
            "after supervisor_binary_stale_self_recycled maps the installed inode, stale-supervisor content_ours refusal is no longer eligible"
        );
    }

