    #[test]
    fn reaper_terminates_wedged_same_project_controller_and_marks_failed() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let sentinel = spawn_controller_sentinel(dir.path());
        let pid = sentinel.id();
        assert!(
            is_same_project_controller_pid(dir.path(), pid),
            "sentinel must present a matching `controller serve --project-root` cmdline"
        );
        let old = timestamp_secs() - 600;
        write_preparing_bootstrap(dir.path(), pid, Some(old));

        let (reaped, kept) =
            terminate_stale_preparing_controllers(dir.path(), Duration::from_secs(45), false)
                .unwrap();
        assert_eq!((reaped, kept), (1, 0));

        // The live wedged process must be dead (the critical difference from the
        // projection reaper). The sentinel is a child of this test, so a killed
        // process lingers as a zombie (with `/proc/<pid>` still present) until we
        // `wait()` it — poll `try_wait` instead of `process_is_alive`.
        let status = wait_for_test_child_exit(
            sentinel,
            Duration::from_secs(2),
            "wedged sentinel pid must be reaped",
        );
        assert!(
            !status.success(),
            "sentinel must be signal-terminated, not exit cleanly: {status:?}"
        );

        // The record must be superseded with `Failed` so the next bind promotes fresh.
        let after = read_bootstrap(dir.path()).unwrap().unwrap();
        assert_eq!(after.handoff_state, ControllerHandoffState::Failed);
        let ops_log = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(ops_log.contains("stale_preparing_controller_reaped pid="));
        assert!(ops_log.contains("caller=gc"));
    }
    #[test]
    fn orphan_reaper_reaps_aged_preparing_sentinel() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let sentinel = spawn_preparing_controller_sentinel(dir.path());
        let pid = sentinel.id();
        // Let the process age past a zero threshold (start age is /proc dir mtime).
        std::thread::sleep(Duration::from_millis(1100));

        let (reaped, kept) =
            reap_orphaned_preparing_controllers(dir.path(), Duration::from_secs(0), false).unwrap();
        assert_eq!((reaped, kept), (1, 0));

        // The live orphan must actually be terminated (the whole point vs. the
        // record-scoped reaper). The sentinel is our child, so a killed process
        // lingers as a zombie until `wait()` — poll `try_wait`.
        let status = wait_for_test_child_exit(
            sentinel,
            Duration::from_secs(2),
            "aged preparing orphan must be reaped",
        );
        assert!(
            !status.success(),
            "orphan must be signal-terminated: {status:?}"
        );

        let ops_log = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(ops_log.contains(&format!("orphaned_preparing_controller_reaped pid={pid}")));
    }
    #[test]
    fn qflood_coalesces_only_auto_in_flight_redispatch() {
        // The flood: an AUTO re-dispatch while the same cycle's dispatch is still in
        // flight (unconsumed) — suppress it so the trigger does not pile into the
        // busy pane.
        assert!(dispatch_should_coalesce_in_flight(true, false));
        // Operator dispatch always passes, even mid-flight (explicit intent must not
        // be blocked by auto-drain backpressure).
        assert!(!dispatch_should_coalesce_in_flight(true, true));
        // Nothing in flight (prior consumed / new cycle) → always admit.
        assert!(!dispatch_should_coalesce_in_flight(false, false));
        assert!(!dispatch_should_coalesce_in_flight(false, true));
    }
    #[test]
    fn qflood2_coalesce_marker_survives_ipc_wrapping() {
        // The route caller only sees the controller error as a string across IPC,
        // wrapped by `request_controller`. The benign-coalesce classifier must still
        // recognise it through that wrapping (the same pattern #ctlstalebin uses).
        let wrapped = format!(
            "project controller command `dispatch` failed: dispatch coalesced for x: a dispatch for generation 66 is already in flight (#qflood); {} receipt_id=3310",
            DISPATCH_COALESCED_IN_FLIGHT_MARKER
        );
        assert!(agent_doc_controller::dispatch::dispatch_error_is_coalesced(
            &wrapped
        ));
        // A real failure (e.g. a paused queue) must NOT be swallowed as success.
        assert!(
            !agent_doc_controller::dispatch::dispatch_error_is_coalesced(
                "project controller command `dispatch` failed: dispatch blocked for x: failed_stage=queue_paused"
            )
        );
    }
    /// `#netadv3` F14/F15, replaying `PassiveTmuxSyncNetAdvanceFirstWedge`: the
    /// graph folded the focus/layout before its effect ran, the effect errored,
    /// and the next identical observation folded to `Idle`. The controller
    /// retains the exact failed intent and reapplies it on that next observation;
    /// a success or a move to another document clears it.
    #[test]
    fn a_failed_editor_surface_effect_is_retried_by_the_next_observation() {
        use agent_doc_editor_surface::{EditorSurface, SurfaceColumn, SurfaceTracking};
        let root = std::path::Path::new("/tmp/netadv3-focus-retry");
        let surface = |focused: &str| EditorSurface {
            column_order: Default::default(),
            focused: focused.to_string(),
            open: vec!["/a.md".to_string(), "/b.md".to_string()],
            visible: vec!["/a.md".to_string(), "/b.md".to_string()],
            columns: vec![SurfaceColumn::new(["/a.md"]), SurfaceColumn::new(["/b.md"])],
            force_reconcile: false,
            focus_only: false,
            preserve_focus: false,
        };
        let (tracking, _) = SurfaceTracking::default().advance(&surface("/a.md"), Some(true));
        let (tracking, intent) = tracking.advance(&surface("/b.md"), Some(true));
        assert!(matches!(intent, SurfaceIntent::Focus { .. }));
        // The select-pane effect errored. Pre-fix, the same focus is now Idle.
        let (_, idle) = tracking.advance(&surface("/b.md"), Some(true));
        assert!(
            idle.is_idle(),
            "the wedge: graph advanced before the effect"
        );
        let focus_intent = SurfaceIntent::Focus {
            document: "/b.md".to_string(),
        };
        record_editor_surface_effect(root, "client-1", &surface("/b.md"), &focus_intent, true);

        // The next observation carries the retained Focus even though the graph
        // has already folded it to Idle.
        assert_eq!(
            pending_editor_surface_retry(root, "client-1", &surface("/b.md")),
            Some(focus_intent.clone())
        );
        // Success clears the retry.
        record_editor_surface_effect(root, "client-1", &surface("/b.md"), &focus_intent, false);
        assert_eq!(
            pending_editor_surface_retry(root, "client-1", &surface("/b.md")),
            None
        );
        // So does the editor moving on; other clients are independent.
        record_editor_surface_effect(root, "client-1", &surface("/b.md"), &focus_intent, true);
        assert_eq!(
            pending_editor_surface_retry(root, "client-2", &surface("/b.md")),
            None
        );
        assert_eq!(
            pending_editor_surface_retry(root, "client-1", &surface("/a.md")),
            None
        );
        assert_eq!(
            pending_editor_surface_retry(root, "client-1", &surface("/b.md")),
            None
        );

        // F14 is the same wedge on the structural lane: the graph advances its
        // layout signature before the desired-layout publication can fail.
        let (tracking, first_sync) =
            SurfaceTracking::default().advance(&surface("/a.md"), Some(true));
        assert!(matches!(first_sync, SurfaceIntent::Sync { .. }));
        let (_, idle) = tracking.advance(&surface("/a.md"), Some(true));
        assert!(idle.is_idle(), "the structural wedge: graph advanced first");
        record_editor_surface_effect(root, "client-2", &surface("/a.md"), &first_sync, true);
        assert_eq!(
            pending_editor_surface_retry(root, "client-2", &surface("/a.md")),
            Some(first_sync.clone())
        );
        // A newer layout observation supersedes rather than replays the stale
        // structural intent, even when focus stayed on the same document.
        let mut changed_layout = surface("/a.md");
        changed_layout.columns = vec![SurfaceColumn::new(["/a.md", "/b.md"])];
        assert_eq!(
            pending_editor_surface_retry(root, "client-2", &changed_layout),
            None
        );
        record_editor_surface_effect(root, "client-2", &surface("/a.md"), &first_sync, true);
        record_editor_surface_effect(root, "client-2", &surface("/a.md"), &first_sync, false);
    }

    /// `#netadv3` SIM-F1, replaying the netadv4 SimWorld trace through the real
    /// handler (`formal/tla/LifecycleSequence.tla`, `Reorder` wedge): the
    /// supervisor sends Ready, then Busy, in one generation; the channel delivers
    /// Busy first. The late Ready carries the OLDER send stamp and must not
    /// overwrite Busy, or the next dispatch is typed into a busy supervisor. A
    /// newer update and an unstamped (older-client) update still apply.
    #[test]
    fn reordered_older_lifecycle_update_is_discarded_by_send_stamp() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/simf1.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-sf\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        agent_doc_session_actor_io::record_session_start_direct(&doc, "session-sf", "%51", "@1", 1)
            .unwrap();
        let bootstrap = test_bootstrap(&dir);
        let lifecycle = |state: &str, sequence: Option<u64>| ControllerRequest {
            command: "mark_lifecycle".to_string(),
            file: Some(doc.clone()),
            session_id: Some("session-sf".to_string()),
            pane_id: Some("%51".to_string()),
            window_id: None,
            generation: Some(1),
            state: Some(state.to_string()),
            caller: Some("supervisor".to_string()),
            reason: Some("simf1".to_string()),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: None,
            sequence,
        };
        let ready_sent = level_update_send_stamp().expect("monotonic clock");
        let busy_sent = level_update_send_stamp().expect("monotonic clock");
        assert!(busy_sent >= ready_sent);
        let busy_sent = busy_sent.max(ready_sent + 1);

        // Delivered out of order: Busy, then the delayed Ready.
        let applied = handle_mark_lifecycle(&bootstrap, None, lifecycle("busy", Some(busy_sent)))
            .expect("busy applies");
        assert_eq!(applied.state, agent_doc_controller::actor::ActorState::Busy);
        let after_late_ready =
            handle_mark_lifecycle(&bootstrap, None, lifecycle("ready", Some(ready_sent)))
                .expect("a stale update is discarded, not an error");
        assert_eq!(
            after_late_ready.state,
            agent_doc_controller::actor::ActorState::Busy,
            "the reordered older Ready must not re-open dispatch into a busy supervisor"
        );

        // A newer Ready applies; a duplicate of it is idempotent.
        let newer = busy_sent + 1;
        assert_eq!(
            handle_mark_lifecycle(&bootstrap, None, lifecycle("ready", Some(newer)))
                .unwrap()
                .state,
            agent_doc_controller::actor::ActorState::Ready
        );
        assert_eq!(
            handle_mark_lifecycle(&bootstrap, None, lifecycle("ready", Some(newer)))
                .unwrap()
                .state,
            agent_doc_controller::actor::ActorState::Ready
        );
        // An unstamped request (older client) is never fenced.
        assert_eq!(
            handle_mark_lifecycle(&bootstrap, None, lifecycle("busy", None))
                .unwrap()
                .state,
            agent_doc_controller::actor::ActorState::Busy
        );
    }

    /// `#netadv3` SIM-F2: a reordered older queue pause must not flip queue
    /// control back over a newer resume; it is rejected with `stale_sequence`.
    #[test]
    fn reordered_older_queue_control_is_rejected_by_send_stamp() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let bootstrap = test_bootstrap(&dir);
        let control = |action: &str, sequence: Option<u64>| ControllerRequest {
            command: "queue_control".to_string(),
            file: None,
            session_id: None,
            pane_id: None,
            window_id: None,
            generation: None,
            state: Some(action.to_string()),
            caller: Some("admin".to_string()),
            reason: Some("simf2".to_string()),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some(action.to_string()),
            diagnostic_payload: None,
            sequence,
        };
        let pause_sent = level_update_send_stamp().expect("monotonic clock");
        let resume_sent = pause_sent + 1;
        let resumed = handle_queue_control(&bootstrap, control("resume", Some(resume_sent)))
            .expect("resume applies");
        assert!(resumed.failed_stage.is_none(), "{resumed:?}");
        let late_pause = handle_queue_control(&bootstrap, control("pause", Some(pause_sent)))
            .expect("a stale control is a rejected receipt, not an error");
        assert_eq!(late_pause.failed_stage.as_deref(), Some("stale_sequence"));
        let conn = open_state_db(dir.path()).unwrap();
        let effective = state_store::load_queue_control_from_db(
            &conn,
            "project",
            &dir.path().to_string_lossy(),
        )
        .unwrap()
        .expect("queue control row");
        assert_eq!(
            effective.state, "resumed",
            "the newer resume stays in force"
        );
    }

    #[test]
    fn qflood_coalesces_in_flight_despite_ready_projection_drift_and_releases_on_ready() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/qflood.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-qf\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        agent_doc_session_actor_io::record_session_start_direct(&doc, "session-qf", "%41", "@1", 1)
            .unwrap();
        // Actor actively running a turn (mid-turn / pane busy).
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-qf",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Busy,
            "supervisor",
            "turn_started",
        )
        .unwrap();
        let document_id = agent_doc_session_actor_io::canonical_document_id_in(
            dir.path(),
            &doc.to_string_lossy(),
        );
        let bootstrap = test_bootstrap(&dir);
        let dispatch = || ControllerRequest {
            command: "dispatch".to_string(),
            file: Some(doc.clone()),
            session_id: Some("session-qf".to_string()),
            pane_id: Some("%41".to_string()),
            window_id: None,
            generation: Some(1),
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("projection_repair".to_string()),
            diagnostic_payload: Some("qflood test".to_string()),
            sequence: None,
        };

        // First dispatch while Busy: nothing in flight yet ⇒ admitted (queued),
        // recording the in-flight marker. The first dispatch of a turn is never lost.
        handle_dispatch(&bootstrap, None, dispatch()).expect("first busy dispatch must queue");
        let conn = open_state_db(dir.path()).unwrap();
        assert!(
            state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "the first busy dispatch must be in flight"
        );

        // Simulate the exact race from Run Agent Doc: a lossy pane reconciler
        // projects Ready before the command has established/finished its turn.
        // This direct state write intentionally bypasses the controller's genuine
        // Ready boundary, so the durable receipt remains open.
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-qf",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Ready,
            "test",
            "premature_idle_projection",
        )
        .unwrap();
        assert!(
            state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "projection drift must not consume the controller-owned receipt"
        );

        // An explicit operator reopen is never swallowed by stale same-generation
        // backpressure. This is the JetBrains `Run Agent Doc` path: the click must
        // reach the pane even while an older receipt remains open.
        let operator_dispatch = || ControllerRequest {
            command: "dispatch".to_string(),
            file: Some(doc.clone()),
            session_id: Some("session-qf".to_string()),
            pane_id: Some("%41".to_string()),
            window_id: None,
            generation: Some(1),
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("dispatch_only_reopen".to_string()),
            diagnostic_payload: Some("operator Run Agent Doc".to_string()),
            sequence: None,
        };
        handle_dispatch(&bootstrap, None, operator_dispatch())
            .expect("operator reopen must bypass stale in-flight coalescing");

        // A non-operator re-fire while the receipt is in flight ⇒ coalesced
        // (bail), even though
        // the actor projection says Ready. It cannot pile another trigger into
        // the pane.
        let err = handle_dispatch(&bootstrap, None, dispatch()).unwrap_err();
        assert!(
            format!("{err:#}").contains("coalesced"),
            "a redundant in-flight re-dispatch must coalesce: {err:#}"
        );
        // `#qflood2`: the coalesce bail must carry the stable machine marker so route
        // callers can recognise the benign dedup across the IPC boundary and report
        // deduped-success instead of an exit-1 failure.
        assert!(
            agent_doc_controller::dispatch::dispatch_error_is_coalesced(&format!("{err:#}")),
            "a coalesce bail must be classifiable as deduped-success: {err:#}"
        );
        assert!(
            !agent_doc_controller::dispatch::dispatch_error_is_coalesced(
                "dispatch blocked for x: failed_stage=queue_paused"
            ),
            "an unrelated dispatch failure must NOT classify as a benign coalesce"
        );
        let coalesced: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM dispatch_attempts WHERE failed_stage = 'coalesced_in_flight'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(coalesced, 1, "the coalesced re-dispatch must be recorded");

        // `#idledispatchstack`: a controller-owned Ready is NOT on its own proof that
        // this receipt's trigger ran. Provenance was the original qflood
        // discriminator (controller boundary vs. the direct write above), and the live
        // 2026-09-12 repro on `tasks/fpe.md` defeated it: `dispatch_in_flight_released
        // ... reason=actor_ready` fired from this very blessed path at 02:09:06, and the
        // trigger's turn then started at 02:09:07 — so the receipt was consumed one
        // second BEFORE the work it represented began, and the idle watch stacked a
        // duplicate at 02:09:12. The turn start has to be observed, not inferred.
        let mark_lifecycle = |state: &str, caller: &str, reason: &str| ControllerRequest {
            command: "mark_lifecycle".to_string(),
            file: Some(doc.clone()),
            session_id: Some("session-qf".to_string()),
            pane_id: Some("%41".to_string()),
            window_id: None,
            generation: Some(1),
            state: Some(state.to_string()),
            caller: Some(caller.to_string()),
            reason: Some(reason.to_string()),
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: None,
            diagnostic_payload: None,
            sequence: None,
        };

        // The premature Ready, now through the controller's own boundary. Still no
        // observed turn for this receipt, so it must survive.
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("ready", "supervisor", "prompt_ready"),
        )
        .expect("mark ready");
        assert!(
            state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "a controller Ready with no observed turn start must NOT consume the receipt"
        );

        // An unrelated supervisor-caused Busy episode must not vouch for it either —
        // this is the `reason=restart_continue_spawn` transition that landed two seconds
        // before the live premature release.
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("busy", "supervisor", "restart_continue_spawn"),
        )
        .expect("mark busy");
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("ready", "supervisor", "prompt_ready"),
        )
        .expect("mark ready");
        assert!(
            state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "an unrelated supervisor busy episode must not vouch for this receipt"
        );

        // The first dispatched trigger finally starts its own turn, and the Ready that
        // ends THAT turn releases its receipt.
        //
        // `#dispatchreceiptperturn`: it releases ONLY its own. Two receipts are open
        // here — the coalescing-bypassed operator reopen above is the second — and this
        // single turn used to release both, which stopped the reopen's still-unsubmitted
        // trigger from blocking a duplicate stacked into the same composer. That is the
        // `#idledispatchstack` shape the receipt exists to prevent.
        let open_receipts = || -> i64 {
            conn.query_row(
                "SELECT COUNT(*) FROM dispatch_attempts \
                 WHERE document_id = ?1 AND failed_stage IS NULL AND dispatch_start_proven = 0",
                params![document_id],
                |row| row.get(0),
            )
            .unwrap()
        };
        assert_eq!(
            open_receipts(),
            2,
            "the reopen opened a second live receipt"
        );

        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("busy", "dispatch", "auto_trigger_inject"),
        )
        .expect("mark busy");
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("ready", "supervisor", "prompt_ready"),
        )
        .expect("mark ready");
        assert_eq!(
            open_receipts(),
            1,
            "one observed turn settles one receipt, not both"
        );
        assert!(
            state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "the operator reopen's trigger has not run yet; its receipt must still block a duplicate"
        );

        // The reopen's own turn then runs, and the marker clears so the next turn
        // dispatches cleanly.
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("busy", "dispatch", "auto_trigger_inject"),
        )
        .expect("mark busy");
        handle_mark_lifecycle(
            &bootstrap,
            None,
            mark_lifecycle("ready", "supervisor", "prompt_ready"),
        )
        .expect("mark ready");
        assert!(
            !state_store::has_open_in_flight_dispatch(&conn, &document_id, 1).unwrap(),
            "the Ready after every dispatched turn must release the in-flight marker"
        );
    }
    #[test]
    fn anw0_stale_generation_redirect_marker_classifies_and_survives_ipc_wrapping() {
        // The route caller only sees the controller error as a string across IPC,
        // wrapped by `request_controller`. The redirect classifier must recognise the
        // marker through that wrapping and extract the retry generation (mirrors the
        // #qflood2 marker contract).
        let wrapped = format!(
            "project controller command `dispatch` failed: dispatch rejected for x: requested generation 1, current generation 2 ({} retry_generation=2) receipt_id=42",
            DISPATCH_STALE_GENERATION_REDIRECT_MARKER
        );
        assert_eq!(
            dispatch_error_stale_generation_redirect_target(&wrapped),
            Some(2),
            "a redirect bail must yield its retry generation across IPC wrapping"
        );
        // A terminal stale_generation reject (current actor Closed/Blocked) carries no
        // marker, so it must stay terminal — never trigger a self-heal retry.
        assert_eq!(
            dispatch_error_stale_generation_redirect_target(
                "dispatch rejected for x: requested generation 1, current generation 2 receipt_id=42"
            ),
            None,
            "a marker-less stale_generation reject must stay terminal"
        );
        // An unrelated failure (e.g. a paused queue) is never a redirect.
        assert_eq!(
            dispatch_error_stale_generation_redirect_target(
                "dispatch blocked for x: failed_stage=queue_paused"
            ),
            None
        );
    }
    #[test]
    fn anw0_stale_generation_redirect_emitted_only_when_current_dispatchable() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/anw0.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-anw0\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        agent_doc_session_actor_io::record_session_start_direct(
            &doc,
            "session-anw0",
            "%41",
            "@1",
            1,
        )
        .unwrap();
        let bootstrap = test_bootstrap(&dir);
        let stale_dispatch = || ControllerRequest {
            command: "dispatch".to_string(),
            file: Some(doc.clone()),
            session_id: Some("session-anw0".to_string()),
            pane_id: Some("%41".to_string()),
            window_id: None,
            // Requested generation 0 is superseded by the live generation 1.
            generation: Some(0),
            state: None,
            caller: None,
            reason: None,
            supervisor_pid: None,
            supervisor_socket: None,
            command_kind: Some("managed_reopen".to_string()),
            diagnostic_payload: Some("anw0 redirect test".to_string()),
            sequence: None,
        };

        // Current generation (1) is Ready ⇒ a retry would be authorized ⇒ structured
        // redirect with the marker + retry target pointing at the current generation.
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-anw0",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Ready,
            "supervisor",
            "prompt_ready",
        )
        .unwrap();
        let err = handle_dispatch(&bootstrap, None, stale_dispatch()).unwrap_err();
        let msg = format!("{err:#}");
        assert!(msg.contains("requested generation 0"), "{msg}");
        assert_eq!(
            dispatch_error_stale_generation_redirect_target(&msg),
            Some(1),
            "a dispatchable current generation must emit a retry-against-N+1 redirect: {msg}"
        );

        // Current generation (1) is Closed ⇒ a retry cannot help ⇒ terminal reject with
        // NO redirect marker, so racing dispatch does not loop against a dead actor.
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-anw0",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Closed,
            "supervisor",
            "superseded",
        )
        .unwrap();
        let err = handle_dispatch(&bootstrap, None, stale_dispatch()).unwrap_err();
        let msg = format!("{err:#}");
        assert!(msg.contains("requested generation 0"), "{msg}");
        assert_eq!(
            dispatch_error_stale_generation_redirect_target(&msg),
            None,
            "a closed current generation must stay a terminal stale_generation reject: {msg}"
        );
    }
    #[test]
    fn anw0_racing_dispatch_self_heals_against_new_generation() {
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let doc = dir.path().join("tasks/anw0heal.md");
        std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
        std::fs::write(
            &doc,
            "---\nagent_doc_session: session-anw0h\nagent: codex\n---\nBody\n",
        )
        .unwrap();
        agent_doc_session_actor_io::record_session_start_direct(
            &doc,
            "session-anw0h",
            "%41",
            "@1",
            1,
        )
        .unwrap();
        agent_doc_session_actor_io::transition_state_direct(
            &doc,
            "session-anw0h",
            "%41",
            Some(1),
            agent_doc_controller::actor::ActorState::Ready,
            "supervisor",
            "prompt_ready",
        )
        .unwrap();

        // A racing dispatcher still holds the superseded generation 0. `authorize_dispatch`
        // must consume the redirect and retry ONCE against the live generation 1, landing
        // the dispatch instead of failing closed.
        let auth = authorize_dispatch(
            dir.path(),
            DispatchRequest {
                file: doc.clone(),
                session_id: "session-anw0h".to_string(),
                pane_id: "%41".to_string(),
                generation: 0,
                command_kind: "managed_reopen".to_string(),
                diagnostic_payload: "anw0 self-heal".to_string(),
            },
        )
        .expect("a racing dispatch must self-heal by retrying against the current generation");
        assert_eq!(
            auth.record.generation, 1,
            "the self-heal retry must land on the current (N+1) generation"
        );
        let ops_log = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops_log.contains("dispatch_stale_generation_redirect"),
            "the first stale dispatch must leave redirect proof:\n{ops_log}"
        );
        assert!(
            ops_log.contains("dispatch_retry_after_stale_generation"),
            "authorize_dispatch must leave retry proof:\n{ops_log}"
        );
        assert!(
            !ops_log.contains(" is closed"),
            "redirectable stale dispatch must not degrade into a terminal generation-closed proof:\n{ops_log}"
        );
    }
    #[test]
    fn resolve_supervisor_auto_recycle_precedence() {
        use agent_doc_supervisor::config::resolve_supervisor_auto_recycle as r;

        // `#suprecyclequeue` precedence: env > frontmatter > project config > default.
        // Env truthy force-enables regardless of frontmatter / project config.
        assert!(r(Some("1"), Some(false), Some(false)));
        assert!(r(Some("true"), None, None));
        assert!(r(Some(" ON "), Some(false), Some(false)));
        // Env falsey force-disables regardless of frontmatter / project opt-in.
        assert!(!r(Some("0"), Some(true), Some(true)));
        assert!(!r(Some("off"), Some(true), Some(true)));
        // Env unset / unrecognized → frontmatter decides over project config.
        assert!(r(None, Some(true), Some(false)));
        assert!(!r(None, Some(false), Some(true)));
        assert!(r(Some("garbage"), Some(true), Some(false)));
        // Frontmatter absent → project config decides.
        assert!(r(None, None, Some(true)));
        assert!(!r(None, None, Some(false)));
        // `#supselfheal` — nothing set anywhere → default ON (turn-boundary
        // blue/green self-recycle is the hands-off self-heal). Opt out via a
        // falsey env/frontmatter/project knob (asserted above).
        assert!(r(None, None, None));
        assert!(r(Some(""), None, None));
    }
    #[test]
    fn resolve_agent_change_restart_precedence() {
        use agent_doc_supervisor::config::resolve_agent_change_restart as r;

        // Env wins.
        assert!(r(Some("on"), Some(false), Some(false)));
        assert!(!r(Some("off"), Some(true), Some(true)));
        // Unrecognized env → fall through to frontmatter.
        assert!(r(Some("garbage"), Some(true), Some(false)));
        // Frontmatter over project.
        assert!(r(None, Some(true), Some(false)));
        assert!(!r(None, Some(false), Some(true)));
        // Project decides when frontmatter absent.
        assert!(r(None, None, Some(true)));
        assert!(!r(None, None, Some(false)));
        // `#agentreloadrestart` — nothing set → default ON.
        assert!(r(None, None, None));
        assert!(r(Some(""), None, None));
    }
    #[test]
    fn pause_reason_stale_supervisor_churn_stop_classification() {
        use agent_doc_controller::dispatch::pause_reason_is_stale_supervisor_churn_stop as c;
        // `#jbrestale` live-repro churn-stop reason → recoverable by recycle.
        assert!(c(
            "churn-stop: do[#c2b6] operator-verify head re-injected by stale supervisor pid1368698 (pre-0.34.0); needs operator recycle, not agent drain"
        ));
        // Explicit discriminators (case-insensitive).
        assert!(c("supervisor_binary_stale pane=%25"));
        assert!(c("re-injected by Stale Supervisor PID 42"));
        assert!(c(
            "#qchurn no-op churn: go-mode re-injecting :pushpin: [#qchurn] each idle boundary; all heads are undrainable under stale host supervisor pid 2715614; zero drainable work"
        ));
        assert!(c(
            "stale route-owned supervisor (pid 968752) replaying already-answered/archived #advance-review queue item"
        ));
        // `churn-stop` + the recycle remedy with no other signature still recovers.
        assert!(c("churn-stop: repeated injection; needs operator recycle"));
        // Deliberate spent-preset pause → NOT a stale-supervisor recovery (must fail closed).
        assert!(!c(
            "advance-review preset head is spent (backlog added + both features shipped); pausing so the go-queue does not re-trigger advance-review. Operator can clear the '- #advance-review' line"
        ));
        // Plain operator pause → not recoverable.
        assert!(!c("operator paused for manual review"));
        // A churn-stop with neither a stale signature nor the recycle remedy → not recoverable.
        assert!(!c("churn-stop: repeated no-op closeouts"));
    }
    #[test]
    fn stale_supervisor_pid_extraction() {
        use agent_doc_controller::dispatch::stale_supervisor_pid_from_pause_reason as p;
        assert_eq!(
            p("re-injected by stale supervisor pid1368698 (pre-0.34.0)"),
            Some(1368698)
        );
        assert_eq!(
            p("stale supervisor pid 2825163; needs operator recycle"),
            Some(2825163)
        );
        assert_eq!(
            p("undrainable under stale host supervisor pid 2715614; zero drainable work"),
            Some(2715614)
        );
        assert_eq!(p("stale supervisor (no pid named)"), None);
        assert_eq!(p("supervisor_binary_stale pane=%25"), None);
    }
    #[test]
    fn dispatch_error_supervisor_restart_redirect_classification() {
        use agent_doc_controller::dispatch::{
            DISPATCH_SUPERVISOR_RESTART_REDIRECT_MARKER, DispatchRecoveryOutcomeClass,
            stale_queue_pause_pid_from_dispatch_error as r,
            stale_queue_pause_recovery_from_dispatch_error as recover,
        };
        // `#jbrestale`: a queue_paused bail tagged with the restart-redirect marker is
        // recoverable; the named stale pid is extracted for the proof line.
        let tagged = "project controller command `dispatch` failed: dispatch blocked for x.md: failed_stage=queue_paused reason=churn-stop: stale supervisor pid1368698; needs operator recycle receipt_id=42 supervisor_restart_redirect stale_pid=1368698";
        assert_eq!(r(tagged), Some(1368698));
        let tagged_recovery = recover(tagged).unwrap();
        assert_eq!(tagged_recovery.stale_pid, 1368698);
        assert_eq!(
            tagged_recovery.outcome.class,
            DispatchRecoveryOutcomeClass::Recoverable
        );
        assert_eq!(tagged_recovery.outcome.invariant_id, "stale_queue_pause");
        assert_eq!(
            tagged_recovery.outcome.proof_marker,
            DISPATCH_SUPERVISOR_RESTART_REDIRECT_MARKER
        );
        assert_eq!(
            tagged_recovery.outcome.next_action,
            "restart_supervisor_once_and_retry"
        );
        // Marker present but no pid named → recoverable with pid 0 (proof line still emits).
        assert_eq!(
            r(
                "dispatch blocked: failed_stage=queue_paused reason=supervisor_binary_stale receipt_id=7 supervisor_restart_redirect stale_pid=0"
            ),
            Some(0)
        );
        // Legacy stale supervisors predate the redirect marker. Route must still recover
        // the stale-supervisor churn-stop instead of surfacing the JB Run Agent Doc error.
        assert_eq!(
            r(
                "project controller command `dispatch` failed: dispatch blocked for tasks/agent-doc/agent-doc-bugs2.md: failed_stage=queue_paused reason=#qchurn no-op churn: go-mode re-injecting :pushpin: [#qchurn] each idle boundary; all 16 heads are clean-session/operator-verify and undrainable under stale host supervisor pid 2715614; zero drainable work. Pausing to stop the flood until restart onto fresh binary. receipt_id=3649 blocked_head_bytes=132"
            ),
            Some(2715614)
        );
        // No marker → terminal (a deliberate operator/spent-preset pause never restarts).
        assert_eq!(
            r(
                "dispatch blocked for x.md: failed_stage=queue_paused reason=advance-review preset head is spent receipt_id=9"
            ),
            None
        );
        // A coalesce / stale-generation failure must not be misread as a restart redirect.
        assert_eq!(
            r("dispatch coalesced for x.md (#qflood); receipt_id=3"),
            None
        );
        assert!(recover("dispatch coalesced for x.md (#qflood); receipt_id=3").is_none());
        assert_eq!(
            r(
                "dispatch rejected: requested generation 1, current generation 2 (stale_generation_redirect retry_generation=2)"
            ),
            None
        );
    }
    #[test]
    fn superseded_editor_route_refusal_names_pid_and_restart_remedy() {
        // GH #76: an editor proven to run unlinked plugin bytes, whose native
        // endpoint cannot answer this controller, refuses the route up front,
        // naming the cause and the backend-restart remedy.
        use agent_doc_fs::plugin_jar::MappedPluginJar;
        use agent_doc_ipc_io::EditorEndpointBuild;
        let jar = "/plugins/agent-doc-jetbrains/lib/agent-doc-jetbrains-0.2.392.jar";
        let mut probed = Vec::new();
        let verdict = superseded_editor_route_verdict(
            &[
                ("jetbrains".to_string(), 7, MappedPluginJar::Unknown),
                (
                    "jetbrains".to_string(),
                    1506046,
                    MappedPluginJar::Deleted {
                        path: jar.to_string(),
                    },
                ),
            ],
            |pid| {
                probed.push(pid);
                EditorEndpointBuild::NoEndpoint
            },
        );
        // The endpoint is probed only for the superseded pid.
        assert_eq!(probed, vec![1506046]);
        let SupersededEditorRouteVerdict::Refuse(refusal) = verdict else {
            panic!("a deleted mapping without a serving endpoint must refuse: {verdict:?}");
        };
        assert!(refusal.starts_with("plugin_bytes_superseded"), "{refusal}");
        assert!(refusal.contains("pid 1506046"), "{refusal}");
        assert!(refusal.contains(jar), "{refusal}");
        assert!(
            refusal.contains("serves no native agent-doc endpoint"),
            "{refusal}"
        );
        assert!(
            refusal.contains(&agent_doc_fs::plugin_jar::superseded_editor_remedy(None)),
            "{refusal}"
        );

        // GH #257: once the installer already recorded a refusal, route
        // admission must skip the install rung and prescribe the restart.
        let restart = superseded_editor_route_refusal_message(
            "jetbrains",
            1506046,
            jar,
            &EditorEndpointBuild::Unanswered,
            Some("exact-263 package has no restart-free upgrade entry point"),
        );
        assert!(
            restart.contains("Restart the editor to load them"),
            "{restart}"
        );
        assert!(restart.contains("did not answer an IPC hello"), "{restart}");
        assert!(restart.contains("pid 1506046"), "{restart}");
        assert!(
            !restart.contains("Re-run the plugin installation once"),
            "{restart}"
        );

        // GH #267: a native generation still on the previous build names both
        // builds and the restart-free native reload before the plugin remedy.
        let stale_native = superseded_editor_route_refusal_message(
            "jetbrains",
            1506046,
            jar,
            &EditorEndpointBuild::OtherBuild {
                editor_build: "0.35.503".to_string(),
                local_build: "0.35.505".to_string(),
            },
            Some("exact-263 package has no restart-free upgrade entry point"),
        );
        assert!(
            stale_native
                .contains("answers with build 0.35.503, not this controller's build 0.35.505"),
            "{stale_native}"
        );
        assert!(
            stale_native.contains("`agent-doc admin reload-lib`"),
            "{stale_native}"
        );
        assert!(
            stale_native.contains("Restart the editor to load them"),
            "{stale_native}"
        );

        // Fail open: current or inconclusive mappings never refuse, and never
        // spend a probe.
        assert_eq!(
            superseded_editor_route_verdict(
                &[
                    ("jetbrains".to_string(), 7, MappedPluginJar::Unknown),
                    (
                        "jetbrains".to_string(),
                        8,
                        MappedPluginJar::Current {
                            path: jar.to_string(),
                            inode: 1,
                        },
                    ),
                ],
                |pid| panic!("a current mapping must not be probed (pid {pid})"),
            ),
            SupersededEditorRouteVerdict::Admit
        );
    }

    /// GH #267 fixture: a real agent-doc native endpoint for this process's pid,
    /// standing in for an IDE whose native library hot-reloaded to the current
    /// build while its plugin jar stayed superseded.
    struct CurrentNativeEndpoint {
        root: PathBuf,
        shutdown: Arc<std::sync::atomic::AtomicBool>,
        thread: Option<std::thread::JoinHandle<()>>,
    }

    impl CurrentNativeEndpoint {
        fn start(root: &Path) -> Self {
            let shutdown = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let (ready_tx, ready_rx) = std::sync::mpsc::channel();
            let thread = {
                let root = root.to_path_buf();
                let shutdown = Arc::clone(&shutdown);
                std::thread::spawn(move || {
                    let _ = agent_doc_ipc_io::start_listener_with_logger_until_ready(
                        &root,
                        |_| None,
                        |_, _| {},
                        shutdown,
                        ready_tx,
                    );
                })
            };
            ready_rx
                .recv_timeout(Duration::from_secs(30))
                .expect("the native endpoint fixture must bind its socket");
            Self {
                root: root.to_path_buf(),
                shutdown,
                thread: Some(thread),
            }
        }
    }

    impl Drop for CurrentNativeEndpoint {
        fn drop(&mut self) {
            self.shutdown
                .store(true, std::sync::atomic::Ordering::SeqCst);
            let _ = agent_doc_ipc_io::wake_listener(&self.root);
            if let Some(thread) = self.thread.take() {
                let _ = thread.join();
            }
        }
    }

    #[test]
    fn superseded_jar_with_current_native_endpoint_is_admitted_gh267() {
        // GH #267: the exact-263 IDE kept its superseded plugin jar mapped, but
        // hot-reloaded the native library and kept serving the controller. The
        // mapped jar alone must not refuse; the live endpoint proves capability.
        use agent_doc_fs::plugin_jar::MappedPluginJar;
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join(".agent-doc")).unwrap();
        let doc = root.join("doc-a.md");
        std::fs::write(&doc, "# doc\n").unwrap();
        let _endpoint = CurrentNativeEndpoint::start(&root);
        let pid = std::process::id();
        let jar = "/data/.agent-doc-jetbrains-install/backup-2411872-1792046538942846469/lib/agent.doc-0.2.609.jar";
        let probes = vec![(
            "jetbrains".to_string(),
            pid,
            MappedPluginJar::Superseded {
                path: jar.to_string(),
                mapped_inode: 11,
                disk_inode: 12,
            },
        )];

        // Production probes the root controller → editor sends resolve.
        assert_eq!(
            agent_doc_project_root_io::resolve_ipc_project_root(&doc),
            root
        );
        let advisory = editor_route_superseded_admission(&root, &doc, &probes)
            .expect("a superseded jar with a current native endpoint must be admitted")
            .expect("the admission must carry the restart advisory");
        assert!(
            advisory.starts_with("plugin_bytes_superseded_advisory"),
            "{advisory}"
        );
        assert!(advisory.contains(&format!("pid {pid}")), "{advisory}");
        assert!(advisory.contains(jar), "{advisory}");
        assert!(advisory.contains("the route was admitted"), "{advisory}");
        assert!(!advisory.contains("refused"), "{advisory}");

        let mut output = "routed doc-a.md".to_string();
        append_superseded_editor_advisory(&mut output, &advisory);
        assert_eq!(output, format!("routed doc-a.md\n{advisory}\n"));

        let ops = std::fs::read_to_string(root.join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops.contains("editor_route_superseded_editor_admitted")
                && ops.contains("reason=native_endpoint_current"),
            "{ops}"
        );
        assert!(
            !ops.contains("editor_route_refused_superseded_editor"),
            "{ops}"
        );
    }

    #[test]
    fn superseded_jar_without_native_endpoint_is_still_refused_gh267() {
        // GH #267: the fail-closed half. A superseded jar whose pid serves no
        // native endpoint for this project cannot receive the controller
        // messages the route depends on, so it still refuses with the remedy.
        use agent_doc_fs::plugin_jar::MappedPluginJar;
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path().canonicalize().unwrap();
        std::fs::create_dir_all(root.join(".agent-doc")).unwrap();
        let doc = root.join("doc-b.md");
        std::fs::write(&doc, "# doc\n").unwrap();
        let pid = std::process::id();
        let jar = "/plugins/agent-doc-jetbrains-263/lib/agent-doc-jetbrains-263-0.2.577.jar";
        let probes = vec![(
            "jetbrains".to_string(),
            pid,
            MappedPluginJar::Deleted {
                path: jar.to_string(),
            },
        )];

        let refusal = editor_route_superseded_admission(&root, &doc, &probes)
            .expect_err("a superseded jar with no native endpoint must refuse")
            .to_string();
        assert!(refusal.starts_with("plugin_bytes_superseded:"), "{refusal}");
        assert!(refusal.contains(&format!("pid {pid}")), "{refusal}");
        assert!(refusal.contains(jar), "{refusal}");
        assert!(
            refusal.contains("serves no native agent-doc endpoint for this project"),
            "{refusal}"
        );
        // No restart verdict was recorded for this process, so the exact
        // remedy is the restart-free install rung.
        assert!(
            refusal.contains(&agent_doc_fs::plugin_jar::superseded_editor_remedy(None)),
            "{refusal}"
        );
        assert!(refusal.contains("Then retry (#76, #267"), "{refusal}");

        let ops = std::fs::read_to_string(root.join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops.contains("editor_route_refused_superseded_editor")
                && ops.contains("reason=plugin_bytes_superseded"),
            "{ops}"
        );
    }

    #[test]
    fn supervisor_drain_handoff_becomes_undrained_only_for_the_same_head() {
        // `#supdrainyieldfalsifiable`: a recorded hand-off is reported once the
        // SAME supervisor head outlives the window, and never after it changes.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        let doc = |head: &str| {
            format!(
                "---\nsession: sid\nagent_doc_format: template\nqueue_active: true\n---\n\n\
## Backlog\n\n<!-- agent:backlog queue=sync -->\n<!-- /agent:backlog -->\n\n\
## Queue\n\n<!-- agent:queue auto go -->\n- {head}\n<!-- /agent:queue -->\n"
            )
        };
        let head = "[focused-cycle] fix queue identity loss";
        let unclaimed = agent_doc_queue::queue_claim::ClaimedQueueItems::none();
        let content = doc(head);
        std::fs::write(&file, &content).unwrap();
        assert!(
            supervisor_drain_head_sha256(&content, &unclaimed).is_some(),
            "fixture must have a supervisor head"
        );

        record_supervisor_drain_handoff(&file, head);
        assert_eq!(
            undrained_supervisor_drain_handoff_age(&file, &content, &unclaimed),
            None,
            "inside window"
        );

        // Backdate past the window; re-recording the same head keeps the first time.
        let canonical = file.canonicalize().unwrap();
        let conn = open_state_db(dir.path()).unwrap();
        let backdated =
            timestamp_secs() - status::SUPERVISOR_DRAIN_HANDOFF_UNDRAINED_AFTER.as_secs() - 60;
        agent_doc_sqlite::state_store::upsert_document_runtime_state_in_db(
            &conn,
            &agent_doc_sqlite::state_store::DocumentRuntimeStateRecord {
                document_hash: agent_doc_hash::document_id_for_path(&canonical),
                state_kind: SUPERVISOR_DRAIN_HANDOFF_STATE_KIND.to_string(),
                canonical_path: canonical.to_string_lossy().into_owned(),
                payload_json: format!(
                    "{{\"head_sha256\":\"{}\",\"handed_off_secs\":{backdated}}}",
                    agent_doc_hash::content_hash(head)
                ),
                updated_at_ms: backdated * 1_000,
            },
        )
        .unwrap();
        record_supervisor_drain_handoff(&file, head);
        let age =
            undrained_supervisor_drain_handoff_age(&file, &content, &unclaimed).expect("undrained");
        assert!(age >= status::SUPERVISOR_DRAIN_HANDOFF_UNDRAINED_AFTER.as_secs());

        // The head drained (a different head is first): the promise was kept.
        let drained = doc("[focused-cycle] a different head");
        assert_eq!(
            undrained_supervisor_drain_handoff_age(&file, &drained, &unclaimed),
            None
        );
    }

    /// Backdate the recorded hand-off of `head` past the undrained window.
    fn backdate_supervisor_drain_handoff(dir: &Path, file: &Path, head: &str) {
        let canonical = file.canonicalize().unwrap();
        let conn = open_state_db(dir).unwrap();
        let backdated =
            timestamp_secs() - status::SUPERVISOR_DRAIN_HANDOFF_UNDRAINED_AFTER.as_secs() - 1_800;
        agent_doc_sqlite::state_store::upsert_document_runtime_state_in_db(
            &conn,
            &agent_doc_sqlite::state_store::DocumentRuntimeStateRecord {
                document_hash: agent_doc_hash::document_id_for_path(&canonical),
                state_kind: SUPERVISOR_DRAIN_HANDOFF_STATE_KIND.to_string(),
                canonical_path: canonical.to_string_lossy().into_owned(),
                payload_json: format!(
                    "{{\"head_sha256\":\"{}\",\"handed_off_secs\":{backdated}}}",
                    agent_doc_hash::content_hash(head)
                ),
                updated_at_ms: backdated * 1_000,
            },
        )
        .unwrap();
    }

    fn has_supervisor_drain_handoff_record(dir: &Path, file: &Path) -> bool {
        let canonical = file.canonicalize().unwrap();
        let conn = open_state_db(dir).unwrap();
        agent_doc_sqlite::state_store::load_document_runtime_state_from_db(
            &conn,
            &agent_doc_hash::document_id_for_path(&canonical),
            SUPERVISOR_DRAIN_HANDOFF_STATE_KIND,
        )
        .unwrap()
        .is_some()
    }

    #[test]
    fn claimed_heads_never_record_or_report_an_undrained_supervisor_handoff() {
        // `#claimeddrainwarn`: the auto-clear yield recorded the FIRST
        // supervisor head ignoring claims; once every head was claimed by a
        // subagent/coordinator the supervisor (which skips claimed heads)
        // correctly had nothing to drain, yet preflight warned for 30+ minutes
        // and told the operator to recycle a healthy supervisor.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        let content = "---\nsession: sid\nagent_doc_format: template\nqueue_active: true\n---\n\n\
## Queue\n\n<!-- agent:queue auto go -->\n- fix claimed thing one\n- fix free thing two\n<!-- /agent:queue -->\n";
        std::fs::write(&file, content).unwrap();
        let none = agent_doc_queue::queue_claim::ClaimedQueueItems::none();
        let first = "fix claimed thing one".to_string();
        let second = "fix free thing two".to_string();
        let first_claimed =
            agent_doc_queue::queue_claim::ClaimedQueueItems::none().with_heads([&first]);
        let all_claimed =
            agent_doc_queue::queue_claim::ClaimedQueueItems::none().with_heads([&first, &second]);
        assert!(supervisor_drain_head_sha256(content, &none).is_some());
        assert_eq!(
            supervisor_drain_head_sha256(content, &all_claimed),
            None,
            "an all-claimed queue has no supervisor head"
        );

        // Recording skips the claimed head and records the one the supervisor
        // will actually dispatch.
        assert_eq!(
            record_supervisor_drain_handoff_for_content(&file, content, &first_claimed).as_deref(),
            Some(second.as_str())
        );

        // Replay the bug: a hand-off recorded for the head that is now
        // claimed, 35 min old. Every head is claimed: no warning, and the
        // settled record is cleared.
        backdate_supervisor_drain_handoff(dir.path(), &file, &first);
        assert_eq!(
            undrained_supervisor_drain_handoff_age(&file, content, &all_claimed),
            None,
            "an all-claimed queue must never report an undrained hand-off"
        );
        assert!(!has_supervisor_drain_handoff_record(dir.path(), &file));

        // The claim is released before the item closes: the stale age must
        // not revive.
        assert_eq!(
            undrained_supervisor_drain_handoff_age(&file, content, &none),
            None,
            "a released claim must not revive a settled hand-off's age"
        );

        // Only the claimed head ahead of an unclaimed one: the warning judges
        // the unclaimed head, not the claimed first one.
        backdate_supervisor_drain_handoff(dir.path(), &file, &first);
        assert_eq!(
            undrained_supervisor_drain_handoff_age(&file, content, &first_claimed),
            None
        );

        // An all-claimed yield clears any earlier record instead of recording.
        backdate_supervisor_drain_handoff(dir.path(), &file, &second);
        assert_eq!(
            record_supervisor_drain_handoff_for_content(&file, content, &all_claimed),
            None
        );
        assert!(!has_supervisor_drain_handoff_record(dir.path(), &file));

        // Control: a genuinely undrained unclaimed head is still reported.
        backdate_supervisor_drain_handoff(dir.path(), &file, &second);
        assert!(
            undrained_supervisor_drain_handoff_age(&file, content, &first_claimed).is_some(),
            "an unclaimed head the supervisor owes stays falsifiable"
        );
    }

    #[test]
    fn editor_reregister_wait_records_episode_escalates_and_clears() {
        // `#reregisterbound` (GH #75): the unanswered-re-register window must be
        // durable across short-lived preflight invocations, reach `Unanswered`
        // once the bound elapses, and restart after escalation clears it.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        std::fs::write(&file, "body\n").unwrap();

        assert_eq!(
            observe_editor_reregister_wait(&file),
            status::EditorReregisterWait::StartWindow
        );
        assert!(matches!(
            observe_editor_reregister_wait(&file),
            status::EditorReregisterWait::Pending { .. }
        ));

        // Backdate the recorded episode past the bound.
        let canonical = file.canonicalize().unwrap();
        let document_hash = agent_doc_hash::document_id_for_path(&canonical);
        let conn = open_state_db(dir.path()).unwrap();
        let backdated = timestamp_secs() - status::EDITOR_REREGISTER_UNANSWERED_AFTER.as_secs() - 5;
        agent_doc_sqlite::state_store::upsert_document_runtime_state_in_db(
            &conn,
            &agent_doc_sqlite::state_store::DocumentRuntimeStateRecord {
                document_hash,
                state_kind: EDITOR_REREGISTER_WAIT_STATE_KIND.to_string(),
                canonical_path: canonical.to_string_lossy().into_owned(),
                payload_json: format!("{{\"first_requested_secs\":{backdated}}}"),
                updated_at_ms: backdated * 1_000,
            },
        )
        .unwrap();
        assert!(matches!(
            observe_editor_reregister_wait(&file),
            status::EditorReregisterWait::Unanswered { age_secs } if age_secs >= 45
        ));

        clear_editor_reregister_wait(&file);
        assert_eq!(
            observe_editor_reregister_wait(&file),
            status::EditorReregisterWait::StartWindow,
            "escalation must restart the window, not re-escalate every call"
        );
    }

    #[test]
    fn schedule_stale_supervisor_cp_recycle_marks_doc_for_idle_recycle() {
        // `#fccsupwarn4`: a preflight-proven stale route-owned supervisor should
        // schedule the safe idle-boundary recycle automatically, not just tell the
        // operator to run `admin recycle` by hand.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        std::fs::write(
            &file,
            "---\nagent_doc_supervisor_auto_recycle: false\n---\nbody\n",
        )
        .unwrap();

        assert!(
            agent_doc_supervisor_io::recycle_request::read_recycle_request(&file.to_string_lossy())
                .is_none(),
            "no request before a stale turn stage schedules one"
        );

        assert!(
            !agent_doc_supervisor_io::config::supervisor_auto_recycle_enabled(&file),
            "test must prove stale recycling overrides the proactive recycle opt-out"
        );
        let status = schedule_stale_supervisor_cp_recycle(&file, "finalize_start");
        assert!(
            status.contains("requested project_root="),
            "schedule status should prove the request was written: {status}"
        );
        assert!(
            status.contains("editor_replica_reregister=requested"),
            "schedule status should prove editor replica re-registration was requested: {status}"
        );

        let request =
            agent_doc_supervisor_io::recycle_request::read_recycle_request(&file.to_string_lossy())
                .expect("recycle-request present after stale-stage scheduling");
        assert_eq!(
            request.reason,
            agent_doc_supervisor::recycle_request::RECYCLE_REQUEST_STALE_SUPERVISOR_TURN_STAGE
        );

        let ops_log = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops_log.contains("stale_supervisor_cp_recycle_requested")
                && ops_log.contains("source=finalize_start")
                && ops_log.contains("reason=supervisor_binary_stale"),
            "ops log should record the automatic recycle request:\n{ops_log}"
        );
    }

    #[test]
    fn schedule_stale_editor_replica_cp_recycle_reports_no_live_registration_when_none_exists() {
        // `#mrnh` / `#ghosteditorliveness`: with no live editor registration there is
        // nothing to re-register, and the old unit-form signal reported a phantom
        // `editor_replica_reregister=requested` that never converged. The counted
        // outcome must instead report `no_live_registration` so session-check stops
        // implying an automatic recovery is pending.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        std::fs::write(&file, "body\n").unwrap();

        let status =
            schedule_stale_editor_replica_cp_recycle(&file, "session_check_terminal_convergence");
        assert!(
            status.contains("reason=no_live_editor")
                && status.contains("editor_replica_reregister=no_live_registration"),
            "with no live editor the status must be honest, not a phantom request: {status}"
        );
        assert!(
            !status.contains("editor_replica_reregister=requested"),
            "must not imply a re-registration was requested when there is no editor: {status}"
        );
        assert!(
            agent_doc_supervisor_io::recycle_request::read_recycle_request(&file.to_string_lossy())
                .is_none(),
            "a successfully published editor repair must not hot-reload a healthy supervisor"
        );
        assert!(!dir.path().join(".agent-doc/crdt-replica-events").exists());
        let ops_log = std::fs::read_to_string(dir.path().join(".agent-doc/logs/ops.log")).unwrap();
        assert!(
            ops_log.contains("stale_editor_replica_recovery_requested")
                && ops_log.contains("source=session_check_terminal_convergence")
                && ops_log.contains("action=reregister_editor_replica")
                && ops_log.contains("reason=editor_authority_unavailable_or_diverged"),
            "ops log should record editor authority recovery:\n{ops_log}"
        );
    }

    #[test]
    fn schedule_supervisor_recycle_marks_served_doc() {
        // `#turnsaferecycle` Goal 1: an install fan-out marks a served route-owned
        // document so its supervisor recycles at the next idle boundary.
        let dir = tempfile::TempDir::new().unwrap();
        std::fs::create_dir_all(dir.path().join(".agent-doc")).unwrap();
        let file = dir.path().join("plan.md");
        std::fs::write(&file, "body").unwrap();

        assert!(
            agent_doc_supervisor_io::recycle_request::read_recycle_request(&file.to_string_lossy())
                .is_none(),
            "no request before scheduling"
        );

        agent_doc_supervisor_io::recycle_request::request_recycle_for_doc(
            &file,
            agent_doc_supervisor::recycle_request::RECYCLE_REQUEST_INSTALL_FANOUT,
        )
        .unwrap();

        let request =
            agent_doc_supervisor_io::recycle_request::read_recycle_request(&file.to_string_lossy())
                .expect("recycle-request present after scheduling");
        assert_eq!(
            request.reason,
            agent_doc_supervisor::recycle_request::RECYCLE_REQUEST_INSTALL_FANOUT
        );
    }

    /// `#turnsaferecycle` Goal 1: the /proc supervisor fan-out is fail-open and
    /// returns a (marked, skipped) tally.
    ///
    /// `#testisolationleaks`: this test used to run the real fan-out over every
    /// supervisor on the machine. Each concurrent `make check` checkpointed the
    /// operator's live documents (a bare-build IPC hello that the editors
    /// rejected) and appended an `install_fanout` recycle request to every live
    /// project's state.db, so open supervisors recycled with nothing installed.
    /// A live-looking supervisor outside the runtime scope now stays invisible
    /// to the fan-out. If discovery regressed, the fan-out would reach the
    /// `guard_test_runtime_target` checks on that document and fail this test.
    #[test]
    fn recycle_supervisors_all_projects_force_never_reaches_a_supervisor_outside_the_test_scope() {
        let live_doc = std::path::Path::new(crate::process::tests::OUT_OF_SCOPE_LIVE_ROOT)
            .join("tasks/plan.md");
        let mut live = crate::process::tests::spawn_fake_agent_doc_process(
            std::path::Path::new("agent-doc"),
            &["start", "--route-owned", &live_doc.to_string_lossy()],
        );
        let raw = crate::process::open_supervisor_document(live.id());
        let outcome = std::panic::catch_unwind(|| recycle_supervisors_all_projects_force(false));
        let _ = live.kill();
        let _ = live.wait();

        assert_eq!(
            raw.as_deref(),
            Some(live_doc.as_path()),
            "raw discovery must see the live probe, or this test proves nothing"
        );
        let (marked, skipped) = outcome
            .expect("the install fan-out reached a supervisor outside the test runtime scope")
            .expect("the fan-out is fail-open");
        let _total = marked + skipped;
        assert!(
            !std::path::Path::new(crate::process::tests::OUT_OF_SCOPE_LIVE_ROOT).exists(),
            "the fan-out must not create state under the out-of-scope root"
        );
    }

    #[test]
    fn recycle_fanout_uses_pid_addressed_ipc_when_stale_document_path_cannot_checkpoint() {
        use std::cell::RefCell;

        // `#renamedsupervisorrecycle`: path transitions must not strand a live
        // supervisor on an unlinked executable. The document-scoped delivery is
        // impossible once its startup path is gone, so every process serving
        // that stale path gets the lease/PID-verified lifecycle delivery.
        let stale = PathBuf::from("/project/tasks/old-name.md");
        let marker_calls = RefCell::new(Vec::new());
        let ipc_calls = RefCell::new(Vec::new());
        let outcome = deliver_supervisor_recycle_requests(
            vec![(41, stale.clone()), (42, stale.clone())],
            |_| anyhow::bail!("document path no longer resolves"),
            |document| {
                marker_calls.borrow_mut().push(document.to_path_buf());
                Ok(true)
            },
            |document, pid| {
                ipc_calls.borrow_mut().push((document.to_path_buf(), pid));
                Ok(())
            },
        );

        assert_eq!(outcome, (2, 0));
        assert!(marker_calls.borrow().is_empty());
        assert_eq!(*ipc_calls.borrow(), vec![(stale.clone(), 41), (stale, 42)]);
    }

    #[test]
    fn recycle_fanout_keeps_document_marker_as_the_deduplicated_primary_path() {
        use std::cell::Cell;

        let document = PathBuf::from("/project/tasks/current.md");
        let checkpoints = Cell::new(0);
        let markers = Cell::new(0);
        let ipc_calls = Cell::new(0);
        let outcome = deliver_supervisor_recycle_requests(
            vec![(41, document.clone()), (42, document)],
            |_| {
                checkpoints.set(checkpoints.get() + 1);
                Ok(true)
            },
            |_| {
                markers.set(markers.get() + 1);
                Ok(true)
            },
            |_, _| {
                ipc_calls.set(ipc_calls.get() + 1);
                Ok(())
            },
        );

        assert_eq!(outcome, (1, 0));
        assert_eq!(checkpoints.get(), 1);
        assert_eq!(markers.get(), 1);
        assert_eq!(ipc_calls.get(), 0);
    }

    #[test]
    fn recycle_fanout_reports_pid_addressed_refusal_as_skipped() {
        let stale = PathBuf::from("/project/tasks/old-name.md");
        let outcome = deliver_supervisor_recycle_requests(
            vec![(41, stale)],
            |_| anyhow::bail!("document path no longer resolves"),
            |_| Ok(true),
            |_, _| anyhow::bail!("lease socket unavailable"),
        );

        assert_eq!(outcome, (0, 1));
    }

    #[test]
    fn recycle_fanout_falls_back_when_checkpoint_returns_no_document() {
        use std::cell::Cell;

        // Live reproduction: a removed startup path produced `Ok(None)` from
        // checkpointing. Mapping that to unit made the fan-out count success
        // and never reach the PID-addressed fallback.
        let marker_calls = Cell::new(0);
        let ipc_calls = Cell::new(0);
        let outcome = deliver_supervisor_recycle_requests(
            vec![(3806401, PathBuf::from("/project/tasks/betterstack.md"))],
            |_| Ok(false),
            |_| {
                marker_calls.set(marker_calls.get() + 1);
                Ok(false)
            },
            |_, pid| {
                assert_eq!(pid, 3806401);
                ipc_calls.set(ipc_calls.get() + 1);
                Ok(())
            },
        );

        assert_eq!(outcome, (1, 0));
        assert_eq!(marker_calls.get(), 0);
        assert_eq!(ipc_calls.get(), 1);
    }

